(window.GIM_TUR_P=window.GIM_TUR_P||{})["OC.7"]={"from":649,"s":[["\u0010c0\u0011\u0010y0\u0011כל הד' מינין פסולין בגזול בין לפני יאוש בין לאחר יאוש ובשאול \u0010c1\u0011\u0010y1\u0011ובשל עיר הנדחת ואשירה של ישראל פסול אבל של עו\"ג לכתחלה לא יטול ואם נטל יצא מיום ראשון ואילך דלא בעינן לכם \u0010c2\u0011\u0010y2\u0011וכל הפסולין כמו שפסולין בראשון כך פסולין כל שבעת הימים חוץ משאול שמותר מיום ראשון ואילך וכן חסר מותר מיום ראשון ואילך \u0010c3\u0011\u0010y3\u0011הלכך ניקב או שנקבוהו עכברים מותר מיום ראשון ואילך אם נשאר בו כשיעור \u0010c4\u0011ובהלכות גדולות פסל אם נקבוהו עכברים כל ז' ימים משום דמאיס אע\"ג דניקב כשר וכ\"כ רב נטרונאי גאון ואדוני אבי הרא\"ש ז\"ל לא חילק \u0010y4\u0011ואפילו לכתחלה מותר לאכול ממנו רק שישאיר ממנו שיעור כדי לצאת בו \u0010y5\u0011ולדידן חשוב יום שני כמו יום ראשון \u0010c5\u0011\u0010y6\u0011אבל כל שאר הפסולין פסולין כל ז' הימים והרי\"ץ גיאת כתב \u0010c6\u0011כל הפסולים אינן פסולין אלא בראשון אבל משם ואילך לא שנא גזול ול\"ש שאר פסולין כולם כשרים וכ\"כ בעל העיטור וה\"ר יונה וא\"א הרא\"ש כתב כסברא ראשונה \u0010y7\u0011וכל הפסולים מחמת מום אם הוא שעת הדחק שאין נמצא כשר כשרים ויכול לברך עליהם והראב\"ד כ' שלא יברך עליהם אלא יאחזם בידו שלא תשתכח תורת לולב ול\"נ לא\"א הרא\"ש ז\"ל \u0010c7\u0011\u0010y8\u0011והרמב\"ם ז\"ל הכשיר לולב יבש בשעת הדחק ולא שאר מינין ולא נראה דמ\"ש זה מזה :",["כל הד' מינים פסולים בגזול בין לפני יאוש בין לאחר יאוש ובשאול בפ' לולב הגזול שנינו דגזול ויבש פסול בכל ד' מינים ובגמ' בר\"פ (כט:) קא פסיק ותני לא שנא ביו\"ט ראשון ולא שנא בי\"ט שני בשלמא יבש הדר בעינן וליכא אלא גזול בשלמא י\"ט ראשון דכתיב לכם משלכם אלא בי\"ט שני מ\"ט א\"ר יוחנן משום רשב\"י משום דהו\"ל מצוה הבאה בעבירה שנאמר והבאתם גזול את הפסח מה פסח לית ליה תקנתא אף גזול לית ליה תקנתא לא שנא לפני יאוש ולא שנא לאחר יאוש בשלמא לפני יאוש אדם כי יקריב מכם אמר רחמנא ולאו דידיה הוא אלא לאחר יאוש הא קנייה ביאוש אלא לאו משום דהו\"ל מצוה הבאה בעבירה ופליגא דרבי יצחק דא\"ר יצחק בר נחמני אמר שמואל לא שנו אלא בי\"ט ראשון אבל בי\"ט שני מתוך שיצא בשאול יצא נמי בגזול מתיב ר' נחמן בר יצחק לולב הגזול והיבש פסול הא שאול כשר אימת אילימא בי\"ט ראשון הא כתיב לכם משלכם והאי לאו דידיה הוא אלא לאו בי\"ט שני וקתני גזול פסול רבא אמר לעולם ביום טוב ראשון ולא מיבעיא קאמר לא מיבעיא שאול דלאו דידיה הוא אבל גזול אימא סתם גזילה יאוש בעלים הוא וכדידיה דמי קמ\"ל ופירש\"י קא פסיק ותני. פסול ל\"ש בי\"ט הראשון דחיוביה מדאורייתא ל\"ש בי\"ט שני דליתיה בנטילת לולב אלא מדרבנן: בשלמא יבש. פסול בדרבנן נמי כיון דמצוה הוא משום זכר למקדש בעיא הידור מצוה: אלא גזול בי\"ט שני אמאי לא מהיכא תיתי למפסליה: אף גזול. אין לו תקנה לאחר זמן ואפי' ביאוש ואע\"ג דלענין מיקנא אמרי' בבבא קמא דקני ליה ביאוש והוי דידיה אפ\"ה אקרובי למזבח לא: מתוך שיוצא בשאול. דהא ביום שני לא כתיב לכם למעוטי: אימא סתם גזילה. מיד ואע\"ג דלא שמעינן דאייאש יאוש בעלים הוא שהרי בפניו גוזלה מידו ואין כח להציל קמ\"ל דעד דשמעינן דאייאש לא קני ליה דמימר אמר השתא הוא דתקיף מינאי למחר תפיסנא ליה בדינא עכ\"ל וכתב הרא\"ש והרב אלפסי שלא הביא אלא המשנה כצורתה ולא הביא פלוגתא דאמוראי דפליגי בגזול מכלל דס\"ל כסתמא דתלמודא דקאמר קפסיק ותני לא שנא בי\"ט ראשון ל\"ש בי\"ט שני ופסיל ליה משום מצוה הבאה בעבירה ואע\"ג דקרא גבי קרבן כתיב ה\"ה לכל המצות כדמוכח בפרק הגוזל קמא דקאמר הרי שגזל סאה חטין וכו' אין זה מברך אלא מנאץ ולא כשמואל דסבר דלא אמרינן הכי אלא במצוה שהיא מדאורייתא ולא מסתבר טעמיה דכיון דמברך ומזכיר שם שמים מנאץ הוא במילי דרבנן כמו במילי דאורייתא ועוד דר\"נ בר יצחק דהוא בתרא פריך לשמואל ממתני' ואע\"ג דדחי ליה לא סמכינן אשינויא דחיקי וכ\"פ בה\"ג ורב פלטוי גאון וגם הר\"ן כתב לענין הלכה הרי\"ף כתב משנתינו כצורתה ולא כתב עליה מחלוקת רבי יוחנן ושמואל מדקא סתם לה סתומי משמע דפסק כר' יוחנן דל\"ש בי\"ט ראשון ל\"ש בי\"ט ב' של דבריהם וכן דעת הראב\"ד והרמב\"ן לפסול כרבי יוחנן דקי\"ל שמואל ורבי יוחנן הלכה כר\"י וכ\"ש הכא דמשמיה דרשב\"י קאמר לה דהוא תנא ור' אמי ס\"ל כוותיה ע\"כ ומיהו אין דעת הרמב\"ם כן שהרי כתב שפסול משום גזל וגניבה אינם פסולים אלא בי\"ט ראשון בלבד וכתב ה\"ה שכן דעת הגאונים וכתב הר\"ן שכן דעת הרז\"ה לפסוק כשמואל: כתב בא\"ח לולב הגזול והגנוב יש פוסלים אותו כל ז' מיהו דוקא לגנב ולגזלן עצמו אבל לאחרים כשר בשאר הימים: וכתב הר\"ן ומיהו כי אמרינן לולב הגזול פסול משום מצוה הבאה בעבירה ה\"מ בשלא קנהו עדיין א\"נ שקנהו אלא שהמצוה מסייעא בקניין דמש\"ה אמרינן גבי קרבן דגזול פסול משום מצוה הבאה בעבירה דס\"ל לרבי יוחנן דיאוש בכדי לא קנה ונמצא שלא קנה גבוה אלא בשינוי רשות ההקדש ודאמרינן בגמרא תיפוק ליה דהא קניה ביאוש יאוש ושנוי רשות קאמרי' אבל כל שקנה בתחלה בלא סיוע המצוה שוב אין בו משום מצוה הבאה בעבירה והביא ראיות לדבר ואח\"כ כתב והיינו דגרסינן בירושלמי מה פליגין כשגזל משופה אבל גזל ושפהו דמים הוא חייב לו כלומר דקנאו בשינוי מעשה וכ\"כ התוס' דמשמע בגמרא דאי קני ליה מצי נפיק ביה ולא חשיב מצוה הבאה בעבירה והא דאמרינן בהגוזל קמא בההיא דגזל סאה דאע\"ג דשינוי קונה מצוה הבאה בעבירה היא אע\"פ שקנאו בשינוי מעשה קודם שבא לידי חיוב חלה התם דיחויא בעלמא הוא א\"נ שאני ברכה דאיכא נמי הזכרה לשם שמים ע\"כ:","\u0003ובשל עיר הנדחת ואשירה של ישראל פסול אבל של עו\"ג לכתחלה לא יטול וכו'\u0004 שם במשנה (כט. לב: לג. לד:) שכל ד' מינים אלו אם היו של אשירה או של עיר הנדחת פסולין ובגמ' (לא.) ושל אשירה פסול והאמר רבא לולב של ע\"ג לא יטול ואם נטל כשר הכא באשירה דמשה עסקינן דכתותי מכתת שעוריה פירש\"י לולב של ע\"ג. ששמשו בו לע\"ג לכבד לפני' קרקע א\"נ שעבודתם בלולב להעבירו לפניה או לזרקה בו לא יטול דמאיס לגבוה ואם נטל כשר ואף ע\"ג דאיסורי הנאה הוא דמצות לאו ליהנות נותנו: באשירה דמשה. אותם שהיו בשעת כיבוש א\"י שהצריכן הכתוב שריפה ולולב צריך שיעור והאי כמאן דמכתת שיעוריה כיון דלשריפה קאי וכתב הרב המגיד דעת רוב המפרשים שראיתי הוא לפרש באשירה דמשה שהיתה בארץ בימי משה שלא היה לה ביטול לפי שהיתה של ישראל דזכו בארץ והוא הדין לע\"ג של ישראל שאין לה ביטול שאף היא אין יוצאין בה אבל אשירה אחרת של עו\"ג אף היא דינה כע\"ג אחרת שאם נטל יצא ומ\"מ בע\"ג אם נתכוין ישראל לזכות בה הו\"ל ע\"ג דישראל ואין לה ביטול ואם נטל לא יצא וכשאמרו יצא הוא בי\"ט ב' שאדם יוצא בשאול עכ\"ל וכ\"כ הר\"ן וכך הם דברי רבינו וכתב עוד הר\"ן דהא דאמר רבא לולב של ע\"ג לא יטול ואם נטל כשר אפי' קודם ביטול הוא דאי לאחר ביטול אפי' לכתחלה נמי דכיון דשרי להדיוט ולא מאוס למצוה ואע\"ג דרב מבעיא ליה בפרק ג' דע\"ז רבא פשיטא ליה כמ\"ש שם עכ\"ל ומיהו מדברי רש\"י שכתב לא יטול משום דמאיס לגבוה לא משמע הכי ודברי הרמב\"ם בדין זה על דרך אחר ולא ראיתי להאריך בהם לפי שהוא דבר שאינו מצוי : כתב בא\"ח גנות הצעירים והדורסים וכיוצא בהם מבתי הכומרים מותר ליטול משם לולב או שאר מינים למצוה:","וכל הפסולין כמו שפסולין בראשון כך פסולין כל ז' הימים חוץ משאול בר\"פ לולב הגזול אהא דאמרי' בגמרא בשלמא יבש בעינן הדר וליכא אלא גזול בשלמא בי\"ט הראשון ולקחתם לכם משלכם אמר רחמנא והאי לאו דידיה הוא אלא בי\"ט שני אמאי לא כתב הרא\"ש משמע דפשיטא ליה דבעינן הדר לכולהו יומי אבל לכם משלכם לא בעינן בשאר ימים וכן ולקחתם דדרשינן מיניה דבעי לקיחה תמה לא מיפסיל אלא בי\"ט א' כדאמרי' בפרקין ר' חנינא מטבל ביה ונפיק ותימה מ\"ש זה מזה הא כולהו בהדי הדדי כתיבי בחד קרא ולקחתם לכם ביום הראשון פרי עץ הדר ואי משום דמשמע דהנך דכתיבי מקמי יום ראשון דוקא עליה קיימי ולא רצו לתקן שיהיו נוהגין בשאר הימים אבל הדר דכתיב בתריה תקון בכל הימים אכתי קשה דהא מולקחתם לכם דרשינן ד' מינים שבלולב מעכבין זה את זה דבעינן לקיחה תמה ודרשינן נמי מדכתיב ולקחתם לשון רבים שתהא לקיחה לכל א' ואחד וא\"כ בשאר הימים תסגי במין א' ולקיחה לאחד בשביל כולם הלכך נראה דהיינו טעמא משום דיום א' דאורייתא בגבולין ושאר הימים דרבנן זכר למקדש הלכך עיקר הלקיחה כגון ד' מינים שבלולב ולקיחה לכל אחד וא' תקון גם בשאר יומי כעין דאורייתא וכן בהדר משום הידור מצוה אבל בחסר לא תקון וכן בשאול ובגזול פליגי בשמעתין מ\"ס דתקון משום מצוה הבאה בעבירה ומ\"ס כיון שהוא מדרבנן לא חשיב מצוה הבאה בעבירה והלכה כמאן דסבר דתקון נמצא שאין חילוק בין י\"ט א' לכל שאר הימים אלא בחסר כדאמרי' לגבי רבי חנינא מטבל ונפיק ביה וכן שאול אבל כל שאר הפסולים נוהגים בכל הימים וי\"ט שני דידן הוא כיום ראשון דספיקא הוא וראיתי דיעות אחרות לפוסקים ונלאתי לכותבם כי לא ישרו בעיני וכאשר כתבתי הוא העיקר עכ\"ל והרמב\"ם כתב שכל הפסולים מפני מומין או מפני גזל וגניבה אינם פסולים אלא ביום ראשון לבד אבל הפסולים משום ע\"ג או מפני שאותו אתרוג אסור באכילה פסול כל ז' הימים וכתב ה\"ה שכן דעת הגאונים ודע שהפסולים מפני שאינן מינן או מפני שהן חסרי השיעור כולם פסולים בשני כראשון וזה מבואר פשוט בדברי רבי' וכתב עוד שיש מוסיפין לפסול עוד בשני גזול ויבש וכ\"ה בהשגות וכבר הכריע הרמב\"ן להכשיר היבש אבל בגזול הודה לדברי הרא\"ש בסמוך כתב סברת הריא\"ג והעיטור והר\"י בזה והיא כסברת הרמב\"ם והגאונים והריב\"א כתב דין היבש יתבאר בסמוך והרשב\"א כתב בתשובה דעתי נוטה דב' ימים ראשונים כיום א' הם ובשניהם בעינן לולב כשר דמספק יום ראשון אנו עושים אותו:","\u0003ומ\"ש רבי' הלכך ניקב או שנקבוהו עכברים מותר מיום ראשון ואילך וכו'\u0004 שם (לו.) אתרוג שנקבוהו עכברים אמר רב אין זה הדר איני והא ר' חנינא מטבל ביה ונפיק ולר' חנינא קשיא מתני' בשלמא מתני' לר' חנינא ל\"ק כאן בי\"ט ראשון כאן בי\"ט שני אלא לרב קשיא אמר לך רב שאני עכברים דמאיסי א\"ד אמר רב זה הדר והא ר\"ח מטבל ונפיק ביה ולר\"ח קשיא מתני' ל\"ק כאן בי\"ט ראשון כאן בי\"ט שני פירש\"י והא ר\"ח מטבל ונפיק ביה אוכל מקצתו ויוצא י\"ח בנותר ומברך עליו ופרכינן ולרבי חנינא קשיא מתניתין דקתני חסר כל שהוא פסול ומשנינן בשלמא מתני' לר\"ח ל\"ק מתני' בי\"ט ראשון שלקיחתו מן התורה ובעי לקיחה תמה ובי\"ט ב' נפיק ביה ר\"ח אע\"ג דלא היה שלם אלא לרב דאמר אין זה הדר קשיא דר\"ח דהא אפילו בשני נמי לרב לא נפיק דהא מצוה הדורה בעיא הואיל ומזכיר ש\"ש עליו והר\"י והר\"א כתבו בלשון הזה אתרוג שנקבוהו עכברים אמר רב אין זה הדר ולא היא דהא ר\"ח מטבל ונפיק ביה ולר\"ח קשיא מתני' ל\"ק מתני' בי\"ט א' ור\"ח ביום ב' וכן הלכתא וכ\"נ שהוא דעת הרמב\"ם שלא חילק בחסר בין נקבוהו עכברים לנקב ע\"י ד\"א ונראה שטעמם מפני שהם פוסקים הלכה כלישנא בתרא דמכשר אפי' בנקבוהו עכברים אלא דא\"כ יש לתמוה על הרי\"ף והרא\"ש שהביאו לישנא קמא וכתבו עליו ולא היא דכיון דמכח לישנא בתרא הוא דפסקי הכי לא הו\"ל לכתוב אלא לישנא בתרא לבד ולכן נ\"ל דממאי דאתמר אלישנא קמא גופיה משמע דהלכה כר\"ח דמתני' כפשטה כוותיה אתיא דאמרינן בשלמא מתני' לר\"ח ל\"ק וכו' אלא לרב קשיא ואע\"ג דשני לרב שאני עכברים דמאיסי שינוייא דחיקא הוא דהא מתני' סתמי קתני חסר פסול בי\"ט ראשון דוקא דמשמע דבשני כשר כל חסר אפי' נקיבת עכברים ובה\"ג שפוסל בניקבוהו עכברים טעמא מפני שפוסק כלישנא קמא דאמר רב אין זה הדר וכדמסיק שאני עכברים משום דמאיסי וצריך טעם למה לא פסק כלישנא בתרא:","ומ\"ש רבינו ואפילו לכתחלה מותר לאכול ממנו פשוט מהא דר\"ח מטבל ביה ונפיק וא\"ת והיכי מצי אכיל מיניה דהא אתקצאי למצותו כבר כתב הרא\"ש דכיון דנשאר בו שיעור לצאת בו ביתר מכשיעור לא אתקצאי וכך תירצו התוס' בפ' לולב וערבה (סוכה מו:) וכתבו עוד דאע\"ג דממ\"נ נאסרה כולה ביום ראשון דחסר כל שהוא פסול דלמא ר\"ח הפריש כולה ליום ראשון ומקצתה לשאר ימים והיה מתנה כוליה ליום א' ובשאר הימים אינו בודל ממקצתו בין השמשות והר\"ן כתב בפרק לולב הגזול דרבי חנינא מן האתרוגים שהיו לו לאכילה היה אוכל מקצתן ויוצא בשאר למחר אבל באתרוג של מצוה ודאי אסור שהרי הוקצה למצותו ע\"כ ומיהו היכא דהפריש כוליה ליום א' ומקצתיה לשאר ימים ודאי דלהר\"ן נמי מצי אכיל מיניה ורבינו כתב דברי הרא\"ש לבד ומיהו ע\"כ צריך לפרש דבהפריש כוליה ליום ראשון ומקצתו לשאר ימים עסקינן דאל\"כ היה אסור לאכול ממנו משום מוקצה וכמו שכתבו התוספות:","ומ\"ש ולדידן חשיב יום ב' כמו יום א' נתבאר שזה דעת הרא\"ש אבל מדברי הרמב\"ם נראה די\"ט ב' דינו כשאר ימים וטעמא משום דבקיאין בקביעא דירחא והר\"ן וה\"ה הזכירו ב' סברות הללו והעלה הר\"ן דנ\"ל דפוסל בראשון ובב' נוטלין אבל ברוכי לא מברכינן :","ומ\"ש רבי' אבל כל שאר הפסולין פסולים כל ז' הימים לעיל קאי שכתב כל הפסולים כמו שפסולין בראשון כך פסולים כל ז' הימים חוץ משאול וחסר ומפני שהפסיק במ\"ש הלכך ניקב או שנקבוהו עכברים ורצה להודיענו סברת הריא\"ג חזר לענין ראשון וחזר לכתוב סיום דברי הרא\"ש דכל שאר הפסולים פסולים כל ז' הימים כדי לכתוב עליו שהריא\"ג חולק: וזה שכתב בשם הריא\"ג ובעל העיטור והר\"י שכל הפסולי' אינם פסולים אלא בראשון אבל מכאן ואילך ל\"ש גזול ל\"ש שאר פסולים כולם כשרים נראה שזהו כסברת הרמב\"ם שכתבתי בסמוך ואע\"פ שסתמו וכתבו כל הפסולים אינם פסולים אלא בראשון כ\"ל דאין בכלל זה הפסולים משום דמכתת שיעורייהו או מפני שאינן מינן וכמו שנתבאר לדעת הרמב\"ם: כתב הר\"ן גבי לולבא דסליק בחד הוצא מדאמרינן בעל מום הוא משמע שפסולו מגופו ופסול כל ז' אפי' בזמן הזה וי\"א שאין פסולו אלא מפני שאינו הדר וביום ראשון בלבד פסול:","\u0003וכל הפסולים מחמת מום אם הוא שעת הדחק שאין נמצא כשר כשרים וכו'\u0004 בפ' לולב הגזול (סוכה לא.) תניא וכולן כמושין כשרים יבישים פסולים רבי יהודה אומר אף יבישים כשירים אמר רבי יהודה מעשה בבני כרכין שהיו מורישים את לולביהם אמרו לו אין שעת הדחק ראיה וכתב הרא\"ש מכאן משמע שבשעת הדחק יוצאין אפי' בפסול וכ\"כ הר\"ר ישעיה מטראני וכ\"כ הראב\"ד ז\"ל ושוב חזר בו ואמר דבין בשעת הדחק ובין שלא בשעת הדחק אין יוצאין ביבש כלל דכל היכא דקתני פסול דמשמע אפילו בדיעבד אפי' במקום הדחק לא יצא בו ואיך יתכן זה להיות שבשעת הדחק יוצאין בו ומברכין עליו ושלא במקום הדחק אפי' בדיעבד לא יצא וסברא הוא כי היבש כמת הוא וכמו שנכתת שיעורו ואיננו ואין מברכין עליו אלא שנוטלין אותו בידים בשעת הדחק כדי שלא תשתכח מהם תורת לולב ואתרוג וזהו שאמר אין שעת הדחק ראיה כלומר שלא עשו כן אלא שלא תשתכח מהם תורת לולב ולשון אין שעת הדחק ראיה אינו מורה על פי' זה דר\"י הביא ראיה לדבריו דאמר יבשים כשרים ומברכים עליהם מבני כרכין שהיו מברכין על היבשים ואמרו לו אין שעת הדחק ראי' שאין ללמוד שלא בשעת הדחק משעת הדחק אבל מודו רבנן דבמקום הדחק (אין) מברכין דאל\"כ יאמרו לו בשעת הדחק נמי לא היו מברכים אלא כל הני פסולים מסרן הכתוב לחכמים והן אמרו שלא בשעת הדחק אפילו דיעבד לא יצא כדי שיזהרו ישראל במצוה אבל במקום הדחק הכשירו כיון שא\"א בענין אחר ומברכין עליהם עכ\"ל והר\"ן כתב שהרמב\"ן לפי שטתו מכשיר אף היבש בשני של דבריהם אבל הראב\"ד הביא ראיה לפוסלו אף בב' של דבריהם והסכים הר\"ן לדברי הראב\"ד והמרדכי כתב בשם רא\"ם אע\"פ שפסלנו יבישים בלולב והדס וערבה אנן בלולב והדס מברכין איבשים משום דלא אפשר והוא שעת הדחק מדתניא איבשים אמרו לו אין שעת הדחק ראיה ופירש ראבי\"ה דה\"ה אתרוג כבוש וחסר ע\"כ וכך הם דברי התוס' בפ' לולב הגזול שאם לא מצא כשר יצא בפסול כמו לולב פסול לרבנן בשעת הדחק ונראה שדייק רבינו לכתוב כל הפסולים מחמת מום לאפוקי אותם שפסולים מפני שאינן מינם כהדס שוטה וצפצפה דהנך לד\"ה אין נוטלין אותם לעולם ואפי' בשעת הדחק כי היכי דלא ליתו למיטעי בהו כדאמרינן בגמרא בפריש ורמון וכ\"כ ר\"י דהדס שוטה פסול לכל הימים דגרע מהדס יבש ושלא כדברי המהפכים בזכות בני אשכנז שנוטלין הדס שוטה ומברכין עליו כמו שכתוב בסי' תרמ\"ו :","והרמב\"ם הכשיר לולב יבש בשעת הדחק ולא שאר המינים בפ\"ח וכתב ה\"ה דמדאמרי' על לולב היבש אין שעת הדחק ראיה אלמא דלולב יבש כשר בשעת הדחק וראיתי כתוב שהגאונים סמכו מכאן דיבש ונקטם ראשו וכל הפסולים יוצאים בהם בשעת הדחק אף ביום ראשון ודעת רבינו שלא להכשיר אלא לולב היבש שהזכירו חכמים וכן העיקר עכ\"ל ולענין מעשה נראה דכל הני פסולים בשעת הדחק נטולי נטלינן ברוכי לא מברכינן : כתב הגה\"מ על הא דמכשיר הרמב\"ם לולב היבש אנו סומכין על זה גם בהדם היבש: כתב בכתבי מה\"ר איסרלן סימן קצ\"ט בסמ\"ק וא\"ז כתב דבשאר הימים אינו יוצא בגזול נראה דאפי' לפי הירושלמי יכול אדם לברך על לולב דחבריה בשאר ימים בלי ידיעתו דניחא ליה לאינש למיעבד מצוה בממוניה כיון דלא מחסר לממוניה וראיה מטלית דאדם מברך בו בלא דעת חבירו :"],["\u0003כל ד' המינין פסולין בגזול וכו'\u0004 בפרק לולב הגזול שנינו דגזול ויבש פסול בכל ד' המינין ובגמרא פליגי ר' יוחנן ושמואל בי\"ט שני דאין נטילתן אלא מדרבנן אי פסלינן נמי בגזול ופסקו הרי\"ף והרא\"ש כר\"י דפוסל אף בי\"ט שני ומשמע בסוגיא דבין לפני יאוש ובין לאחר יאוש פסול משום דהו\"ל מצוה הבאה בעבירה אלא שהתוס' כתבו דבלאחר יאוש אינו פסול אא\"כ בגזלו אגוד דלית ביה לא שינוי השם ולא שינוי מעשה אבל בגזלו כשאינו אגוד ואח\"כ אגדו דאיכא יאוש בהדי שינוי השם ושינוי מעשה וקני ליה מקמי דחל חיוב המצוה תו לא הוה מצוה הבאה בעבירה ע\"ש בדף ל' בד\"ה הא קנייה בייאוש ובד\"ה ולקנייה בשינוי השם. ואיכא לתמוה על רבינו שסתם וכתב דפסול בלאחר יאוש ולא חילק ונראה לומר דס\"ל דדוקא למ\"ד לולב צריך אגד חשיב שינוי מעשה כשאגדו אבל למאי דקי\"ל דלולב א\"צ אגד לא חשיב שינוי מעשה ואע\"ג דאיכא שינוי השם דמעיקרא הו\"ל לולב והשתא הושענא כיון שחוזר לברייתו לא שמיה שינוי ועייו בסוגיא ובדברי התוספות ומ\"מ היכא דקננהו לאחר היאוש בשינוי מעשה ממש תו לא הו\"ל מצוה הבאה בעבירה שהרי קננהו מקמי דחל חיוב המצוה וכ\"כ הר\"ן ודוקא לגזלן ולגנב עצמו אבל לאחרים לית בהו משום מצוה הבאה בעבירה וכ\"כ באורחות חיים:","ובשל עיר הנדחת ואשרה של ישראל פסול שם במשנה של אשרה ושל עיר הנדחת פסול ובגמ' מוקמינן לה דוקא באשרה של ישראל שאין לה ביטול וכתותי מיכתת שעוריה דומיא דעיר הנדחת אבל של עו\"ג לכתחילה לא יטול כיון שלא ביטלו ואם נטל יצא דכיון שמועיל לו ביטול לאו כתותי מיכתת שיעוריה הוא ואע\"ג דכל זמן שלא ביטלו איסורי הנאה נינהו מצות לאו ליהנות ניתנו וכתב רבינו דוקא מיום ראשון ואילך דאילו ביום ראשון ממה נפשך אינו יוצא בו דאם נתכוין לזכות בו כשהוא משל הפקר הו\"ל ע\"ג של ישראל ואי לא נתכוין לזכות בו הו\"ל כמו שאול ופסול בי\"ט ראשון ועיין במ\"ש גבי שופר בסימן תקפ\"ו:","\u0003וכל הפסולים וכו'\u0004 טעמו דכל הפסולין משום דבעינן הדר כמו יבש ונקטם ראשו וכיוצא בהם דאית ביה משום הידור מצוה בעינן הידור כל הז' וכן היכא דאית ביה משום כתותי מכתת שיעוריה וכן היכא דפסולין מפני שאינן מינן או שאינן כדי שיעורן סברא הוא דאין חלוק וכן היכא דפסולים משום דבעינן לקיחה שמה והוא מעיקר הלקיחה דהיינו שיקח הד' מינין ביחד ולקיחה לכ\"א ואחד כמו שיתבאר לקמן תקינו נמי רבנן דפסולין כל שבעה אבל שאול דשפיר מתקיים עיקר לקיחה וכן חסר אע\"ג דפסולים משום דבעינן לקיחה תמה מ\"מ שפיר מתקיים ביה עיקר לקיחה לא תקנו רבנן למיפסליה בשאר הימים דכל עיקר נטילתן אינו אלא מדרבנן וכ\"כ התוספות והרא\"ש ר\"פ לולב הגזול:","ומ\"ש הלכך ניקב או שנקבוהו עכברים מותר מיום ראשון ואילך הכי איתא בפ' לולב הגזול בלישנא בתרא דרב דקאמר זה הדר וכן פסקו הרי\"ף והרא\"ש ומ\"ש ואם נשאר בו כשיעור פשוט הוא דבעינן דנשאר בו כשיעור אלא דאתא לאשמועינן דסגי בהכי אלא שהר\"ן מחמיר דאפילו נשאר בו כשיעור לא מכשרינן אלא בשרובו קיים דשמו עליו הא לאו הכי לא דאתרוג אמר רחמנא ולא חצי אתרוג וז\"ל התו' בפרק לולב וערבה (סוכה דף מ\"ו ע\"ב) דר' חנינא כיון דלא אכיל ליה כוליה ומשייר ביה כשיעור דמצי נפיק ביה שרי וכו' ואפשר לומר דאף התוספו' ס\"ל דדוקא בשרובו קיים ולא הוצרכו לפרש ועוד דבכלל לשון זה שכתבו ומשייר ביה כשיעור דמצי נפיק ביה הוא ג\"כ דמשייר ביה הרוב דתרתי בעינן שיהא רובו קיים ושיהא אותו הרוב כביצה והכי מסתברא:","\u0003ומ\"ש ובה\"ג פסל אם נקבוהו העכברים כו'\u0004 פסק כלישנא קמא דרב דמחמיר בנקבוה עכברים משום דמאיסי ואין זה הדר והכי נקטינן לחומרא וכן פסק מהרי\"ל:","\u0003ומ\"ש אבל כל שאר הפסולין פסולין כל ז' הימים לעיל קאי וכו'\u0004 כמו שפי' בית יוסף גם אפשר לומר דתחלה קאמר כל הפסולין כו' דהוה משמע דוקא אותן שהזכיר בדבריו קודם זה לכך בא כאן והוסיף לומר דאף שאר כל הפסולין שיתבארו עוד בדבריו פסולין ג\"כ כל הז' וטעמן של הרי\"ג ודעימיה דמכשירין אף בגזול בשאר הימים הוא מפני שפוסקין כשמואל דאמר הכי וס\"ל דלא חיישינן למצוה הבאה בעבירה במצוה שאינה אלא מדרבנן אבל ביום א' דאף בגבולין חייבין ליטול לולב ד\"ת פסול הגזול אף לאחר יאוש דהו\"ל משלכם אפ\"ה פסול משום מצוה הבאה בעבירה אם לא קנאו קודם שחל חיוב המצוה וכתב הב\"י דאף לדעת הרי\"ג ודעימיה כל הפסולין משום דמכתת שעורייהו או מפני שאינן מינן פסולין כל הז' וכסברת הרמב\"ם וה' המגיד:","\u0003וכל הפסולים מחמת מום אם הוא שעת הדחק וכו'\u0004 היתר שעת הדחק מפורש בברייתא פרק לולב הגזול והתוס' מפרשי' אותה כפשטא דמתיר לברך עליו. וכן הסכים הרא\"ש וכ\"כ המרדכי בשם רא\"ם אבל הראב\"ד מפרש דהיתר שעת הדחק הוא דוקא בלא ברכה והאריך הר\"ן בטעם דבריו ע\"ש ובאשר\"י. כתב רבינו ירוח' דהדס שוטה פסול לכל הימים ומשמע אף בשעת הדחק נמי אין נוטלין אותו אפילו בלא ברכה משום דזימנין דנפיק מיניה חורבא דאתו למיסרך כדאיתא בגמרא בפריש ורמון במקום אתרוג וה\"ה לכל הפסולים מפני שאינן מינן כצפצפה וכיוצא בו:","\u0003ומ\"ש והרמב\"ם הכשיר לולב יבש כו'\u0004 טעמו משום דהיתר שעת הדחק איתא בברייתא גבי לולב וס\"ל דדוקא לולב דמתקיים ביה הדר קצת מפני צורתו אף על פי שהוא יבש אבל שאר מינים לא מתקיים בהו הדר כל עיקר ורבינו השיג עליו דמ\"ש וכ\"כ ה\"ה בשם הגאונים:"]],["\u0010c0\u0011\u0010y0\u0011שיעור הדס וערבה שני טפחים וחצי שהן י' גודלים \u0010c1\u0011\u0010y1\u0011ושדרה של לולב לבד מעלין העולין למעלה מהשדרה צריך \u0010c2\u0011שיהא יוצא למעלה מההדס טפח חסר שתות \u0010y2\u0011ואם ירצה יוסיף עליהם כל מה שירצה שאין להם שיעור למעלה:",["\u0003שיעור הדס וערבה ב' טפחים וחצי וכו'\u0004 בפרק לולב הגזול (סוכה לב.) שיעור הדס וערבה ג' ולולב ד' רבי טרפון אומר באמה בת ה' טפחים כי אתא רבין אמר אמה בת ה' טפחים עשה אותה ששה צא מהם ג' להדס והשאר ללולב אר\"ה אמר שמואל הלכה כר\"ט נמצא לפ\"ז דשיעור הדס וערבה טפחיים ומחצה וכן פסקו הרא\"ש והר\"ן ותמהו על הרי\"ף שהשמיט הא דר\"ט והרמב\"ם סתם וכתב בפ\"ז דשיעור הדס וערבה אין פחות מג\"ט ומתוך דבריו משמע דג\"ט גמורים קאמר דאל\"כ הו\"ל לפרושי וכתב ה\"ה בהשגות א\"א ג\"ט קטנים שהם י' אצבעות בגודל ע\"כ וכן פסקו מקצת הגאונים והאחרונים ז\"ל אבל בהלכות לא הביאו אותה סוגיא דר\"ט כלל ואפשר שהם סוברים דשמואל הוא דפסיק כר\"ט דאמר דסגי בטפחים קטנים ולא כת\"ק דברייתא דבעי טפחים שלמים ולא קיימא לן כוותיה דשמואל ואף בעל העיטור לא כתב אלא מימרות כפשטן ומ\"מ הנכון כדעת שאר המפרשים ז\"ל עכ\"ל :","\u0003ומ\"ש רבינו ושדרה של לולב לבד מן העלין העולין למעלה מהשדרה צריך שיהא יוצא וכו'\u0004 שם אר\"י א\"ש שיעור הדס וערבה ג' ולולב ד' כדי שיהא לולב יוצא מהדס טפח ורבי פרנך א\"ר יוחנן שדרו של לולב צריך שיצא מן ההדס טפח וידוע דשמואל ורבי יוחנן הלכה כר\"י וכן פסקו הפוסקים: וכתב הר\"ן דמסתברא דאפי' הוסיף באורך ההדס וערבה אפי' כמה צריך שיצא שדרו של לולב ולמעלה מהם טפח: וכתב עוד הר\"ן י\"א שהטפח שצריך שיהא יתר בו הלולב על ההדס וערבה טפח קטן הוא ג\"כ ונמצא שיעור לולב ד\"ט קטנים וכו' שהם י\"ג גודלים ושליש וכ\"כ התוספו' והה\"ר יונה מנח ביה סימנא מי בעל דברים יגש שהלולב שאומרים בו דברים הרבה והיינו ברכת לולב והלל שיעורו יגש דהיינו י\"ג גודלי' ושליש אבל הרמב\"ן כ' שלא חלק ר\"ט בטפח עודף של לולב ומודה הוא שצריך שיהא טפח שלם של ד' גודלים ונמצא לפי דבריו שיעורו של לולב י\"ד גודלים לפי שהג\"ט קטנים הם והד' טפח שלם ע\"כ ודברי רבינו כדברי התו' והה\"ר יונה וכל זה לפי דרכם שפוסקים דטפחים דהדס וערבה הם טפחים קטנים אבל כ\"כ שיש חולקים בדבר ולפי דבריהם שיעור אורך הלולב אין פחות מי\"ו גודלים:","ומ\"ש ואם ירצה יוסיף עליהם כל מה שירצה שאין להם שיעור למעלה כ\"כ הרי\"ף והרמב\"ם והרא\"ש והכי איתא:"],["שיעור הדס וערבה שני טפחים וחצי שהן י' גודלים פלוגתא דחכמים ור' טרפון בברייתא בפ' לולב הגזול ופסק שמואל הלכה כר\"ט דאמר הכי והתם מותבינן דשמואל אדשמואל דאמר שעור הדס וערבה שלשה ומשני לא דק ולחומרא לא דק והרי\"ף והרמב\"ם פסקו כההיא דשמואל דשעור הדס וערבה שלשה שהם מפרשים הא דקאמר ולחומרא לא דק ה\"פ שמואל הלכה למעשה אתי לאשמועינן שיהו תופסי' בשיעור לחומרא שלא לדקדק בשיעור מצומצם כר\"ט אע\"ג דהילכתא כוותיה והכריחם לפרש כן משום דקשיא להו דאמאי לא דק שמואל ונקט שיעורא לחומרא טפי מר\"ט אלא ודאי שמואל הלכה למעשה אתי לאשמועינן וכדפי':","\u0003ומ\"ש ושדרו של לולב כו'\u0004 שם הכל מודים דבעינן שיהיה הלולב יוצא מן ההדס טפח אלא דפליגי בשדרה דשמואל סבר דסגי בטפח יוצא אף בעלין ור' יוחנן סבר דוקא שדרה והלכה כר\"י דר\"י ושמואל הלכה כר\"י ותו דברייתא בפרק המפלת מסייע לר\"י דקא חשיב ה' שיעורן טפח וקא חשיב שדרו של לולב: ומ\"ש דהיוצא הוא טפח חסר שתות ה\"ט דבגמר' אמרי' דר\"ט ס\"ל דשיעור הדס ג' טפחים קטנים שכל טפח חסר שתות טפח בינוני דהיינו ב' טפחים ומחצה בינונים שהן י' גודלים וממילא טפח היוצא ללולב נמי הוי בטפח קטן כמו אלו שהוא ג' גודלים ושליש גודל ס\"ה י' גודלים ושליש וכן פירש\"י על צא מהן ג' להדס והשאר ללולב וכן פירשו התוספות וכ\"כ הר\"ן ובשם ה\"ר יונה. וכתב עוד שהרמב\"ן חולק וס\"ל דטפח היוצא טפח שלם בעינן שהוא ד' גודלים וכן פסק במרדכי ונראה דטעמן משום דקי\"ל כברייתא דהמפלת דה' שיעורן טפח ומשמע דטפח דלולב שוה לאחרים עי' בתו' בפרק לולב הגזול ובפר' המפלת ולענין הלכה נקטינן לחומרא דבעינן ג' טפחים שלמים להדס שהן י\"ב גודלין ובלולב ד\"ט שלמים שהן ט\"ז גודלים:","\u0003ומ\"ש ואם ירצה יוסיף עליהם כל מה שירצה וכו'\u0004 הכי איתא בפ' התכלת (מנחות בדף מ\"ב) וכן פסקו הרי\"ף והרא\"ש בפרק לולב הגזול. ואיכא למידק דלמעלה גבי טפח דשופר הכריח רבינו דכדי שיאחזנו לאו אתוקע קאי דאם כן הו\"ל למתנייה בהדיא הכל לפי מה שהוא אדם כו' וכאן פסק טפח דלולב הוא טפח קטן ולא קשיא ליה דאם כן הו\"ל למיתני בהדיא וי\"ל דדוקא גבי טפח דשופר דאיכא למיטעי ולפרש לקולא דכדי שיאחזנו אדם סתמא קאמר והיינו טפח בינוני ומשום הכי חשיב ליה עם שאר טפחים בפרק המפלת הלכך ודאי קשה הו\"ל למתנייה בהדיא הכל לפי מה שהוא אדם דאגרופו של בן אבטיח גדול טפי וכשהוא תוקע אינן יוצאין בשופר שאין בו כי אם טפת בינוני אבל גבי טפח דלולב שאין צריך רק טפח קטן חשיב ליה התם עם שאר טפחים כיון דאיכא שם טפח עליה ולא חש לבאר שלא לטעות דבעי טפח בינוני חדא דאפי' אם נטעה לא יבא לידי תקלה דמה בכך שנתפוס לחומר'. ועוד דחילוק מועט יש ביניהן ב' שלישי גודל ואין דרך להקפיד כל כך ועוד דסתמא דמילתא טפח דלולב היוצא הוא שוה לטפח דהדס וערבה שאינן כי אם טפחים קטנים א\"כ לא אתי למיטעי משא\"כ בשופר דאיכא כל הני דאתי למיטעי להקל וגם חילוק גדול יש ביניהם כמו בן אבטיח וליכא ראיה והוכחה שלא לטעות בכך אדרבה איכא הוכחה על הטעות מדחשיב ליה עם שאר טפחים הילכך הו\"ל למתנייה בהדי' ומדלא תנייה בהדיא שמע מינה דכדי שיאחזנו אדם סתמא קאמר ודו\"ק:"]],["\u0010c0\u0011\u0010y0\u0011מצות ד' מינין שיטול כל אחד וא' מישראל לולב אחד וב' ערבות שלימות וג' הדסין אפי'\u0010y1\u0011 שלשתן קטומים בראשיהן והרמב\"ם ז\"ל הכשיר גם בערבה קטומה ולא נהירא \u0010c1\u0011\u0010y2\u0011ויעשה מהדס והערבה והלולב אגודה אחת אע\"ג דקי\"ל לולב א\"צ אגד מצוה לאגדו משום נוי \u0010c2\u0011\u0010y3\u0011וכיון שאין חובה לאגדו אפילו אגדו במין אחר שפיר דמי \u0010c3\u0011\u0010y4\u0011ומשום חציצה נמי ליכא אע\"ג שהקשר מפסיק בין ידו ללולב דכיון שהוא לנאותו אינו חוצץ \u0010c4\u0011וכן מין במינו אינו חוצץ \u0010y5\u0011הלכך אם נשרו מעלי הלולב או מעלי ההדס ונשארו בתוך האגודה בענין שמפסיק אין לחוש \u0010c5\u0011\u0010y6\u0011ורש\"י פי' אע\"ג דא\"צ אגד מ\"מ לכתחילה חובה לאגדו משום זה אלי ואנוהו התנאה לפניו במצות \u0010c6\u0011\u0010y7\u0011ואם לא אגדו מאתמול או שהותר אגודו בי\"ט א\"א לאגדו בקשר גמור אלא אוגדו באגודה של ירק שכורך האגודה סביב ותוחב ראש האגודה לתוכה בלא קשירה \u0010c7\u0011\u0010y8\u0011ויטול האגודה בידו הימנית \u0010y9\u0011ויהיו ראשיהם למעלה ועיקריהם למטה \u0010y10\u0011והאתרוג בידו השמאלית \u0010c8\u0011ואף אם הוא איטר יד ימינו יטול האתרוג בשמאל כל אדם שהוא ימינו \u0010c9\u0011\u0010y11\u0011וכשיטול הלולב בידו קודם שיטול האתרוג יברך על נטילת לולב ושהחיינו כדי שיברך קודם לעשייתו שאילו יטול ארבעתן קודם שיברך נמצא שכבר יצא קודם לעשייתו ושכיון שהגביה יצא או יהפוך הלולב או האתרוג עד שיברך ונמצא שלא יצא כיון שלא נטלו דרך גדילתו אי נמי יכוין שלא לצאת עד שיברך \u0010y12\u0011והרמב\"ם ז\"ל כתב שיברך קודם שיטלנו בידו \u0010y13\u0011ול\"נ לר\"י \u0010c10\u0011וי\"א כיון שלא נענעו ועדיין יש לו לתפסו בידו אע\"פ שאינו מעכב קרינן ביה שפיר קודם לעשייתו וטוב לעשות באחד מן הדרכים שכתבתי \u0010c11\u0011ולא יברך שהחיינו בשעת עשייתו \u0010c12\u0011\u0010y14\u0011ולקיחה ע\"י דבר אחר שמה לקיחה הלכך אפילו עשה בית יד ונתן בו הלולב ונטלו שפיר דמי אפילו כל הלולב חוץ מידו ובלבד שיהא דרך כבוד אבל אם אינו דרך כבוד כגון שנתנו בכלי ונטלו לא יצא \u0010c13\u0011\u0010y15\u0011וינענע בשעה שמברך \u0010c14\u0011וכן ינענע בשעת קריאת ההלל \u0010c15\u0011בהודו בכל פעם שמחזירין אותו הקהל וכן באנא ה' הושיעה נא אבל לא באנא ה' הצליחה נא וכן ינענע בהודו שבסוף המזמור \u0010c16\u0011\u0010y16\u0011והניענוע הוא שמוליך ידו מכנגדו להלאה וינענע שם ג\"פ בהולכה וג\"פ בהובאה ואח\"כ מטה ידו לצד צפון ועושה כן ג\"פ וכן לצד דרום וכן לצד מערב ומעלה ידו למעלה ועושה כן ג\"פ ומורידה לצד מטה ועושה כך ג\"פ סך הכל ל\"ו פעמים \u0010c17\u0011וב\"ה כ' וניענוע דרבנן ואזלינן ביה לקולא וא\"צ לכל רוח ג\"פ הולכה וג\"פ הובאה אלא בין הולכה והובאה ג\"פ לכל רוח \u0010y17\u0011וכ' עוד מנהג אבותינו מוליך ומביא מעלה ומוריד בלבד מוליך ומביא למי שד' רוחות שלו והמושל בב' מושל בד' והמוליך לצפון ולדרום דעת חיצוני הוא \u0010c18\u0011וא\"א ז\"ל כתב והעולם לא נהגו כן אלא מוליכין לד' רוחות ומנהג כשר הוא הקצרה יד ימיננו להודות למי שד' רוחות שלו ומנהג אחר הוא חיצוני והראשון שהנהיג כן היה נראה לו שהמוליך ומביא לד' הרוחות נראה כמו שהעו\"ג עושין והבל הוא דאדרבא כשמוליך ומביא לשתי רוחות ואחר כך מעלה ומוריד נראה כו' שיש לו ארבע קצוות אבל כשמוליך ומביא לד' רוחות ואח\"כ מעלה ומוריד יש לו שש קצוות ע\"כ \u0010c19\u0011\u0010y18\u0011כתב ב\"ה הולכה והובאה הוא הנענוע וא\"צ נענוע שדרה ועלין וכ\"כ גאון ז\"ל שא\"צ נענוע שדרה ועלין שלא אמרו אלא כדרך שאמרו בתנופה מוליך ומביא מעלה ומוריד \u0010c20\u0011\u0010y19\u0011ואלו הד' מינין מעכבין זה את זה שאם \u0010y20\u0011חסר לו אחד מהן לא יברך על הנמצאים בידו אבל אם יש לו כולם אפילו לא נטלן ביחד אלא נטלן זה אחר זה יצא ובלבד שיהו כולם לפניו \u0010c21\u0011ויטול הלולב תחלה \u0010c22\u0011חסר לו אחד מן המינין \u0010y21\u0011 לא יקח מין אחר במקומו \u0010c23\u0011ולא יפחות מהן \u0010c24\u0011ולא יוסיף עליהן מין אחר אפי' אם לא יאגדנו עמהם אם יאחזנו בידו עמהם לשם מצות לולב איכא בל תוסיף \u0010c25\u0011\u0010y22\u0011אבל מאותם ד' המינין יכול להוסיף עליהם \u0010c26\u0011ובהדס שוטה שאינו עבות נחלקו בו הגאונים אם הוא מין הדס ויכול להוסיף אותו אם לאו בהלכות גדולות כתב הדס שוטה אפי' בהדי אסא אחריני פסול ורב נטרונאי כתב אם יכול לעשותו כולו עבות מצוה מן המובחר ואם אינו מוצא אלא ג' הדס עבות ממלא אותו הדס שוטה ושפיר דמי וכ\"כ א\"א הרא\"ש ז\"ל \u0010y23\u0011כתב רב עמרם נהגו במקומינו במתיבתא מכמה דורות שלא לפחות מששים ושמונה ערבות כמנין לולב ויש מוסיפים עד שבעים כמנין הפרים:",["מצות ד' מינים שיטול כל אחד מישראל לולב אח' וב' ערבות בפ' לולב הגזול (סוכה לד.) תנן ר' ישמעאל אומר ג' הדסים וב' ערבות לולב אחד ואתרוג אחד אפי' ב' קטומים ואחד שאינו קטום ר\"ט אומר אפילו שלשתן קטומים רבי עקיבא אומר שכשם שלולב אחד ואתרוג אחד כך הדס אחד וערבה אחת ופסק הרמב\"ם בפ\"ז במנין כדברי ר' ישמעאל דבעי ג' הדסים וכתב ה\"ה שכן דעת כל הגאונים משום דר\"ט נמי כרבי ישמעאל ס\"ל במניינא שהרי אמר שלשתן קטומין אלמא תלתא בעי כר' ישמעאל אבל הרמב\"ן כתב דהלכה כר\"ע במניין שאפי' בהדס אחד יוצא י\"ח ור\"ט נחלק על רבי ישמעאל בדין הקטימה ולא הכניס עצמו במחלוקת המנין אלא בקטימה וקיימא לן כר\"ט בקטימה לפי שנפסקה הלכה כמותו וקיימא לן דהלכה כר\"ע במנין ושתיהן להקל דאפי' אחד וקטום יוצא בדיעבד אלא שלא קיים מצוה מן המובחר עכ\"ד ונתלה בזה באותה סוגיא האמורה שם ולדרוש להו כר\"ע וכבר כתבתי שדעת כל הגאונים כרבינו עכ\"ל:","\u0003ומ\"ש רבי' בדין קטימ' ראשי ההדס וערבה כבר נתבאר כל אחד במקומו:\u0004 ","ויעשה מההדס והלולב והערבה אגודה אחת אע\"ג דקיימא לן לולב א\"צ אגד מצוה לאגדו משום נוי פרק הקומץ רבה (מנחות כז.) ופרק לולב הגזול (סוכה לג.) פליגי רבי יהודה ורבנן אם לולב צריך אגד ואמרינן דאפילו לרבנן דאמרי א\"צ אגד מצוה לאגדו משום זה אלי ואנוהו: כ' המרדכי בפ' לולב הגזול כתב רא\"מ צריך שיאגדנו ב' קשרים זה על זה דתניא הותר אגדו בי\"ט אוגדו כאגודה של ירק וכו' הא בחול יש לאגדו אגד הנאסר בשבת וי\"ט ואין אסור אלא שני קשרים זה על זה וראבי\"ה כ' אנן נהגינן לקשר פעם א' ושוב מתעגל וכורכו סביב ומתוך כך מהודק יפה כאילו קשרום בב' ראשי האגד ב\"פ :","ומ\"ש וכיון שאין חובה לאגדו אפי' אגדו במין אחר ש\"ד בפ' לולב הגזול (סוכה לז:) תנן אין אוגדין את הלולב אלא במינו דברי ר\"י ר\"מ אומ' אפילו בחוט ואפי' במשיחה ובגמרא (שם.) אמרינן מ\"ט דר\"י קסבר לולב צריך אגד ואי מייתי מינא אחרינא הוה ליה ה' מינים פי' ועובר משום בל תוסיף ובפרק הנחנקין אמרינן דאי ס\"ל לולב א\"צ אגד האי לחודיה קאי והאי לחודיה קאי כלומר מש\"ה אגדו במין אחד לית ביה משום בל תוסיף ופסקו הפוסקים כר\"מ:","ומ\"ש ומשום חציצה נמי ליכא אע\"פ שהקשר מפסיק בין ידו ללולב דכיון שהוא לנאותו אינו חושש בפ' לולב הגזול (סוכה לו:) אמר להו רבה להנהו דגדלי הושענא דבי ריש גלותא שיירו ביה בית יד כי היכי דלא תהוו חציצ' ופירש\"י שיירי בית יד מתחת לאגד שלא יקחנו במקום אגדו דקסבר אין האגד מן המצוה כרבנן דאמרי א\"צ אגד דלא להוי חציצה בין יד להושענא ואין זו לקיחה רבא אמר כל לנאותו אינו חוצץ ופסקו הפוסקים כרבא:","ומ\"ש הלכך אם נשר מעלי הלולב או מעלי ההדס ונשארו בתוך האגודה בענין שמפסיק אין לחוש שם אמר רבה לא לדוץ איניש לולבא בהושענא דנתרי טרפי והוי חציצה ורבא אמר מין במינו אינו חוצץ ואמר רבה לא ליגוד איניש לולבא בהושענא דמשתיירי הוצי והוי חציצה ורבא אמר מין במינו אינו חוצץ ופירש\"י לא לדוץ איניש לולבא בהושענא. לאחר שאגד לולב הערבה וההדס יחד לא יתחוב הלולב מלמעלה בתוך האגד דלמא נתרי טרפי הלולב משיר עלי ההדס והערבה ומשתיירין באגד וחוצצין בין מין ומין ואינן אגודין להיות אגודה אחת: לא ליגוד איניש לולבא בהושענא אם הוא ארוך יותר מדאי מן הערבה ובא לקצצו מתחת לא יקצצנו בעודו באגודה אלא יוציאנו ויגוז מתחת ויחזור ויאגוד דמשתייר הוצא של לולב תלושים מן השדרה בתוך האגד ופסקו הפוסקים כרבא דאמר מין במינו אינו חוצץ:","\u0003ומ\"ש רבינו ורש\"י פירש אע\"ג דלולב א\"צ אגד מ\"מ לכתחלה חובה לאוגדו וכו'\u0004 שם בפרק לולב הגזול (סוכה לג.) בהא דת\"ר הותר אגדו ביום טוב אוגדו ביום טוב כאגודה של ירק וכו' כתב רש\"י שמעינן מהכא דבעינן בלולב קשר גמור שיקשור ב' ראשי האגד והאוגדן כאגודה של ירק לאו אגד הוא ואפי' רבנן דפליגי עליה דרבי יהודה ואמרי לולב שאינו אגוד כשר מודו דמצוה לאגדו כדתניא משום זה אלי ואנוהו ואוקימנא כרבנן ע\"כ ומ\"מ אין מכאן ראיה לומר דהוא סובר שחובה לאוגדו דהא רש\"י מצוה קאמר ולא חובה:","ומ\"ש ואם לא אגדו מאתמול או שהותר אגודו בי\"ט א\"א לאגדו בקשר גמור אלא אוגדו כאגודה של ירק וכו' שם גמ' הדס הגזול והיבש פסול ת\"ר היתר אגדו בי\"ט אוגדו כאגודה של ירק אמאי לענביה מיענב הא מני ר\"י הוא דאמר עניבה קשירה מעליא היא ופירש\"י דכריכה בעלמא יכרוך האגד סביב וידחוק ראשו בתוך הכרך כמו שאוגדין אגודת ירק ולא יקשור ב' הראשים כאחד כשאר קשרים דקשר של קיימא מאבות מלאכות הוא וזה של קיימא הוא שאינו חושש להתירו עולמית נראה מדבריו שהוא גורס כאגודה של ירק וכ\"נ שגורס הרא\"ש אבל מדברי הר\"ן נראה שהרי\"ף גורס באגודה בבי\"ת שהרי כתב לא אגיד ליה אלא באגודה של ירק משום דחזיא לאכילה ולאו מוקצה הוא ומאחר דאמרי' דהא דלא קתני דליענביה מענב היינו משום דרבי יהודה היא דאמר עניבה קשירה מעלייתא היא א\"כ לדידן דלא קי\"ל כרבי יהודה בהא אלא דעניבה לאו קשירה היא מותר לאגדו ע\"י עניבה וכ\"כ הרי\"ף והרא\"ש דאגיד ליה כאגודה של ירק א\"נ דעניב ליה מענב ונ\"ל דחוט או משיחה נמי לאו מוקצה הוא והא חזי לענוב מענב:","ויטול האגודה בידו הימנית שם אמר רבא לולב בימין ואתרוג בשמאל מ\"ט הני תלת מצות והאי חדא מצוה:","ומ\"ש ויהיו ראשיהם למעלה ועיקריהם למטה בפרק לולב וערבה (סוכה מה.) כל המצות אין יוצאין בהם אלא דרך גדילתן:","ומ\"ש ואתרוג בידו השמאלית בפ' לולב הגזול מימרא הזכרתיה בסמוך וכתב עליה הרא\"ש ואם הוא איטר יד ימין יקח הלולב בשמאל דימין דידיה הוא נראה מדבריו שאיטר יד ימינו יטול הלולב בימין דידיה שהוא שמאל כל אדם ואתרוג בשמאל דידיה שהוא ימין כל אדם דבתר ימין ושמאל דידיה אזלינן אבל מלשון ואף שכ' רבינו וגם מדכתב יטול האתרוג בשמאל כל אדם משמע בהיפך דאיטר נמי נוטל לולב בימין כל אדם שהוא שמאל דידיה ואתרוג בשמאל כל אדם שהוא ימין דידיה דבתר רוב ב\"א אזלינן ור\"י כתב בשם התוס' ובשם מהר\"מ אם הוא איטר כלומר שמשתמש תמיד בצד שמאלו נוטל הלולב בשמאלו שהוא ימין שלו ע\"כ ונראה דהיינו לומר דבתר ימין ושמאל דידיה אזלינן וכדמשמע לדברי הרא\"ש ז\"ל אח\"כ מצאתי שכתב העיטור אהא דת\"ר איטר מניח תפילין בימינו שהוא שמאלו מסתברא תפילין דאורייתא דוקא בימין אבל לולב דרבנן הוא ומשום חשיבותא איטר הוא ככל אדם ומניח בימינו שהיא לכל אדם ואי עביד איפכא לית לן בה דלא גרע מתפילין עכ\"ל והדבר מבואר שסתם רבינו דבריו כדברי בעל העיטור ומ\"ש דלולב דרבנן היינו לומר דנטילתו בימין הויא דרבנן משום דהני ג' מצות והאי חד מצוה: כתב הרוקח גידם שאין לו אלא יד אחת נוטל לולב והאתרוג בזרועו כמו (סנהדרין מה) גבי אין לו בוהן נותן על מקומו ודיו ויותר טוב ממה שיקח הלולב ואח\"כ אתרוג או אם אין לו אלא שמאל או איטר עכ\"ל:","\u0003וכשיטול הלולב בידו קודם שיטול האתרוג יברך על נטילת לולב כדי שיברך קודם לעשייתו וכו'\u0004 כל זה כתבו התוספות בפרק לולב הגזול (סוכה לט.) גבי כל המצות כולם מברך עליהם עובר לעשייתן וכ\"כ הרא\"ש שם בסוף הפרק וז\"ל צריך לדקדק מתי יברך אדם על הלולב אם יברך אחר שנטלו בידו הא אמרינן הכא מדאגבהיה נפיק ביה ובעינן שיהא מברך על כל המצות עובר לעשייתן והיה נראה שיברך עליו קודם שיטלנו בידו אבל לא מסתברא דהיאך יברך עליו בעוד שהוא מונח בכלי הא אמרינן בפרק הקומץ רבה (מנחות לה.) תפילין מאימתי מברך עליהם משעת הנחה עד שעת קשירה דכל זמן דאין המצות מזומנות בידו לעשותם לא מסתבר שיברך וטוב שיברך משיתחיל ליטול הלולב קודם שיטול האתרוג דהיינו עובר לעשייתן שמעכבין זה את זה אי נמי יהפוך אחד מהם עד שיברך כדאמרינן הכא שאינו יוצא אלא כדרך גדילתן אי נמי יכוין שלא לצאת עד אחר הברכה אע\"ג דאמרינן בר\"ה (כח:) דמצות אינן צריכות כונה הני מילי בסתם אבל במכוין שלא לצאת לא נפיק בעל כרחיה אי נמי משום דלא נגמר מצות הלולב עד אחר הנענוע ועוד כדקאמר בסוף פרקין אדם יוצא מביתו ולולבו בידו קורא שמע ומתפלל ולולבו בידו אע\"פ שכל אלו הדברים אינן מעכבין מ\"מ הואיל ויש בהם מצוה מן המובחר חשיב כעובר לעשייתן והר\"ן בסוף הפרק הנזכר כתב סברות אלו ומסקנת דבריו דאע\"ג דמדאגבהיה נפק ביה מ\"מ עדיין יש כאן שיורי מצוה שצריך לנענע הלכך שפיר מיקרי עובר לעשייתן שלא בא למעט אלא שאין גומרין את המצוה כולה קודם שיברך עליה:","ומ\"ש רבינו בשם הרמב\"ם שיברך קודם שיטלנו בידו נראה שהוא ממ\"ש בפ\"ז ז\"ל מצוה מן המובחר לאגוד לולב והדס וערבה ולעשות שלשתן אגודה אחת וכשהוא נוטלן לצאת בהם מברך תחלה על נטילת לולב הואיל וכולן סמוכים לו ואח\"כ נוטל האגודה הזאת בימינו:","ומ\"ש שאין נראה לר\"י הוא מהטעם שכתבתי בסמוך בשם הרא\"ש והיאך יברך עליו בשעה שהוא מונח בכלי: ודע שזה שכתב הרמב\"ם שיברך ע\"נ לולב לאו למימרא שיברך בלשון הזה שמאחר שכתב שהוא מברך עליו עובר לעשייתו צריך לברך בלמ\"ד ולא בא לומר אלא שיברך על הלולב ולא על שאר מינים ובענין נוסח הברכה סמך על מ\"ש בסוף ה' ברכות נטל את הלולב מברך על נטילת לולב שכיון שהגביהו יוצא ידי חובת לולב אבל אם ברך קודם שיטול מברך ליטול לולב כמו לישב בסוכה מכאן אתה למד שהמברך אחר שעשה מברך על העשייה ואע\"פ שכתב עוד בפרק הנזכר ובכל יום ויום מברך עליו אקב\"ו ע\"נ לולב מפני שהיא מצוה מדברי סופרים איכא למימר דהכא נמי סמך על מ\"ש בהל' ברכות בנוסח הברכה ולא בא אלא ללמדנו שאע\"פ שאינו חייב בלולב מן התורה מיום ראשון ואילך צריך לברך עליו אבל לא נחת לפרושי נוסח הברכה וא\"כ מי שעושה באחד מהדרכים שכתב רבינו היה ראוי שיברך ליטול כיון דאכתי לא נפק ביה והעולם אינם נוהגים לברך אלא ענט\"ל משום דכיון דאגבהיה נפק ביה אע\"ג דלא נפק ביה לגמרי מפני שעשה באחד מהדרכים הנזכר דע\"כ לא קאמר הרמב\"ם דיברך ליטול אלא כשמברך קודם שיטלנו בידו כלל: ומ\"ש רבינו שמברך שהחיינו בשעת נטילה ולא בשעת עשייה בפרק לולב וערבה (סוכה מו.) ת\"ר העושה לולב לעצמו אומר ברוך שהחיינו נטלו לצאת בו אומר אקב\"ו על נטילת לולב וכתב הרא\"ש האידנא לא נהוג לברך שהחיינו בשעת עשייה אלא בשעת נטילה כדאמרינן לקמן בשהחיינו דסוכה דרב כהנא מסדר להו אכסא דקידושא ה\"נ דלולב מברכין ליה בשעת נטילה: כתב הרשב\"א בתשובה דאף ע\"ג דקי\"ל לולב א\"צ אגד ויכול ליטלן כל אחד לעצמו אין מברכין אלא ברכה אחת על כולן דמצוה אחת היא ואין מברכין על כל חלק דמצוה ברכה אחת: כתב בא\"ח מעשה בה\"ר משולם שנטל לולב בי\"ט ראשון ובירך על נטילת לולב ושהחיינו ואח\"כ הסתכל בו ולא מצא בו ערבה והניחה בלולב וחזר ונטלו ונטל ג\"כ האתרוג ובירך על נטילת ערבה ושהחיינו משום ערבה ונהי שא\"צ ליטול אלא הערבה בלבד אלא מצוה מן המובחר בעי למעבד ליטול ד' מינים בבת אחת וכן מצינו מכתיבת ידי הראב\"ד ז\"ל עד כאן לשונו :","ולקיחה על ידי דבר אחר שמה לקיחה בפרק לולב הגזול (סוכה לז.) אמר רבה לא לינקוט איניש הושענא בסודרא דבעינן לקיחה תמה וליכא ורבא אמר לקיחה על ידי דבר אחר שמה לקיחה ופסקו הפוסקים כרבא ובסוף פרקא (מב.) אמר רבא שאם הוציא הלולב בכלי לא יצא ופריך והא רבא הוא דאמר לקיחה ע\"י ד\"א שמה לקיחה ומשני ה\"מ דרך כבוד אבל דרך ביזיון לא ופירש\"י דרך כבוד. כגון כורך ידיו בסודר כדאמרן לעיל ודרך ביזיון כגון בקערה וכתבו התוספות אהא דאמר רבא דבעינן לקיחה תמה וליכא הכא לא שייך למימר דלא ליהוי חציצה כדאמרינן לעיל דיש לומר דמיירי שעשה מן הסודר כמין בית יד ללולב ואין שייך כאן חציצה שכל הלולב חוץ מידו ואוחזו בית יד הבולט הנעשה מן הסודר ולא חשיב ליה רבה לקיחה תמה ורבא סבר שמה לקיחה עד כאן וזהו שכתב רבינו אפילו עשה בית יד ונתן בו הלולב ונטל שפיר דמי אפילו כל הלולב חוץ מידו אלא שיש לדקדק על לשון אפילו דנקט דמשמע לא מבעיא אם אין כל הלולב חוץ מידו דיצא אלא אפילו כל הלולב חוץ מידו יצא ולכאורה משמע מדברי התוס' דאיפכא הוי דבשכל הלולב חוץ מידו לית ביה משום חציצה וכשאין כל הלולב חוץ מידו לא יצא משום דהוי חציצה וי\"ל שסובר רבי' דהיינו דוקא לרבה אבל לרבא דאמר כל לנאותו אינו חוצץ לא הויא חציצה משום דסתם בית יד לנאותו הוא אבל קשה שהרי התוס' כתבו בפ' הוציאו לו (יומא נח.) ובפ' מקום שנהגו (פסחים נז.) דהא דאמר רבא לקיחה ע\"י ד\"א שמה לקיחה מיירי שכורך סודר סביב הלולב ומאריך בו ועושה מן הסודר כמו בית יד אבל היכא דכריך ידיה בסודר ותופס הלולב לא שמה לקיחה ע\"כ וכתב המרדכי דבריהם פ' לולב הגזול וכ\"כ ר\"י ולפיכך צריך לומר דגבי לקיחה בשכל הלולב חוץ מידו גרע טפי ומשום הכי קאמר דאפ\"ה שמה לקיחה וכשהלולב תוך ידו אלא שכרך סודר על ידו או על הלולב אע\"ג דלית ביה משום לקיחה ע\"י דבר אחר בק\"ו מבשכל הלולב חוץ מידו מ\"מ מיפסיל מטעם חציצה אם אינו לנאותה וכבר נתבאר זה בדבריו לעיר בסמוך שכתב וכיון שאין חובה לאגדו אפילו אגדו במין אחר שפיר דמי ומשום חציצה נמי ליכא אע\"פ שהקשר מפסיק בין ידו ללולב דכיון שהוא לנאותו אינו חוצץ דמשמע בהדיא דאם אינו לנאותו חוצץ: ודע שכתבו התוס' עוד ולולב שהוציא בכלי בס\"פ לא כשאוחזו כדופני הכלי אלא מניח ידו תחת שוליו או שאוחז בבית יד של כלי ע\"כ וה\"פ לא באוחז בדופני הכלי מיירי דא\"כ הוו ממעטי ליה בגמרא משום חציצה אלא במניח ידו תחת שוליו או אוחז בבית יד של כלי מיירי דליכא משום חציצה אלא משום דלא הוי לקיחה תמה אפילו לרבא משום דדרך ביזיון הוא והלכך כל בכלי בין אוחז בדופני הכלי בין מניח ידו תחת שוליו לא יצא אוחז בדופני הכלי אף משום חציצה ומניח ידו תחת שוליו משום לקיחה תמה ומפני כך סתם רבינו לומר שכל שנטלו בכלי לא יצא ולא חילק בין אוחז בדופני הכלי למניח ידו תחת שוליו והר\"ן כתב אהא דאמר רבא לקיחה ע\"י דבר אחר שמה לקיחה וא\"ת וכיון דלא הוי לנאותו ליהוי חציצה יש לומר דאנן לית לן קרא לפסול חציצה בלולב ומאי דחיישינן ביה היינו משום דלא הוי לקיחה תמה ומסקינן לנאותו בטל לגבי לולב והרי הוא כאילו נוטל בו ממש וכל שכן טפל לידו בטל לגבי ידו והרי הוא כאילו נוגע ממש ידו בלולב לאפוקי כל שאינו לנאותו ולא טפל לידו כגון שכרך הסודר על הלולב או שנטלו בכלי שאינו דרך כבוד כדאמרי' לקמן דמפסיל משום דלא הוי לקיחה תמה והויא כחציצה אבל לאו משום חציצה ממש אתינן עלה דלא פסלינן משום חציצה אלא היכא דאיכא קרא כטבילה ותפילין עכ\"ל ומצאתי כתוב בשם ספר אגודה בפרק מקום שנהגו שכל דבר חוצץ בין הלולב ובין היד ולכן מסירין ציציות ותפילין מן היד ונשים טבעותיהם אבל נראה לי דמשום הכי א\"צ להסירן דדוקא היכא דכרך כוליה ידיה :","\u0003וינענע בשעה שמברך וכן ינענע בשעת קריאת ההלל וכו'\u0004 בפרק לולב הגזול (סוכה לז.) תנן והיכן מנענעים בהודו לה' תחלה וסוף אף באנא ה' הושיעה נא כדברי ב\"ה ב\"ש אומרים אף באנא ה' הצליחה נא וידוע דהלכה כב\"ה וכתבו התוס' והרא\"ש דבשעת ברכה לא מצינו שצריך לנענע בתחלת הנטילה אלא מדאמרי' בסוף פירקין קטן היודע לנענע חייב בלולב משמע שמנענע בתחלת הנטילה אע\"פ שאינו יודע לקרות את ההלל ועוד מדתניא בס\"פ תפלת השחר השכים לצאת לדרך מביאין לו שופר ותוקע לולב ומנענע אלמא בשעת נטילה בעי נענוע וכתב הרא\"ש שראבי\"ה הביא ראיה לזה מן הירושלמי וזהו שכתב רבינו שינענע בשעה שמברך וכ\"כ הר\"ן ג\"כ שמנענע בשעת נטילה וכן נהגו העולם והא דתנן בהודו לה' תחלה וסוף פירש\"י הודו שבתחלת הפסוק והודו שבסוף הפסוק בסוף ההלל דמהודו ועד סוף ההלל חדא פרק הוא ממנין הפרשיות של תהילים וי\"מ תחלת הפסוק וסוף הפסוק ולא מסתבר לנענע בפסוק א' ב\"פ הא דמנענעים באנא ה' הושיעה נא אף ע\"פ שאינה תחלת הפסוק ולא סוף הפסוק היינו ע\"פ המקרא דכתיב אז ירננו עצי היער וגו' וכתיב בתריה הודו לה' כי טוב וכתיב נמי בתריה ואמרו הושיענו אלהי ישענו ואיתא במדרש לפי שבר\"ה באין לדין ישראל ועו\"ג ואין יודעין מי יצא זכאי ומי יצא חייב נתן הקב\"ה מצוה זו לישראל שיהיו שמחים בלולביהם כאדם היוצא לפני השופט זכאי שהוא שמח והיינו דכתיב ירננו עצי היער כלומר ירננו בעצי היער כאשר יצאו מלפני ה' זכאין כשבא לשפוט את הארץ ובמה ירננו בהודו ובהושיעה נא ועכשיו שנהגו שש\"ץ אומר יאמר נא והצבור עונין הודו וכן ביאמרו נא בית אהרן וכן ביאמרו נא יראי ה' הצבור מנענעין על כל הודו והודו שיאמרו ע\"כ ל' הרא\"ש וכן הם דברי רבינו שכתב וכן מנענע בשעת קריאת ההלל בהודו בכל פעם שמחזירין אותו הקהל ונראה מדבריהם שש\"צ לא ינענע בשעה שאומר יאמר נא ויאמרו נא והתוס' כתבו שי\"מ שאף ש\"צ מנענע אגב צבורא שעונין בכל פעם ופעם הודו ומנענעין מנענע נמי ש\"צ ביאמר נא ויאמרו נא והר\"ן כתב שכל זה אינו מחוור שכיון שמה שעונין הצבור הודו אינו אלא כדי לצאת מיאמר נא ויאמרו נא כשם שיאמר נא ויאמרו נא א\"צ נענוע כך עניית הודו אינה צריכה נענוע ולפיכך אין מנענעין בהודו לה' שבתחלה אלא פעם אחת אבל בהודו לה' שבסוף שכופלין אותו ש\"צ והצבור מנענעין בו ע\"כ פעם ופעם וכן באנא ה' הושיעה נא וכן נהגו :","\u0003והניענוע הוא שמוליך ידו מכנגדו להלאה וינענע שם ג\"פ בהולכה וג\"פ בהובאה וכו'\u0004 שם תנן התם שתי הלחם ושני כבשי עצרת כיצד הוא עושה מניח ב' הלחם ע\"ג ב' הכבשים ומניח ידו תחתיהם ומניף מוליך ומביא מעלה ומוריד שנא' אשר הונף ואשר הורם אר\"י מוליך ומביא למי שד' רוחות שלו מעלה ומוריד למי שהשמים והארץ שלו במערבא מתנו הכי מוליך ומביא כדי לעצור רוחות רעות מעלה ומוריד כדי לעצור טללים רעים אמר רבא וכן ללולב פירש\"י וכן ללולב. מוליך ומביא מעל' ומוריד וכתב הרא\"ש איכא מאן דאמר צריך לנענע ג\"פ בהולכה ובהובאה חוץ ממוליך ומביא מעלה ומוריד וגמיר לה מגמרא דבני מערבא דגרסינן התם תנא צריך לנענע ג\"פ על כל דבר ודבר ר' זירא בעי הכין חד והכין חד א\"ד הכין והכין חד כלומר ההולכה אחד וההובאה אחד א\"ד ההולכה וההובאה שניהם אחד אלמא נענוע זה חוץ ממוליך ומביא מעלה ומוריד הוא ופירש\"י כן על כל דבר ודבר כלומר לכל רוח שמוליך הלולב צריך לנענע ג\"פ חוץ ממוליך ומביא וכו' כלומר אין מספיק לו ההולכה וההובאה עד שינענעו ג\"פ בכל הולכה והובאה והיה ראוי לפרש שיתפוס ידו במקום א' וינענע נענוע כל דהוא ג\"פ לולא בעיית ר' זירא דבעי הכין וכו' משמע דלכל צד בעי להוליך ולהביא ג\"פ ומיבעי ליה אי הולכה א' והובאה א' או ההולכה והובאה שתיהן אחד וכתבו התוס' וכיון דלא איפשיטא עבדינן לחומרא וכ\"כ ר\"ח בשם רב האי ואף ע\"ג דנענוע זה מדרבנן משום חביבות המצוה אמרו כן נמצא שצריך ג' הולכות וג' הובאות לכל צד וצד שהם שלשים וששה בין הכל ובעל העיטור כתב כיון דנענוע דרבנן הוא לקולא אמרינן לחומרא לא אמרינן עכ\"ל ורבינו סתם דבריו כדברי הרא\"ש וז\"ש והנענוע הוא שמוליך מכנגדו להלאה וינענע שם ג\"פ בהולכה וג\"פ בהובאה ואח\"כ מטה ידו לצד צפון ועושה כן ג\"פ וכן לצד דרום וכן לצד מערב ומעלה ידו למעלה ועושה כן ג\"פ ומורידה לצד מטה ועושה כן ג\"פ סך הכל ל\"ו פעמים ולפי גירסא זו דבריו פשוטים וא\"צ ביאור אבל יש ספרים דגרסי הנענוע והוא שמוליך ידו מכנגדו להלאה וינענע שם ג\"פ בהולכה וג\"פ בהובאה ומביא אליו ועושה כן ג\"פ ואח\"כ מטה ידו לצד צפון ועושה כן ג\"פ וכן לצד דרום ג\"פ ומעלה ידו למעלה ושמעתי שזאת היתה גירסת חכמי ספרד ושהיו מדקדקין מדכתב ומביאה אליו ועושה כן ג\"פ ולא כתב ומטה ידו לצד מערב כמ\"ש גבי צפון אלמא שהוא סובר שא\"צ להטות את ראש הלולב לצד מערב כדרך שהוא מטה אותו לשאר הרוחות אלא כשהוא מביאה אליו מן המזרח מוליך ומביא באחורי הלולב כלאחר ידו ג\"פ למערב ואח\"כ מטה ראש הלולב לצפון ואם הדבר כן צריך טעם למה נשתנה רוח מערב משאר רוחות ואפשר שהטעם מפני שבשאר הרוחות שהם לפניו או לצדדים ע\"כ צריך להטות ראש הלולב לרוח שהוא מוליך לו אבל ברוח מערב שהוא לאחוריו כשמביא ידו מן המזרח ומוליך אחורי ידו כלפי מערב מינכר מלתא שפיר שלרוח מערב הוא מוליך ולפיכך אם רצה שלא להטות ראש הלולב לצד מערב אלא לנענע בענין זה רשאי הוא ואף לפי גירסא זו אפשר לפרש שמ\"ש ומביאה אליו ועושה כן ג\"פ היינו לומר שמטה ראש הלולב לצד מערב כדרך שהטה לרוח שכנגדו ואפשר עוד לומר שא\"צ להטות ראש הלולב לשום רוח אלא הלולב דרך גדילתו מוליכו לרוח שכנגדו ומנענעו ומביאו לרוח שכנגדו ומנענע וכן לשאר רוחות דשתי הלחם וכבשי עצרת כה\"ג הוה מוליכם ומביאם והדבר ידוע שלהוליך היד לרוח שכנגדו או להביאה אליו א\"צ לנטות ימין ושמאל משא\"כ כשמוליכה לצפון או לדרום ומפני כך כתב מטה ידו לצד צפון וכן לצד דרום ובשאר רוחות לא הזכיר לשון הטייה אבל דרך העולם להטות ראש הלולב לכל רוח ואף כשהוא מוריד הלולב מטה ראשו כלפי מטה ואבא מורי ז\"ל היה אומר שאין להטות ראשו כלפי מטה משום דהוי שלא כדרך גדילתו וכיון דכשנטלו שלא כדרך גדילתו לא יצא כל נענועיו נמי צריך לעשותן כדרך גדילתו : כתוב בתשובת מהרי\"ל בלולב נ\"ל להקיף דרך ימין כשמנענעו למזרח דרום מערב צפון ודלא כאיכא דמפכי לה ולא ידעי טעמא ע\"כ : וכתב הר\"ן שיש מן הראשונים שאמרו שבניענועו של לולב אינו צריך אלא מוליך ומביא מעלה ומוריד כדמשמע פשטא דמימרא דרבא דאמר וכן ללולב וא\"צ טירוף אחר אבל אין זה נכון שאם כן למה הצריכו שיהא הלולב יוצא על ההדס טפח כדי לנענע בו והלא בכל שהוא בין גדול בין קטן ראוי להוליכו ולהביאו אלא ודאי לפי שצריך לטרוף הלולב ולכסכסו בעצמו הצריכו בו טפח עודף נמי לנענע בו וכן דעת הרמב\"ם שכתב בפרק ז' שיש לו לטרוף הלולב ג\"פ כשמוליך וכן כשמביא וכן כשמעלה וכן כשמוריד ונראה שהוא ז\"ל היה מפרש הירושלמי דה\"ק צריך לנענע על כל דבר ודבר היינו על כל תנועה של הולכה והובאה והעלאה והורדה ובתר הכי מיבעי ליה אם מוליך ומביא חשוב חד ואין לנענע בשניהן אלא ג' תנועות קטנות וכן במעלה ומוריד או כ\"א מהם חשוב אחד ויש לו לנענע ג' תנועות קטנות בכל א' וא' מהם וכיון דלא אפשיטא עבדינן לחומרא ומנענעו ג\"פ בכל דבר ודבר זו היא שטת הרי\"ף ואחרים פירשו הירושלמי על דרך אחרת לפי שטה זו דמצרכת לטרוף הלולב ג\"פ חוץ ממעלה ומוריד מוליך ומביא ואומרים דכי אמרינן דצריך לנענע על כל דבר ודבר היינו על כל מקומות הללו ועל שעת הנטילה שמנענעין בהן שצריך לטרוף את הלולב ג\"פ בתנועות קטנות חוץ ממוליך ומביא מעלה ומוריד ואח\"כ שאלו באותן תנועות קטנות אם ההולכה הקטנה חשיבא חד וההובאה הקטנה חשיבא חד וסגי במוליך ומביא ומוליך בתנועות קטנות או דלמא ההולכה וההובאה לא חשיבא אלא חד וצריך ג' זוגות של תנועות קטנות מהולכה והובאה וכיון דלא איפשיטא נקטינן לחומרא ונמצא על זה סדר נטילת לולב מוליך ומביא מעלה ומוריד על כל דבר ואח\"כ יטרוף את הלולב שלשה זוגות של תנועות קטנות וכן דעת הרמב\"ן ז\"ל עכ\"ל ושטה זו האחרונה היא שטת הרא\"ש ז\"ל: וכתב הרא\"ש בשם הראבי\"ה עיקר הנענוע נראה בעיני שהיא בשעת ברכה אבל נענוע דמתניתין בהודו ובאנא ה' הושיעה נא הוא נענוע בעלמא ע\"כ אבל מדברי הר\"ן שכתבתי יתבאר לך דלא שאני לן בין ניענוע דמתניתין לנענוע דבשעת ברכה בכולם צריך לנענע בענין אחד וגם המרדכי כתב על דברי ראבי\"ה אמנם באלפסי ובר\"ן לא משמע הכי וכן נהגו העולם ונראה שמפני כך השמיט רבינו דברי ראבי\"ה משום דסוגיין דעלמא דלא כוותיה:","\u0003וכתב עוד מנהג אבותינו מוליך ומביא מעלה ומוריד בלבד וכו'\u0004 הרא\"ש בפרק לולב הגזול הביא דבריו וכתב עליהם והעולם לא נהגו כן וכו' עד יש לו ו' קצוות:","\u0003כתב ב\"ה הולכה והובאה הוא הנענוע וא\"צ נענוע שדרה ועלין וכ\"כ הגאון ז\"ל וכו'\u0004 כבר כתבתי שהר\"ן הביא סברא זו וכתב שאינה נכונה אלא צריך לטרוף הלולב ולכסכסו וכן דעת הרמב\"ם ז\"ל ונראה שכך היה סברת הרא\"ש שהרי מצריך לנענע ג' זוגות של תנועות קטנות על כל הולכה והובאה וא\"כ יש לתמוה האיך סתם רבינו כהרא\"ש ואח\"כ כתב דברי ב\"ה כאילו אין ביניהם מחלוקת ואפשר שרבינו סובר דלא פליגי אהדדי דנהי דכתב הרא\"ש דצריך לנענע ג\"פ על כל הולכה והובאה היינו שעושה ג' הולכות וג' הובאות קטנות דכל הולכה והובאה בלא נענע דשדרה ועלין. אם צריך לחבר האתרוג ללולב בשעת נענוע לנענע שניהם יחד או אם אינו מנענע אלא אגודת הלולב לבד ויד שמאלו שהאתרוג בה תהא עומדת במקומה בלי נענוע דבר זה לא נתבאר בגמרא ולא בדברי הפוסקים אבל ה\"ר מנחם מרקנ\"ט כתב בפרשת אמור צריך לסמוך האתרוג עם שאר המינים שלא להפריד מן הבניין וסוד זה נגלה אלי בחלום בליל י\"ט הא' של חג הסוכות בהתאכסן אצלי חסיד א' אשכנזי שמו הרב ר' יצחק ראיתי בחלום שהיה כותב השם יו\"ד ה\"א והיה מרחיק הה\"א אחרונה מן הג' האותיות ראשונות ואמרת לו מה זה עשית והשיב כך נוהגים במקומינו ואני מחיתי בו וכתבתי אותו שלם ואשתומם על המראה ואין מבין למחר בעת נטילת לולב ראיתי שלא היה מנענע רק הלולב ומיניו בלא אתרוג והבנתי פתרון חלומי וחזר בו ורז\"ל רמזו סוד זה בויקרא רבה אמר שם פרי עץ הדר זה הקב\"ה שנאמר הוד והדר לפניו כפות תמרים זה הקב\"ה שנאמר צדיק כתמר יפרח וענף עץ עבות זה הקב\"ה שנאמר והוא עומד בין ההדסים וערבי נחל זה הקב\"ה שנאמר סולו לרוכב בערבות תראה שכל המינים האלו רומזים בשי\"ת עכ\"ל:","ואלו הארבעה מינים מעכבים זה את זה שאם חסר לו אחד מהם לא יברך על הנמצאים בידו אבל אם יש לו כולם אפילו לא נטלן ביחד אלא נטלן זה אחר זה יצא ובלבד שיהיו כולן לפניו ויטול הלולב תחלה בפרק הקומץ רבה (מנחות לז.) תנן ד' מינין שבלולב מעכבין זה את זה ובגמרא שם א\"ר חנן בר רבא לא שאנו אלא שאין לו אבל יש לו אין מעכבין וכתבו הרי\"ף פרק לולב הגזול וסיים בה ואע\"ג דנטל כל חד וחד לחודיה נפיק י\"ח דקי\"ל לולב א\"צ אגד וכתב שם הרא\"ש שכ\"כ בה\"ג לא נהירא לר\"ת דכיון דכולם מצוה אחד לא מסתבר שיועילו בזה אחר זה והגיה בספרים לא שנו דמעכבין זה את זה משום תמה אלא שאין לו אבל יש לו תמה הוא אע\"פ שלא חברם באגודה אחת כרבנן דלא דרשינן לקיחה לקיחה ולא נהירא לי גירסתו ופירושו אלא אתא לאשמעינן דכיון שמונחין כל ארבעתן לפניו שמברך ונוטלן זה אחר זה ומסתבר שמגביה הלולב תחלה שמזכירין אותו בברכה עכ\"ל. וגם הרמב\"ם כתב בפ\"ז שאם נטלן אחד אחד יצא וכדברי הרי\"ף והרא\"ש וכ\"נ מדברי רש\"י בפרק הקומץ גם הר\"ן כתב שלא נראה לו דברי ר\"ת אלא אפילו נטל כל חד וחד לחודיה נפיק י\"ח וכתב עוד ובשם הרמב\"ן מקילין עוד ואומרים שאע\"פ שלא היו ברשותו ביחד כל שנטל כולם יצא וכי אמרינן דאין לו מעכבין היינו לומר שכל שלא נטל את כולן אפי' באחד מהם לא יצא אבל כל שבאו לידו אפילו בזה אחר זה יצא ואע\"פ כן אין ראוי לברך על הלולב אא\"כ הוא יודע בבירור שיבואו לידו כולן שאפי' שאין מברכין אלא על הלולב אפ\"ה כיון דאמרינן שאם לא יבאו כולן לידו לא יצא שמא לא יבאו לידו והו\"ל ברכה לבטלה עכ\"ל והרמב\"ם חולק בזה שכתב בפרק הנזכר ואם לא אגדן ונטלן אחד אחד יצא והוא שיהיו ארבעתם מצויין אצלו אבל אם לא היה לו אלא מין אחד או שחסרו מין אחד לא יטול עד שימצא השאר וז\"ל א\"ח כ' הראב\"ד אם נטלן אחד אחד מברך על כל אחד לעצמו מאחר שאינן אגודים ביחד שתהא ברכת הלולב פוטרתן עכ\"ל. ולענין מעשה נ\"ל שיברך על הלולב לבד וכדברי הרמב\"ם דבסמוך וכ' עוד א\"ח אם נטלן שניהם בידו אחת כתב הירושלמי דלא יצא כדאמרינן בגמ' דלא אגדינן אתרוג עמהם משום דכתיב כפות ולא וכפות: וכתב הרא\"ש בשם הראב\"ד דכשם שאמרו ביבשה שנוטלין אותם לזכרון בעלמא כדי שלא תשתכח תורת לולב ה\"נ במקום שיש לולב ואין לו אתרוג אע\"פ שמעכבין זה את זה ואין מברכין על הלולב בלא אתרוג אפ\"ה מצוה ליטול את הלולב לבדו בלא אתרוג לזכרון בעלמא כדי שלא תשתכח תורת לולב ולפי שדברים אלו כתבם הראב\"ד לפי סברתו שסובר שאין מברכין על לולב יבש אפילו בשעת הדחק אלא שנוטלין אותן בידים כדי שלא תשתכח מהם תורת לולב ולא נראו דבריו בעיני הרא\"ש אלא דבשעת הדחק מברכין עליו וא\"כ אין ראיה לומר דכשחסר מין אחד יטול שאר המינים מפני כך השמיט רבינו דין זה ומהר\"י קולן כתב בשורש מ\"א בשם בעל ההשלמה שאם אין לו אחד מהמינים יביא השאר ויברך עליו והוא ז\"ל תמה עליו ודעתו שלא יברך אבל יטלם כדי שלא תשתכח תורת לולב: כתב בהג\"א דהא דד' מינין מעכבין זה את זה דוקא בי\"ט ראשון אבל ביום טוב שני אין מעכב ואפילו אין לו אתרוג יטול שאר מינים ויברך דהא דרשינן לקיחה תמה למעוטי חסר ודרשינן נמי לד' מינים שמעכבין זה את זה הלכך כי היכי דלקיחה תמה פוסלת אתרוג חסר דוקא בי\"ט ראשון ה\"נ לקיחה תמה המעכב בד' מינים דוקא בי\"ט ראשון וכן הלכה מא\"ז עכ\"ל וכ\"כ המרדכי בשם ר\"ת מאורליינ\"ש וכתב ואע\"פ שראבי\"ה חולק היא נראה לו לעשות מעשה כדברי ר\"ת מאורלייניש ואין דעת הפוסקים כן שהרי סתמו דבריהם ולא חילקו בדבר זה בין י\"ט שני לראשון ומצאתי בתשובת מהרי\"ל דמי שאין לו אתרוג יטול שאר המינין ולא יברך אע\"ג דא\"ז מסיק דיברך דולקחתם דמיניה דרשינן לד' מינים שמעכבין זה את זה בראשון דוקא הוא משום דהרא\"ש סותר אותה סברא דא\"כ האי דילפינן מלכם שתהא לקיחה לכל אחד ואחד שמא נמי דוקא בראשון אלא מסיק הרא\"ש דמלתא דתליא בעיקר המצוה כגון לכל אחד ואחד וכן דבעינן ד' מינים התקינו רבנן כולי יומי זכר למקדש הלכך הואיל ופלוגתא דרבוותא אמינא מספיקא דאין לברך ואפילו בי\"ט שני אמינא ליטול הג' מינים אע\"ג דהרא\"ש כתב כל דפסול בי\"ט ראשון פסול לדידן בשני וא\"כ כיון דמעכב בי\"ט ראשון ניחוש בי\"ט שני לזילותא כמו בשמיני עצרת דלא שקילנא לולב משום זלזול אע\"פ דספק ז' הוא אפ\"ה אמינא ליטלו כמ\"ש רבותינו בשאול וחסר דכשר בי\"ט שני וזלזול לא שייך הכא דדוקא בשמיני עצרת דאם ח' הוא הוי לולב מוקצה אבל בי\"ט שני אפילו אם הוי יום ראשון מ\"מ לאו מוקצה הוא דמצות היום בד' מינים ונהי דאין לו כולם מ\"מ חזו למי שיש לו אתרוג ע\"כ:","חסר לו אחד מן המינים לא יקח מין אחר במקומו ברייתא ר\"פ לולב הגזול ארבע מינים שבלולב כשם שאין פוחתין מהן כך אין מוסיפין עליהן לא מצא אתרוג לא יביא פריש ולא רימון ולא דבר אחר ובגמרא שם אמר מר כשם שאין פוחתין מהן כך אין מוסיפין עליהם פשיטא מהו דתימא הואיל וא\"ר יהודה לולב צריך אגד ואי מייתי מינא אחרינא האי לחודיה קאי והאי לחודיה קאי קמ\"ל אמר מר לא מצא אתרוג לא יביא לא רימון ולא פריש ולא ד\"א פשיטא מהו דתימא ליתי כי היכי דלא תשתכח תורת אתרוג קמ\"ל זימנין דנפיק חורבא מיניה ואתי למיסרך ופירש רש\"י אי מייתי מינא אחרינא ולא אגיד ליה בהדיה וכתבו התוס' דלא דמי לאגדו שלא במינו דשרי כמו שכתב רבינו בסמוך דכשאגדו בו אין זה כמוסיף משום דאין זה דרך גדילתו והכא אפילו לרבי יהודה קאמר דמייתי מינא אחרינא ונקט ליה כדרך גדילתו דאפילו חוץ לאגד חשיב כמוסיף וכ\"ש לרבנן ע\"כ וקשה לי בלשון רבינו שכתב לא יפחות מהן דהא כבר כתב שארבע מינים אלו מעכבים זה את זה והא תו למה לי ליכתוב ולא יפחות מהם וגם הברייתא לא אתא לאשמעינן דלא יפחות מהן דהא ממתניתין שמעינן לה אלא לאשמעינן דאין מוסיפין עליהם אתא והיינו דקתני כשם שאין פוחתין מהם כך אין מוסיפין עליהם ולא קתני לא יפחות מהם ולא יוסיף עליהם ולכן נראה לי דלשון רבינו בזה אינו מדוקדק:","ומ\"ש דכשמוסיף מין אחר אם יאחזנו בידו עמהם שלא לשם מצות לולב אינו עובר עליו קשה דהא אסיקנא בס\"פ ראוהו (כח.) דלעבור בזמנו לא בעי כונה :","\u0003אבל מאותם המינים יכול להוסיף עליהם ובהדס שוטה שאינו עבות נחלקו בו הגאונים וכו'\u0004 בפרק לולב הגזול (סוכה לד.) אהא דתנן רבי ישמעאל אומר ג' הדסים וב' ערבות לולב אחד ואתרוג אחד כתב הרא\"ש וכל הני שיעורי שלא לפחות מהם אבל להוסיף יכול ואין כאן משום בל תוסיף אפילו למ\"ד לולב צריך אגד אא\"כ מוסיף מין אחר כדמוכח בסוף פרק ראוהו ב\"ד והרמב\"ם כתב אם רצה להוסיף בהדס כדי שתהיה אגודה גדולה מוסיף ומנויי מצוה היא אבל שאר המינים אין מוסיפין על מניינם ואין גורעין מהם ואם הוסיף או גרע פסול ואיפכא מסתברא דבהדס כתיב ענף עץ עבות ובערבות כתיב ערבי ומיעוט ערבי שתים אבל כל מה שמוסיף בכלל ערבי הוא וחכמי פרובינצא הקשו עליו וחזר בו והכשיר הכל ויראה שכן באתרוג ולולב אין בהם משום בל תוסיף אף על גב דכתיב כפות ופרי עץ כיון שאינו מוסיף מין אחר והא דאמרינן פרי אחד אמר רחמנא ולא שנים וג' (כי היכי דתנכר לקיחה פרי אמר רחמנא ולא שנים וג') היינו לענין חובת לקיחה כלומר אם באת להצריך שנים וג' כי היכי דתנכר לקיחה פרי אחד אמר רחמנא ולא ב' ובהדס שאינו עבות נחלקו הגאונים אם הוא מין הדס ויכול להוסיף ממנו לנוי בה\"ג כתב דהדס שוטה אפילו אסא אחריני פסול ורב נטרונאי כתב אם יכול לעשות כולו מן העבות מצוה המובחר ואם אינו מוצא אלא ג' הדסים עבות ממלא אותו הדס שוטה ושפיר מי וכ\"כ רב פלטוי מן המקרא היה משמע דשני מינין הן כדכתיב בעזרא ועלי הדס ועלי עץ עבות ואמנם אנו רואין שגדלים בערוגה אחת ושוין במראה ובקומה זה יוצאין עליו עבות וזה אין יוצאין עליו עבות ואפילו שפסלו הכתוב למצות הדס מכל מקום מין אחד הוא ואין כאן בל תוסיף מידי דהוה אסיב ועקרא דדיקלא דאמר לעיל דאוגדין בו את הלולב לר\"י אבל לא במין אחר משום דסבר לולב צריך אגד ואי מייתי מינא אחרינא הו\"ל חמשה מינים אבל סיב ועיקרא דדיקלא אין בו משום בל תוסיף משום דמינא דדיקלא הוא אע\"פ שאינו כשר ללולב ומה שחלקו הכתוב לשנים לאו משום דשני מינים נינהו אלא אמר להן עזרא שידקדקו ויחפשו להביא עבות למצות לולב ומעלי הדס יביאו הרבה לעשות סוכה עכ\"ל הרא\"ש ז\"ל ומדברי הראב\"ד בהשגות ג\"כ נראה שסובר שאפילו באתרוג ולולב ליכא משום בל תוסיף וה\"ה הקשה עליו מסוגיא דפרק המוצא תפילין דאמרינן התם בהדיא שהמניח ב' תפילין בראש עובר משום בל תוסיף ומה בין זה לב' לולבין והוא ז\"ל כתב שמה שנראה לו לתרץ הסוגיות הוא שאם נטל ב' לולבין הוסיף ועבר והוא שנטלן כאחת דומיא דתפילין אבל אם לקח עמו מין אחר לדידן דקיימא לן לולב אין צריך אגד לא עבר משום בל תוסיף דהאי לחודיה קאי והאי לחודיה קאי כמוזכר בפרק הנחנקין (סנהדרין פח:) ומ\"מ אין מוסיפין לכתחלה כמוזכר פרק לולב הגזול כשם שאין פוחתין מהם כך אין מוסיפין עליהם והעמידוה שם אפילו למ\"ד לולב אין צריך אגד והוא בלכתחלה וה\"נ מדברי רבינו שכתב למעלה ואין מוסיפין עליהם ולא כתב ואם הוסיף פסול וכאן כתב ואם הוסיף או גרע פסול מ\"מ כל לנוי מוסיף הוא בין במינו בין מין אחר ורשאי לאגדו בכל מה שירצה ולזה הותר רבוי ההדס בין עבות בין שוטה וכן היה מן הגאונים שהיה מתיר תוספת הערבה דומה להדס וכבר השיב רבינו תשובה שכיון שלא מצינו בתלמוד היתר תוספ' אלא בהדס אין להוסיף במין אחר עכ\"ל ה\"ה ונראה מדבריו שלא באה לידו תשובת הרמב\"ם לחכמי פרובינצא שהזכיר הרא\"ש ובספר ר\"י כתב שכתב הרמ\"ה בתשובה אם יכול אדם להוסיף על ב' בדי ערבה או לא כבר נשאלתי מאתכם פעם אחרת והייתי מורה בדבר לאיסור כדברי הרמב\"ם ואח\"כ העיד לי אדם גדול מחכמי פרובינצא שהוא עמד על תשובת הרמב\"ם שחזר בו בסוף ימיו מדבר זה והורה בדבר להכשיר וכן הדעת נוטה להכשיר מ\"ט ערבי נחל כתיב ומשמע שנים ואפילו מאה כדדרשינן מכות (ח:) גבי עדים והעלה בסוף הלכך גבי לולב ואתרוג כיון דחד חד משמע אסור לאוסופי ואי הוסיף כיון דקי\"ל לולב א\"צ אגד אפילו אגדו ביחד האי לחודיה קאי והאי לחודיה נמצא שלא פסול וגבי הדס וערבה אפילו לכתחלה נמי ע\"כ:","כתב ר\"ע נהגו במקומינו במתיבתא מכמה דורות שלא לפחות מששים ושמנה ערבות זה לשון הג\"א יש נוהגין שעושין פארות ערבה כמנין לולב שזהו ס\"ח ושלשה כנגד אתרוג ולולב והדס הרי ע\"א כנגד סנהדרי גדולה וכן מנהג בישיבה ובהגהת מיימוני כתב שכן נוהגים באשכנז וכן כתב המרדכי בפרק לולב אנן נהגינן ליטול ערבה כמנין לולב ג' קשרים כנגד ג' אבות סך הכל כמנין סנהדרין :"],["\u0003מצות ד' מינין שיטול כל אחד ואחד מישראל לולב אחד כו'\u0004 ר\"פ לולב וערבה ולקחת' שתהא לקיחה ביד כל אחד ואחד ופירשו התו' בר\"פ לולב הגזול דתשמע ליה מדלא כתיב ולקחת לשון יחיד דהוה משמע דאחד נוטל בשביל כולם וכתיב ולקחתם שתהא לקיחה לכל אחד ואחד ומ\"ש לולב א' וב' ערבות וכו' משנה בפ' לולב הגזול ר' ישמעאל אומר ג' הדסי' וב' ערבות לולב אחד ואתרוג אחד אפי' ב' קטומים וא' שאינו קטום ר\"ט אומר אפילו שלשתן קטומים ר\"ע אומר כשם שלולב א' ואתרוג אחד כך ערבה אחד והדס אחד ומוכח בגמרא דר\"ע חד ולא קטים קאמר ואמרינן נמי דחזר בו ר' ישמעאל וסובר דסגי בחד ולא קטים כר\"ע ותו אמרי' א\"ר יהודא א\"ר שמואל הלכה כר\"ט ומשמע דלגמרי פסק כר\"ט בין לחומרא דבעינן שלשה ובין לקולא דמכשיר בשלשתן קטומין אבל הרמב\"ן פוסק כר\"ע וס\"ל דלא איפסיק' הילכתא כר\"ט אלא במאי דמכשיר בג' קטומים אבל ודאי הילכתא נמי כר\"ע דמכשיר בחד ולא קטים כדמוכח בגמרא דקאמר ולידרוש להו כר\"ע דמיקל טפי וכ\"כ במרדכי בשם ראבי\"ה וראב\"ן אבל דעת שאר כל המחברים כדברי רבינו דבעינן שלשה בדוקא ועיין במ\"ש הר\"ן וה\"ה ע\"ז ומ\"ש בדין קטימת ראשי הדס וערבה נתבאר למעלה: ויעשה וכו' עד מצוה לאגדו משום נוי הכי אסיקנא אליבא דרבנן דהלכה כותייהו לגבי ר\"י בפ\"ק דסוכה ופ' לולב הגזול:","ומ\"ש וכיון שאין חובה לאגדו אפי' אגדו במין אחר שפיר דמי כלומר ולית ביה משום בל תוסיף כיון דאין חוב' לאגדו האי לחודי' קאי והאי לחודי' קאי הכי איתא בפ' לולב הגזול משנה וגמ'.","\u0003ומ\"ש ומשום חציצה נמי ליכא וכו'\u0004 שם פלוגת' דרבה ורבא ופסקו הפוסקים כרבא דכל לנאותו אינו חוצץ ומשמע דאף באגדו בשאינו מינו נמי אינו חוצץ כיון שהוא לנאותו ודלא כמו שכתבו התוס' דהך פלוגתא איירי בשאגדו במינו:","\u0003ומ\"ש וכן מין במינו אינו חוצץ הילכך אם נשרו וכו'\u0004 כלומר אעפ\"י שאינו לנאותו נמי אין חוצץ כשהוא מין במינו כגון שנשרו עלי לולב כו' וגם זה פלוגת' דרבה ורבא שם ופסקו הפוסקים כרבא דאמר הכי:","\u0003ומ\"ש שרש\"י פי' אע\"ג דאין צריך אגד מ\"מ לכתחלה חובה לאגדו כו'\u0004 שם כתב רש\"י שמעי' מהכא דבעי' בלולב קשר גמור וכו' ומשמע לרבינו שבא רש\"י ז\"ל לפסוק הוראה שטובה לאגדו דאי למצוה לחוד תלמוד ערוך הוא דאין לומר דאתי לאשמעי' דכשאגדו צריך שיקשור ב' ראשי האגד הא נמי פשיטא דמדקאמר בי\"ט אוגדו באגודה של ירק אלמא דבחול בעינן ב' קשרים:","\u0003ומ\"ש ואם לא אגדו מאתמול וכו'\u0004 שם ברייתא ואוקימתא דגמרא וגרסינן אוגדו כאגודה בכ\"ף וכן מבואר בפירש\"י וזה לשון הרב אלפס אלא כאגודה של ירק ששוזר שני קצוות של הוצא וכו' דאלמא דמיירי באוגדו בהוצא של לולב ותוחבו מלתחת כמו שתוחבין כשאוגדין את הירק ומ\"ש הר\"ן אלא באגודה של ירק משום דחזי לאכילה ולאו מוקצה הוא לא לפרש דברי הרי\"ף כתב כן אלא לפי גירסתו בגמרא באגודה בבי\"ת כתב כן שלא כגירס' הרי\"ף ופירושו וק\"ל. כתוב במרדכי ע\"ש הרא\"ם דבחול צריך שיקשרנו שני קשרים זה על זה וראבי\"ה כתב אנן נהגינן בקשר של לולב וגם בקשר של ציצית לקשור פעם אחת ושוב מתעגל וכורכין סביב ומתוך כך מהודק יפה כאילו קשרו בב' ראשי האגד שני פעמים עכ\"ל:","\u0003ויטול האגודה בידו הימנית וכו'\u0004 שם מימרא דרבא:","\u0003ומ\"ש ואף אם הוא אטר יד כו'\u0004 כ\"פ בע\"ה כמו שהעתיק הב\"י ותימה על רבינו שפסק הפך דעת הרא\"ש בפ' לולב הגזול שאיטר יד יטול הלולב בשמאל דימין דידיה הוא וכ\"כ הר\"י בשם התו' ומהר\"ם וכ\"כ במרדכי הארוך בשם ר\"י הלוי והוא בתשובת הרשב\"א סימן אלף ק\"כ וכתב מהר\"ש לוריא נ\"ל דטעות נפל בספרי רבינו וצריך להגיה כמ\"ש הרא\"ש דאזלינן בתר ימין דידיה וכן משמע במהרי\"ל שפסק כדברי הרא\"ש וכתב שכן הוא באגודה ובאורח חיים. ולענין הלכה נקטינן ככל הני רבואתא ולא כהעיטור שהוא יחיד בדבר זה וכן נהגו כמ\"ש במהרי\"ל ובמנהגי מהר\"א טירנ\"א:","\u0003וכשיטול הלולב בידו וכו'\u0004 כל זה כתבו התוס' בפ' לולב הגזול גבי כל המצות כולם מברך עליהן עובר לעשייתן וכ\"כ הרא\"ש והר\"ן בסוף הפרק אלא דק\"ל דלדעת התוס' גופייהו ודאי ניחא הא דכתבו ושמא משיתחיל ליטול הלולב קודם שיטול האתרוג מברך היינו עובר לעשייתן שמעכבין זה את זה אי נמי לאחר שנוטל שניהם אלא שהופך אחד מהן וכו' דאינהו ס\"ל כר\"ת דכיון דארבעתן מצוה אחת הן אינו יוצא כשמגביה כל אחד ואחד לבדו אפי' כולן לפניו כמ\"ש התוס' בדף ל\"ז בד\"ה שתהא לקיחה תמה אבל הרא\"ש שחלק על ר\"ת ופסק דכשהם לפניו מברך זה אחר זה א\"כ מאי עובר לעשייתן איכא כשנוטל הלולב בידו קודם שיטול האתרוג או מהפך האתרוג שהרי הרא\"ש גופיה כתב דטעמא דהוי עובר לעשייתן בנוטל הלולב בידו קודם שיטול האתרוג היינו מפני שמעכבין זה את זה והרי בפירוש אמרו אבל יש לו אין מעכבין ופירש הרא\"ש דהיינו כשיש לו והם לפניו אין מעכבין ונוטלן בזה אחר זה וא\"כ לא הוי עובר לעשייתן. ואפשר לומר דשני דרכים אלו שכתב הרא\"ש לא כתבם ע\"פ סברת עצמו אלא ע\"פ סברת ר\"ת אבל לפי סברתו כתב דרך אחר דהיינו שיכוין שלא לצאת עד אחר הברכה ועוד העיקר לפי דעתו כמ\"ש במסקנת דבריו דלא נגמר מצות הלולב עד אחר הנענוע אבל אלשון רבינו קשיא דמשמע מדבריו דבכל אחד מהדרכים שפיר דמי והוא עצמו פסק דכשהם כולם לפניו נוטל זה אחר זה ואין מעכבין וצ\"ל דס\"ל לרבינו דלענין ברכה שפיר הוי עובר לעשייתן כל זמן שלא נטל הד' מינים בידו דרך גדילתן לפחות זה אחר זה והא דאין מעכבין היינו כשנוטלן כולן בזה אחר זה יצא למפרע אבל מתחלה ודאי עדיין לא יצא י\"ח עד שיטול כולן והלכך שפיר הוי עובר לעשייתן וכן נהגו עכשיו הכל לאחוז בדרך זה ליטול הלולב בימין ולהפך האתרוג לבדו ומ\"מ נראה כדי לצאת מידי ספק יהפוך שניהם וכ\"כ בתשב\"ץ בשם מהר\"ם וכך מצאתי ברוקח סוף סי' ר\"ך וכך ראוי לנהוג נ\"ל ומ\"ש בשם הרמב\"ם שיברך קודם שיטלנו בידו ולא נראה לר\"י כ\"כ התוס' לשם דלא מסתבר לברך עליו והוא מונח בכלי כדאמרינן בתפילין דמברך עליהן משעת הנחה ועד שעת קשירה דאלמא דקודם הנחה דאין המצוה מזומנת בידו לא יברך ואינה ראיה דודאי טפי עדיף לברך סמוך לעשיית המצוה אם אפשר ולפיכך מברך עליהן משעת הנחה אבל אינו מעכב אם מברך עליה קודם שיהא מזומנת בידו לברך ולפיכך כאן בלולב דלא אפשר דשני דרכים הראשונים לא נתחוורו לו מטעם שכתבתי בסמוך דכיון דאין מעכבים בזה אחר זה לא הוי עובר לעשייתן גם הדרך הג' שיכוין שלא לצאת ס\"ל להרב דלאו מילתא היא דכיון דמצות א\"צ כונה אפילו צווח שאינו רוצה לצאת ידי מצוה יצא כדעת הרשב\"א והרא\"ה שהביא ב\"י לעיל סוף סימן תקפ\"ט ולברך מקמי נענוע נמי כיון דאין נענוע מעכב אינו שייך כלל לעיקר מצות נטילה שכבר יצא ידי חובתו בנטילה בלי נענוע כל עיקר ולפיכך ס\"ל להרמב\"ם דאין שום דרך לברך עליהן עובר לעשייתן אלא א\"כ שיברך קודם שיטלנו בידו:","\u0003ומ\"ש וי\"א כיון שלא נענעו כו'\u0004 וטוב לעשות כו' נראה מדברי רבינו שלא נתחוור לו סברת הי\"א אע\"פ שכתבה הרא\"ש במסקנתו בסתם. ונ\"ל דמשום דהתוס' הקשו על סברא זו וז\"ל ומיהו לא דמי כולי האי דנענוע אינו אלא מכשירי מצוה בעלמא ולא מעכב כדאמר מדאגבהיה נפיק ביה ומשני כשהפכו ולא משני בשלא נענע עכ\"ל ועל הג' דברים לא הקשו כלום אלמא דטוב לעשות בא' מן הדרכים האלו כדברי רבינו ובסמוך כתבתי היאך ראוי לנהוג:","ולא יברך שהחיינו בשעת עשייתו כ\"כ התוס' בפרק לולב וערבה דהכי נהגו האידנא דלא כדתניא התם דמברך בשעת עשייה ונתן טעם לדבר ע\"ש ובמרדכי הארוך מצאתי בשם הר\"י בר יקר וז\"ל זמן הלולב לא ניתקן לאמרו אלא בשעת עשייה דהוי בחול ומה שהנהיגו לאומרו בי\"ט לפי שיש בני אדם שאין להם לולב וסומכין אלולב של קהל תיקנו שיהא כל אחד מברך שתים בנטילתו ויהא הכל שוין באותה ברכה ע\"כ:","\u0003ולקיחה ע\"י ד\"א וכו'\u0004 בפ' לולב הגזול אמר רבה לא לינקוט איניש הושענא בסודרא דבעינן לקיחה תמה וליכא רבא אמר לקיחה ע\"י ד\"א שמה לקיחה ופסקו הפוסקים כרבא ופירש\"י לא לינקוט וכו' כשנוטלו לצאת בו לא יכרוך סודר שבין כתפיו על ידו ויאחוז הלולב ובסוף פירקא קאמר רבא אם הוציא הלולב בכלי לא יצא ופריך והא רבא הוא דאמר לקיחה ע\"י דבר אחר שמה לקיחה ומשני ה\"מ דרך כבוד אבל דרך ביזיון לא ופירש\"י דרך כבוד. כגון כורך ידיו בסודר כדאמר לעיל ודרך ביזיון כגון בקערה והתוס' כתבו אהא דאמר רבה דבעינן לקיחה תמה וליכא הכא לא שייך למימר דלא ליהוי חציצה כדאמר לעיל דלעיל איירי כשהאגד בלולב והכא כשכרך ידו ובדבר הכרוך בידו לא שייך חציצה. ובסוף פרק מקום שנהגו ביששכר איש כפר ברקאי דהוה כריך ידיה בשיראי דמשמע דאיסורא משום חציצה התם דרך ביזיון הוה דלכבוד עצמו היה עושה שלא יתלכלכו ידיו בדם האיברים א\"נ דל טעמא דחציצה נענש משום ביזיון קדשים ומיהו לא יתכן פירוש זה דמדאייתו עלה ההיא דאזוב שספקו בחוט אלמא דמיירי דהאגד הוא בלולב דומיא ההיא דאזוב ואפ\"ה ליכא חציצה וי\"ל דמיירי שעשה מן הסודר כמין בית יד ללולב ואין שייך כאן חציצה שכל הלולב חוץ מידו ואחזו בבית יד הבולט הנעשה מן הסודר ודמי לאזוב שספקו בחוט ולא חשיב ליה רבה לקיחה תמה ורבא סבר שמה לקיחה ולולב שהוציאו בכלי לא בשאוחזו בדופני הכלי אלא מניח ידו תתת שוליו או שאוחז בבית יד של כלי עכ\"ל התוס' משמע מדבריהם שכונתם לפרש דאפילו בכורך הסודר בלולב אפ\"ה לית ביה משום חציצה אפי' לרבה דע\"כ לא קאמר רבה דאית ביה משום חציצה אלא באגד שסביב הלולב שאוגדו כדי שלא יתפרדו המינין דאין האגד מסייעו בלקיחת לולב אבל אם עשה מן הסודר בית יד ללולב דאוחז הלולב על ידי הסודר כעין צבת שהסודר מסייעו להחזיקו כה\"ג לא הוי חציצה אלא דלרבה לא שמה לקיחה ולרבא שמה לקיחה ולולב שהוציאו בכלי דלא יצא לא כשאוחזו בדופני הכלי דההוא ודאי הוה כבית יד אלא במניח ידו תחת שוליו. ומ\"ש בסוף דבריהם או שאוחז בבית יד של כלי הוא חוזר על ההיתר כלומר שכשאוחזו בשפת הכלי או בבית יד של כלי ודאי שמה לקיחה לרבא אלא במניח ידו תחת שוליו התם הוא דקאמר רבא דלא שמה לקיחה אבל בכורך ידיו בסודר ונוטלו פשיטא דשמה לקיחה לפחות אליבא דרבא ולית ביה נמי משום חציצה ואפילו לרבה ואע\"ג דאין הסודר מסייע כל עיקר משום דלא שייך חציצה אלא כשהאגד בלולב אבל בדבר הכרוך בידו לא שייך חציצה וההיא דיששכר שאני דכיון דהיה דרך ביזיון אית ביה משום חציצה א\"נ דל חציצה נענש משום ביזיון קדשים כך היא דעת התוס' למעיין בדבריהם וכדי לתקן לשון התוס' היה נראה לומר דטעות נפל בספרי הדפוס והלשון מהופך וכצ\"ל ולולב שהוציאו בכלי לא בשאוחזו בדופני הכלי או שאוחזו בבית יד של כלי אלא מניח ידו תחת שוליו וק\"ל. ונמצא פסקן של דברים למאי דקי\"ל כרבא דלקיחה ע\"י ד\"א שמה לקיחה לא מיבעיא בכורך ידיו בסודר אלא אפילו עשה בית יד ללולב והלולב כולו חוץ לידו נמי שמה לקיחה ואם נתנו בכלי נמי שמה לקיחה בכל ענין אלא אם כן מניח ידו תחת שוליו ורבינו שכתב הילכך וכו' אפילו כל הלולב חוץ מידו נמי הכי קאמר ל\"מ בעשה בו בית יד ונותן בו הלולב כגון דכרך בידיו בסודר ונטלו דש\"ד אע\"פ שלא חברו ללולב אלא אפילו כל הלולב חוץ מידו שכרך הסודר בלולב ונוטל הסודר בידו וכל הלולב חוץ מידו נמי שמה לקיחה וזהו כדעת התוס' שכתבתי אבל מ\"ש אח\"כ ובלבד שיהא דרך כבוד אבל אם אינו דרך כבוד כגון שנתנו בכלי ונטלו לא יצא הוא שלא כדעת התוספות דמחלקין בין כשאוחזו בדופני הכלי או אוחזו בבית יד למניח ידו תחת שוליו אלא דס\"ל דבנתנו בכלי בכל ענין לא יצא וכדברי הרי\"ף והרא\"ש שכתבו בסתם דבהוציאו בכלי הו\"ל דרך ביזיון ומשמע אפילו באוחזו בדופני הכלי או בבית יד של כלי ולא דמי לסודר דסודר ודאי הו\"ל דרך כבוד בכל ענין בין בכורך הסודר בידו בין בכורך הסודר בלולב ועשה ממנו בבית יד משא\"כ בהוציאו בכלי דהו\"ל דרך ביזיון בכל ענין וכן נראה עיקר ואע\"פ שהתוס' בפ' הוציאו לו ובפרק מקום שנהגו כתבו דאפילו לרבא בכרך ידיה בסודר ונוטל הלולב לא שמה לקיחה וכן נראה מדבריהם בפ\"ב דזבחים וכ\"כ המרדכי פרק לולב הגזול בשם ר\"י מ\"מ ס\"ל לרבינו דהעיקר הוא כמ\"ש התוס' בפרק לולב הגזול במקום הלכות לולב והוא מסכים לפירושו של רש\"י דבכרך ידיו בסודר פשיטא דשמה לקיחה לפחות אליביה דרבא וכן נראה מפסקי הרא\"ש שכתב פלוגתא דרבה ורבא בסתם ופסק הלכה כרבא דשמה לקיחה משמע דבכל ענין שמה לקיחה בין בכורך הסודר בלולב והלולב כולו חוץ לידו בין בכורך ידיו בסודר וע\"ז סמך רבינו שפסק להקל בסתם ולא כתב שום מחלוקת בזה גם מדברי ה\"ר ירוחם נראה כן אלא שדבריו מעורבין מט\"ס ע\"ש וכל מ\"ש הב\"י בזה בפי' דברי רבינו והתוס' לא נהירא לפענ\"ד: כתוב בתשובת מהרי\"ו בשם ספר אגודה דמסירין הציצית והתפילין מן היד ונשים טבעותיהם משום חציצה אבל נ\"ל דמש\"ה אין צריכין להסירן דדוק' היכא דכרך כוליה ידיה עכ\"ל ולא משמע הכי בסוגיא דהא באגד דלולב לא שרי רבא אלא משום דהאגד ללולב לנאותו הוא וכל לנאותו אינו חוצץ אלמא דכל שאינו לנאותו וגם אינו ממינו כההיא דציצית ותפילין וטבעות אף על גב דמקצת בלא חציצה כההיא דאגד דלולב יש בו משום חציצה דלא בעינן דלהוי כולו בחציצה והא דמשמע בפ\"ק דבכורות גבי קדושת רחם דלא הוי חציצה במקצתה לידה שאני דאורחייהו בהכי כדכתבו התוס' בפרק לולב הגזול ע\"ש ומטעם זה צריך ליטול גם החוט שרגיל להיות סביב ההדס:","וינענע בשעה שמברך כן הכריחו התוספות והרא\"ש והר\"ן ממתניתין דסוף פרק לולב הגזול ומברייתא דפת\"ה וכתב הרא\"ש דראבי\"ה הביא ראיה על זה מהירושלמי עיין שם:","ומ\"ש וכן ינענע בשעת קריאת ההלל בהודו משנה בפ' לולב הגזול והיכן הוא מנענע בהודו לה' בתחלה ובסוף ובאנא ה' הושיעה נא דברי ב\"ה וב\"ש אומר אף באנא ה' הצליחה נא וידוע דהלכה כב\"ה וטעמו של דבר כתבו התוס' והרא\"ש דאיתא במדרש אז ירננו עצי היער וגז' ואמרו הושיענו לפי שבר\"ה באין לדין וכו' ע\"ש:","ומ\"ש שמנענע בהודו בכל פעם שמחזירין אותו הקהל כ\"כ התוס' והרא\"ש וכן נהגו דלא כהר\"ן שחולק על זה וז\"ל התוס' הצבור מנענעין על כל הודו והודו שעונין. אבל ש\"ץ לא ינענע. וי\"מ דאף ש\"ץ מנענע אגב צבורא שעונין בכל פעם ופעם הודו ומנענעים מנענע נמי ש\"ץ ביאמר נא וביאמרו נא ע\"כ ובהגה\"ה אשיר\"י מא\"ז כתב וש\"ץ מנענע ביאמר נא ולא ביאמרו נא א\"נ אגב צבורא שעונין על כל פעם ופעם ומנענעין מנענע כמו כן ש\"ץ ע\"כ והמנהג כסברא הראשונה מא\"ז וטעמו של דבר מדתנן בהודו בתחלה וסוף פירשו בו כמה פירושים רש\"י פירש הודו שבתחלת ההלל והודו שבסוף ההלל וי\"מ בסוף פי' כי לעולם חסדו שהוא סוף הפסוק ואע\"פ שהתוספות והרא\"ש דחו אותו פירוש בסמ\"ק כתב שיש לעשות כדברי שניהם ועוד יש לפרש דבסוף היינו יאמר נא שכתב אחר הודו לכך יש לש\"ץ לנענע ביאמר נא אבל ביאמרו נא אין צריך שכבר יצא ידי כל הפירושים כתב סמ\"ק אין מנענעים בשם לא בהודו ולא באנא ע\"כ:","והניענוע הוא שמוליך ידו מכנגדו להלא' כלומר שהולכה שמוליך ידו מכנגדו להלאה היא עצמה הנענוע וא\"צ לטרוף הלולב ולכסכס העלין כל עיקר וכמ\"ש אח\"כ בשם בעל העיטור שכן עיקר כך סתם דבריו מתחלה ואח\"כ כתב שמספר נענוע זה הוא ג' פעמים דהיינו ג' פעמים בהולכה וג' פעמים בהובאה ואח\"כ מטה ידו לצד צפון ועושה כן ג\"פ וכן לצד דרום וכן לצד מערב ומעלה ידו למעלה כו' ס\"ה ל\"ו פעמים וזו היא דעת הרא\"ש ודלא כהרמב\"ם בפ\"ז שכתב שאינו עושה רק הולכה אחת ומנענע שם בראש הלולב ג\"פ באותה הולכה שמוליך מכנגדו ואח\"כ עושה הובא' אחת ומנענע ג\"כ בראש הלולב ג\"פ באותה הובאה שמביא אליו וכן בירידה ועלייה ולדעתו צריך לומר שהנענוע הוא שיטרוף הלולב ויכסכס העלין בכל נענוע וכ\"כ הר\"ן לדעתו גם צריך לומר לדעתו שאין צריך להטות ראש הלולב לכל צד כמבואר מדבריו שלא הזכיר הטייה כל עיקר והמנהג באשכנז להטות ראש הלולב לכל צד וגם נהגו להקיף דרך ימין מזרח דרום מערב צפון וכ\"כ במהרי\"ל ודלא כמ\"ש רבינו גם נהגו כהרא\"ש וכרבינו שמוליכין ג\"פ ומביאין ג\"פ אלא שנהגו ג\"ב לטרוף הלולב ולכסכס העלין בכל הולכה והובאה וא\"צ אלא דכדי לצאת ידי סברת הרמב\"ם די שיכסכס ויטרוף בהולכה ראשונה והובאה ראשונה והב\"י הבין כדברי הרא\"ש שצריך לנענע ג' זוגות קטנות של הולכה ושל הובאה על כל הולכה והובאה גדולה ולא דק שהרי מבואר בלשון הרא\"ש דדוקא לולי בעיית דרבי זעירא היינו מפרשים דצריך לנענע ג' תנועות קטנות על כל הולכה והובאה אבל מכח בעיית דרבי זירא אנו למדין שא\"צ כלל תנועות קטנות אלא ג\"פ הולכה והובאה לכל רוח וא\"צ כסכוס וטרוף בלולב ועלין כל עיקר כי ההולכה וההובאה עצמה היא הנענוע כמ\"ש בעל העיטור וגם מ\"ש הב\"י ששטה האחרונה שכתב הר\"ן בשם האחרים והרמב\"ן היא שיטת הרא\"ש הוא שלא בדקדוק שהרי שיטת האחרים והרמב\"ן היא דעל כל דבר שמנענעים בהלל מוליך ומביא ומעלה ומוריד ואח\"כ מנענע ג' זוגות קטנות של הולכה והובאה ודיו ואילו להרא\"ש בכל א' מההולכה וההובאה והעלאה והורדה צריך לנענע ג' פעמים בהולכה ובהובאה גדולה וכבר הארכתי בתשובה בדבר הנענוע כל הצורך וכאן מספיק במ\"ש:","\u0003ומ\"ש וב\"ה כתב ונענוע דרבנן וכו'\u0004 טעמו דבירושלמי גרסינן תני צריך לנענע ג\"פ על כל דבר ודבר ואיבעיא לן הכין חד והכין חד א\"ד הכין והכין חד ולא איפשיטא ואזלינן ביה לקולא וסגי בי\"ח כוחות: וכתב עוד מנהג אבותינו כו' הכי משמע מפשטא דתלמודא שלא הזכיר רק מוליך ומביא מעלה ומוריד וכתב הר\"ן שכן נהגו:","\u0003ומ\"ש בשם הרא\"ש שהעולם לא נהגו כן וכו'\u0004 עד ו' קצוות בפ' לולב הגזול כתב כן וכ\"כ הסמ\"ק וה\"ר ירוחם ומהר\"ל חביב בתשובה סי' ע\"ט כתב עוד שאין ראוי לשנות מן המנהג שנהגו ע\"פ סברת הרא\"ש ורבינו להוליך ולהביא לכל ו' קצוות וכן כתבו כל האתרוגים שהמנהג כהרא\"ש:","\u0003כתב בעל העיטור הולכה והובאה הוא הנענוע כו'\u0004 טעמו מבואר בדבריו כדרך שאמרו בחנופה גם בדברי הרא\"ש משמע הכי שכתב בסוף דבריו נמצא שצריך ג' הולכות וג' הובאות לכל צד וצד שהם ל\"ו בין הכל והב\"י השיא דברי הרא\"ש לדעת אחר ולא דק:","\u0003ואלו הד' מינין מעכבין זה את זה כו'\u0004 משנה וגמרא פרק הקומץ רב' ודברי רבינו בפירושם כדברי הרי\"ף ולא כפר\"ת דמחמיר דאינו בזה אחר זה אפילו כולם לפניו והכל תפסו עליו בזה:","ומ\"ש ויטול הלולב תחלה כ\"כ הרא\"ש דהכי מסתברא ופסק הב\"י דיברך על הלולב ומשמע מכאן דא\"צ לחבר האתרוג ללולב בשעת ברכה ואין צ\"ל בשעת הנענוע דא\"צ דהא אפילו בנטלן בזה אחר זה יצא כשהם כולם לפניו אלא שהרב מהר\"מ ראקאנט\"י כתב שצריך לסמכם יחד ע\"פ הקבלה ופשיטא דלמצוה מן המובחר כתב כן אבל מדינא א\"צ לסמכן יחד:","חסר לו אחד מן המינין לא יקח לו מין אחר במקומו פירוש אע\"פ שלא יברך אלא לזכרון בעלמא כדי שלא תשתכח תורת אותו מין נמי לא דזימנין דנפיק חורבה מיניה ואתי למסרך והכי איתא בברייתא ובגמ' בפ' לולב הגזול. וכתב הר\"ן לשם דדוקא מין אחר הוא דלא יביא משום דילמא אתי למיסרך אבל אם לא מצא כשר מביא פסול מאותו מין שחסר והכי מוכח בברייתא דאמרו לו לרבי יהודה על הלולב היבש שהיו נוטלין דאין שעת הדחק ראיה דאלמא דבשעת הדחק מביא הפסולין שבמינן ולשטתו אזיל שהסכים לדעת הראב\"ד שאין לברך על הפסולין אלא יאחזם בידו שלא תשתכח תורת ארבע מינין וע\"ל סוף סימן תרמ\"ט ובתשובת מהרי\"ל כתב דאם חסר אחד מן המינים דיטול שאר המינין בידו ולא יברך והעתיקה הב\"י ועוד כתב סברות בזה ע\"ש ולענין הלכה נקטינן דאין לברך על השאר אבל נוטלם בלא ברכה לזכר בעלמא בין ביום הראשון בין בשאר הימים:","ומ\"ש ולא יפחות מהן ולא יוסיף עליהן הכי איתא בברייתא בפ' לולב הגזול ד' מינין שבלולב אין פוחתין מהן ואין מוסיפין עליהן כך היא גירסת הרי\"ף והרא\"ש והב\"י השיג על רבינו וז\"ל וק\"ל בלשון רבינו שכתב לא יפחות מהן דהא כבר כתב שד' המינין אלו מעכבין זה את זה והא תו למה לי לכתוב ולא יפחות מהן וגם הברייתא לא אתי לאשמעינן דלא יפחות מהן דהא ממתניתין שמעינן לה אלא לאשמעינן דאין מוסיפין עליהם אתא והיינו דקתני כשם שאין פוחתין מהן כך אין מוסיפין עליהן ולא קתני לא יפחות מהן ולא יוסיפו עליהן ולכן נ\"ל דלשון רבינו בזה אינו מדוקדק עכ\"ל ואני אומר בדקדוק הוא ע\"פ גי' הרי\"ף והרא\"ש ומאי דקשיא ליה הא כבר כתב שד' מינים אלו מעכבים זה את זה והא תו למה לי ל\"ק דמעכבין לחוד ואין פוחתין לחוד דמעכבין זה את זה מיירי שחסר לו אחד מהן לגמרי שאין שם אלא ב' או ג' מינין ואין פוחתין מיירי כשיש שם כל הד' המינין אלא שנפחת מן השעור שניתן להן בין שנחסר ממניינם כגון לולב אחד וכו' בין שהם חסרי השיעור כגון אתרוג פחות מכביצה וכו':","\u0003ומ\"ש ולא יוסיף עליהן מין אחר וכו'\u0004 אפילו אם לא יאגדנו עמהם פי' דהוה סד\"א כיון שנותן אותו חוץ לאגד ליכא משום בל תוסיף דהאי לחודיה קאי והאי לחודיה קאי אפ\"ה מאחר שנוטל אותו מין אחר כדרך גדילתו אפילו חוץ לאגד חשיב כמוסיף כך פי' התוס' פ' לולב הגזול ע\"ש. וז\"ש רבינו אם יאחזנו בידו עמהם לשם מצות לולב כלומר שיאחזנו דרך גדילתו כמצותו של לולב איכא משום בל תוסיף אבל אם לא יאחזנו בדרך גדילתו כמצותו של לולב ליכא משום בל תוסיף ובזה נתיישב מה שהקשה הב\"י ז\"ל וז\"ל ומ\"ש דכשמוסיף מין אחר אם יאחזנו בידו עמהן שלא לשם מצות לולב אינו עובר עליו קשה דהא אסיקנא בפ' ראוהו ב\"ד דלעבור בזמנו לא בעי כונה עכ\"ל ואף לפי משמען של דברים כמו שהבינם הב\"י יש לתרץ ולומר דס\"ל לרבינו כהרא\"ש דפסק כמ\"ד צריכות כונה כדלעיל בסימן תקפ\"ט ומסיקנא דהתם היא אליבא דרבא דאמר מצות א\"צ כונה אבל למ\"ד צריכות כונה לעבור נמי בעי כונה אפילו בזמנו. אפילו אם תמצא לומר דלעבור בזמנו לא בעי כונה אף למ\"ד צריכות כונה אפ\"ה ל\"ק מידי דמאחר דהתוס' בפ' לולב הגזול כתבו דהא דאמר בסנהדרין למ\"ד א\"צ אגד האי לחודיה קאי והאי לחודיה קאי דהיינו לענין דאין כל המוסיף גורע דלעולם ידי מצוה יצא אלא דעובר על בל תוסיף א\"כ לפי דעת הרא\"ש ורבינו דפסקו דמצות צריכות כונה צריך לומר שיאחזנו בידו לשם מצות לולב דאם לא כן ידי מצוה נמי לא יצא ומאחר שרבינו כתב דאיכא משום בל תוסיף ומשמע אבל ידי מצוה יצא לכך הוצרך לומר דהיינו שאוחזם בידו לשם מצות לולב וראשון ושני שכתבתי מתיישב יותר:","ומ\"ש אבל מאותן ד' מינין יכול להוסיף עליהן בפרק לולב הגזול כתבו התו' (דף לד) בד\"ה ערבי נחל שתים אפילו נותן כמה הדסים וכמה ערבות בלולב אין זה בל תוסיף אפילו למ\"ד צריך אגד כדפי' בפרק ראוהו ב\"ד עכ\"ל ונ\"ל ראיה ברורה להתיר תוספת הדסים מדאסיקנא התם דהא דאמר רבי ישמעאל ג' הדסים אפי' שנים קטומים ואחד אינו קטום דחזר בו ר\"י ופירש\"י דחזר בו רבי ישמעאל מתחלת דבריו שהיה מצריך ג' שאינם קטומים ואמר אפילו שנים קטומים והוא הדין אי לא מייתי להו לגמרי דהא קטומים כמאן דליתנהו דמי עכ\"ל אלמא דאין לחוש משום בל תוסיף אי מייתי תרתי קטומים אע\"ג דלכתחלה לא בעי אלא חד שאינן קטום כמו לולב אחד ואתרוג א' ומשמע להדיא דלכתחלה קאמר ר\"י דמייתי להו גם ה\"ה כתב שלא מצינו בתלמוד היתר תוספת אלא בהדס וא\"א לקיים דבריו אלא על הדרך שכתבתי וכתב ה\"ה שדעת הגאונים שתוספת הערבה דומה לתוספת הדס דלא כהרמב\"ם שפוסל תו' אף בערב' וא\"צ בב' לולבים ובב' אתרוגים והרא\"ש כתב שאף הרמב\"ם עצמו חזר מדבריו והכשיר הכל ר\"ל אף הערבה וכ\"כ ה\"ר ירוחם שחזרת הרמב\"ם הית' בערב' דוקא והטעם דערבי נחל כתיב ומשמע שנים ואפילו ק' וכן ענף עץ עבות ג' ואפילו טובא אבל לולב ואתרוג כיון דחד חד משמע אסור לאוסופי ולא חזר הרמב\"ם מזה כל עיקר וכן נראה מדברי התוס' שלא הזכירו בדבריהם רק הדס וערבה אלא שהרא\"ש הוסיף מדעתו וכתב שאף בלולב ואתרוג אין בהן משום בל תוסיף ולפיכך סתם רבינו וכתב דמאותן ד' המינין יכול להוסיף עליהן וכך היא דעת הראב\"ד בהשגות ולענין הלכה נקטינן כרוב גאונים דלא מכשרי אלא בהדס וערבה אבל לא בלולב ואתרוג והכי נהוג. ובתשובת הרשב\"א בסימן ע\"ה ובסימן תקל\"ה החמיר אף בהדס אם אינו לנאותו דדוקא כשהוא לנאותו אינו משום בל תוסיף ובערבה אין בו משום נוי בתוס' שלו וע\"ש וכ\"כ הר\"ש בן הר\"ש בר צמח בתשובה העתיקה ב\"י לקמן בסימן תרס\"ד ולפיכך אלו שמוסיפין ערב' כדי לצאת י\"ח ערבה כשרה על כל פנים אי נמי לנאותו לא יפה הם עושין דבערבה אין שום נוי בתוספת שלו ועיין במ\"ש לקמן בסימן תרס\"ד:","\u0003ומ\"ש ובהדס שוטה כחלקו כו'\u0004 מחלוקת זו כתובה באשיר\"י וע\"ש בפירוש דברי ר\"נ שכתב אם יכול לעשותו כולו עבות מצוה מן המובחר היינו לומר דאע\"פ דסגי בג' עבות מ\"מ מצוה מן המובחר לנאותו משום זה אלי ואנוהו ובתוס' הדסים דאיכא אגודה גדולה נויי מצוה היא כמ\"ש הרמב\"ם להדיא. אבל אם אינו מוצא אלא ג' הדס עבות ממלא אותו האגד הגדול בהדס שוטה ושפיר דמי דמינא דהדס הוא:","ומ\"ש וכ\"כ הרא\"ש אינו מדוקדק שלא כ\"כ בפירוש אלא הביא מחלקותם ומ\"מ משמע דס\"ל כר\"נ מדהביא דבריו במסקנא. כתב ר\"ע וכו' במרדכי כתב גם כן דנוטלין ס\"ח ערבות כמנין לולב וג' קשרים שהוא ס\"ה ע\"א כמנין סנהדרין וג' קשרים הם כנגד ג' אבות אבל בהג\"ה אשיר\"י כתב שהג' קשרים הם כנגד אתרוג ולולב והדס:"]],["\u0010c0\u0011\u0010y0\u0011מצות לולב ביום ולא בלילה \u0010y1\u0011וכל היום כשר לנטילת לולב \u0010c1\u0011\u0010y2\u0011שאם לא נטלו שחרית יטלנו ערבית ומ\"מ זריזין מקדימין למצות ונוטלין אותו בבוקר \u0010c2\u0011\u0010y3\u0011שמצותו מעלות השחר \u0010c3\u0011\u0010y4\u0011ועיקר מצותו בשעת ההלל \u0010y5\u0011ואם צריך לילך בדרך ואינו יכול להמתין נוטלו מיד קודם שילך ובלבד שיעלה עמוד השחר וקורא ההלל בלא לולב \u0010c4\u0011\u0010y6\u0011והמדקדק במעשיו יעשה כאנשי ירושלים שהיה אדם יוצא מביתו ולולבו בידו היה קורא ק\"ש ומתפלל לולבו בידו אע\"פ שאסור לאחוז בידו ספר תורה ותפילין בשעת תפלה שמא יתבטל מכוונתו \u0010y7\u0011שאני הכא כיון שדבר מצוה הוא לא חיישינן שמא יתבטל מכוונתו קורא בתורה ונושא כפיו מניחו על גבי קרקע לנחם אבלים ולבקר חולים לולבו בידו נכנס לבית המדרש משגרו ביד בנו או ביד עבדו \u0010y8\u0011ואסור לאכול קודם שיטלנו שכח ואכל קודם שנטלו והוא על שולחנו ביום הראשון שהוא מן התורה יפסיק אפילו אם יש שעות ביום ליטלו אחר שיאכל ומיום ראשון ואילך אם יש שהות ביום לא יפסיק ואם לאו יפסיק:",["מצות לולב ביום ולא בלילה בספ\"ב דמגילה (כ.) ומייתי לה מדכתיב ולקחתם לכם ביום הראשון ביום ולא בלילה:","\u0003ומ\"ש וכל היום כשר לנטילת לולב שם במשנה:\u0004 ","ומ\"ש שאם לא נטלו שחרית יטלנו ערבית כלומר לא תימא כיון דתנן כל היום כשר ללולב אפי' לכתחלה יכול לעסוק בעסקיו ואח\"כ יטול לולב בחצי היום או בסופו דליתא אלא לכתחלה צריך ליטלו בתחלת היום דזריזין מקדימין למצות וכדאיתא בריש פסחים (ד.) גבי מילה בזמנה כל היום ואפ\"ה מצוה למקדם מצפרא כדכתיב וישכם אברהם בבקר וה\"ה לנטילת לולב דצריך לאקדומי מצפרא ולא אמרו שכל היום כשר לנטילת לולב אלא דהיכא שלא נטלו שחרית שיטלנו ערבית פי' בסוף היום וכדתנן בפ' לולב הגזול (סוכה לח:) לא נטל שחרית יטול ערבית שכל היום כשר ללולב:","ומ\"ש שמצותו מע\"ה לאו עיקר מצותו לכתחלה קאמר דעיקר מצותו לכתחלה אינה אלא משתנץ החמה כדין דברים שמצותן ביום וכדתנן פרק ב' דמגילה (כ.) אין קורין את המגילה ולא מלין ולא טובלין ולא מזין וכן שומרת יום כנגד יום לא תטבול עד שתנץ החמה וכולן שעשו משעלה עמוד השחר כשר:","ומ\"ש עיקר מצותו בשעת ההלל הכי משמע מדתנן בפרק לולב הגזול והיכן מנענעין בהודו לה' תחלה וסוף וכו':","ומ\"ש ואם צריך לילך בדרך ואינו יכול להמתין נוטלו מיד ברייתא בפ' תפלת השחר (ברכות ל.) השכים לצאת לדרך מביאין לו שופר ותוקע לולב ומנענע:","\u0003והמדקדק במעשיו יעשה כאנשי ירושלים שהיה אדם יוצא מביתו ולולבו בידו וכו'\u0004 עד משגרו ביד בנו או ביד עבד בס\"פ לולב הגזול:","ומ\"ש שאני הכא כיון שדבר מצוה הוא לא חיישינן פירושו דס\"ת ותפילין אין מצוה לאוחזן והויין עליו למשא ולפיכך טרוד במשאן וכבד עליו משאן ושמירתן אבל לולב נטילתו ולקיחתו מצוה היא ומתוך שחביבה מצוה עליו אין משאן ושמירתן כבד עליו ולא טריד וכן פירש\"י ואהא דאמרינן קורא בתורה ומניחו ע\"ג קרקע נכנס לב\"ה משגרו וכו' פי' קורא בתורה צריך להניח הלולב לפי שגולל ס\"ת ופותחו נכנס לביה\"מ טריד בשמעתא ויפול מידו והמרדכי כתב קורא בתורה ונושא את כפיו מניחו לארץ שמעינן מהכא הקורא בתורה אוחז בעמוד התורה בשעת ברכה וקורא מדמניחו לארץ:","ואסור לאכול קודם שיטלנו שכח ואכל קודם שנטלו והוא על שולחנו ביום הראשון שהוא מן התורה יפסיק וכו' בפרק לולב הגזול תנן מי שבא בדרך ואין בידו לולב משיכנס לביתו יטול על שולחנו ופירש\"י אם שכח ולא נטל קודם אכילה צריך להפסיק סעודה וליטול לולב ואסיקנא בגמ' דמתני' בי\"ט ב' איירי מדקתני מי שבא בדרך והא דמפסיק סעודתו ונוטלו על שולחנו איירי בשאין לו שהות ביום אבל אם יש שהות ביום אינו מפסיק כי ההיא דתנן גבי תפלה אם התחיל אין מפסיקין ודוקא בי\"ט שני אבל בי\"ט ראשון אפילו אם יש שהות מפסיק והכי אמרינן התם דמפסיקין לקרות ק\"ש שהוא דאורייתא ותמהני על הרי\"ף למה לא הביא שקלא וטריא דגמרא עכ\"ל הרא\"ש ז\"ל וכתב הר\"ן דהא דאמרינן דלמידי דאורייתא אפילו אם התחיל מפסיק ה\"מ בדאתחיל בתר דמטא זמן חיובא או סמוך לו דהיינו חצי שעה אבל אתחיל מקמי הכי אפילו בדאורייתא כיון דאיכא שהות לא מפסיק והביא ראיה לדבר:"],["מצות לולב ביום ולא בלילה בר\"פ לולב וערבה אמרינן דבין לרבנן ובין לר\"א אין נטילת לולב בלילה אלא דמר מפיק ליה מביום ולא בלילה ומר מפיק לה מושמחתם לפני ה' אלהיכם שבעת ימים ימים ולא לילות. ומ\"ש וכל היום כולו כשר לנטילת לולב משנה ספ\"ב דמגילה:","\u0003ומ\"ש שאם לא נטלו שחרית כו'\u0004 משנה ס\"פ לולב הגזול לא נטל שחרית יטול בין הערביים שכל היום כשר ללולב משמע דוקא אם לא נטל שחרית אבל לכתחלה יטול שחרית משום הקדמת זריזין:","ומ\"ש שמצותו מעלות השחר כלומר שגם מעלות השחר היא מצותו ולפיכך נקט התנא בלישני' שחרית לאורויי לן דאף משעלה עמוד השחר היא מצותו אבל ודאי עיקר מצותו לכתחלה אינה אלא בהנץ החמה וכן פסק הב\"י:","\u0003ומ\"ש ועיקר מצותו בשעת ההלל הכי משמע מדתנן התם והיכן מנענעין בהודו כו':\u0004 ","\u0003והמדקדק במעשיו יעשה כאנשי ירושלים כו'\u0004 בפרק לולב הגזול א\"ל מר בר אמימר לרב אשי אבא צלויי קא מצלי ביה מיתיבי לא יאחז אדם תפילין בידו וס\"ת בחיקו ויתפלל התם לאו מצוה נינהו וטריד בהו הכא מצוה נינהו ולא טריד בהו תניא רבי אלעזר בר צדוק אומר כך היה מנהגן של אנשי ירושלים אדם יוצא מביתו ולולבו בידו הולך לבית הכנסת ולולבו בידו קורא קריאת שמע מתפלל ולולבו בידו קורא בתורה ונושא את כפיו מניחו על גבי קרקע הלך לבקר חולים וכו' ומשמע מדקאמר אבא צלויי קא מצלי ביה משמע דכולי עלמא לא עבדי הכי ולפיכך כתב רבינו דהמדקדק במעשיו יעשה כאנשי ירושלים וכן עיקר דלמי שאינו מדקדק בשאר מעשיו מחזי כיוהרא וכמ\"ש ראבי\"ה גבי תפלת ערבית:"]],["\u0010c0\u0011\u0010y0\u0011אתרוג של מצוה מותר להריח בו שעיקרו לאכילה ומזה לבד הוקצה ולא מלהריח \u0010y1\u0011והמריח בו כתב רבי' שמחה שאין לו לברך ברוך שנתן ריח טוב בפירות דעיקרו לאו לריח עבידי ואבי\"ה כתב שיש לו לברך הדס של מצוה אסור להריח בו שעיקרו אינו אלא להריח ומזה הוקצה:",["\u0003אתרוג של מצוה מותר להריח בו הדס של מצוה אסור להריח בו וכו'\u0004 מימרא דרבא בפרק לולב הגזול (סוכה לו.) ופירש\"י אסור להריח בו דגמרינן מסוכה דילפינן בפ\"ק דחל שם שמים על עצי סוכה לאסור בהנאה כל שבעה הואיל והוקצה למצוה כתב בתשובת הרשב\"א שאלת הדס של לולב אם מותר להריח בו כמו שאמר בהבדלה כשהתנה מסתבר שהתנאי מועיל בו דמ\"ש מאתרוג דאמרינן הפריש ז' אתרוגים לז' ימים כ\"א יוצא בה ואוכלה לאלתר לרבא או למחר לרב אסי ולא דמי לעצי סוכה דהתם חג הסוכות לה' כתיבא :","\u0003ומ\"ש רבינו והמריח בו כתב רבינו שמחה שאין לו לברך וכו'\u0004 ואבי העזרי כתב שיש לו לברך מחלוקת זה כתב המרדכי בפרק לולב הגזול וסמ\"ק כתב כדברי אבי העזרי וכתב וע\"כ טוב למנוע שלא להריח בו בשעת נטילה דרוב פעמים אינו זכור מברכה זו ואסור ליהנות מן העה\"ז בלא ברכה ואותן המריחים כשמברכין על הנטילה מנהג שטות הוא כדפרישנא עכ\"ל : כתב בהג\"א פרק המביא כדי יין בשם א\"ז עבדה להושענא ולא אגבה למיפק שרי בהנאה דהזמנה לאו מילתא היא:"],["\u0003אתרוג של מצוה מותר להריח בו כו'\u0004 הדס של מצוה אסור להריח בו כו' מימרא דרבא בפ' לולב הגזול ומחלוקת ה\"ר שמחה ואבי העזרי בברכת הריח דאתרוג כתובה במרדכי שם ומשמע מלשונו שס\"ל כה\"ר שמחה אבל בסמ\"ק כתב כאב\"י העזרי וכתב וע\"כ טוב למנוע שלא להריח בו כו' והכי נהוג וע\"ל בסי' רי\"ו ס\"ג ובמ\"ש לשם בס\"ד:"]],["\u0010c0\u0011\u0010y0\u0011מקבלת אשה מיד בנה או מיד בעלה הלולב ומחזירתו למים ביום טוב ותוסיף עליו אם צריך ובלבד שלא תחליף המים ובחול המועד מצוה להחליפם כדי שישאר לח והדור:",["מקבלת האשה מיד בנה או מיד בעלה הלולב ומחזירתו למים ביום טוב ותוסיף עליו אם צריך וכו' משנה בפרק לולב הגזול בי\"ט מוסיפין במועד מחליפין ופירש\"י בי\"ט מוסיפין אבל לא מחליפין דטורח הוא לתקוני מנא ובחולו ש\"מ מצוה להחליף ע\"כ וכ\"כ המרדכי בשם רא\"מ מכאן דמנהג כשר וטוב לתת הלולב וערבה במים שלא ייבשו : וכתב בא\"ח בזמן הזה שאין לולב ניטל בשבת אם שגג והוציאו מן המים אין מחזירין אותו למים שהרי הוא כאבן לענין טלטול :"],["\u0003מקבלת אשה כו'\u0004 ס\"פ לולב הגזול פריך פשיטא מה\"ד הואיל ואשה לאו בת חיובא היא אימא לא דלגבה איכא איסור טלטול קמ\"ל ופירש\"י קמ\"ל כיון דראוי לנטילת אנשים תורת כלי עליו ומותר בטלטול לכל עכ\"ל ופירושו זה לפי שיטתו דס\"ל כהרמב\"ם דאין הנשים מברכין על מ\"ע שהזמן גרמא אבל לר\"ת דמתיר לברך מפרש כפשוטו קמ\"ל כיון דראוי לה לעצמה ליטול ולברך אין בו משום איסור טלטול ועיין בהג\"ה אשיר\"י לשם:"]],["\u0010c0\u0011\u0010y0\u0011עו\"ג שהביא לולב לישראל בי\"ט מחוץ לתחום כתב הרשב\"א שמותר ליטלו שלא אסרו חכמים דבר שהובא מחוץ לתחום אלא לאותו שהובא בשבילו ואפילו הוא מותר לטלטלו ולא אסרוהו לו אלא באכילה ובהנאה ומצות לאו ליהנות ניתנו:",["\u0003עו\"ג שהביא לולב לישראל בי\"ט מחוץ לתחום כתב הרשב\"א שמותר ליטלו וכו'\u0004 גם בהג\"א פרק לולב וערבה כתב בשם א\"ז שמותר ליטלו דאין שייך לגזור שמא יאמר לעו\"ג להביא כדי לצאת בו דמלתא דלא שכיחא הוא דיעשה אדם מצוה הבאה בעבירה והמרדכי כתב בפרק לולב הגזול אתרוג ולולב שהובא מחוץ לתחום בשביל ישראל מותר לישראל אחר לצאת בו ואפשר כי גם לישראל שהובא בשבילו מותר לצאת בו כיון שהוא דבר של מצוה כדאמרינן בפרק אלו עוברין וכו' ועוד ראיה מגזל עצים וסכך בהם וכו':"],["\u0003עו\"ג שהביא לולב וכו'\u0004 דברי רשב\"א הללו כתובים גם במרדכי פרק הדר והוסיף שם וז\"ל וכאן דאין שיוך למיגזר שמא יאמר לעו\"ג להביא כדי לצאת בו דלא שכיחא שיעשה אדם מצוה בעבירה הילכך אפילו למ\"ד מצות ליהנות ניתנו שרי' עכ\"ל וכ\"כ בהג\"ה אשיר\"י פרק בתרא דר\"ה אבל בר\"פ לולב וערבה כתוב בקיצור. ודע דמאי דמשמע מדברי הרב דאסור לומר לכתחלה לעו\"ג להביא האתרוג מחוץ לתחום חולקים על זה במרדכי פרק הדר וז\"ל הר\"י הלוי התיר לומר לעו\"ג להביא אתרוג אפילו מרחוק בי\"ט היכא דאיכא אונס שלא היה להם אתרוג משום דתחומין דרבנן אפילו די\"ב מיל ע\"כ וזה לשיטתו כמ\"ש המרדכי משמו ספ\"ק דעירובין אבל למאי דקי\"ל דתחומין די\"ב מיל ד\"ת כמ\"ש למעלה בסימן שצ\"ז אסור לכתחלה לומר לעו\"ג להביא אתרוג מרחוק י\"ב מיל אבל מתוך שנים עשר מיל שרי לדידיה ובהגהת מנהגים השיג על זה ממה שכתב בספר מצות גדול לאוין נ\"ז דגילוח מצורע אין עושין על ידי עו\"ג אף על גב דליכא אלא איסור דרבנן ולא דק דהתם ודאי אע\"ג דאין בו מלקות כיון דאינו מסייע מכל מקום איסורא דאורייתא מיהא איכא אבל באיסורא דרבנן איכא למימר דשרי ע\"י עו\"ג כדי לקיים מצות עשה דאורייתא. אי נמי גלוח מצורע דאיסורא קא עביד בגופו חמיר טפי ואפילו לא הוה אלא איסורא דרבנן נמי הוה אסור אלא דלפי האמת איסורא דאורייתא נמי הוי כדפי' ומ\"מ ודאי אף הר\"י הלוי לא התיר אלא דוקא בי\"ט מותר להביא מחוץ לתחום אבל בשבת דאיכא איסור הוצאה והבערה פשיטא דאסור והעולם טועים בזה ששולחין האתרוג ע\"י עו\"ג אף בשבת הסמוך לי\"ט מלפניו או מלאחריו ועיין מדין זה למעלה בסי' רע\"ו ובסימן ש\"ז וסי' תקפ\"ו גבי שופר ועיין עוד במרדכי ר\"פ לולב הגזול בתשובת הר\"א כ\"ץ בדין ישראל שהביא לולב מחוץ לתחום בי\"ט אם אסור ליטלו משום מצוה הבאה בעבירה:"]],["\u0010c0\u0011\u0010y0\u0011קנה אתרוג שראוי לצאת בו ומצא אחר נאה ממנו מצוה להוסיף עד שליש בדמי הראשון כדי להחליפו ביותר נאה:",["קנה אתרוג שראוי לצאת בו ומצא אחר נאה ממנו מצוה להוסיף עד שליש בדמי הראשון בפ\"ק דב\"ק (ט:) א\"ר זירא א\"ר הונא דמצוה עד שליש מאי שליש אילימא שליש ביתו אלא מעתה אי איתרמי ליה תלתא מצותא ליתיב לכולי ביתיה אלא א\"ר זירא בהידור מצוה עד שליש בעי רב אשי שליש מלגיו או שליש מלבר תיקו במערבא אמרי עד שליש משלו מכאן ואילך משל הקב\"ה ופירש\"י בהידור מצוה עד שליש במצוה שאם מוצא שני ס\"ת לקנות א' הדור מחבירו יוסיף שליש הדמים ויקח את ההדור: שליש מלגיו. כגון אם הקטן נמכר בשש יוסיף ב' דינרין דהיינו שליש מלגיו שליש שבתוך הדמים ויקח את ההדור: או שליש מלבר. הדמים יחלוק לשנים ויוסיף חלק ג' משלו דהיינו קטן נמכר בו' יוסיף ג' דינרין ויקח את הגדול בט': עד שליש משלו. דהיינו אותו שליש שיוסיף בהידור מצוה משלו הוא שאינו נפרע לו בחייו כדאמרינן היום לעשותם ולא היום ליטול שכרם מכאן ואילך מה שיוסיף בהידור יותר על שליש יפרע לו הקב\"ה בחייו עכ\"ל וכתב הרא\"ש הידור מצוה עד שליש מצוה אם מצא אתרוג שהוא ראוי לצאת בו שהוא כאגוז יוסיף שליש לקנות יפה ממנו ולא שיהיה מחוייב לקנות אתרוג יפה שימצא בתוספ' שליש על אתרוג שחפץ לקנות וז\"ל התו' פי' שאם מצא אתרוג כאגוז כמו ששיערו חכמים ואחד גדול ממנו שליש יקנהו. וסמ\"ג כתב מפ' רבינו יעקב שאינו ר\"ל בס\"ת נאה או באתרוג נאה יוסיף שליש שהרי לעולם ימצא נאה ונאה אלא אם קנה אתרוג ושיעורו כאגוז או כביצה ומצא נאה יש לו ליתן עד שליש יותר אבל אם גדול מכביצה אין לו להוסיף עליו לשון מורי ר\"י ור\"ג שקנה אתרוג באלף זוז חומרא הוא מלבו מפני שמצות היו חביבים עליו עכ\"ל ונראה שביאור דבריו וביאור דברי הרא\"ש שמוסיף שליש על מה ששוה אתרוג שיוצאין בו בצמצום שאם פיחת מאותו השיעור לא היו יוצאין בו ואע\"ג דקי\"ל דהלכה כר\"י דאמר שיעור אתרוג כביצה נקט הרא\"ש אם מצא אתרוג שהוא ראוי לצאת בו שהוא כאגוז לדוגמא בעלמא נקטיה אליבא דר\"מ ומיניה נשמע לר' יהודה בכביצה שאם קנה אתרוג כביצה מוסיף שליש לקנות יפה ממנו דכיון דלא נחת הכא לפסוק דין שיעור אתרוג הכשר לא דק וזהו דרכו של סמ\"ג שאע\"פ שפסק הלכה כרבי יהודה דאמר כביצה כתב ושיעורו כאגוז או כביצה כדי להעמיד הא דהידור מצוה בין לר\"מ בין לרבי יהודה לכל חד כדאית ליה כנ\"ל ולא כמו שכתב מהר\"י קולון בשורש ס\"ב דלהרא\"ש אם קנה אתרוג כביצה א\"צ להוסיף עליו אפי' לר' יהודה ואין דבריו נכונים כלל דא\"כ לא הו\"ל להרא\"ש לפרש הא דהידור מצוה באתרוג כיון דלר\"י דקי\"ל כוותיה לא שייך להוסיף משום הידור. וגם רבינו שפסק דעל אתרוג שראוי לצאת בו מצוה להוסיף שליש מוכיח בבירור שהיה מפרש דברי הרא\"ש כמו שכתבתי ולרש\"י אם מצא ב' אתרוגים לקנות צריך לקנות היפה מהם אם אין מייקרין אותו יותר משליש בדמי חבירו אבל משקנה אתרוג הכשר לצאת בו אינו חייב שוב לקנות אחר אפילו הוא יפה מאוד ובזול ובמאי דאיבעיא לן שליש מלגיו או מלבר כתב הרא\"ש דכיון דלא איפשטא נקטינן דשליש מלגיו קאמר ונראה שהטעם משום דספיקא דרבנן הוא ולקולא: כתב הרא\"ש מדאמרינן אילו מיתרמו ליה תלתא מצותא יהיב לכוליה ביתיה שמעינן שאין אדם מחוייב לבזבז הון רב בשביל מצוה ואפי' היא מצוה עוברת כגון אתרוג ולולב ותלמודא בפרק לולב הגזול (סוכה מא.) חשיב גוזמא על ר\"ג שהיה נשיא ישראל מה שנתן אלף זוז באתרוג א' וגם תקנו חכמים שהמבזבז אל יבזבז יותר מחומש עכ\"ל ור\"י כתב דברים אלו בנתיב י\"ג חלק ג' ובסוף כ' ומ\"מ בעישור נכסיו חייב לקנותו עכ\"ל ולא ידעתי מנין לו והרשב\"א כתב מהא דאמרינן אילו מתרמי ליה תלתא מצותא יהיב כוליה ביתיה משמע דאפי' למצוה עוברת כאתרוג וסוכה אינו מחוייב לתת אפי' שליש ממונו וזה תימא איך נתנו דמים למצוה עוברת וכתב הראב\"ד ז\"ל כדי שלא יבא לידי עוני ויפיל עצמו על הצבור וכמו שאמרו כתובות (נ:) המבזבז אל יבזבז יותר מחומש שהעוני כמיתה ומ\"מ לא כמיתה ממש אמר הרב שלא אמרו אלא במ\"ע בשב ואל תעשה אבל במצות לא תעשה אפילו כל ממונו עכ\"ל:"],["\u0003קנה אתרוג שראוי לצאת כו'\u0004 בפ\"ק דב\"ק א\"ר זירא ולהידור מצוה עד שליש במצוה במערבא אמרי משמיה דרבי זירא עד שליש משלו מכאן ואילך משל הקב\"ה והרי\"ף הביאו בפרק לולב הגזול גם הרא\"ש הביאו לשם וכתב עד שליש במצוה פי' אם קנה לולב ונזדמן לו אחר יפה יותר יוסיף עד שליש בדמי הראשון להחליפנו ביפה עכ\"ל ובב\"ק כתב בע\"א וז\"ל עד שליש במצוה אם מצא אתרוג שהוא ראוי לצאת בו שהוא כאגוז יוסיף שליש לקנות יפה ממנו לא שהוא מחוייב לקנות אתרוג יפה ממנו אלא שיימינן בתוס' שליש על האתרוג שחפץ לקנות עכ\"ל וכדי ליישב דבריו דלא ליסתרו אהדדי נראה בעיני לבאר שלא היתה כוונתו בב\"ק לומר דדוקא בחפץ לקנות ועדיין לא קנה ונזדמן לו אתרוג בדינר הוא דקונה יפה ממנו בדמים שליש יותר ממה שהיה קונה זה אבל משקנה כבר אינו מחויב לקנות יפה ממנו וכדמשמע מפרש\"י בב\"ק דלדעת הרא\"ש ודאי אין חילוק וכמ\"ש בפ' לולב הגזול אם קנה לולב וכו' דאפילו קנה כבר מחוייב להוסיף שליש להחליפנו ביפה אלא כך היתה כוונתו בב\"ק כשחפץ לקנות אתרוג והסכים בדעתו לקנותו בסלע או בדינר בין קנה ובין לא קנה עדיין ואח\"כ מצא אתרוג יפה ממנו בדמים שהסכים בדעתו מתחילה מוסיף שליש על אותן הדמים אבל אם כבר הוסיף שליש על מה שהיה חפץ מתחלה שוב א\"צ להחליפנו באחר אפילו מצא נאה ממנו וז\"ש הרא\"ש לא שהוא מחוייב לקנות אתרוג יפה ממני וכו' כלומר לא שהוא מחוייב עכ\"פ לקנות אתרוג יפה מזה שבידו שקנה או שרצה לקנותו ויוסיף שליש מדמיו אלא שיימינן בתוספת שליש על אתרוג שהיה חפץ לקנותו בכך וכך בין שקנה כבר באותן הדמים בין לא קנה עדיין יוסיף שליש על אותן הדמים ויקנה יפה ממנו כנ\"ל לפרש דברי הרא\"ש בזה ומאי דנקט הרא\"ש כאגוז דבר ברור הוא דלדוגמא בעלמא נקטיה אליבא דר\"מ דהא אנן קי\"ל כר' יהודה דבעינן כביצה ומיניה נשמע שאם קנה אתרוג בכביצה מוסיף שליש לקנות יפה ממנו וה\"ה אם היה גדול מכביצה נמי יש לו להוסיף שליש על מה שהיה חפץ לקנות מתחלה לדעת הרא\"ש והא דנקט הרא\"ש שיעורא דאתרוג אינו אלא לאורויי לן שלא נתנו רז\"ל שיעור שליש אלא בשקנה אתרוג שראוי לצאת בו או נזדמן לפניו לקנותו או יוסיף שליש על מה שהיה חפץ לקנות אבל אם לא היה האתרוג כשיעור לר\"מ בכאגוז ולר\"י בכביצה פשיטא דצריך להוסיף יותר משליש כדי לקנות אתרוג הראוי לצאת בו אבל שיעור שליש על אתרוג שראוי לצאת בו אין חילוק בין כביצה לגדול הרבה יותר מכביצה לעולם צריך להוסיף שליש על מה שהיה חפץ לקנות וכך הם דברי רבינו שכתב קנה אתרוג שראוי לצאת בו וכו' כלומר לאפוקי אם אינו ראוי לצאת בו אפילו קנה אותו כבר יוסיף יותר כדי שיברך על אתרוג כשר אלא כשראוי לצאת בו אז נתנו חז\"ל שיעור שליש להוסיף בדמי הראשון כדי להחליפו ביותר נאה ולא חילק בין אם הראשון הוא כביצה בין יותר גדול מכביצה לעולם צריך להוסיף שליש וה\"ה אפילו לא קנה עדיין צריך להוסיף אלא רבותא נקט אפי' קנאו כבר צריך להחליפנו ולהוסיף שליש ומכל שכן כשלא קנה עדיין יוסיף שליש על מה שהיה חפץ לקנות כן נראה לי לפרש דברי הרא\"ש ודברי רבינו להסכימו עם דברי הרא\"ש ודלא כמו שפי' הב\"י דלדעת הרא\"ש ורבינו אם הוא יותר גדול מכביצה א\"צ להוסיף כל עיקר וכמ\"ש הסמ\"ג בשם ה\"ר יעקב דודאי דעת הרא\"ש בפרק לולב הגזול ודברי רבינו שבכאן אין מורין כן ונסחא מוטעת נזדמנה להרב ז\"ל בדברי הרא\"ש בב\"ק שוב מצאתי שר' ירוחם הבין דברי הרא\"ש בב\"ק כפשטן דשיעור שליש אינו אלא בחפץ לקנות ולא קנה עדיין אבל אם כבר קנה א\"צ להוסיף כל עיקר ובפרק לולב הגזול כתב פירוש אחר דאפילו אם כבר קנה מחוייב להוסיף שליש והוא חולק אאותו פירוש שכתב בב\"ק שהוא פירושו של רש\"י והתוס' ואם כך היה דעת רבי' ג\"כ צ\"ל דס\"ל לרבי' דהעיקר הוא מ\"ש בפרק לולב הגזול שהוא מקום הלכות אתרוג ולולב והוא אחרון ולכך כתב באותו פי' ולפי זה לעולם צריך להוסיף שליש על מה שקנה כבר אפילו הוא יותר על מה שהסכים בדעתו מתחלה לקנות אתרוג כשר בכך וכך משמע פשט לשון רבינו שסתם ולא חילק וכך יש לתפוס לחומרא נ\"ל. ודע דבגמרא איבעיא לן אי לא בעינן אלא שליש מלגאו או בעינן שליש מלבר ולא איפשיטא. והרי\"ף והרא\"ש בפ' לולב הגזול מסתם לה סתומי נראה מדבריהם דס\"ל למינקט לחומרא וכך פי' הר\"ן לשם דעת הרי\"ף וכך נראה דעת רבינו שכתב בסתם אבל מדברי הרא\"ש דפ\"ק דב\"ק נראה דלא בעינן אלא שליש מלגאו וכך פסק ה\"ר ירוחם בני\"ג אבל דעת רבי' דדברי הרא\"ש סתרי אהדדי גם בהא פסק לחומרא דבעינן שליש מלבר כמו שנראה מדבריו בפרק לולב הגזול מקום הלכות לולב שהוא העיקר והאחרון כמ\"ש בסמוך ודע דאההיא דעד שליש משלו מכאן ואילך משל הקב\"ה פירש\"י משלו שאינו נפרע לו בחייו כדאמר היום לעשותם ולא היום ליטול שכרם אבל מה שיוסיף יותר על שליש יפרע לו הקב\"ה בחייו וכה\"ג כתבו התו' וז\"ל משל הקב\"ה אוכל פירות בעה\"ז והקרן קיימת לו לעולם הבא עכ\"ל אבל הנ\"י בפ\"ק דב\"ק כתב וז\"ל עד שליש משלו כלומר צריך להוסיף שליש מיגיעו ודוחק את חייו כדי להדר את המצוה מכאן ואילך משליש ולמעלה אם זימן לו הקב\"ה ממון שלא מיגיעו יוסיף ואם לאו חייו קודמין ודיו בתוספת שליש וכתב הרמ\"ה ז\"ל מסתברא דה\"ה אם העשיר מיגיעו והרי הוא יכול להוסיף יתר על שליש ואין חייו נדחקין בכך כזימן לו הקב\"ה שלא מיגיעו דמי כענין שנאמר כי הוא הנותן לך כח לעשות חיל עכ\"ל והר\"ן בפרק לולב הגוזל כתב מכאן ואילך משל הקב\"ה כלומר לוו עלי ואני פורע וכו' עכ\"ל: גרסינן בברייתא בס\"פ לולב הגזול ר\"ג לקח אתרוג באלף זוז ובגמרא למה לי למימר שלקחו באלף זוז להודיעך כמה מצות חביבות עליהן ולא קשיא מדר' זירא הידור מצוה עד שליש ולא יותר דהא אמרינן מכאן ואילך משל הקב\"ה ולכל הפירושים שפיר עביד ואפי' לא היה עשיר ומק\"ו שהיה ר\"ג עשיר ונשיא וברירא מילתא דלאו גוזמא קאמר אלא אלף זוז ממש מדקאמר להודיעך כמה מצות חביבות עליהן נ\"ל אבל הרא\"ש בב\"ק כ' מדקאמר בגמ' במצוה עד שליש מאי שליש אילימא שליש ביתו אלא מעתה אי איתרמי ליה תלתא מצוה ליתיב לכולא ביתא שמעינן שאין אדם מחוייב לבזבז הון רב בשביל מצוה אחת ואפילו היא מצוה עובר' כגון אתרוג ולולב ותלמוד' חשיב גוזמא על ר\"ג שהיה נשיא מישראל מה שנתן אלף זוז באתרוג אחד וגם תיקנו חכמים המבזבז אל יבזבז יותר מחומש עכ\"ל נראה מדבריו דס\"ל דלא לקחו באלף זוז אלא לפי שלקחו ביותר אמר דרך גוזמא שלקחו באלף זוז וכ\"כ ה\"ר ירוחם וז\"ל ואפילו היא מצוה עוברת אל יבזבז יותר מחומש והא דר\"ג גוזמא הוה עכ\"ל ותימה בעיני מי הגיד להם דאלף זוז היה טפי מחומשו דר\"ג דילמא עשיר גדול היה ועוד דפירש זוז בכל מקום הוא של מדינה ולא של צורי ואינו אלא שמינית מצורי. לכן נראה עיקר דגוזמא דכתב הרא\"ש לאו גוזמא כפשטא קאמר אלא מלשון רבותא הוא שבא הרא\"ש להכריח מר\"ג נמי שאין אדם מחוייב מדינא לבזבז הון רוב אפי' בשביל מצוה עוברת דאל\"כ מאי רבותא דר\"ג שאמרו עליו בגמרא להודיעך כמה חביבות מצות עליהן הלא במצוה עוברת כמו סוכה ולולב ואתרוג וכה\"ג דינא הכי הוא אלא ודאי מדחשיב ליה תלמודא גוזמא על ר\"ג כלומר רבותא ודבר גדול אלמא דמדינא לא היה חייב לקנותו אפי' לגבי מצוה עוברת משום דאלף זוז לגבי דר\"ג היה יותר מחומשו ואפ\"ה היתה המצוה חביבה עליו ול\"ק היאך עבר ר\"ג על מ\"ש אל יבזבז יותר מחומש דאיכא למימר כיון דטעמא לא הוי אלא שלא יבא לידי עוני ויפיל עצמו על הצבור בנשיא ליכא למיחש להכי דבלאו הכי כל צרכיו של נשיא מוטל על הצבור ואף להעשירו מדרשת והכהן הגדול מאחיו גדלהו משל אחיו ודוקא במי שאינו נשיא אמרו אל יבזבז וכו' דמדינא אסור לו לבזבז הון רב ביותר מחומש אפילו במצוה עוברת וכך היא גם דעת רבינו ירוחם למעיין בו גם התו' שמהם למדו הרא\"ש וה\"ר ירוחם דין זה כתבו להדיא וז\"ל ובסוכה חשיב ליה רבות' דר\"ג שקנה אתרוג באלף זוז ע\"כ כל זה לשיטת התו' והנמשכים אחריהם אבל מדברי הר\"ן יראה דר\"ג שאני דעשיר גדול היה שהרי כתב וז\"ל משמע דאפילו למצוה עוברת כאתרוג ולולב אינו מחוייב לתת אפילו שליש ממוניה וכו' ומיהו כל חד וחד מחויב ליתן כפום ממוניה כדי לקיים מ\"ע כר\"ג שלקח אתרוג באלף זוז עכ\"ל: וכתב עוד בשם הראב\"ד דה\"ט דאינו מחוייב לתת אפילו שליש ממונו למצוה עוברת כדי שלא יבא לידי עוני ויפיל עצמו על הצבור וכו' מיהו מסתברא דלא אמרינן הכי אלא במצות עשה משום דשב ואל תעשה שאני אבל במצות ל\"ת את כל הון ביתו יתן קודם שלא יעבור עליה וכ\"כ הב\"י בשם הרשב\"א ואיכא למידק דמדקאמר ביומא ופ' בן סורר ומורה אם נאמר בכל נפשך למה נאמר בכל מאודך לפי שיש אדם שחביב עליו ממונו מגופו לכך נאמר בכל מאודך והתם בע\"ג קאמר דיהרג ואל יעבור ומשמע דבשאר ל\"ת אין לו להפסיד כל ממונו וי\"ל דאדרבה משם ראיה דאל\"כ מאי קשיא למה נאמר בכל מאודך הא איצטריכא ליה ללמד דדוקא משום ע\"ג יפסיד כל ממונו ולא יעבור אבל שאר מצות ל\"ת יעבור ולא יפסיד אלא ודאי דאין חילוק ולכך קא קשיא למה נאמר בכל מאודך ועיין במ\"ש הריב\"ש בסי' שפ\"ו ועיין עוד בי\"ד בסי' קנ\"ז:"]],["\u0010c0\u0011\u0010y0\u0011קטן היודע לנענע הלולב אביו צריך לקנות לו לולב כדי לחנכו במצות:",["\u0003קטן היודע לנענע הלולב אביו צריך לקנות לו לולב וכו'\u0004 משנה בסוף פרק לולב הגזול (סוכה מב.) ואיתא בירושלמי לא סוף דבר לנענע אלא מוליך ומביא מעלה ומוריד כשורה ומנענע:"],["\u0003קטן היודע לנענע וכו'\u0004 משנה וברייתא ס\"פ לולב הגזול קטן היודע לנענע חייב בלולב ומהרש\"ל השיג על לשון רבי' שכתב חייב לקנות לו לולב הלא בהדיא שנינו חייב בלולב ולא נאמר שם צריך לקנות לו לולב כמו שאמרו גבי תפילין לשמור תפילין אביו לוקח לו תפילין וכן למקצת גאונים גבי ציצית גורסין אביו קונה לו ציצית אבל בלולב תנן חייב בלולב והטעם פשוט שא\"צ לקנות לו לולב בפני עצמו כי לאחר שיצא בו אביו יתננו לבנו לברך עליו מה שאין כן בתפילין ודו\"ק עכ\"ל ואפשר לומר דלמאי שכתב בסי' תרנ\"ב דהמדקדק במעשיו יעשה כאנשי ירושלים כו' א\"כ צריך לקנות לו לולב דהא שייך הכא נמי הך טעמא דשייך גבי תפילין ומשנה וברייתא דנקטו חייב בלולב איירי דוקא בסתם בני אדם וק\"ל:"]],["\u0010c0\u0011\u0010y0\u0011מן התורה לולב ניטל במקדש כל ז' וחוץ למקדש רק יום ראשון וחכמים תקנו שיהא ניטל בכל מקום כל ז' ימים \u0010y1\u0011אבל בשבת אינו ניטל בכל מקום לא שנא אם חל יום ראשון בשבת או אחד משאר הימים \u0010c1\u0011\u0010y2\u0011הלכך ביום ראשון שהוא מן התורה אין אדם יוצא בלולב של חבירו אא\"כ יתננו לו במתנה גמורה דדרשי' ולקחתם לכם ביום הראשון משלכם \u0010c2\u0011אבל אם נתנו לו במתנה ע\"מ להחזירו לו אחר כך הוא מתנה \u0010c3\u0011ובלבד שיתננו לו במתנה גמורה ע\"מ להחזיר לו במתנה אבל אם אמר לו יהא שלך עד שתצא בו ואח\"כ תחזירהו לי לא יצא \u0010c4\u0011וצריך שיחזירנו לו אח\"כ לקיים תנאו אבל אם לא החזירהו אח\"כ הרי לא קיים תנאו ונמצאת המתנה בטילה למפרע ולא יצא ואפי' נאנס מידו בענין שאינו יכול להחזירו ורוצה להחזיר לו דמיו לא יצא ואפי' נתנו לו סתם ולא פירש ע\"מ שתחזירהו לי מסתמא דעתו שיחזירנו לו כיון שצריך לצאת בו ואם לא החזירהו לו לא יצא ומיהו אפי' לא החזירו לידו אלא לאחר ואחר לאחר והאחרון מחזירו לבעליו יצא \u0010y3\u0011וי\"א שא\"צ להחזירו לו אא\"כ כפל תנאו שאומר לו הרי הוא לך במתנה ע\"מ שתחזירהו לי ואם לא תחזירהו לי לא ליהוי מתנה שאם לא כפל תנאו הוי תנאה דהיינו החזרה בטל ומעשה דהיינו המתנה קיים ויצא בו אפי' לא החזיר לו \u0010y4\u0011אבל לפי מה שכתב דאפי' בסתמא צריך להחזירו לו כ\"ש אם התנה ולא כפל \u0010c5\u0011\u0010y5\u0011ומטעם זה דבעינן משלכם לא ליקני איניש לולבא לקטן ביומא קמא דקטן מקני קני אקנויי לא מקני ונמצא שאין א' יכול לצאת בו אחר שהגיע לידו: \u0010y6\u0011אחין או שותפין שיש להן אתרוג בשותפות אם יכול אחד מהן לאכלו ואין חבירו מקפיד עליו יוצא בו דחשיב כשלו ואם לאו לא יצא שאין השותפין יכולין לצאת באתרוג המשותף עד שיתן לו חבירו חלקו במתנה \u0010y7\u0011ומה שנוהגין במקום שאין אתרוג מצוי שכל הקהל קונין אתרוג בשותפות ויוצאין בו פירשב\"ם שכיון שקנאוהו כדי לצאת בו מסתמא הוי כאילו פירשו שכל הקהל נותנין חלקם לכל מי שנוטל לצאת בו ע\"מ שיחזירהו להם כיון דבענין אחר אין יכולין לצאת בו: \u0010y8\u0011תשובה לרב שרירא מקום שאין אתרוג ולולב מצויין וגובים מהקהל מכל א' וא' וקונין ונוטלו חזן הכנסת בידו בשעת ההלל ומברך עליו ונותנו לזקנים ומברכין עליו ושוב נוטלו כל אחד מחבירו עד שמברכין עליו כל הקהל יצאו ידי חובתן או לא והשיב ודאי בשאר ימות החג מיום ב' והלאה יצאו ידי חובתן באותו לולב אבל ביום הראשון צריך כל א' לולב שלו וכן ראוי שתעשו להיות קונין הלולב לא' מן הצבור או שיקחנו מממונו או שיתנו הדמים לחזן במתנה והוא יקנהו לעצמו ובי\"ט הראשון יתנו במתנה לא' מן הזקנים וכל אחד יתנהו לחבירו במתנה עד שיבא ליד כולם ובאשכנז ובצרפת נוהגים כרשב\"ם:",["מן התורה לולב ניטל במקדש כל ז' וחוץ למקדש רק יום ראשון וחכמים תקנו שיהא ניטל בכל מקום כל ז' הימים משנה בפרק לולב הגזול (סוכה מא.) ובפרק בתרא דר\"ה (ל:) בראשונה היה לולב ניטל במקדש ז' ובמדינה יום אחד משחרב בה\"מ התקין ריב\"ז שיהא לולב ניטל במדינה ז' זכר למקדש ופירש\"י במקדש ז' כדדרשי' בת\"כ מושמחת' לפני ה' אלהיכם שבעת ימים ולא בגבולין ז' ימים:","ומ\"ש אבל בשבת אינו ניטל בכ\"מ לא שנא אם חל יום ראשון בשבת או אחד משאר הימים היינו דוקא אחר שחרב בה\"מ אבל בזמן שבה\"מ קיים אף ע\"פ שכשחל אחד משאר הימים בשבת לא היה ניטל בשבת כשחל יום א' בשבת היה ניטל בשבת בין במקדש בין כל היכא דבקיאי בקיבועא דירחא דתנן בפ' לולב וערבה י\"ט ראשון של חג שחל להיות בשבת לולב ז' ושאר כל הימים ו' ופירש\"י לולב שבעה די\"ט ראשון דחי שבת ושאר כל הימים שחל בהם יום ראשון ונמצא שבת בחש\"מ לא דחי ובגמ' אמאי טילטול בעלמא הוא ולידחי שבת אמר רבא גזרה שמא יטלנו בידו וילך אצל בקי ללמוד ויעבירנו ד\"א בר\"ה אי הכי יום ראשין נמי ראשון דאיתיה מן התורה בגבולין לא גזרו ביה רבנן הנך דליתנהו מן התורה בגבולין גזרו בהו רבנן אי הכי האידנא נמי אנן לא ידעינן בקביעותא אינהו דידעי בקביעא דירחא לידחו אה\"נ דתני חדא בי\"ט ראשון של חג שחל להיות בשבת כל העם מוליכין לולבם להר הבית ותניא אידך לבהכ\"נ ש\"מ כאן בזמן שב\"ה קיים כאן בזמן שאין בית המקדש קיים ש\"מ ובתר הכי אסיקנא דליתא אלא לדידהו נמי לא דחי ולא קשיא הני תרתי דתני הכא חדא כל העם מוליכין לולביהם להר הבית ותניא אידך לבה\"כ ומתרצים כאן בזמן שבית המקדש קיים כאן בזמן שאין ב\"ה קיים לא אידי ואידי בזמן שב\"ה קיים ול\"ק כאן במקדש כאן בגבולין ופירש\"י בגבולין מוליכין לב\"ה וכולהו בזמן הבית דהוו כולהו בארץ סמוכין להיות ב\"ד ויודעים אימת הוקבע החודש אבל עתה משחרב ב\"ה אין לולב דוחה שבת אפי' לבני א\"י:","הלכך ביום ראשון שהוא מן התורה אין אדם יוצא בלולבו של חבירו פי' כיון דחוץ למקדש נמי יום ראשון הוא מן התורה דקרא דולקחתם לכם ביום הראשון בגבולין נמי משמע א\"כ אין אדם יוצא בלולבו של חבירו ודין זה מפורש במשנה בפרק לולב הגזול י\"ט הראשון של חג אין אדם יוצא י\"ח בלולבו של חבירו ובגמרא מנא ה\"מ דת\"ר ולקחתם לכם משלכם להוציא את השאול ואת הגזול מכאן אמרו אין אדם יוצא י\"ח בלולבו של חבירו אא\"כ נתנו לו במתנה ומעשה בר\"ג ורבי יהושע ור\"א בן עזריה ור\"ע שהיו באים בספינה ולא היה לולב אלא לר\"ג בלבד שלקחו באלף זוז נטלו ר\"ג ויצא בו ונתנו לרבי יהושע במתנה נטלו ר' יהושע ויצא בו ונתנו לר\"א בן עזריה במתנה נטלו ר\"א בן עזריה ויצא בו ונתנו לר\"ע במתנה נטלו ר\"ע ויצא בו והחזירו לר\"ג ל\"ל למימר החזירו מלתא אגב אורחיה קמ\"ל מתנה ע\"מ להחזיר שמה מתנה כי הא דאמר רבא הא לך אתרוג זה ע\"מ שתחזירהו לי נטלו ויצא בו החזירו יצא לא החזירו לא יצא וכתב הרא\"ש על זה וכן היתה מתנת ר\"ג ולהכי תנא והחזירו לר\"ג דאם לא החזירהו לו לא יצאו אע\"פ שכל א' לא החזירו לר\"ג כן היתה המתנה שכ\"א יתנהו לחבירו ויחזור הוא לבסוף וצריך שיתנהו לו במתנה גמורה ע\"מ שיחזור ואחר שיצא בו צריך לחזור וליתנו לו במתנה בשעת חזרה אבל אם אמר לו יהא שלך עד שתצא בו ואח\"כ יהא שלי כבתחלה לא יצא בו דהוי כמו שאול ותדע מדאמרינן לקמן לא ליקני איניש לולבא לינוקא בי\"ט דינוקא מקני קני אקנויי לא מקני ואם א\"צ לחזור לו במתנה נהי דקטן לאו בר אקנויי הוא ליקניה ליה עד שיצא בו ולחזור לו ממילא א\"ו צריך לחזור וליתנו לו במתנה וקטן לאו בר אקנויי הוא כתב בעל העיטור מסתבר כיון שהמקבל מתנה יודע שהנותן אין נותן במתנה גמורה שהרי צריך הוא עדיין לו לצאת בו שאין לו לולב אחר א\"צ לפרש לו ע\"מ להחזיר לו אלא נותן לו סתם והמקבל מחזיר לו סתם וא\"צ לתנאי דהא ר\"ג נתן במתנה ולא אמר לו ע\"מ להחזיר אלא כיון שלקחו ר\"ג לצאת בו ולא היה לו אחר מסתמא ע\"מ להחזירו נתנו ע\"כ ודבר פשוט הוא דלענין לצאת בו יותר טובה מתנה ע\"מ להחזיר אלא שבא לחדש דאפילו במתנה סתם הוא ע\"מ להחזיר ואם לא החזירו לו לא יצא ואם גזל ממנו ולא החזירו כתב בעל העיטור מסתברא אע\"ג דחזרת דמים הוי חזרה כדאמרי' גבי איצטלית דאמרינן תתן לו את דמיה דוקא באצטלית אמרינן מה לי היא מה לי דמיה אבל אתרוג כי אמר החזירו לי דוקא אתרוג קאמר לצאת בו י\"ח ואם לא החזירו לא יצא כדאמרי' (ב\"ב קלו) גבי אחין שקנו אתרוג בתפוסת הבית אם יכול לאכלו יצא ואם לאו לא יצא דחזרת דמים לאו חזרה היא עכ\"ל וגם הר\"ן כתב יש שלמדו מכאן שהנותן לולב לחבירו בי\"ט ראשון סתם מתנה ע\"מ להחזיר הוא ואומדנא דמוכח היא אע\"פ שלא פירש דאין אדם מתרוקן ממצותו ונותן לאחרים דהא הכא סתם נתנו להן ר\"ג ואפ\"ה אמרי' דקמ\"ל במתנה ע\"מ להחזיר שמה מתנה ועל זה סמכו ליתן כל אדם לולבו לחבירו בי\"ט סתם וטעמא דמסתבר הוא אע\"פ שאין כאן ראיה מוכרחת וכתב עוד מסתבר דכי אמר החזירו יצא דוקא בשהחזירו בענין שיכול עדיין לצאת בו הא אם החזירו לאחר שעברה מצותו לא יצא דאומדן דעתא הכי הוי וחזרת דמים הכא לאו חזרה הוא ודאי דאלולב קפיד: ואיכא למידק אהא דאמר רבא הילך אתרוג זה ע\"מ שתחזירהו לי נטלו ויצא בו החזירו יצא דכיון דאינו יוצא בו אלא כשקיים תנאו היאך יצא בו הא באותה שעה שהחזירו אינו בידו וליכא למימר דכשאמר מעכשיו מיירי דכשהחזירו וקיים תנאו איגלאי מלתא למפרע דהויא מתנה מעיקרא דא\"כ הו\"ל לפרושי למלתיה וי\"ל דרבא ס\"ל דכל האומר ע\"מ כאומר מעכשיו דמי כ\"כ התוס' בפרק מי שאחזו (גיטין עה:) וא\"ת היכא דלא החזירו אמאי לא יצא הא תנאי ומעשה בדבר אחד הוא והתנאי בטל ומעשה קיים כדאמרינן בפרק מי שאחזו תירצו התוס' בפרק י\"נ דרבא סבר לא בעינן תנאי בדבר אחד ומעשה בדבר אחר א\"נ שאני התם דס\"ל כל האומר ע\"מ לאו כאומר מעכשיו דמי ונמצא שאינה מגורשת עד שמחזרת הנייר ואז אינו שלה וסותרין זה את זה התנאי והמעשה אבל רבא דס\"ל כל האומר ע\"מ כאומר מעכשיו דמי לא סתרי אהדדי:","\u0003ומ\"ש רבינו וי\"א שא\"צ להחזירו לו אלא א\"כ כפל תנאו וכו'\u0004 הג\"מ כתב בשם סמ\"ג וז\"ל א\"נ צריך שיאמר ע\"מ שתחזירהו לי הרי הוא לך במתנה ואם לאו לא יהא שלך אלא שלא חש להאריך ע\"כ והקשה הרמ\"ך דאדרבה אם לא יהא בתנאי כל זה כ\"ש שהמתנה טובה והתנאי בטל אפילו אם לא יחזיר וצ\"ע עכ\"ל:","ומ\"ש רבינו אבל לפי מה שכתבתי דאפילו בסתמא צריך להחזירו לו כ\"ש אם התנה ולא כפל פשוט הוא דהא ודאי ליכא למימר דטפי עדיף כי לא אתני כלל מכי אתני ולא כפליה לתנאיה דכיון דמשום דאזלינן בתר אומדן דעתא הוא דאמרינן דאם לא החזירו לא יצא אע\"פ שלא הזכיר החזר' כשהזכירו ודאי לא מיגרע גרע והלכך אע\"ג דלא כפליה לתנאיה אם לא החזירו לא יצא: כתב הרוקח בנדרים פ' השותפין מתנה שאם הקדישה אינה מקודשת לא שמה מתנה על כן יאמר לחברו אתרוג זה נתון לך במתנה ע\"מ שתרזירהו ולא יאמר לי עכ\"ל ויש לתמוה עליו דא\"כ רבא דנקט הילך אתרוג זה ע\"מ שתחזירהו לי לאו דוקא נקט לי והר\"ן כתב בפ' הנזכר כל מתנה שאם הקדישה אינה מקודשת אינה מתנה כלומר דנהי דמתנה ע\"מ להחזיר שמה מתנה אע\"ג דאם הקדישה אינה מקודשת וכדאמרי' בפ' יש נוחלין שאני התם דמ\"מ לשעת' מתנה היא אבל מתנה זו של בית חורון אפי' לשעתה אינה שלא נתכוון להקנותה לו כלל אלא שתקרא על שמו כדי שיהא אביו מותר בה עכ\"ל:","\u0003ומטעם זה דבעינן משלכם לא ליקני איניש לולבא לקטן ביומא קמא וכו'\u0004 מימרא דרבי זירא בפרק לולב וערבה (סוכה מו.) ופירש\"י מקני קני דרבנן תקיני ליה זכייה לנפשיה אקנויי לא מקני אינו יכול לחזור ולהקנותו לאביו במתנה דלאו בר דעת הוא וכ' הר\"ן דבתינוק שלא הגיע לעונת הפעוטות מיירי דזוכה לעצמו ואינו מזכה לאחרים דאי פשהגיע לעונת הפעוטות כבן ו' או כבן ז' אקנויי נמי מקני דהא קי\"ל הפעוטות מקחן מקח וממכרן ממכר במטלטלין ומסקינן נמי בהניזקין (נט.) דמתנתו מתנה וא\"ת והא איהו ע\"מ להחזיר יהביה ניהליה ואי אקנויי נמי לא מקני ולא מצי לאהדורי נמצא מתנתו בטילה ליתא דהא קי\"ל דכל תנאי דא\"א להתקיים בסופו והתנה עליו בתחלה תנאו בטל ונמצא שהקטן קנאו ואע\"פ שאינו יכול להחזירו עכ\"ל: \u0005ב\"ה ומדברי הרמב\"ם נראה דאפי' בהגיע לעונת הפעוטות מיירי:\u0006 וכתוב במרדכי ובהג\"א בשם א\"ז שאם תופס עם התינוק כיון שלא יצא מידו לגמרי שפיר דמי ובקיאי הדעת מחזירין אותו למקומו והתינוקות מעצמם נוטלין אותו ומברכין עליו:","\u0003אחין או שותפין שיש להם אתרוג בשותפות וכו'\u0004 בפרק יש נוחלין (בבא בתרא קלז.) אמר רבה ב\"ר הונא האחין שקנו אתרוג בתפוסת הבית נטלו א' מהן ויצא בו אם יכול לאכלו יצא ואם לאו לא יצא ופרשב\"ם שקנו אתרוג ירשו מאביהם או לקחו במעו' ירושת אביהם בתפוסת הבית כל זמן שלא חלקו ונטלו אחד מן האחין בלא דעת חבירו ויצא בו רואין אם אין האחין מקפידין זה על זה ויכול לאכלו בלא רשותא כגון שיש אתרוגים הרבה בתפוסת הבית או שימצאו הרבה אתרוגים בעיר או שכבר יצאו ואין צריכין לו עוד יצא דקרינן בו לכם שהרי כולו שלו הוא ואם לאו לא יצא דכתיב ולקחתם לכם משלכם שיהא כולו שלו ולא מקצתו שלו והרי\"ף והרא\"ש הביאו מימרא זו בפרק לולב הגזול וכתבו עליה ש\"מ דהני בי תרי דזבני לולב בשותפות לא נפקי ביה ידי חובתייהו ביומא קמא עד דיהיב חד לחבריה מנתא דיליה ואי לא לא נפיק וכ\"כ הרמב\"ם ז\"ל:","ומ\"ש רבינו ומה שנוהגין במקום שאין אתרוג מצוי שכל הקהל קונין אתרוג בשותפות ויוצאין בו פרשב\"ם כיון שקנאוהו לצאת בו מסתמא הוי כאילו פירש וכו' כ\"כ בפ' י\"נ והביא הרא\"ש בפרק לולב הגזול:","ומ\"ש בשם תשובת רב שרירא עד סוף הסימן כתבו הרא\"ש בפרק לולב הגזול והחילוק שבין דעת רשב\"ם לדעת רב שרירא פשוט דלרשב\"ם א\"צ להקנותו לשום אדם אלא גובין סתם וקונין אותו סתם ונוטלו אחד מהם ויוצא בו ונותנו לחבירו ויוצא בו ונותנו לחבירו וכן כולם ולרב שרירא צריך להקנות בפירו' הדמים או הלולב לאחד מן הקהל ויוצא בו ואח\"כ יתנהו במתנה לחבירו ויוצא בו ונותנו לחבירו עד שיבא לידי כולם וה\"ה כ' בשם הרשב\"א מסתברא לי דהא דאחין בשלא לקחוהו לצאת בו הוא אלא לאוכלו ולהריח בו אבל לקחוהו לצאת בו ודאי בכל גוונא יוצאין בו דאמרינן יש ברירה שהרי בשעה שלקחוהו היו יודעין שאינו ראוי ליחלק ועל דעת כן לקחוהו שבשעה שיטלנו כל אחד מהן לצאת בו שיהא כולו שלו דומיא דשותפין שנדרו הנאה זה מזה שהן נכנסין לחצר שניהם שאין בה דין חלוקה כמו שמבואר בח\"ז מה' נדרים והטעם שיש ברירה שכשלקחוהו על דעת כן נשתתפו שבשעה שכל אחד מהן נכנס יהא מקום דריסתו שלו אף בלולב כיוצא בו ואינן צריכין להקנות עכ\"ד ואפשר שעל דעת זה סמכו בהרבה מקומות שלוקחים לולב אחד וכל הקהל יוצאים בו בין בראשון בין בשני עכ\"ל: והיכא דשנים שותפים באתרוג א' ואחד מהם אינו רוצה לוותר חלקו לחבירו ולא נמכרו לו חבירו אומר או מכור לי חלקך או קנה לך חלקי (והלה אינו רוצה) לפי שרוצה להפסידו עליו: ודע דבהאי מימרא דאחין שקנו אתרוג בתפוסת הבית מסיים בגמרא ודוקא אתרוג אבל פריש או רמון לא וכתב רשב\"ם דלא גרסינן ליה אבל הרי\"ף גריס ליה בפרק לולב הגזול וכתב הר\"ן אם יכול לאכלו לפי שיש שם אתרוגים אחרים ומגיע זה לחלקו יצא דכדידיה דמי וכ\"ת ואפי' יש שם אתרוגים אחרים מאן פלג ליה י\"ל דהכא באחין שאינם מקפידין זה על זה עסקי' והלכך כיון שאף להם יש אתרוגים אפילו נטל זה היפה אין מקפידין בכך אבל אם אין להם אלא או פריש או רמון ודאי מקפידין הם שאף הם רוצים לקיים מצוה כמוהו וגם הרמב\"ם נראה שהיה גורס כגירסת הרי\"ף שכתב וז\"ל האחין שקנו אתרוגים בתפוסת הבית ונטל אחד מהם אתרוג ויצא בו אם יכול לאוכלו ואין האחים מקפידין בכך יצא ואם היו מקפידין לא יצא עד שיתנו לו חלקו במתנה ואם קנה זה אתרוג וזה פריש או שקנו כאחד אתרוג ורימון ופריש מתפוסת הבית אינו יוצא באתרוג עד שיתן לו חלקו במתנה ואע\"פ שאם אכלו אין מקפידים עליו באכילתו עכ\"ל וביאר ה\"ה דכל שאין שם אתרוגים אחרים אע\"פ שאין מקפידין עליו באכילתו אינו יוצא בו לפי שכל שאין שם מאותו המין אין מחילתן בסתם מועלת אבל בשיש שם מאותו המין אפי' היה זה מעולה מן האחרים מחילתן מועלת לפי שאינן מקפידין עכ\"ל ודבריו כדברי הר\"ן ז\"ל :"],["\u0003מן התורה וכו'\u0004 אבל בשבת אינו ניטל בכל מקום כו' היינו דוקא אחר שחרב בית המקדש דאילו בזמן שבית המקדש היה קיים אם חל יום א' בשבת היה ניטל בשבת בין במקדש ובין כל היכא דבקיאי בקביע' דירח' כדאיתא ריש פ' לולב וערב' במשנה וגמרא וז\"ש ל\"ש אם חל יום ראשון בשבת או א' משאר הימים כלומר דאילו בזמן שב\"ה קיים יש חילוק בין כשחל יום ראשון בשבת או בא' משאר הימים","\u0003ומ\"ש והילכך יום ראשון שהוא מן התורה כו'\u0004 פי' כיון דחוץ למקדש הוי מן התורה וטעמא הוא משום דדרשינן ולקחתם לכם ביום הראשון ראשון אפי' בגבולים משמע כדאיתא ר\"פ לולב וערבה א\"כ אין אדם יוצא בלולבו של חבירו ביום ראשון בשום מקום אא\"כ יתננו לו במתנה גמורה שהרי כתיב לכם משמע משלכם וקאי אביו' הראשון למימרא דחיוב נטילת לולב ביום הראשון בכל מקום דוקא משלכם ודין זה מפורש במשנה וברייתא ס\"פ לולב הגזול:","ומ\"ש אבל אם נתנו לו במתנה ע\"מ להחזירו לו אח\"כ הוה מתנה שם מפורש בגמ' דמעשה דר\"ג בברייתא איירי במתנה ע\"מ להחזיר וכי הא דאמר רבא הא לך אתרוג זה במתנה ע\"מ שתחזירהו לו נטלו ויצא בו החזירו יצא לא החזירו לא יצא:","ומ\"ש ובלבד שיתננו לו במתנה גמורה ע\"מ להחזיר אבל אם אמר לו יהא שלך עד שתצא בו ואח\"כ תחזירהו לי לא יצא כ\"כ הרא\"ש וביאור דבריו דאם נותן לו במתנה גמורה ע\"מ להחזיר יצא לו האתרוג מרשות נותן לרשות מקבל לגמרי והו\"ל של מקבל אלא שהתנה עמו שיחזירהו לו אח\"כ וזה אינו אלא תנאי גרידא כאילו התנה עמו שום תנאי אחר שהרי אמר ע\"מ ואין הנותן חוזר וזוכה באתרוג אא\"כ חוזר המקבל ונותן לו האתרוג במתנה כמו שהתנה עמו אבל אם א\"ל יהא שלך עד שתצא בו וגם לא אמר ע\"מ אלא אמר ואח\"כ תחזירהו לי הרי לא יצא מרשות נותן לגמרי ואין המקבל צריך לחזור וליתן לנותן במתנה אחר שיצא דממילא הוא שלו כבתחלה אחר שיצא בו המקבל שהרי לא הקנה לו אלא כדי לצאת בו והוי כמו שאול ובלשון הרא\"ש מבואר יותר ע\"ש:","\u0003ומ\"ש וצריך שיחזירנו לו אח\"כ כדי לקיים תנאו כו'\u0004 כן היא מסקנת הרא\"ש שם דלא כה\"ר ישעיה דפטר ליה בנאנס מידו ע\"ש הטעם. ומ\"ש וי\"א דא\"צ להחזיר לו אא\"כ כפל תנאו וכו' כן נראה מדברי התו' לשם וכ\"כ הסמ\"ג כדבריהם. אבל הרא\"ש השמיט דברי התו' בזה וס\"ל דהעיקר דאזלינן בתר אומדן דעתא וכמ\"ש לשם בשם העיטור א\"כ כ\"ש אם התנה ולא כפל דאיכא נמי גילוי דעתא ועיין בתשובת הרשב\"א בסי' קפ\"ו גם הוא פסק דלא בעי תנאי כפול וכן פסק המרדכי בשם רשב\"ם ור\"ש בן חפני הכהן ושכן עמא דבר כ\"כ ראבי\"ה והכי נקטינן:","\u0003ומ\"ש ומטעם זה דבעינן משלכם כו'\u0004 מימרא דר' זירא בפ' לולב וערב' ומשמע מדברי הרא\"ש דדוקא לאקנויי לגמרי ע\"מ שיחזירהו לו לא ליקני לינוק' אבל אם אמר ליה יהא שלך עד שתצא בו ואחר כך תחזירנו לי דאינו אלא כמו שאול אצל התינוק שפיר דמי ועיין בתשובת הרשב\"א סימן ס\"ב וסי' פ\"ז:"]],["\u0010c0\u0011\u0010y0\u0011ואחר שגמרו ההלל אומר קדיש שלם ומוציאין שני ספרים בא' \u0010y1\u0011קורין שור או כשב בפ' אמור ובב' קורא המפטיר קרבנות המוספין ובחמשה עשר יום לחודש הזה ומפטיר בזכריה הנה יום בא ומחזיר הספרים ואומר קדיש ומתפללין הצבור מוסף ג' ראשונות וג' אחרונות וקדושת היום באמצע אתה בחרתנו ומפני חטאינו את מוסף יום חג הסוכות הזה וכו' כאמור ובחמשה עשר יום לחדש הזה וכו' ומחזיר ש\"צ התפלה ואומר קדיש:",["\u0003ואחר שגמרו ההלל אומר קדיש שלם ומוציאין ב' ספרים דין הוצאת ב' ספרים נתבאר בסימן תפ\"ח:\u0004 ","ומ\"ש שקורין שור או כשב או עז ומפטיר בזכריה הנה יום בא לה' פשוט בפרק בני העיר:"],["ואחר שגמר ההלל אומר קדיש שלם לפי שהוא סיום התפלה וכן בכל יום שיש קרבן מוסף אומר קדיש שלם אחר שגמרו ההלל לאפוקי חנוכה. ומ\"ש ומוציאין ב' ספרים נתבאר בסי' תפ\"ח:"]],["\u0010c0\u0011\u0010y0\u0011ואחר כך אומר הושענות ויש שאין אומרין קדיש קודם הושענא \u0010c1\u0011ונוהגין להקיף התיבה פעם א' בכל יום ומעלין ס\"ת על התיבה כשמקיפין אותה וביום השביעי מקיפין אותה ז' פעמים זכר למקדש דתנן בכל יום מקיפין המזבח פעם אחד וביום השביעי ז\"פ ואומר אנא ה' הושיעה נא אנא ה' הצליחה נא ר' יהודה אומר אני והו הושיעה נא: \u0010y1\u0011אני והו שני שמות של ע\"ב ומה שמזכירין \u0010c2\u0011\u0010y2\u0011אלו השנים על שם עמו אנכי בצרה וכתיב ואני בתוך הגולה והוא אסור בזיקים כביכול. \u0010y3\u0011וגם אני והו בגי' אנא ה' \u0010c3\u0011ובירוש' איתא זכר ליריחו \u0010c4\u0011ורב סעדיה כתב שמקיפין מיד אחר קריאת ההפטרה בעוד הספר על התיבה ומנהג טוב הוא כדי שלא להוציא הספר שלא לצורך כיון שאין קורין בו אלא שאין נוהגין כן \u0010c5\u0011\u0010y4\u0011וסדר ההקפה כ' רב האי בכל יום ב\"פ א' לימינו וא' לשמאלו וביום הז' ג\"פ לימינו וג\"פ לשמאלו ואחד לימינו ואין נוהגין כן עתה אלא בכל יום אחד לימינו \u0010c6\u0011ובשבת אין מקיפין \u0010y5\u0011כ' רש\"י דאף בחול מי שאין לו לולב לא יקיף כמו בשבת שאין מקיפין כיון שאין לו לולב וכ' רב שרירא גאון שאין לומר הושענא בשבת מפני התינוקות שישמעו שאומרים בשבת כמו בחול וילכו גם ליטול הלולב אבל כשאין אומרים הושענא מתברר להם. ונראה דכיון שאין מקיפין בשבת מתברר להם במה שאין מקיפין וא\"צ למנוע מלומר הושענא וכ\"כ ב\"ה \u0010c7\u0011ואומר קדיש ונפטרין לבתיהם:",["\u0003אח\"כ אומר הושענא וכו'\u0004 דתנן בכל יום מקיפין את המזבח פעם אחד וביום השביעו ז' פעמים ואומר אנא ה' הושיעה נא אנא ה' הצליחה נא רבי יהודה אומר אני והו הושיעה נא בפרק לולב וערבה (סוכה מה.):","ומ\"ש רבי' אני והו ב' שמות של ע\"ב כן פירש\"י דמע\"ב שמות הן הנקובים בג' מקראות הסמוכים ויסע ויבא ויט ושלשתן בני ע\"ב אותיות ומהם שם המפורש אות ראשון של פסוק ראשון ואחרונה של אמצעי וראשונה של אחרון וכן בזה הסדר כולם השם הא' והו וי\"ו של ויסע ה' דכל הלילה וי\"ו דויט ושם הל\"ז הוא אני אל\"ף דישראל נו\"ן ראשונה דהענן בחשבון של מפרע ויו\"ד דרוח קדים:","ומ\"ש רבינו שמזכירין אלו הב' שמות יותר מאחרים על שם עמו אנכי בצרה וכתיב ואני בתוך הגולה וכו' כ\"כ שם בתוס':","\u0003ומ\"ש וגם אני והו בגי' אנא ה' כ\"כ שם רש\"י:\u0004 ","\u0003וסדר ההקפות כתב רב האי בכל יום ב\"פ אחד לימינו ואחד לשמאלו וכו'\u0004 ואין נוהגין אלא בכל יום אחד לימינו כ\"כ ברוקח :","\u0003כתב רש\"י דאף בחול מי שאין לו לולב לא יקיף כמו בשבת שאין מקיפין וכו'\u0004 כ\"כ בהגהת אשיר\"י פ' לולב וערבה אהא דאמרינן לולב דאית ליה עיקר מן התורה יום אח' עבדי' כל ז' זכר למקדש וכו' פירש ריב\"ן ומהאי טעמא היכא דליכא לא אתרוג ולא לולב לא מקיפין סביב הבימה פעם אחד בכל יום ושבת יוכיח שאין לולב ניטל בו ולא מקיפין וכ\"כ רש\"י בתשובתו ועוד האריך בא\"ז ע\"כ ובא\"ח כתב י\"א שאין מקיפין בלא לולב וי\"א שמקיפין עכ\"ל: כתב הכלבו בסי' קי\"ד שמנהג נרבונא שאם בא לו אבל בחג הסוכות אינו מקיף בהושענא לא הוא ולא היושבים עמו ודברי תימא הם למה יפסידו ההקפה וכן נהגו להקיף אפי' האבל עצמו :"],["ואחר כך אומר הושענא ויש שאין אומרים קדיש קודם הושענות טעם הושענות אלו שאנו אומרים אחר תפילת המוספין הם דוגמא מה ששנינו בכל יום מקיפים את המזבח פעם אחת ואומרים אנא ה' הושיעה נא ובגמרא שקלינן וטרינן אי הואי האי היקף בלולב או בערבה ואנו סוברין כמ\"ד בלולב ולפיכך נוהגין להקיף בלולב כל שבעה ואומרים הושענא זכר למקדש שמאחר שאותה ההקפ' שבמקדש הית' אחר הקרבת קרבן מוסף והתפללו תפילת מוספין כדמשמע מדתנן בשעת פטירתן מה היו אומרים יופי לך מזבח כו' דאלמא שתכף אחר ההקפה נפטרו והלכו להם אף אנו עושין כן ואומרים הושענא אחר תפילת המוספין ונפטרין לשלום אלא די\"א דלאחר שסיימו כל התפלה ואמרו קדיש מתחילין לומר ההושענות וי\"א דראוי לכלול תפלה זו דהושענות דרך תחנונים סמוך לתפלת המוספים ואח\"כ לומר קדיש על הכל וכן אנו נוהגין:","ומ\"ש ונוהגין להקיף התיבה פעם אחת בכל יום ומעלים ס\"ת על התיבה כבר התבאר למעלה בסי' ק\"נ דבלשון התלמוד התיבה היא שמונח בה ס\"ת וש\"ץ יורד לפניה להתפלל ובתענית היו מוציאין התיבה לרחובה של עיר ואין תיבה זו ההיכל שבו הס\"ת שמוציאין אותה בכל שבת וב' וה' ולא הבימה שאנו קורין אלמימבר\"א שאין שם ס\"ת אלא שמשכיבין שם הס\"ת לקרות בה בצבור. והנה היה מנהגם להקיף התיבה פעם אחת בכל יום ולהעלות הס\"ת על התיבה כשמקיפים אותה ונראה דטעם מנהגם מפני שסוברים דתיבה זו שהש\"ץ יורד לפניה להתפלל שם תפלות צבור שהם במקום קרבנות היא מכפרת עלינו דוגמת המזבח שמקריבין עליו קרבן ומה שמעלים הס\"ת על התיבה נראה ג\"כ מפני ששנינו ר\"א אומר שהיו אומרים ליה אנחנו מודים כו' והס\"ת היא כולה שמותיו של הקב\"ה על כן מקיפין אותה לומר אנו ליה ועינינו ליה ובמלכות זה אין לנו שום תיבה אלא הש\"ץ עומד לפני ההיכל שבו ס\"ת ומתפלל ונהגו להקיף האלמימבר\"א ומוציאין ס\"ת מן ההיכל ומעלים על האלמימבר\"א כשמקיפין אותה אולי שאנו תופסין עיקר כי שמיעת התורה היא מכפרת עלינו כמו המזבח ויותר נראה לומר שמ\"ש רבינו ונוהגים להקיף התיבה ומעלים הס\"ת על התיבה האלמימבר\"א הוא שקורא תיבה וכן מבואר בתשוב' רשב\"א סי' צ\"ו שהבימה שהוזכרה בפ' החליל היא כעין תיבה שלנו אלמא דאלמימבר\"א קורין תיבה בלשון המחברים:","\u0003ומ\"ש אני והו שני שמות כו'\u0004 כ\"ז בפירש\"י ותו' בפרק לולב וערבה ורמב\"ם כתב עוד בפי' המשנה שהוא רומז למ\"ש ראו עתה כי אני אני וגו' שזה הפסוק בא בשמירת ישראל ושועתם וכאילו אמר אתה שאמרת ראו עתה כי אני אני הוא הושיעה נא כמו שהבטחתנו:","ומ\"ש בירושלמי איתא זכר ליריחו נראה בעיני שבא לתת טעם על הקפת המזבח שבמקדש ז' פעמים שהוא זכר ליריחו אבל הקפתינו ודאי אינה אלא זכר למקדש וק\"ל:","\u0003ורב סעדיה כתב שמקיפין מיד אחר קריאת ההפטרה כו'\u0004 אפשר דס\"ל לרב סעדיה דכשם שנטילת לולב סמוך לתפלת שחר כך ההקפה בלולב היתה באותה שעה הכל קודם תפלת המוספין ולפי זה צריך לפרש הא דתנן בשעת פטירתן היינו בשעה שנפטרו מהקפתן אבל לא שנפטרו והלכו לבתיהן ורבינו כתב שהמנהג טוב הוא בעיניו אלא שאין נוהגין כן ואני אומר כיון שכל עיקר אינן עושין כי אם זכר למקדש יפה מנהג שלנו שמאחרין ההקפה סמוך לשעה שנפטרין לבתיהן כדמשמע פשטא דמתניתין:","\u0003וסדר ההקפה כתב רב האי כו'\u0004 אע\"ג דכל פינות שאתה פונה אינם אלא דרך ימין מ\"מ ס\"ל לרב האי דבמקדש היו מקיפין בסדר הזה לשום כוונה ואנן צריכין לעשות זכר למקדש ממש אבל אנו נוהגין בכל יום לימינו:","ומ\"ש ובשבת אין מקיפין טעמו משום דהקפה שלנו אינה כי אם זכר למקדש שהיו מקיפין את המזבח בלולב או בערבה כדאיתא בגמרא ובשבת שאין שם לא לולב ולא ערבה ג\"כ אין שם הקפה ולא אמרינן מה בכך שאין שם לא לולב ס\"ס נעביד הקפה גרידא זכר למקדש זה אינו דהא בסוגיא קא מסיק דאף ע\"פ דערבה במקדש כל ז' מן התורה אפ\"ה לא עבדינן ערבה כל ז' זכר למקדש מאחר דערבה אין לה עיקר מן התורה בגבולין אפי' יום א' א\"כ לפי זה הקפה נמי מאחר דאין לה עיקר מן התור' בלא לולב וערבה לא עבדינן לה זכר למקדש: וכ' בהגה' אשיר\"י דמה\"ט נמי היכא דליכא לא אתרוג ולא לולב לא מקיפין סביב הבימה פעם אחת בכל יום ומשמע לי דמ\"מ בשביעי יש להקיף ז' פעמים בערבה אע\"ג דליכא לולב דכיון דאיכא למ\"ד דהקפת המזבח בערבה היתה יש לנו לעשות זכר למקדש לדידיה אע\"ג דבשאר ששה ימים אי אפשר להקיף זכר למקדש כיון דלא עבדינן ערבה כל ז' זכר למקדש מ\"מ בשביעי דאיכא למיעבד עבדינן כדאמר בפרק התכלת אלא מאן דלית ליה תרי מצוה חדא מצוה נמי לא ליעבד בתמיה וכך אפשר לדקדק מלשון הג\"ה הנזכרת שלא כתב בסתם דאין מקיפין בלא לולב ואתרוג אלא כת' דאין מקיפין סביב הבימה פעם אחת בכל יום דמשמע אבל בשביעי בשמקיפין ז' פעמים יש להקיף אפי' בלא לולב ואתרוג מאחר שיש שם ערבה נ\"ל וז\"ל מהר\"ש לוריא כתוב במנהגים מי שאין לו לולב לא יקיף אם ירצה פי' אם ירצה שלא להקיף ונ\"ל דבהושענא רבה ראוי להקיף בערבה אף מי שאין לו לולב מאחר שעושין זכר למקדש ושם היו מקיפין בערבה אלא שאין המנהג להקיף בלא לולב לכן מי שאינו מוחזק ביראת השם ראוי לו שלא להקיף כי היכא דלא ליחזי כיוהרא נ\"ל עכ\"ל ועיין במה שאכתוב בסימן תרע\"ד בס\"ד: כתוב בכלבו אבל בחג הסוכות אינו מקיף ומנהגינו אבל כל י\"ב חדש על אביו ואמו לא יקיף ונראה בעיני לתת טעם למנהג דפ' לולב וערבה קאמר ר\"ל דכהנים בעלי מומין נכנסין בין האולם למזבח כדי לצאת בערבה ופליג עליה ר' יוחנן וקאמר מנ\"ל הא דילמא אין הל\"מ אלא בתמימין הראויין לעבודה והתוס' כתבו וז\"ל כהנים בעלי מומין ה\"ה דהו\"מ למימר ופרועי ראש דתרווייהו אסירי אי לאו משום ערבה וכו' וידוע דהלכה כר' יוחנן לגבי ר\"ל ולר\"י לא היתה הקפת המזבח בב\"מ ובפרועי ראש וכיון דאבל פרוע ראש הוא כל י\"ב חדש ע\"כ לא נהגו להקיף וכדין הקפת המזבח ואע\"ג דלא קפדינן בב\"מ ובזרים דאף הם מקיפין זכר למקדש אפשר לומר התם כיון שאינו נודע בפרסו' שהוא ב\"מ וזר לית לן בה מאחר שאינו כ\"א זכר למקדש משא\"כ אבל שנתפרסם אבלותו לכל רואיו דפרוע ראש הוא קפדינן טפי ותו דמדכתיב ושמחתם לפני ה' אלהיכם ז' ימים ובאבל ליכא שמחה הילכך אינו מצטרף בהקפה כנ\"ל טעם המנהג והב\"י כתב שתימה הוא למה יפסידו ההקפה וכן נהגו להקיף אפילו ההקפה עצמו ע\"כ ומה שנראה לפע\"ד ליישב מנהג שלנו כתבתי וכתב רב שרירא גאון כו' ומנהג שלנו לומר הושענות אף בשבת:","ומ\"ש ואומר קדיש היינו אף למי שסובר דאומר קדיש קודם הושענות מכל מקום צריך לחזור ולומר קדיש אחר ההושענות שהרי אומר פסוקים דרך בקשה:"]],["\u0010c0\u0011\u0010y0\u0011למנחה מתפללין כמו ביוצר וכן בערבית כמו בליל ראשון ובקידוש של ליל ב' אומר קידוש וזמן אחריו מיד ואח\"כ סוכה דזמן לא קאי אלא אקידוש ולא אסוכה דאף אם יום ראשון חול יצא בזמן דסוכה הלכך צריך שלא להפסיק בסוכה בין קידוש לזמן. ואבי העזרי כתב שאף בליל ב' יש לומר זמן באחרונה כמו יקנה\"ז אע\"פ שהזמן אינו חוזר על ההבדלה וא\"א ז\"ל הסכים לסברא ראשונה :",["\u0003למנחה מתפללין כמו ביוצר וכו'\u0004 ובקידוש של ליל שני אומר קידוש וזמן אחריו מיד וכו' בפרק לולב וערבה כתב הרא\"ש וז\"ל גרסינן בפרק החליל (סוכה נו.) איתמר רב יהודה אמר סוכה ואח\"כ זמן רבה בב\"ח אמר זמן ואח\"כ סוכה והלכתא סוכה ואח\"כ זמן יש מן הגדולים דבליל שני אומר זמן תחלה דזמן לא קאי אסוכה דאפי' אם היה ליל י\"ט ראשון יצא בזמן דסוכה ולפי סברת בני אייברא שחילקו בין בשעת עשייה בין אחר עשייה קאי זמן נמי אסוכה וראבי\"ה כתב שבכל פעם י\"ל זמן באחרונה דהא י\"ט שחל להיות אחר השבת מברך יקנה\"ז אע\"ג דזמן לא קאי אהבדלה ויש לומר דלא דמי דהתם היינו טעמא משום דהבדלה טעונה כוס הלכך אין להפסיק בזמן בין בורא פרי הגפן להבדלה אבל הכא אי סוכה לא בעי זמן בלילה למה יפסיק בסוכה בין קידוש לזמן דהא איכא אמורא דס\"ל דאפי' בליל א' דסוכה בעי זמן סמוך לקידוש וקאי נמי אסוכה דבתריה וא\"כ בליל שני אי סוכה לא בעי זמן לכ\"ע ראוי לסמוך הזמן לקידוש מיד עכ\"ל והמרדכי כתב שם שתי הסברות ולא הכריע ובת\"ה סימן צ\"ה כתב שהם היו נוהגים כראבי\"ה:"],["\u0003למנחה מתפללין כמו ליוצר כו'\u0004 ובקידוש של ליל שני אומר קידוש כו' סברות אלו כתבם הרא\"ש בפ' לולב וערבה וסובר רבינו שהרא\"ש הסכים לסברא הראשונה מפני שכתב בסוף דבריו וז\"ל וא\"כ בליל ב' אי סוכה לא בעיא זמן לכ\"ע ראוי לסמוך הזמן לקדוש מיד עכ\"ל כוונתו דאי סוכה לא בעיא זמן אפי' היה אתמול חול ולא היה שעת עשיית סוכה דלא כסברת בני אייברא א\"כ ראוי לסמוך הזמן לקדוש מיד ומאחר שכבר גילה הרא\"ש דעתו גבי זמן דלולב ביום שני דלא כסברת בני אייברא שהרי כתב בסוף דבריו לשם וז\"ל ומיהו יש לומר דשאני הכא דנטלו לשם מצוה לברך עליו ועדיף טפי משנטלו בחול אחר עשייה וכן נוהגין באשכנז שאין מברכין זמן על הלולב בשני עכ\"ל אם כן גם כאן הסכמתו כך היא: ולענין המנהג נראה בעיני אע\"ג דלא קי\"ל כסברת בני אייברא שהרי אין אנו נוהגין לברך זמן אלולב ביום ב' אפ\"ה כאן ראוי לנהוג כראבי\"ה שסובר דאף בליל שני אומר זמן בקדוש באחרונה וה\"ט דמאחר דאמרינן בגמרא דמברכין אסוכה ברישא משום דחיובא דיומא עדיף א\"כ אין חילוק בין ראשון לשני והכי משמע פשטא דסוגיא דאע\"ג דלא אמרי' זמן בשביל הסוכה אלא בשביל המועד כגון בעשוייה ועומדת כמו שפירש\"י אפ\"ה סוכה קודמת משום דחיובא דיומא עדיף והכי אסיק בסמ\"ק דהכי משמע מפשטא דסוגיא דאין חילוק גם בהג\"ה מיימונית כתב שכן היא דעת הרמב\"ם ושכן עיקר שלא מצינו חלוק בין שני הימים ראשונים עכ\"ל וכן היא דעת אחרונים עיין עליהם:"]],["\u0010c0\u0011\u0010y0\u0011וביום ב' מתפללין כמו בראשון ונוטלין לולב ומברכין על נטילת לולב וכן כל שבעה \u0010y1\u0011אבל לענין זמן בי\"ט ב' נחלקו בו ה\"ר שלמה בר שמשון כתב שאין לאומרו דממ\"נ יצא בזמן שאמר בראשון אף אם הוא חול דלא גרע מאילו אמרו בשעת עשייה שיצא ולא דמי לזמן דקידוש שאומר בליל ב' שאותו הוא בשביל היום ולא בשביל הסוכה וכ\"כ רש\"י ור\"י וי\"א שצריך לאומרו משום שלא תקנו זמן אלא או בשעת עשייה או בשעת נטילה ואם היה אתמול חול א\"כ לא היה לא שעת עשייה ולא שעת נטילה הלכך לא יצא בזמן של אתמול \u0010y2\u0011וא\"א הרא\"ש ז\"ל הסכים לסברא הראשונה וכן נוהגין באשכנז \u0010y3\u0011ומיהו נראה שאם חל יום ראשון בשבת שצריך לאומרו בשני כיון שלא אמרו בראשון: \u0010y4\u0011ומוציאין ב' ספרים וקורין בא' כמו אתמול ומפטיר קורא ג\"כ כמו אתמול ומפטיר במלכים ויקהלו עד בהוציאו אותם מארץ מצרים ומחזירין הספרים למקומן ואומר קדיש ומתפללין מוסף כמו אתמול ואומר קרבנות המוספין ובחמשה עשר כמו אתמול \u0010y5\u0011ומכאן קשה למנהג טוליטולה שאומרים ביום הב' הושיענו בחגיגת יום ב' דכיון שעשינו אותו קודש היאך נעשנו חול לומר יום שני:",["וביום ב' מתפללין כמו בראשון ונוטלין לולב ומברכין ענט\"ל וכן כל ז' בפרק לולב וערבה איכא מ\"ד דאינו מברך עליו אלא ביום ראשון בלבד ואיכא מ\"ד דמברך עליו כל ז' ופסקו הפוסקים כמ\"ד כל שבעה בעי ברכה:","\u0003ומ\"ש אבל לענין זמן בי\"ט שני נחלקו ה\"ר שלמה ב\"ר שמשון כתב שאין לאמרו וכו'\u0004 ז\"ל הרא\"ש בפרק לולב וערבה ולענין זמן על הלולב בי\"ט שני כתב רבי' שלמה ברבי שמשון נשאלתי אם אומרים זמן על הלולב בי\"ט ב' ותמהני על מ\"ש בה\"ג דזמן דכסא פטר דלולב והלא לענין לולב מפסקי לילות מימים ור\"י פסק דאין אומרים זמן בי\"ט שני וכן נהגו גדולי גרמיזא וטעם שלהם ממ\"נ יצא בזמן שאמר ביום א' דאפי' את\"ל דחול הוא הא אמרי' העושה לולב לעצמו מברך שהחיינו ושוב אין מברך בשעת נטיל' וא\"כ ה\"נ יצא בזמן שבירך אתמול אפי' אם היה חול ולא דמי לזמן של קידוש שאומר בשני הלילות דאותו הזמן הוא בשביל היום ולא בשביל הסוכה ולולב מידי דהוה אשאר י\"ט ועוד משום דבעי נטילת לולב ז' ימים ואם נברך זמן מספק בי\"ט שני וביום שביעי ספק שמיני לא מברכין נמצא שאין לולב ניטל אלא ו' ימים וזה הטעם אינו נ\"ל דבין אמר זמן בי\"ט שני ובין אמר זמן ביום ראשון ספק הוא ומיהו איכא למימר אנן דבקיאין בקיבועא דירח' ואינו ספק לנו אלא מנהג בעלמא הוא מה שאנו עושים שני ימים אבל אם נברך זמן ביום שני אז אנו מראים בשעת נטילת לולב שהן ספק וכ\"פ רש\"י בתשובה שאין לומר זמן ביום שני וה\"ר שמואל מאייברא כתב בשם רש\"י דעכשיו שנהגו לברך זמן בשעת נטילה א\"כ צריך לברך גם ביום השני דשמא יום ראשון חול הוא ולא יצא דזמן לא נתקן לאמרו אלא בשעת נטילה או בשעת עשייה אפי' בחול אבל אם לא אמרו בשעת עשייה ואמרו בחול לאחר עשייה לא יצא וצריך לאומרו בשעת נטילה מיהו י\"ל דשאני הכא דנטלו לשם מצוה לברך עליו ועדיף טפי מנטלו בחול אחר עשייה וכן נוהגין באשכנז שאין מברך זמן על הלולב ביום שני עכ\"ל:","\u0003ומ\"ש רבינו וא\"א ז\"ל הסכים לסברא ראשונה כך משמע מתוך דבריו:\u0004 ","\u0003ומ\"ש ומיהו נראה שאם חל יום א' בשבת שצריך לאומרו בשני וכו'\u0004 פשוט הוא דכיון שאין אנו מברכין בשעת עשייה אלא בשעת נטילת לולב צריך לברך בפעם הראשונה שנוטלה:","ומוציאין ב' ספרים וקורין בא' כמו אתמול ומפטיר במלכים ויקהלו פשוט בפרק בני העיר וכתב רש\"י שטעם הפטרה זו מפני שחנוכת הבית היתה באותה אסיפה ובחג הסוכות:","ומכאן קשה למנהג טוליטולה שאומרים ביום השני הושיענו בחגיגת יום שני דכיון שעשינו אותו קודש היאך נעשנו חול לומר יום שני איני יודע למה הוקשה לו יותר מפסוקי הקרבנות ממה שאנו אומרים בו את י\"ט מקרא קודש הזה וגם ברכת זמן שאנו מברכין בו וממה שאנו עושים אותו קודש לכל דבריו ופסוקי קרבנות המוספין אינה קושיא למנהג טוליטולה שבכל ספרד לא היו אומרים פסוקי קרבנות המוספין ובעיקר הקושיא מי\"ט מקרא קודש ומברכת זמן שאנו אומרים בו וכן בכל דבריו אנו עושים אותו קודש י\"ל דמאי יום שני יום ב' להקפה ואע\"ג דקאמר בחגיגה האי חגיגה לא לשון חג ומועד הוא אלא לשון הקפה וסבוב מלשון יחוגו וינועו ואפי' את\"ל שהוא מלשון חג ומועד י\"ל דהכי קאמר הושיענו בחגיגת יום הזה שהוא יום שני להקפה ועי\"ל דחגיגה מלשון חג ומועד הוא ויום שני לחגיגה זו קאמרינן ואפ\"ה אין אנו עושין אותו חול בכך שאע\"פ שאנו חוגגים שני ימים לא יתחייב שהיום השני חול דהא אפשר דיום שני עיקר ולא דמי למברך על הסוכה בשמיני דאמרינן ביה שהוא עושהו חול:"],["וביום שני מתפללין כמו בראשון נוטלים לולב ומברכין ענט\"ל וכן כל ז' בפ' לולב וערבה פליגי אמוראי בהך מילתא ופשט שם רש\"י דמברכין כל ז' אע\"ג דמדרבנן היא זכר למקדש מברכין עליה כי היכא דמברכין בנר חנוכה ובמגילה דרבנן וכן פסקו הפוסקים:"]],["\u0010c0\u0011\u0010y0\u0011בחול המועד מתפללין ערבית שחרית ומנחה כדרכן ואומר יעלה ויבא בעבודה ולמעלה בהל' פסח כתבתי אם יש להזכיר בו יום מקרא קודש הזה ונוטלין הלולב ומברכין עליו \u0010c1\u0011וגומרין ההלל \u0010y1\u0011ומקיפין התיבה בכל יום חוץ מבשבת \u0010y2\u0011ומוציאין ס\"ת וקורין בו ד' בקרבנות החג שבפנחס \u0010y3\u0011ורבו הדיעות בסדר קריאתן והעיקר כך הוא שביום הא' של ח\"ה קורא כהן וביום הב' ולוי וביום הג' וישראל חוזר וקורא וביום הג' והד' קורא ספיקא דיומא שהוא וביום הב' וביום הג' ובשני קורא כהן וביום הג' ולוי וביום הד' וישראל חוזר וקורא וביום הרביעי והרביעי חוזר וקורא וביום הג' וביום הד' וכן כל הימים עד יום שביעי והוא בכלל ומחזיר ס\"ת למקומו ומתפללין תפלת מוסף ג' ראשונות וג' אחרונות וקדושת היום באמצע אתה בחרתנו ומפני חטאינו ואומר קדיש ואומרים בכל יום בקרבנות המוספין ספיקא דיומא ביום הא' אומר כאמור וביום הב' פרים בני בקר שנים עשר ואילים שנים כבשים בני שנה ארבע עשר תמימים וביום הג' פרים עשתי עשר וגו' ובשני אומר וביום הג' וביום הד' וכן בכל יום וסימן שלא תטעה לעולם הפרים והימים ביחד הם י\"ד \u0010y4\u0011ושבת שבח\"ה ערבית שחרית ומנחה מתפללין כדרכן ואומר יעלה ויבא בעבודה ובמוסף ג' ראשונות וג' אחרונות אתה בחרתנו וקדושת היום באמצע וכולל עמו השבת לומר את יום המנוחה הזה ואת יום חג הסוכות הזה וחותם מקדש השבת ישראל והזמנים \u0010y5\u0011ומוציאין שני ספרים וקורין בא' ז' בפרשת כי תשא ראה אתה אומר אלי ומפטיר קורא קרבנות של ספיקא דיומא לפי מה שהוא היום ומפטיר ביחזקאל ביום בא גוג ולמעלה בהלכות פסח כתבתי למה מפטירין כך:",["\u0003בחה\"מ מתפללין ערבית שחרית ומנחה כדרכה ואומר יעלה ויבא בעבודה נתבאר בסי' ת\"צ:\u0004 ","\u0003ומקיפין התיבה בכל יום חוץ מבשבת נתבאר בסי' תר\"ס:\u0004 ","ומוציאין ספר תורה וקורין בו ד' בקרבנות החג שבפנחס שקורין בו ד' פשוט בפרק הקורא עומד (מגילה כא.) וקורין בקרבנות החג פשוט בפ' בני העיר (מגילה לא:):","ומ\"ש ורבו הדעות בסדר קריאתו והעיק' כך הוא שביום הראשון של ח\"ה קורא כהן וביום השני וכו' בסוף סוכה (נה.) אתקין אמימר בנהרדעא דמדלגי דלוגי וכתבוהו הרי\"ף והרא\"ש בפרק בני העיר ופירשו בשם גאון כמ\"ש רבינו ורש\"י כתב כך היו נוהגים רבותי שנים הראשונים קורין ב' ספיקות היום והג' בפ' יום המחרת שאינה מספיקות היום כלל והרביעי חוזר מה שקראו שנים הראשונים והתוס' הקשו עליו וכתבו הם שראוי להנהיג שביום ראשון של ח\"ה יקרא הראשון ביום השני והשני ביום הג' וחוזר שלישי ביום הב' ורביעי ביום הג' וכיוצא קורין בספיקות בכל יום ויום והרמב\"ם בפרק י\"ג מהלכות תפלה בקצת נוסחאות כתב כמנהג רבותיו של רש\"י ובקצת נוסחאות כתב כפירוש הגאון שכתב הרי\"ף והרא\"ש ונוסחא זו עיקר וא\"ת מפני מה אין מתחילין לקרות בספיקו של יום מיום שני כבר כתבו רש\"י והרי\"ף והרא\"ש והר\"ן שהטעם מפני שאין להזכיר בו וביום השני דלא לזלזולי בקדושת היום: ובארץ ישראל שאין ספיקא דיומא אין קורין בכל יום כי אם פרש' היום בלבד כי ביום השני שהוא ראשון לח\"ה קורא כהן פרשה ביום הב\" וכו' הג' העולים אחריו חוזרים וקורין אותה פרשה עצמה ועל דרך זה בכל יום משאר הימים:","\u0003ושבת שבח\"ה ערבית שחרית ומנחה מתפללין כדרכן וכו'\u0004 ובמוסף ג' ראשונות וג' אחרונות אתה בחרתנו וקדושת היום באמצע וכו' נתבאר בסי' ת\"צ:","ומוציאין ב' ספרים וקורין בא' ז' בפרש' כי תשא ראה אתה אומר אלי ומפטי' ביחזקאל ביום בוא גוג פשוט בפרק בני העיר (מגילה לא:):"],["\u0003בחול המועד וכו'\u0004 ולמעלה כתבתי כו' סימן ת\"ץ:","ומ\"ש וגומרין ההלל משנה ר\"פ לולב וערבה ההלל ושמחה שמנה ופירש\"י ההלל לגמור כל שמנה כן תקנו נביאי' הראשוני' ובערכין מפרש מ\"ש מפסח מפני שימי החג חלוקים בקרבנות עכ\"ל ומ\"ש ורבו הדעות וכו' בסוף סופה אתקין אמימר בנהרדעא דמדלגי דלוגי וכתבוהו הרי\"ף והרא\"ש בפ' בני העיר ופירשו בשם גאון כמ\"ש רבינו אכן רש\"י בשם רבותיו בסוף סוכה כתב פי' אחר גם התוספות פי' עוד פי' אחר ומנהגינו כרש\"י וכתב רש\"י לשם ולא מצינו למימר בי\"ט שני פ' ביום השני דאם כן עבדינן ליה חול ומ\"ש ואומר בכל יום בקרבנות המוספים ספיקא דיומא וכו' הך היא תקנתא גופא דאמימר לענין תפלה אלא דאנן עבדינן נמי הכי לענין קוראי התורה כמו שפירש\"י לשם. ושבת שבח\"מ כו' נתבאר בסי' ת\"ץ:"]],["\u0010y0\u0011ביום חמישי של חול המועד שהוא הושענא רבה נוהגין שמרבין מזמורים כמו בי\"ט ואומר קדושה רבה במוסף ומרבים קצת בנרות כמו בי\"ה לפי שבחג נדונין על המים והכל הולך אחר החתום וכל חיי אדם תלויין במים \u0010c0\u0011\u0010y1\u0011ויש נוהגין להתיר בו אגדו של לולבו סמך לדבר דכתיב כפת חסר ו' פי' ו' ימים יהיה כפות ולא יותר \u0010c1\u0011ומקיפין ז\"פ ומרבים תחנונים על המים \u0010y2\u0011ונוטלין ערבה \u0010c2\u0011זכר למקדש שהיו מקיפין בו ביום בערבה \u0010c3\u0011\u0010y3\u0011ופליגי בה רבי יוחנן אמר יסוד נביאים הוא פי' נביאים אחרונים חגי זכריה ומלאכי יסדום ולכך מברכין עליה ור' יהושע אומר מנהג נביאים היא פירוש מנהג בעלמא שנהגו כך ואין מברכין עליה ופסק רי\"ף שאין לברך עליה דאסיקנא איבו הוה קאי קמיה דר\"א בר צדוק ואייתי ההוא גברא ערבה קמיה חביט חביט ולא בריך קסבר מנהג נביאים הוא ואמנהג לא מברכינן ובעל העיטור כתב הא דלא בריך ר\"א משום דיחיד הוא ויחיד אינו קובע ברכה לעצמו אבל צבור ודאי מברכין ורב שמואל בן חפני פסק כר' יוחנן שמברכין וא\"א הרא\"ש ז\"ל כתב ונהגו כרי\"ף \u0010c4\u0011\u0010y4\u0011כתב גאון שיעור החבוט ב\"פ בתפלת מוסף של יום ז' לפי שבתפלת התמיד אנו נוטלין הלולב ובתפלת המוסף של יום ההוא אנו נוטלין הערבה בפני עצמה \u0010y5\u0011ורש\"י פי' חבוט (ונוהגים לכבות הנרות עם ההושענות לשמחה) לשון ניענוע \u0010c5\u0011והרמב\"ם ז\"ל כתב חובט בה על הקרקע או על הכלי ב\"פ או ג' וכ\"כ הרי\"ץ גיאת \u0010c6\u0011\u0010y6\u0011וערבה זו צריכה שיעור וכמה שיעורה רב נחמן אמר ג' בדי עלין לחין ורב ששת אומר אפי' עלה אחת בבד אחד \u0010c7\u0011\u0010c8\u0011והלכתא כרב ששת אלא שכתב רב האי שמכוער הדבר עלה אחת בבד אחד \u0010y7\u0011ואינה ניטלת אלא בפני עצמו \u0010y8\u0011פי' שלא יאגד ד\"א עמה אבל יש לו בידו ד\"א אין לחוש \u0010y9\u0011ואין אדם יוצא ידי חובתו בערבה שבלולב אפי' אם הגביה אותה ב\"פ אחת לשם לולב ואחת לשם ערבה ורב נחמן אומר אדם יוצא ידי חובתו בערבה שבלולב אם הגביה אותה ב\"פ \u0010y10\u0011ופסק הרמב\"ם ז\"ל דאין אדם יוצא בה ואבי העזרי פסק שיוצא בה ולזה הסכים א\"א ז\"ל:",["\u0003ביום חמישי של ח\"ה שהוא הושענא רבה נוהגים שמרבים מזמורים כמו בי\"ט וכו'\u0004 ומקיפין ז' פעמים זה מפורש במשנה פ' לולב וערבה (סוכה מה.) שביום השביעי היו מקיפין את המזבח ז\"פ:","ומ\"ש ויש נוהגים להתיר בו אגודה של לולב וסמך לדבר דכתיב כפת חסר כ\"כ המרדכי בפרק לולב הגזול:","ומ\"ש ונוטלין ערבה זכר למקדש עיקר נטילת ערבה זו הלכה למשה מסיני כדאיתח בפ' לולב וערבה (סוכה מד.) ומשמע התם שלא נאמרה הלכה אלא במקדש בלבד ומצותה במקדש להקיף בה כל שבעת הימים וחכמים תקנו ליטלה בגבולין ביום השביעי זכר למקדש וא\"ת למה לא תקנו לנוטלה כל ז' כשם שתקנו בלולב כבר תירצו בגמרא לולב דאית ליה עיקר מן התורה שהרי יום ראשון הוא מן התורה אף בגבולין עבדינן ליה ז' זכר למקדש ערבה דלית ליה עיקר מן התורה בגבולין לא עבדינן שבעה זכר למקדש: והטעם שקבעו יום ז' לערבה יותר מיום אחר נראה שהוא מפני שאותו היום היה מיוחד במקדש משאר הימים שאם חל יום שביעי להיות בשבת היה ערבה דוחה שבת משא\"כ כשחל להיות בשאר הימים מפני כך כשרצו חכמים לקבוע בגבולים יום א' לנטילת ערבה קבעו היום המיוחד יותר לערבה שבמקדש והטעם שנטילת ערבה בז' דוחה שבת ולא בשאר ימים מפורש שם בגמ': וכתב הר\"ן בגמ' שקלי' וטרי' הא דתנן (סוכה מה.) בכל יום היו מקיפין את המזבח פעם אחת ואותו היום כלומר בז' מקיפין את המזבח ז\"פ אי הוה האי היקף בלולב או בערבה ולפי מנהגינו עכשיו שמקיפין את התיבה בכל יום פעם אחת ובשביעי ז\"פ משמע דסברי שאותו היקף היה בלולב דאי בערבה כיון שאין אנו עושין בערבה זכר למקדש אלא יום ז' בלבד לא היה לנו להקיף אלא בשביעי אבל אי הוה בלולב מתוך שהוטל עלינו חובה לעשות לולב זכר למקדש שבעה הנהיגנו להקיף בו זכר למקדש וכ\"כ רש\"י בתשובה ואף הרמב\"ם כ\"כ בפ\"ז ולפי זה אף בשביעי של ערבה ראוי להקיף בלולב ולא בערבה עכ\"ל ולא נהגו כן אלא להקיף ביום השביעי גם בערבה ואפשר שהטעם לעשות ככ\"ע דלמ\"ד דמקיפין בלולב אם נטל עמו ערבה אין בכך כלום וכן למ\"ד מקיפין בערבה אם נטל עמה לולב אין בכך כלום:","\u0003ופליגי בה (שם מד:) ר\"י אמר יסוד נביאים הוא וכו'\u0004 שם:","\u0003כתב הגאון שיעור החבוט ב' פעמים וכו'\u0004 עד אנו נוטלין ערבה בפני עצמה כ\"כ הרא\"ש בפ' לולב וערבה בשם גאון ביאור דבריו דהא דאמרינן חביט חביט ולא בריך היינו כשנוטלה פעם א' וחובט ב' פעמים:","\u0003ומ\"ש ורש\"י פי' חובט לשון נענוע וכו'\u0004 כלומ' ולענין מהו חבוט זה רש\"י פירש שהוא נענוע והרמב\"ם פי' שהוא חבטה ממש על הקרקע או על הכלי:","\u0003וערבה זו צריכה שיעור וכמה שיעורה וכו'\u0004 בפרק לולב וערבה (שם) וכתב הרא\"ש שפסקו הגאוני' כרב ששת משום דהלכתא כוותיה באיסורי וכן פסק הרמב\"ם והר\"ן כתב וקי\"ל כרב ששת ומיהו מסתבר דשיעור ארכה כשיעור אורך ערבה שבלולב שלא מצינו שהקלו בה בזה:","\u0003ואינה ניטלת אלא בפ\"ע שם מימרא דרבי אמי:\u0004 ","\u0003ומ\"ש פי' שלא יאגוד דבר אחר עמה וכו'\u0004 כ\"כ הרא\"ש וכ\"נ מפי' רש\"י:","ואין אדם יוצא ידי חובתו בערבה שבלולב אפי' אם הגביה אותה ב' פעמים ור\"נ אמר אדם יוצא ידי חובתו בערבה שבלולב אם הגביה אותה ב' פעמים ג\"ז שם:","ומ\"ש שהרמב\"ם פסק דאין אדם יוצא בה בפ\"ז ומ\"ש שאבי\"ה פסק שיצא בה בפסקי הרא\"ש ובמרדכי פ' לולב וערבה ומ\"ש ולזה הסכים הרא\"ש שם וכתב עוד המרדכי שם בשם רבינו אפרים נראה הא דנהגינן שהחזן נוטל עוד ערבה אחרת עם ערבה שבלולב דאותה ערבה לא חשיבא כערבה אחרת דהא ס\"ל לולב א\"צ אגד ואם הוסיף על ד' מינים שבלולב ואגד עמהם לא עבר על בל תוסיף דהאי לחודיה קאי והאי לחודיה קאי ומאחר דהכי הוא האגד כמאן דליתיה דמי והוי כמו ערבה שבלולב עכ\"ל כ' ה\"ר שלמה בן הרשב\"ץ וז\"ל ערבה ביום השביעי נראה בעיני שאינו יכול ליטול עם הלולב בשעה שהוא יוצא י\"ח עד אחר שיברך ויטול וינענע בתחלה ואם נטלה עובר משום בל תוסיף ואחר הנענוע הראשון יכול הוא ליטלה עם הלולב וכ\"ש בשעת הקפה וזה נלמוד ממה שאמר הרמב\"ם שהמוסיף על ב' ערבות עובר על בל תוסיף וכן דעת הגאונים והרשב\"א בתשובותיו וכן כל האחרונים ז\"ל אע\"פ שקצת מהראשונים חולקים ובענין ערבה של יום השביעי אמרינן דניטלת בפני עצמה ופירש\"י שאינה נקשרת עם ד\"א וקי\"ל נמי דלולב א\"צ אגד ובפרק ראוהו ב\"ד אמרי' דלעבור בזמנו לא בעי כוונה ושלא בזמנו בעי כוונה וכל שעברה מצותו הוי כלאחר זמנו וכ\"כ רבוותא ז\"ל בפי' התם וכ' עוד נראה דגם אחר נטילה ונענוע צריך לתפוס הערבה לבדה להכיר שחובה היא וע\"כ אמרו וניטלת בפני עצמה ובשעת החבטה שצריך לחבט בה משום מנהג נביאים יטלטלנה בפני עצמה ויצא בה ידי חובה ע\"כ: ומה שנהגו עכשיו שהמתעסקין בצרכי צבור מביאין הערבה כתב הר\"ן בפרק לולב וערבה מפני שבזמן שבית המקדש קיים לא היה מביאה כל אחד בביתו אלא שלוחי ב\"ד היו מביאים אותה לעזרה ושם נוטלין אותה ונשאר מנהג זה בידם אף בגבולין ומזה נתפשט המנהג שהשמש מביא ערבה ומוכר אותה לכל אחד ואחד: כתב בהג\"א פרק בני העיר בשם א\"ז הושענא שבלולב וכיוצא בה אע\"פ שנזרקת אין לפסוע עליה כתוב בהגהות מיימוניות בשם רא\"ם דאסור להנות מן הערבה לאחר ברכה ונטילה אם לא התנה עליה מעיקרא דלכולי יומא אתקצאי למצותיה לאפוקי מאותם שצולין בהם תפוחים ובשר וריב\"ק היה נוהג בערבה שהיה מתקן ממנה עצים לקולמוסים והיה מבער בהם חמץ בפסח כדאמרינן גבי עירוב הואיל ואיתעביד ביה חדא מצוה ליעבד ביה מצוה אחריתי וגם המרדכי כתב בסוף סוכה אסור ליהנות מערבה לאחר נטילתה אם לא התנה מתחלה דלכולי יומא איתקצאי ולפי שראיתי בני אדם צולין בשר ופירות בעצי ערבה לאחר נטילה כתבתי כן ע\"כ: מ\"כ ראיתי ב\"א שהולכין בשדה של עו\"ג ברשות העו\"ג וקוצצין ערבה להושענא רבה ונ\"ל דשלא כדין הן עושין מדא\"ר הונא להנהו אוונכרי כי גזיתו אסא לא תיגזון אתון וכו' והא דא\"ר אשי התם כי אזל בארבא להנהו שיבשי דגופנא דתלו ביה קיטפי דעינבי וכו' מפרשי רבותי' משום הפקר דתלו להו לבר מפרדיסא שרי: במרדכי פ' לולב הגזול כתב רבינו אביגדור כהן כשחל הושענא רבה באחד בשבת וקצצו עו\"ג ערבה בשבת והביאו כשירה ולא אמרינן מצוה הבאה בעבירה היא והביא ראיה לדבר ובתשובת הרשב\"א כתב על אחד שאמר לעו\"ג מבע\"י שיחתוך ערבה כדי שתהא מזומנת למ\"ש והלך העו\"ג בשבת למקום קרוב לעיר וחתך משם והיו שם רבים ויצא הקול בעיר שביום שבת היו קוצצין ערבה לצורך ישראל והשיב דמותרת היא דעו\"ג במלאכתו הוא עסוק אבל יפה עשיתם להחמיר כיון שנעשה בפרהסיא ובמקום פרהסיא יש לחוש לרינון שעה:"],["\u0003ביום חמישי וכו'\u0004 גם האחרונים בחבוריהם כתבו שביום זה הוא גמר חתימה כמה מים צריכין לקרקפתי דגברי ויש להם סימן בצל הלבנה ונראה בעיני דמאחר שהלבנה מניע יסוד המים על כן ניתן בכחה ענין זה:","\u0003ומ\"ש ויש נוהגין להתיר בו אגודו כו'\u0004 פי' כפת חסר וי\"ו כתיב משום דו' ימים קשור ודומה לכף אחת וביום השביעי מתירין אותו וכן כתב המרדכי בשם רבינו אבי העזרי והטעם משום דהנענוע הוא לעצור הטללים רעים ורוחות רעות וכשסותר אגודו מנענע בו יותר וכיון שעכשיו הוא גמר החתימה למים מתירין אגודו כדי לנענע בו היטב:","\u0003ומ\"ש ומקיפין ז' פעמים וכו'\u0004 נתבאר בסימן תר\"ס שבמקדש היו מקיפין המזבח ביום ז' ז' פעמים ולפיכך עכשיו ג\"כ נוטלין הערבה ביום ז' ומקיפין ז' פעמים זכר למקדש ואעפ\"י דדבר תורה היו נוטלין במקדש הערבה כל ז' הל\"מ מ\"מ אין אנו עושין זכר למקדש אלא יום אחד. ובגמרא מפרש מאי שנא מלולב דניטל כל ז' זכר למקדש וקאמר דשאני לולב דחשיב טפי דהא יום ראשון הוא מן התורה אף בגבולין משא\"כ ערבה והר\"ן פירש לולב אי אפשר לעשותו יום אחד בלבד זכר למקדש שכבר הוא ניטל בגבולין יום אחד מדינו מן התורה ולא יהא כאן זכר כמקדש כלל וכיון דלא סגי ביום א' עבדינן ז' אבל ערבה שאינה ניטלת מן התורה בגבולין כלל ביום א' בלחוד איכא זכר למקדש ומה שאנו נוטלין הערבה ביום ז' זכר למקדש יותר מיום אחר היינו מפני שאותו היום היה מיוחד במקדש יותר משאר הימים דאם חל יום ז' בשבת היה דוחה שבת כדי לפרסמה שהיא מן התורה משא\"כ בשאר הימים וכדמפרש טעמא בגמרא וא\"כ ג\"כ עכשיו שאנו עושין זכר למקדש כל כונתינו לפרסמה שבמקדש היתה ניטלת מן התורה ולפיכך נוטלין אותה בשביעי מאחר שגם במקדש היתה ניטלת בשביעי אפילו כשחל בשבת כדי לפרסמה שהיא מן התורה ודו\"ק וכיוצא בזה כתב גם הב\"י:","ומ\"ש זכר למקדש שהיו מקיפין בו ביום בערבה נראה מכאן שסובר הלכה כמ\"ד דהקיפו בערבה ולא בלולב והכי מוכח פשטא דסוגיא דמ\"ד ערבה בזקיפה ולא בנטילה איתותב אלא ערבה בנטילה ובזקיפה ופירוש בנטילה שהיו נוטלין אותו ומנענעין ומקיפין בה את המזבח ואח\"כ זוקפין אותה כדמוכח הסוגיא ולפי זה צריך ליישב מנהגינו שאנו מקיפין בכל יום פעם אחת בלולב דמאחר שאין אנו עושין בערבה זכר למקדש אלא יום ז' בלבד לא היה לנו להקיף ג\"כ אלא בז' בערבה אבל לולב אין לו ענין להקפה או נעשה זכר למקדש להקיף כל ז' אפילו אין שם לולב וכן בשבת. ונ\"ל דס\"ל דלמ\"ד הקפה בערבה לא אתי למעוטי לולב אלא הקפה בשניהם היתה בלולב ובערבה לאפוקי למ\"ד בלולב ולא בערבה דערבה אינה אלא בזקיפה דליתא אלא הקפה בשניהם היתה לדידיה וכך פי' התוס' אליבא דר\"י בן ברוקא דאמר חריות של דקל וכו' דתרוייהו הוי ערבה וחריות של דקל והשתא בשאר ימים עבדינן הקפה בלולב לחודיה וביום הז' עבדינן הקפה בתרתי בלולב ובערבה להאי מ\"ד וכ\"כ במנהגים ומקיפין עם הלולב והושענות וכו' והכי נהוג ודלא כמ\"ש הר\"ן דסברינן כמ\"ד בלולב ולא בערבה ולדידיה צריך לדחוק ולומר דאע\"ג דקי\"ל דערבה בנטילה היינו נענוע לחודיה אבל לא הקפה כל עיקר דאין להקיף בערבה אף בז' אלא בלולב ולא נהגינן הכי אלא מקיפין בשניהם ביום ז' ומ\"מ אם אין כאן לא לולב ולא אתרוג מקיפין בערבה לחוד ביום הז' וכמ\"ש למעלה בסי' תר\"ס בס\"ד:","\u0003ופליגי בה וכו'\u0004 בפרק לולב וערבה הבי' הרא\"ש דברי הר\"ש בן חפני ושהעם נהגו כרב אלפס וגם ר\"ת פסק הלכה כריב\"ל לגבי ר' יוחנן ובתשובת הגאונים פסק כריב\"ל בכל מקום ומ\"ש בשם בעל העיטור לחלק בין יחיד לצבור נראה דטעמו משום דקשיא ליה מ\"ש דמברכין אב' י\"ט של גליות שאינן אלא מנהג כדאיתא פ\"ק דביצה דשלחו מתם הזהרו במנהג אבותיכם ומחלק דצבור ודאי מברכין אף על המנהג ומש\"ה נמי קאמר י\"ח ימים יחיד גומר בהן את הלל ובגולה כ\"א יום דמשמע דבצבור גומרין אותו אפילו בר\"ת וממילא נמי מברכין עליה אף על פי שאינו אלא מנהג כדמוכח מרב דאיקלע לבבל חזי דקרו הלל בר\"ח וכו' ויחידים היו דקרו הלילא ועיין בתוס' ובדברי הר\"ן בפ' לולב וערבה תפסו להם שיטה אחרת:","\u0003כתב גאון שיעור החבוט ב' פעמים בתפלת מוסף של יום ז' לפי כו'\u0004 כוונתו לתת טעם למה בתפילת מוסף ולא בתפילת תמיד וקאמר לפי שבתפלת התמיד אנו נוטלין הלולב ולא מוכחא מצות נטילת הערבה שהרואה הוא אומר שהכל הוא ערבה שבלולב ולכך אנו נוטלין הערבה בתפלת מוסף בפני עצמה דמוכחא מצות הערבה ואיכא פרסומא ולאו דוקא בתפילת מוסף ממש דודאי בשעת התפלה אסור לחבוט לכל הפירושים דהחבוט מבטל כוונתו דאינו דומה למה ששנינו קורא ק\"ש ומתפלל ולולבו בידו דהתם מחזיקו בידו בלא נענוע אבל החבוט שהוא הנענוע בלי ספק כשהוא נותן דעתו לנענע מתבטל מכוונתו וכ\"ש אם החבוט הוא על הקרקע אלא על אמירת ההושענות בסוף תפילת מוסף קודם קדיש קאמר כי היכי דנטילת לולב בסוף תפילת תמיד בשעת קריאת ההלל קודם קדיש ויש ללמוד מכאן דבשעת אמירת ההושענות יטול הערבה בפני עצמה בלא לולב ואע\"ג דהקפה בלולב ובערבה מ\"מ אח\"כ יניח הלולב ויתפוס הערבה לבדה ומ\"ש שהחבוט ב' פעמים היינו מפני שאמרו בגמרא חביט חביט ולא בירך דמשמע שנוטלה וחובטה פעמים ומ\"ש ורש\"י פי' חבוט לשון נענוע כך פי' בסוגיא דפ' לולב וערבה והיא מלשון חבוט רמי דבפ\"ק דסוכה שפירש נענוע:","ומ\"ש בשם הרמב\"ם נראה שטעמו מפני ששנינו ר\"י בן ברוקא אומר חריות של דקל היו מביאין וחובטין אותם בקרקע בצידי המזבח כו' וסובר הרב דחבוטי דערבה נמי בקרקע היא דבהא לא פליגי:","\u0003וערבה זו צריכה שיעור כו'\u0004 בפרק לולב וערבה ופרש\"י והר\"ן שלשה בדין שיש בכל אחד שלשה עלין נחין ע\"כ:","\u0003ומ\"ש והלכה כרב ששת:\u0004 הרא\"ש כתב הטעם משום דקי\"ל דהלכה כרב ששת באיסורי והר\"ן כתב משום דמנהג נביאים הוא ואזלינן ביה לקולא כתב במרדכי בשם ר' אפרים מרעגנשפור\"ק הא דנהיגין שהחזן נוטל עוד ערבה אחרת עם הערבה שבלולב דאותה ערבה לא חשיבא כערבה אחרת דהא ס\"ל לולב א\"צ אגד ואם הוסיף על הד' מינין שבלולב ואגדו עמהן לא עבר על בל תוסיף דהאי לחודיה קאי והאי לחודיה קאי ומאחר דהכי הוא האגד כמאן דליתיה דמי והוי כמו ערבה שבלולב עכ\"ל פי' דלרבי יהודא דלולב צריך אגד ודאי אם נוטל עוד ערבה אחרת חוץ לאגד איכא משום בל תוסיף ואע\"ג דאם היה תוך האגד ליכא משום בל תוסיף כיון דהכל הוא מין א' היינו משום דיכול להוסיף הרבה ערבות אבל חוץ לאגד ערבה אחרת היא ואינו כמו ערבה שבלולב מאחר דלולב צריך אגד אבל לרבנן דא\"צ אגד ואפי' הוסיף מין אחר על ד' מינין שבלולב ואגדו עמהם לא עבר על בל תוסיף כדאיתא בפרק הנחנקין א\"כ גם ערבה אחרת שנוטל חוץ לאגד לא חשיבא כערבה אחרת דהאגד כמאן דליתיה דמי והוי כמו ערבה שבלולב כך היא פי' דבריו וחולק אדברי התו' בפרק לולב הגזול בד\"ה הואיל ואמר רבי יהודא בדף ל\"א ע\"ב ע\"ש אבל הר\"ש בן הר\"ש בר צמח בתשובה כתב דנראה בעיניו שאם נוטל אחרת עם הערבה שבלולב דעובר משום בל תוסיף ואע\"ג דלרבנן ודאי אפילו נוטל מין אחר ליכא משום בל תוסיף על ידי האגד דהאגד כמאן דליתא דמי אפילו הכי בערבה איכא משום בל תוסיף שהרי אסור להוסיף על ב' ערבות לדעת הרמב\"ם ושכן היא דעת הגאונים והרשב\"א בתשובותיו וכן כל האחרונים ז\"ל אע\"פ שקצת מהראשונים חולקין וא\"כ לדידהו אפילו לרבנן דהאגד כמאן דליתא דמי והוי כמו ערבה שבלולב מ\"מ מוסיף על ב' ערבות ועוב' משום בל תוסיף והב\"י כתב על זה בש\"ע ז\"ל ואעפ\"י שמה שכתב שאם נטלה עובר משום בל תוסיף טעות הוא בעיני מ\"מ אין הפסד לחוש לדבריו וכו' כתב כן מפני שכבר קבע ההלכה בסימן תרנ\"א דיכול להוסיף על ב' ערבות ולא ידעתי למה לו ליחס שום טעות ע\"ז שפסק באיסור דאורייתא כהרשב\"א שהעיד כך משם הגאונים דאיכא בל תוסיף אף בערבה ואעפ\"י שהרמב\"ם חזר בו בסוף ימיו מ\"מ הגאונים והרשב\"א לא חזרו מדבריהם ופסקו דאיכא בל תוסיף בלולב ואתרוג וערבה כמבואר בתשובה סימן ע\"ה וסימן תקל\"ה הילכך נראה עיקר להחמיר ואעפ\"י שהמרדכי בשם ר\"א כתב גם כן טעם למנהג היינו מפני שסובר ג\"כ דיכול להוסיף על ב' ערבות כל שהוא ממינו אבל לאותן גאונים שסוברים שאסור להוסיף על ב' ערבות ודאי אסור גם מצאתי כתוב וז\"ל מהר\"ש לקח ז' בדי להושענ' נגד ז' הושענות ואינו נוטלה ידו אלא כשאמר ההושענות עכ\"ל ותו דעיקר מצות ערבה אינה בשחרית אלא במוסף כדלעיל א\"כ אין תועלת בנטילת' בשעת נטילת לולב כי אם היזק שמכניס ראשו בפלוגתא דרבוותא באיסור דאורייתא וכן ראיתי רבותי נוהגין וכן ראוי לנהוג:"]],["\u0010c0\u0011\u0010y0\u0011אתרוג בשביעי אסור שהרי הוקצה לכל הז' \u0010c1\u0011ואפי' נפסל אסור כל ז' הימים ובשמיני עצרת מותר \u0010y1\u0011ולדידן דאית לן תרי יומי בשמיני ספק ז' אסור אבל בט' ספק שמיני מותר \u0010y2\u0011וכתב ה\"ר פרץ שאם חל י\"ט האחרון של חג באחד בשבת שאסור אף בט' אע\"ג דקי\"ל שמותר בט' היינו בשאר ימים אבל הכא אסור משום הכנה דכיון דשבת לפניו אין שבת מכינה לי\"ט ולא נהירא לא\"א הרא\"ש ז\"ל דלא שייך ביה הכנה וכן נוהגין בה היתר: \u0010y3\u0011הפריש ז' אתרוגים לז' ימים כל אחד יוצא בו ואוכלו למחר אבל ביומו אסור שהוקצה לכל אותו היום:",["אתרוג בשביעי אסור שהרי הוקצה לכל שבעת הימים ובשמיני עצרת מותר בפרק לולב וערבה (סוכה מז.) איפליגו אמוראי במלתא ופסקו הפוסקים כר\"י דאמר אתרוג בז' אסור בשמיני מותר וא\"ת אמאי מותר בח' הא ע\"כ בין השמשות אסור דשמא יום הוא וכיון דאתקצאי לבה\"ש אתקצאי לכולי יומא כבר תירץ הרא\"ש דבכה\"ג לא שייך למימר מגו דאתקצאי לבין השמשות כיון דלא נאסר בין השמשות אלא מחמת ספק יום שעבר וכן נמי אמרינן הפריש ז' אתרוגים לז' ימי החג כל א' יוצא בו ואוכלו למחר ואע\"ג דאתקצאי מחמת יום שעבר וכ\"כ התוס' בפ\"ק דסוכה גבי עטרה בקרמים והר\"ן תירץ דליכא למימר דמגו דאתקצאי לבה\"ש אתקצאי לכולי יומא משום דלבין השמשות גופיה לא אתקצאי שהרי בין השמשות אינו ראוי למצות אתרוג שאפילו לא נטל כל היום אינו נוטלו בין השמשות דכיון דלולב בזמן הזה מדרבנן בר מיום ראשון ובין השמשות ספק הוא ספיקא דרבנן לקולא:","ומ\"ש רבי' ולדידן דאית לן תרי יומי בשמיני ספק שביעי אסור אבל בט' ספק ח' מותר הכי אסיקנא בפרק לולב וערבה וא\"ת כיון דלא נטלינן ליה בח' אמאי אסור דליכא למימר דאסור משום דכיון דאתקצאי לבה\"ש אתקצאי לכולי יומא מהטעמים שכתבתי כבר תירץ הרא\"ש דטעמא משום דכיון דאם יבא אליהו ויאמר דעברוה לאלול הוי שמיני ז' והר\"ן תירץ דטעמא משום דאי שרית ליה אתי למימר דלא מספקו בז' כלל אלא ודאי ח' ולא ישמע לנו לישב בסוכה:","\u0003וכתב הר\"פ שאם חל י\"ט של חג בא' בשבת וכו'\u0004 כ\"כ הרא\"ש וכתב עליו ולמאי דפרישית דלא שייך כאן הכנה מותר וכן עמא דבר עכ\"ל. ונראה שמה שפי' דלא שייך כאן הכנה היינו מ\"ש דלא מתסר מטעם דאתקצאי לבין השמשות ויותר נראה שרומז למ\"ש בריש מסכת י\"ט דהא דא\"ר שיורי פתילה שכבו בשבת אסור להדליק בהן בי\"ט לא קי\"ל הכי משום דמטעם קדושה אחת אסרי ליה ולא מטעם הכנה דלא שייך הכנה בכה\"ג ומה\"ט נמי כי מקלע ש\"ת באחד בשבת שרי אתרוג באכילה אע\"ג דבשבת אסור דב' קדושות הן והכנה אין כאן עכ\"ל והר\"ן כתב בהדיא כדעת הרא\"ש דלא מיתסר משום הכנה והתוס' בפ' המביא כדי יין (ביצה ל.) כתב בדברי הרי\"ף ונתנו טעם לדבריהם דהואיל ובע\"ש היה אסור שהוא ט' והוא י\"ט אם היה נאכל בשבת מוכן לי\"ט אסור לשבת דהוי כעין נולד כיון שבא עתה ראויות שלו ולא בא בי\"ט:","\u0003הפריש ז' אתרוגים לז' ימים כל אחד יוצא בו ואוכלו למחר וכו'\u0004 שם פלוגתא דאמוראי ופסקו הפוסקים כרב אסי דאמר כל א' וא' יוצא בו ואוכלו למחר וכתב הר\"ן בריש ביצה בשם הרא\"ה דה\"ט דלא אמרי' בכל חד מגו דאתקצאי לבין השמשות אתקצאי לכולי יומא דכיון דהפריש ז' אתרוגים לז' ימים הרי הוא כמתנה בפירוש שאינו מקצה אותו אלא למצותו: כתוב בא\"ח ירושלמי אתרוג שנפסל ביום א' מותר לאכלו עכ\"ל ויש לתמוה ע\"ז אמאי לא מיתסר משום דאתקצאי לבין השמשות כתוב בהגהות אשיר\"י פרק המביא כדי יין בשם א\"ז עבדה להושענא ולא אגדה למיפק ביה שרי בהנאה דהזמנה לאו מלתא היא:"],["\u0003אתרוג בשביעי אסור כו'\u0004 בפרק לולב וערבה פליגי בה ר\"י ורשב\"ל ומשמע בסוגיא דקי\"ל כר\"י דאמר אתרוג כשר כל יום ז' ואפילו לאחר שיצא בה דלכל יום ז' אתקצאי דקאמר ואנן דאית לן תרי יומי היכי עבדינן אמר אביי שמיני ספק ז' אסור ט' ספק ח' מותר מרימר אמר אפילו ח' ספק ז' מותר והילכתא כאביי פירוש אנן דאית לן תרי יומי היכי עבדינן מי אסרינן ליה כיומא קמא משום ספק ז' או לא אלמא דפשיטא לן דביום ז' אסור וכן פירש\"י:","\u0003ומ\"ש ואפי' נפסל כו'\u0004 מימרא דר' זירא שם והב\"י העתיק ירושלמי אתרוג שנפסל ביום א' מותר לאוכלו עד כאן לשונו נראה בעיני דהכי פירושו שנפסל ביום ראשון קודם שיצא בו דאין לו דין מוקצה מאחר שלא עשה מעשה בגוף האתרוג אלא הזמנה בעלמא דלאו מילתא היא דדוקא כשבירך עליו אז הוקצה לכל ז' ימים ושוב אין לו היתר אפי' נפסל אחר כך וה\"ה נמי דאפילו לא נפסל מותר לאכלו אם יש לו אתרוג אחר לצאת מטעם דהזמנה לאו מילתא היא אלא דאורחא דמילתא נקט כנ\"ל לפרש שלא יחלוק הירושלמי אתלמודא דידן ועדיין צ\"ע לענין מעשה ומה שהקשה אמאי מותר בשמיני ולא אמרינן כיון דאתקצאי לב\"ה דשמיני ספק שביעי אתקצאי לכולי יומא כבר האריכו התוס' על זה בפ\"ק דסוכה בדף י' והרא\"ש בפ' לולב וערבה ע\"ש ומ\"ש בשם הר\"פ ושהרא\"ש כתב כתב עליו דלא נהירא דלא שייך בזה הכנה נראה בעיני ליישב דהר\"פ לאו הכנה ממש קאמר אלא כעין הכנה מאחר דבשבת היה אסור אם היה מותר ביום א' הוי כעין נולד כיון שעכשיו בא ראויות שלו וכן צריך לפרש בהכנה שאמרו בביצה בפ\"ק די\"ט בשבת וי\"ט הסמוכים דלאו הכנה ממש קאמר כמו שפי' התו' והר\"ן להדיא לשם גם בתוס' בפ' המביא כדי יין מבואר שמזה הטעם נהגו העולם איסור באתרוג וכך היא העיקר כדברי הר\"פ ז\"ל נ\"ל: הפריש ז' אתרוגים כו' שם פלוגתא דרב ורב אסי והילכתא כמ\"ד דביומו אסור לגמרי דקיימי בשיטת ר\"י דאמר לכולי יומא אתקצאי:"]],["\u0010c0\u0011\u0010y0\u0011אע\"פ שגמר סעודתו ביום ז' לא יסתור סוכתו שמא יזדמן לו סעודה אחר כך ויצטרך לאכול בה ומוציא הכלים ממנה מן המנחה ולמעלה ומתקן הבית לכבוד י\"ט האחרון \u0010y1\u0011ואם רוצה לאכול בה בשמיני צריך לפחות בה מקום ד' על ד' לעשות היכר שאנו יושבין בה שלא לשם מצות סוכה שלא יהא נראה כמוסיף וזהו דוקא לבני א\"י שאין צריכין לישב בה בח' ויום ז' הוא להם חול הלכך יכולין לסותרה ולפחות בה אבל אנו שצריכין לישב בה בח' אין לעשות בה שום הכירא של פסול שהרי משום ספק ז' אנו יושבין בה ואם רוצה לישב בה בט' א\"א לפחות בה בח' מפני שהוא י\"ט ומה יעשה להכירא אם היא קטנה שאסור להניח בה הנר יניחנו בה ובזה יש הכירא ואם גדולה היא שמותר להניח בה הנר יניח בתוכה כלי המאכל שאין אסורין להניחם בתוכה:",["אע\"פ שגמר סעודתו ביום השביעי לא יסתור סוכתו שמא יזדמן לו סעודה אחר כך ויצטרך לאכול בה משנה בפ' לולב וערבה (סוכה מח.) סוכה שבעה כיצד גמר מלאכול לא יתיר את סוכתו אבל מוריד הוא את הכלים מן המנחה ולמעלה מפני כבוד י\"ט האחרון של חג ופירש\"י גמר מלאכול: בשביעי: לא יתיר את סוכתו. לא יתיר אגדיה שלא לסותרה דהא כל היום חובתה לישן ולשנן ואי איקלע ליה סעודתא אכל לה בגווה: אבל מוריד הוא את הכלים. ואת המצעות שנשתמש בהם בתוכה מפני כבוד י\"ט שמראה כמכין עצמו לקראתו למקום שיסעוד שם הלילה ודבר פשוט הוא דהיינו דוקא לבני א\"י אבל לבני ח\"ל דעבדי תרי יומי מספק צריך לאכול בסוכה גם בשמיני וכמו שיתבאר בסי' תרס\"ח:","\u0003ומ\"ש רבינו ואם רוצה לאכול בה בשמיני צריך לפחות בה מקום ד' על ד' וכו'\u0004 עד סוף הסי' שם אין לו מקום להוריד כליו מהו רבי חייא בר רב אמר פוחת בה ארבעה וריב\"ל אמר מדליק בה את הנר ולא פליגי הא לן והא להו תינח סוכה קטנה סוכה גדולה מאי איכא למימר דמעייל בה מאני מיכלא דאמר רבא מאני מיכלא בר ממטללתא ופרש\"י אין לו מקום. אחר לאכול שם שיוריד כליו וצריך לאכול בה בי\"ט האחרון מה יעשה להוכיח שאינו מוסיף על המצוה לעשות סוכה ח' ימים והא דאסור להניח בשבעת ימי החג נר בסוכה קטנה ומאני מיכלא אפי' בסוכה גדולה נתבאר בסי' תרל\"ט:"],["\u0003אע\"ג וכו'\u0004 משנה פ' לולב וערבה סוכה שבעה כיצד גמר מלאכול לא יתיר את סוכתו אבל מוריד הוא את הכלים מן המנחה ולמעלה מפני כבוד י\"ט האחרון של חג ובגמרא אין לו מקום להוריד כליו וצריך לאכול בסוכה בי\"ט האחרון מה יעשה להוכיח שאינו מוסיף על המצוה לעשות סוכה שמנה ימים רב חייא בר רב אומר פוחת בה ארבעה וריב\"ל אומר מדליק בה את הנר ולא פליגי הא לן והא להו פירש\"י הא לן לבני בבל שהשמיני שלהם ספק ז' ולא קים להו בקיבועא דירחא מדליק בה את הנר דאמרינן שרגא בסוכה קטנה לבר ממטללתא ולא יפחתנה ויפסלנה לפי שצריך לישב בה מחר והא להו לבני א\"י דקים להו בקיבועא דירחא ולא יתבי בסוכה בשמיני פוחת ע\"כ מבואר מפירושו דס\"ל דאף לדידן צריך שיעשה היכר בשמיני שלא יהא נראה כבל תוסיף ומש\"ה מדליק בה את הנר בליל שמיני ספק שביעי. והרא\"ש הקשה על דבריו וז\"ל ותימה לי שלא ראיתי מי שעשה כן ועוד דא\"כ דאפילו יש לו מקום להוריד שם כליו צריך להדליק בו את הנר שלא יהא נראה כבל תוסיף מה שאוכל בה בלילה ונראה בעיני דל\"ק מידי דפשיטא דכשיש לו מקום להוריד שם כליו איכא היכירא טובא במה שהוריד מן הסוכה כל כליו הנאים והמצעות הנאות שהיו בסוכה לישן עליהן ולא נשאר שם כי אם כלי אכילה ולפיכך א\"צ להדליק בה את הנר אלא בשאין לו מקום להוריד שם כליו דנשארו כל הכלים והמצעות בסוכה כבראשונה ומותר לאכול ולישן שם דליכא משום בל תוסיף בלא כונה כיון שאינו בזמנו כדאיתא בפרק ראוהו ב\"ד ואע\"ג דאיסורא מיהא איכא כמ\"ש במרדכי ס\"פ לולב וערבה היינו דוקא לכתחלה אבל כאן שאין לו מקום ודאי דיעבד הוא ושרי כמ\"ש המרדכי לשם להדיא וא\"כ ליכא היכירא כל עיקר לפיכך הצריכו להדליק בה את הנר להיכירא ובזה נתיישב ג\"כ מה שתמה הרא\"ש במה שלא ראה מי שעשה כן דזהו משום דרובא דרובא יש להם מקום להוריד שם המצעות ושפיר איכא היכירא במה שסילק המצעות שלא לישן בסוכה עוד אכן הרא\"ש ז\"ל לא נראה לו פירש\"י ופי' בע\"א דלדידן ודאי מאחר שצריכין לישב בסוכה בח' משום ספק אין לעשות בה היכירא של פסול לא לפחות בה ד' ולא להדליק בה את הנר ואפילו יש לו מקום להוריד שם כליו אינו מוריד שהרי צריך הוא לחזור ולהעלות כליו לסוכה לאכול שם בשמיני י ותנא דמתניתין בא\"י קאי שא\"צ לישב בה בח' כל עיקר לפיכך אם יש לו מקום מוריד שם כליו ביום ז' מן המנחה ולמעלה שמראה כמכין עצמו לקראת י\"ט האחרון ואם אין לו מקום וצריך לאכול בה בשמיני פוחת בה ד' ביום ז' שהוא חש\"מ להיכירא שיושבין בה בשמיני שלא לשם מצות סוכה אבל לדידן דביום ז' אין לעשות בו שום היכירא של פסול וכ\"ש לפחות בה דבר שהרי צריך לישב בה בח' משום ספק ז' הלכך אם רוצה לישב בה בתשיעי ספק שמיני ואי אפשר לפחות בה בשמיני מן המנחה ולמעלה שהרי הוא י\"ט צריך להדליק בה את הנר בליל תשיעי להיכירא שלא יהא נראה כמוסיף וכך נראה מדברי הרי\"ף שמפרש כן וכך הם דברי רבינו. ולענין הלכה כבר נתפשט המנהג ברוב העולם שמורידין כל המצעות והכלים הנאים ביום ז' מן המנחה ולמעלה ובלילה אוכלין בסוכה ואין עושין שום היכירא של פסול בהנחת הנר או כלי המאכל דדי היכירא במה שהורידו המצעות וע\"פ פירש\"י וכמו שביארתי דעתו ואם לא היה לו מקום להוריד שם המצעות כל עיקר יעשה היכירא בליל ז' בהנחת הנר או כלי מאכל לחוש לפירש\"י אבל מה שנהגו מקצת שלא לאכול בסוכה ביום המחרת ומקצתם אוכלין מקצת סעודה בסוכה ומקצתן בבית וניתלין במדרש ר' תנחומא שכתב שם שנפטרין מן הסוכה בי\"ט האחרון של חג כדי שיתפללו על הגשמים בלב שלם נראה בעיני שהן עוברין על התלמוד דאיפסקא הילכתא בהדיא יתובי יתבינן ברוכי לא מברכינן ומתנחומא אין ראיה דאפשר דעל מה שנפטרין מן המנחה ולמעלה קאמר דעושין כן כדי שיתפללו בלב שלם על הגשמים אבל סעודה ודאי אסור ואפילו מן המנחה ולמעלה וכמו שפסק במרדכי להדיא דכשחל בשבת צריך לסעוד סעודה שלישית בסוכה אלא לאחר שכבר סעדו נפטרו מן הסוכה ואין יושבין בה כל היום וכמו שמשמע נמי מן התלמוד על זה קאמר בתנחומא שעושין כן כדי שיתפללו בלב שלם על הגשמים ועוד נהגו מקצתם שלא לישב בסוכה בליל ח' כל עיקר וביום ח' יושבין ואפשר שדעתם לעשות היכירא במה שאין אוכלין שם בלילה שלא יהא נראה כמוסיף מה שאוכל בסוכה ביום ח' מאחר שכבר הפסיק מלאכול בסוכה ורבינו כתב לקמן בסי' תרס\"ח שזה אינו מנהג. וכל בעל נפש יחמיר לישב בסוכה כל שמיני בלילה וביום כדין התלמוד:"]],["\u0010c0\u0011\u0010y0\u0011סוכה ונויה אסורין גם בח' \u0010c1\u0011\u0010y1\u0011ולדידן גם בט' שהוא ספק ח' \u0010y2\u0011כתב א\"א הרא\"ש ז\"ל וכדמקלע שבת במוצאי י\"ט האחרון של חג נוהגין שלא להסתפק מנויי סוכה עד מוצאי שבת ונראה דשרי:",["עצי הסוכה ונוייה אסורים גם בשמיני בפ' לולב וערבה (סוכה מו.) אר\"י סוכה אפי' בשמיני אסורה ומפרש טעמא משום דחזיא לבהש\"מ דאי מתרמי ליה סעודה בעי למיתב בגוה ומיכלא אתקצאי לבהש\"מ ומגו דאתקצאי לבה\"ש אתקצי לכולי יומא דשמיני וכתב הרא\"ש אע\"ג דלא מיחייב לאכול בה אלא משו' ספק יום שעבר דלמא אכתי יום הוא מ\"מ מיחייב למיכל בה מאיזה טעם שיהיה וצריך לעשות מעשה בין השמשות לאכול בה והר\"ן כתב בריש ביצה דאע\"ג דבעלמא לא אמרינן מגו דאיתקצאי כשהאיסור מחמת יום שעבר מוקצה למצותו חמיר טפי כתב הר\"ן בפ' המביא כדי יין אם התנה ליהנות מעצי סוכה ונוייה לכשיפלו אין תנאו כלום. דכי היכי דסוכה אסורה כ\"ז מצותה אפי' נפלה נוייה נמי אסירי ומיהו ביום הח' משמע ודאי דמהני תנאה לסוכה ולנוייה כל שנפלו דכיון דלא מתסר אלא משום מוקצ' מהני בהו תנאה כי היכי דמהני בכל מוקצה עכ\"ל וכבר כתבתי זה בסימן תרל\"ח:","\u0003ומ\"ש רבינו ולדידן גם בט' שהוא שמיני פשוט הוא:\u0004 ","וכתב הרא\"ש כדמקלע שבת במוצאי י\"ט האחרון של חג נוהגין שלא להסתפק ז\"ל התוספות בפרק המביא כדי יין נהגו העולם כשחל תשיעי של חג בע\"ש אין מסתפקין מהן בשבת שהוא עשירי ומ\"ט אי משום סתירת אהל לא שייך כדפי' ואי משום דאתקצאי בין השמשות דתשיעי תרי מגו כה\"ג לא אמרי' דבתשיעי נמי לא נאסר אלא מטעם מגו וי\"ל דהיינו טעמא משום הכנה דהואיל ובע\"ש היה אסור שהוא תשיעי והוא י\"ט אם הי' נאכל בשבת מוכן לי\"ט אסור בשבת דהוי כעין נולד כיון שבא עתה ראויות שלו ולא בא בי\"ט וכבר כתבתי בסי' תרס\"ה שהרא\"ש והר\"ן חולקים ואומרים דלא מתסר משום הכנה ובפ\"ק דסוכ' כתבו התוס' והיכא דמקלע שבת במי\"ט אחרון של חג נוהגין איסור להסתפק בנוי סוכה עד מ\"ש ולכאור' שרי דמאיזה טעם נאסור אי משום דכקדושה אחת היא שבת וי\"ט הא אמר רב פ\"ק דביצה הלכה כד' זקנים ואליבא דר\"א דאמר שתי קדושות הן ואי משום הכנה מה הכנה יש כאן ע\"כ וכ\"כ הרא\"ש בריש מסכת י\"ט:"],["\u0003סוכה ונויה וכו'\u0004 בפרק לולב וערבה אמר ר' יוחנן סוכה אפילו בשמיני אסורה ומפרש אביי דה\"ט דכיון דחזיא לבין השמשות דאי מתרמי ליה סעודתא בעי מיתב בגווה ומיכל בגווה אתקצאי לב\"ה ומגו דאתקצאי לב\"ה אתקצאי לכולא יומא וכתבו התו' וא\"ת ל\"ל טעמא דאי אתרמי סעודתא תיפוק ליה דאסורה משום יתירת אהל וי\"ל דאיצטריך למיסר בשמיני אפי' נפלה בחש\"מ כו' א\"נ לענין נוי סוכה דאין בהם משום סתירת אהל עכ\"ל וכך הם דברי רבינו סוכה ונוייה וכו' כלומר סוכה דומיא דנויה שאין בהן משום סתירה אהל אסורין גם בשמיני:","\u0003ומ\"ש ולדידן גם בתשיעי וכו'\u0004 פי' דכיון דאתרוג דמיקל ביה ר' יוחנן דמותר בח' לדידהו מ\"מ לדידן אסור בשמיני ממילא סוכה דמחמיר בה ר\"י דאף בשמיני אסור לדידהו ממילא לדידן אסור נמי בתשיעי ועוד לפי הטעם דאי אתרמי ליה סעודתא וכו' ודאי אף בתשיעי אסור דשייך ביה נמי האי טעמא לדידן דמיתב יתבינן כל שמיני. וכתב הרא\"ש ז\"ל וכד מקלע שבת כו' עד סוף הסי' בפ' לולב וערבה כ\"כ וכבר כתבתי בסי' תרס\"ו ושהעיקר כדברי הר\"פ דשייך דין הכנה בכל מה שהיה אסור בשבת ושרינן ליה בי\"ט שאחר השבת אע\"ג דלא הוי הכנה ממש הילכך גם נויי סוכה אין להתיר בשבת דמאחר שהיו אסורין בע\"ש שהוא תשיעי וי\"ט אם היה נאכל בשבת הו\"ל כמכין מי\"ט לשבת והתו' ג\"כ כתבו שכבר נהגו העולם איסור בזה:"]],["\u0010c0\u0011\u0010y0\u0011ליל ח' ערבית מתפללין ג' ראשונות וג' אחרונות וקדושת היום באמצע ואומר ותתן לנו את יום שמיני חג עצרת הזה ומקדש בב\"ה ונפטרין לבתיהם לשלום \u0010c1\u0011\u0010y1\u0011ואוכלין בסוכה מפני שהוא ספק שביעי \u0010c2\u0011ואין מברכין על ישיבתה שא\"כ היינו עושין אותו חול אלא שאנו יושבין בה מספק ולא שייך בישיבתו בה לומר היאך נעשנו חול שכך דרך בני אדם לפעמים לישב בצל סוכה אפילו שלא לשם מצות סוכה \u0010c3\u0011\u0010y2\u0011ומקדשים ואומרים זמן \u0010y3\u0011וכן למחר יושבין בה עד לאחר הסעודה \u0010c4\u0011\u0010y4\u0011ויש נוהגין שלא לישב בה בליל שמיני וביום השמיני יושבין בה ואינו מנהג \u0010y5\u0011בבקר משכימין לב\"ה ומתפללים יוצר כמו בערבית וגומרין ההלל ומוציאין שני ספרים וקורין באחד ה' בראה כל הבכור ואם הוא שבת קורין שבעה ומתחילין עשר תעשר ויש שמתחילין לעולם עשר תעשר לפי שהוא זמן אסיפה ומתנות עניים והמפטיר קורא בשני ביום השמיני עצרת עד סוף הסדר \u0010y6\u0011ומפטיר במלכים ויהי ככלות שלמה ומחזיר הספרים ואומר קדיש ומכריז משיב הרוח ומוריד הגשם ואין פוסקין כדלעיל בתפלת החול:",["ליל שמיני ערבי' מתפללין ג' ראשונות ואומר ותתן לנו את יום שמיני חג עצרת הזה בפ' לולב וערבה (סוכה מז. מח:) תניא שמיני רגל בפ\"ע לענין פז\"ר קש\"ב פייס בפ\"ע זמן בפ\"ע רגל בפ\"ע קרבן בפ\"ע שירה בפ\"ע ברכה בפ\"ע ופירשו התוס' והרא\"ש דברכה בפ\"ע היינו שבתפלה ובבה\"מ אומרים את יום שמיני חג עצרת הזה וכ\"פ ג\"כ רש\"י אהא דאמרי' התם שמיני ספק שביעי שביעי לסוכה ושמיני לברכה:","\u0003ואוכלין בסוכה מפני שהוא ספק שביעי ואין מברכין על ישיבתה וכו'\u0004 מסקנא דגמ' שם (מז.) והילכתא מיתב יתבינן ברוכי לא מברכינן וכתב הרא\"ש והיינו טעמא דלא מברכינן דכיון דיום שמיני עצרת הוא א\"א לברוכי בסוכה דקשיין אהדדי אי יום סוכה הוא לאו שמיני עצרת הוא ואי שמיני עצרת הוא לאו יום סוכה הוא ומשום ספקא דתרווייהו עבדינן לחומרא יתבינן בסוכה ולא מברכינן ונוהגים בו מנהג י\"ט דהוא יום שמיני עצרת ועבדינן לחומרא אבל בלולב לא רצו לתקן שיטלוהו בלא ברכה מספק מפני שהוא מוקצה לטילטול ומינכרא מלתא שהוא נוהג בו מנהג חול אבל סוכה פעמים שסוכתו עריבה עליו ואוכל בה בי\"ט האחרון כתב המרדכי יתובי יתבינן ברוכי לא מברכינן פי' ראבי\"ה כיון דאיכא היכירא דלא מברך כאשר עשה כל ז' ימים לא הוה כמוסיף אבל לישן בסוכה אסור משום דמיחזי כמוסיף ע\"כ . ואין נראה כן דעת הפוסקים שסתמו ולא חלקו בכך:","\u0003ומ\"ש ומקדשין ואומרים זמן כבר נתבאר בסמוך שהוא רגל בפ\"ע לענין זמן:\u0004 ","\u0003ומ\"ש וכן למחר יושבין בה פשוט הוא:\u0004 ","ומ\"ש ויש נוהגין שלא לישב בה בליל ח' טעמו מפני שבלילה צריך לברך זמן ואם אוכל אז בסוכה נמצאת אז אכילתו בסוכה סותרת את ברכת זמן ומפני כך סוברים שמה שאמרו בגמ' מיתב יתבינן ביום דוקא אמר וכן שאין אומרים בו זמן וכתב רבי' שאינו מנהג משום דכיון דסתמא אמרו מיתב יתבינן אין לחלק בין יום ללילה:","\u0003בבקר משכימין לב\"ה ומתפללין יוצר וכו'\u0004 וקורין בא' חמשה בראה כל הבכור שבי\"ט קורין ה' פשוט פ' הקורא עומד (כ.) וכשקורין כל הבכור בח' עצרת בפ' בני העיר (מגילה לא.):","ומ\"ש שמפטיר ויהי ככלות שלמה ג\"ז שם וכתב רש\"י שהטעם שמפטירין כן על שם ביום השמיני שלח את העם:"],["\u0003ליל שמיני כו'\u0004 בפ' לולב וערבה תניא דשמיני עצרת רגל בפני עצמו הוא לענין ברכה והסכימו התוס' והרא\"ש דהיינו לומר את יום השמיני חג העצרת הזה בתפלה וברכת המזון ודלא כמ\"ש בתוספות דהיינו ברכה שמברכין את המלך וכן פירש\"י אהא דקאמר רב שמיני שביעי לסוכה ושמיני לברכה:","\u0003ומ\"ש ואוכלין בסוכה כו'\u0004 מסקנא דגמרא שם והילכתא יתובי יתבינן ברוכי לא מברכינן:","ומ\"ש שהטעם שאין מברכין על ישיבת' שא\"כ היינו עושין אותו חול פי' וכבר עשינו אותו קדש שאומר את יום שמיני חג העצרת הזה וא\"כ סתרי אהדדי שאם יום סוכה הוא לאו שמיני עצרת הוא ואי שמיני עצרת הוא לאו יום סוכה הוא הילכך אזלינן לחומרא ויושבין בה מספק ולא מברכינן ונוהגין בה מנהג י\"ט דהוא יום שמיני עצרת ועבדינן לחומרא וכ\"כ הרי\"ף והרא\"ש ומ\"ש ולא שייך בישיבתו וכו' כ\"כ הרא\"ש לשם:","ומ\"ש ומקדשין ואומרין זמן שם בברייתא רגל בפני עצמו לעניין זמן ומ\"ש וכן למחר יושבין בה עד אחר הסעודה נראה שכונתו לומר דלאחר הסעודה כבר הוא מן המנחה ולמעלה ומוריד כליו להכין עצמו לי\"ט האחרון שהוא שמיני ספק תשיעי וכבר כתבתי בסימן תרס\"ז דלאו שפיר עבדי הני דאכלי הסעודה בבית אפילו מקצת הסעודה:","\u0003ומ\"ש ויש נוהגין וכו'\u0004 גם על זה כתבתי שם שאפשר שנהגו כן כדי לעשות הפסקה בין ז' לח' דכיון שאכל בליל ח' בביתו שוב אף אם יאכל ביום ח' בסוכה אינו נראה כמוסיף מידי דהוה אאוכל בסוכה באמצע השנה ועוד אפשר לומר דכיון דמצוה הוא להוסיף מחול על הקודש אם כן אם יאכל בליל ח' בסוכה צריך הוא לברך לישב בסוכה מאחר שעדיין יום ז' הוא בשעת קידוש ומאחר שאומר את יום שמיני העצרת הזה אין לו לברך על הסוכה ולעשותו חול דאם כן סתרי אהדדי ועל כן נהגו שלא לישב בה בליל שמיני וכתב רבינו שאינו מנהג דמה נפשך אם יום הוא בשעת הסעודה אסור לו לאכול חוץ לסוכה מדין התורה ואם לילה הוא יאכל בסוכה ולא יברך והב\"י פי' בע\"א מכל מקום ראוי שלא לעשות קידוש בליל ח' בסוכה אלא א\"כ הוא ודאי לילה וכן נמצא בליקוטים בשם מה\"ר טעבלין:"]],["\u0010y0\u0011ליל תשיעי מתפללין כמו בליל שלפניו ומקדשין ואומרים זמן ולמחר מתפללין כמו ביום שלפניו ומוציאין ג' ספרים \u0010y1\u0011וקורין בא' וזאת הברכה והמפטיר קורא בשני כמו אתמול ומפטיר במלכים ויעמוד שלמה לפני ה' ובירושלים יש שמפטירין ויהי אחרי מות משה והכי מנהגינו ובשלישי מתחיל בראשית וקורין אותו ש\"ת לפי שמסיימין בו התורה וראוי לשמוח בסיומה ורגילין להתחיל מיד בראשית כדי שלא יהא פתחון פה לשטן לקטרג לומר כבר סיימו אותה ואינם רוצים לקרותה עוד ומרבין בפיוטים כמו אשר בגלל אבות ויש מקומות שמוציאין כל הספרים ואומרים על כל אחד ואחד פיוט כל מקום לפי מנהגו \u0010y2\u0011ונוהגין באשכנז שהמסיים והמתחיל נודרין נדבות וקוראין לכל מרעיהן ועושין משתה ושמחה וי\"ט לסיומה של תורה ולהתחלתה \u0010y3\u0011ולמוצאי י\"ט מבדילין בתפלה וכן על הכוס כדרך שמבדילין במוצאי שבת אלא שאין מברכין על הנר ולא על הבשמי':",["\u0003ליל תשיעי מתפללין כמו בלילה שלפניו וכו'\u0004 כל זה פשוט:","\u0003ומ\"ש וקורין בא' וזאת הברכה וכן מ\"ש ומפטיר ויעמוד שלמה פשוט בפרק בני העיר (שם:\u0004 ","ונוהגים באשכנז שהמסיים והמתחיל נודרין נדרים וקוראים לכל מרעיהם ועושין משתה ושמחה וי\"ט לסיומה של תורה כ\"כ בהג\"א פ' לולב וערבה בשם א\"ז. ומצאתי עיקרו של מנהג במדרש בתחלת שיר השירים ויבא ירושלים ויעמוד לפני ארון ברית ה' וכו' ויעש משתה לכל עבדיו אמר רבי יצחק מכאן שעושין סעודה לגמרה של תורה:","ולמוצאי י\"ט מבדילין בתפלה וכן על הכוס כדרך שמבדילין במ\"ש אלא שאין מברכין על הנר ולא על הבשמים כבר נתבאר בסימן תצ\"א:"],[]],["\u0003הלכות חנוכה\u0004\n\u0010c0\u0011\u0010y0\u0011מאי חנוכה דתניא בכ\"ה בכסליו יומי חנוכה תמניא אינון דלא למספד בהון ודלא למגזר בהון תענית שכשנכנסו עו\"ג בהיכל טמאו כל השמנים שבהיכל וכשגברה יד מלכות בית חשמונאי ונצחום בדקו ולא מצאו אלא פך א' של שמן \u0010c1\u0011שהיה חתום בחותמו של כ\"ג \u0010c2\u0011ולא היה בו אלא כדי להדליק יום א' ונעשה בו נס והדליקו בו ח' ימים לשנה אחרת קבעום ח' י\"ט בהלל ובהודאה פי' לומר בהן הלל ולהודות לומר בו על הנסים בהודאה אבל מותרין הן בעשיית המלאכה \u0010c3\u0011\u0010y1\u0011ונוהגות הנשים שלא לעשות מלאכה בעוד שהנרות דולקות ואין להקל להן: \u0010y2\u0011וגם אם יש מקומות שנוהגין איסור בכל היום אין להקל להן \u0010c4\u0011משום דברים המותרים ואחרים נהגו בהן איסור אי אתה רשאי להתירם בפניהם וקראום חנוכה חנו בכ\"ה \u0010y3\u0011והיה אומר הר\"מ מרוטנבורק ז\"ל שרבוי הסעודה שמרבים בהם הן סעודת הרשות שלא קבעו אלא להלל ולהודות ולא משתה ושמחה אין מספידין בהם אלא לחכם בפניו ולעיל בהלכות ר\"ח כתבתי אם יש לומר בהן צידוק הדין:",["\u0003מאי חנוכה דתניא בכ\"ה בכסליו וכו'\u0004 בפ' במה מדליקין (שבת כא.) איכא למידק כי חתום בחותמו של כ\"ג מאי הוי נהי דאפי' נגעו בו מבחוץ לא נטמא דכלי חרס אינו מטמא מגבו אלא מתוכו מ\"מ ליחוש שמא הסיטוהו ונטמא כבר תירצו בתוס' שאם כבר גזרו על העו\"ג להיות כזבים צ\"ל שהיה מונח בחותם בקרקע שלא הסיטו הכלי וכן משמע מדברי רש\"י שכתב בחותמו בהצנעו וחתום בטבעתו והכירו שלא נגעו בו והר\"ן תירץ שאם הסיטוהו היו שוברים אותו לראות אם יש בו זהב או מרגליות כיון שראוהו נחתם בחותם של כ\"ג אלא ודאי לא מצאוהו כלל ולא ראוהו ואפשר שגם לזה כיון רש\"י במ\"ש והכירו שלא נגעו בו: והטעם שהוצרכו להדליק ח' ימים מאותו פך מפני שכל ישראל היו בחזקת טמאי מתים וא\"א לתקן שמן טהור עד שיעברו עליהם ז' ימים מיום טומאתם ויום א' לכתישת הזיתים ותקונם להוציא מהם שמן טהור והר\"ן כתב שהיה להם שמן טהור רחוק ד' ימים והוצרכו ח' ימים בין הליכה וחזרה ואיכא למידק למה קבעו ח' ימים דכיון דשמן שבפך היה בו כדי להדליק לילה א' נמצא שלא נעשה הנס אלא בז' הלילות וי\"ל שחילקו שמן שבפך לח' חלקי' ובכל לילה היו נותני' במנורה חלק א' והיה דולק עד הבקר ונמצא שבכל הלילות נעשה נס ועוד י\"ל שלאחר שנתנו שמן בנרות המנורה כשיעור נשאר הפך מלא כבתחלה וניכר הנס אף בליל הא' א\"נ שבליל ראשון נתנו כל השמן בנרות ודלקו כל הלילה ובבקר מצאו הנרות מלאים שמן וכן בכל לילה ולילה:","\u0003ונוהגות הנשים שלא לעשות מלאכה בעוד שהנרות דולקו' טעמן כדי שיהא להם היכירא שאסור להשתמש לאורן:\u0004 ","ומ\"ש וגם אם יש מקומות שנוהגין איסור בכל היום אין להקל להם משום דברים המותרים ואחרים נוהגים בהם איסור שאי אתה רשאי להתירם בפניהם הא דדברים המותרים ואחרים נהגו בהם איסור וכו' ברייתא היא בפרק מקום שנהגו (פסחים נא.) וסובר רבינו שאף בדבר שאין בענינו שום צד איסור לומר דגזרו הא אטו הא מיתני' ומפני כך כתב דחנוכה אע\"פ שאין שום זמן ממנה אסור בעשיית מלאכה לא ביום ולא בלילה אם היו נוהגים איסור בכל היום אין להקל עליהם ואינו מוכרח דאיכא למימר דכיון דאין בו צד סרך איסור לית לן בה:","והיה אומר הר\"ם מרוטנבורק שריבוי הסעודות שמרבים בהם הם סעודות הרשות כ\"כ ג\"כ המרדכי בפרק מקום שנהגו בשם הר\"ם כבר כתבתי בסימן ת\"ר דלדברי הכל מברין את האבל בחנוכה:"],["\u0003מאי חנוכה וכו'\u0004 פי' בפרק ב\"מ קא מפרש תלמודא הלכות חנוכה ובתר הכי קאמר מאי חנוכה כלומר על איזה נס קבעוה וכן פירש\"י ולפ\"ז התשובה היא דתניא וכו' ושמעתי דיש מפרשים דמאי חנוכה דתניא וכו' כל זה הוא לשון השאלה והתשובה הוא שכשנכנסו עו\"ג כו' וטועין דהא במגלת תענית כתובה ברייתא זו בלשון זה בכ\"ה בכסליו יומי חנוכה אינון וכו' וכן בסמ\"ג ומגיד משנה הובאה בלשון זה והא דנקט תלמודא לשון שאלה טפי בחנוכה וקאמר מאי חנוכה זהו לפי שכל המועדים וכן ימי פורים וד' צומות מפורש בכתוב משא\"כ חנוכה:","\u0003ה\"ג שהיה מונח בחותמו של כ\"ג וכו'\u0004 ופי' שהיה מונח בהצנעו בקרקע וניכר שלא הסיטו הכלי וגם היה חתום בחותם של כהן גדול וניכר שלא פתחוהו ונגעו בשמן וכן פירש\"י והתוס' ע\"ש ובהגהות החדשות למרדכי כ' י\"א שהיה מונח בתוך שידה קבועה בכותל שלא היה יכולים האויבים להסיטה והיה פתחה סגור וחתום בחותמו של כהן גדול ובסגירת הפתח בחותם הכירו שלא נגעו בפך וי\"א שזה היה קודם שגזרו עליהם עכ\"ל וע\"ש בתוס' ועיין עוד בביאורי הרא\"ם שעל הסמ\"ג ואפשר עוד לומר שהיה פיו צר שאינו יכול לכנוס בו אצבעו וכיון שאי אפשר ליטמא במגע בעודו בכלי אינו מטמא נמי בהיסט דלהכי אפקיה רחמנא להיסט בלשון נגיעה לומר לך שכל שאינו מטמא במגע אינו מטמא בהיסט וצריך שיהיה חתום דאם לא כן איכא חששא שמא הוציאו קצתו ונטמא והחזירוהו בתוכו א\"נ נטמא באהל המת כשלא היה צמיד פתיל עליו ועיין במ\"ש הרא\"ם בזה גם מ\"ש ב\"י שח' ימים הוצרכו להמתין מפני טומאה שבעה ימים וכו' כל אלו הפירושים כתב הרא\"ם לשם. והא דכתב ב\"י וכן בכל לילה ולילה חוזר גם לפירוש השני שכתב מקודם. ובהגהות החדשות למרדכי כתב טעמים אחרים לקביעות שמנה ימים: קבעום ועשאום כתב הרא\"ם לפי גירסא זו קבעום קאי אהדלקה דלעיל ועשאום קאי אהלל והודאה אבל לספרים שלא כתבו בהן אלא וקבעום לבד קשיא ממה שלא הוזכר גם הדלקה שהוא העיקר ע\"ש:","\u0003ומ\"ש ולא היה בו אלא כדי להדליק יום אחד וכו'\u0004 איכא להקשות היאך היו הכהנים מדליקין הנרות בטומאתן תירץ הרא\"ם שהדליקוה על ידי פשוטי כלי עץ שאינן מטמאין ומה שהקשה הלא גם המנורה היתה טמאה תירץ שהחשמונאים עשו מנורה של עץ כדמוכח בפרק כל הצלמים בפירוש רש\"י אך קשה הלא נטמאה המנורה בגמר עשייתה וי\"ל דלא נטמאו כל ישראל ומי שהיה טהור עשאה ולא קשה אם כן יעשו הטהורים גם כן שמן דאפשר שלא היו בקיאין בעשיית שמן כשר למנורה וכן צריך לומר להר\"ן שכתב שהיה להם שמן טהור והוצרכו ח' ימים בין הליכה וחזרה דקשיא ג\"כ דהו\"ל לעשות שמן מיד אלא צ\"ל שלא היו בקיאין בעשייתו והשתא אין צריך לפרש שהדליקום ע\"י פשוטי כלי עץ אלא הכהן שלא נטמא הדליקם דהדלקת נרות אין צריך כ\"ג ותדע דהא קשיא היאך נתנו השמן לתוך הבזיכין הלא נטמא מיד כשאחז בפך אלא ודאי דכהן טהור אחז בו ונתנו לבזיכין. ומה שק' הלא הדלקת נרות דוחה את הטומאה תירץ הרא\"ם דשאני עשיית השמן שהוא ממכשירי ההדלקה ואינה דוחה דומיא דמכשירי מילה בשבת ע\"ש:","\u0003ונוהגות הנשים וכו'\u0004 וגם אם יש מקומות שנוהגין איסור וכו' פי' גם אם יש מקומות שנוהגין הנשים איסור כל היום אין להקל אבל באנשים אין מנהג כלל לאיסור והכי משמע בספר צידה לדרך:","\u0003ומ\"ש משום דדברים המותרים וכו'\u0004 השיג ב\"י ואמר ואינו מוכרח דאיכא למימר דכיון דאין בו צד סרך איסור לית לן בה עכ\"ל ולפע\"ד נראה דדמיא להא דפוסק מהר\"ם בתענית שלפני ראש השנה ויום הכפורים ושלא לאכול בשר מי\"ז בתמוז דצריך התרה ואע\"ג דליכא התם ג\"כ סרך איסור מדין התלמוד וה\"ט דכיון דקיבל עליו תעניות אלו לשם תשובה ושוייה עילויה חתיכה דאיסורא אסור להקל בהו וה\"נ גבי חנוכה כיון שנעשה הנס ע\"י אשה וקבלו עליהם איסור מלאכה כדין י\"ט שויוה עלייהו חתיכה דאיסורא ואין להקל להן וכ\"כ בספר צידה לדרך. וז\"ל מהרי\"ל קבלה בידינו שאין לאדם לעשות מלאכה בשעה שנרות דולקים בחנוכה. וי\"ל גם ביום הראשון וביום האחרון מנהג רבותינו נ\"נ לאסור מלאכה עכ\"ל ונראה קצת ראיה מדקראו להו חנוכה לומר חנו בכ\"ה דאי אין איסור כלל במלאכה מאי חנייה שייך כאן דדוחק הוא לומר דר\"ל חנייה ממלחמה ועוד דרז\"ל במדרש שחנוכת הנשיאים היתה בחנוכה והקב\"ה שילם להם שכרם בימי מתתיהו וכו' הנה כשם שהנשיאים כל אחד עשה ביומו יום טוב גם בחנוכה יש להם לעשות י\"ט בענין בטול מלאכה ומטעם זה נהגו להרבות בסעודות ובפרט הנשים שהנס נעשה ע\"י אשה והוא הדין לענין מלאכה שאסור לנשים וכדין ר\"ח ועיין בהגהות החדשות לספר מרדכי והיה אומר מהר\"ם וכו' ואיכא למידק היא גופה קשה למה לא קבעום למשתה ולשמחה כמו בפורים ונראה דבפורים עיקר הגזירה היתה לפי שנהנו מסעודתו ועל כן נגזר עליהם להרוג ולאבד את הגופים שנהנו מאכילה ושתייה של איסור ושמחה ומשתה של איסור וכשעשו תשובה עינו נפשותם וכמ\"ש אסתר לך כנוס את כל היהודים ואל תאכלו ואל תשתו שלשת ימים וגו' ולפיכך קבעום למשתה ויום טוב לזכור עיקר הנס אבל בחנוכה עיקר הגזירה היתה על שהתרשלו בעבודה וע\"כ היתה הגזירה לבטל מהם העבודה כדתניא בברייתא שגזר עליהן לבטל התמיד ועוד א\"ל מצוה אחת יש בידן אם אתם מבטלין אותן מידם כבר הם אבודין ואיזה זה הדלקת מנורה שכתב בה להעלות נר תמיד כל זמן שמדליקין אותן תמיד הם עומדין כו' עמדו וטמאו כל השמנים וכשחזרו בתשובה למסור נפשם על העבודה הושיעם ה' על ידי כהנים עובדי העבודה בבית ה' ע\"כ נעשה הנס גם כן בנרות תחת אשר הערו נפשם למות על קיום העבודה ולפיכך לא קבעום אלא להלל ולהודות שהיא העבודה שבלב ולענין הלכה יראה לע\"ד דלא כמהר\"מ דמנהג זה שמרבים בסעודה כבר נהגו בו גדולי הדור הקדמונים ומהרש\"ל כתב גם כן דברמב\"ם משמע דימי שמחה הן וכן כתב המרדכי הארוך עכ\"ל ועיין ברמב\"ם פרק שלישי הלכה ג' וז\"ל מהר\"ש מאוסטרייך דבחנוכה יש לנהוג שמחה ומשתה וכן מוכח קצת ברמב\"ם ויש מביאין ראיה מפ\"ב דשבת במרדכי והוכיחו קצת מרבינו יואל שפסק בברכת המזון אם לא אמר על הנסים מחזירין אותו ש\"מ דשאני משאר הימים ולא סגי בלא פת עכ\"ל:"]],["\u0010c0\u0011\u0010y0\u0011ויען כי אירע הנס בנרות תקנוה להדליק נרות בכל לילה כדי להזכיר הנס וצריך כל אדם ליזהר בהן מאד ואפילו עני המתפרנס מן הצדקה שואל או מוכר כסותו ולוקח שמן להדליק \u0010c1\u0011\u0010y1\u0011והזהיר בהן יהיו לו בנים ת\"ח \u0010c2\u0011\u0010y2\u0011וכמה נרות הם בליל א' מדליק א' מכאן ואילך מוסיף והולך א' בכל לילה עד שבאחרונה יהיו שמנה ואפילו אם רבים בני הבית לא יעשה יותר. \u0010c3\u0011\u0010y3\u0011נר שיש לו ב' פיות עולה בשביל שנים כגון מליל א' ואילך \u0010c4\u0011\u0010y4\u0011ואם מילא קערה שמן והקיפה פתילות אם כפה עליה כלי כל פתילה עולה בשביל נר אחד לא כפה עליה כלי אפילו לנר אחד אינו עולה לפי שהיא כמדורה \u0010y5\u0011וכתב א\"א הרא\"ש ז\"ל מסתברא שלא הרחיקם זה מזה עד כאצבע אבל אם הרחיקם זה מזה עד כאצבע שאינו נעשה כמדורה יצא \u0010y6\u0011ונראה לי דאפילו הרחיקם אין להתיר בלא כפיית כלי דמה גבול יש בהרחקה אם הפתילות גסות והלהב גדול אפילו יותר מכאצבע מתחברות ואם הם דקות אפילו פחות מכאצבע סגי להכי קאמרינן כפיית כלי דהוא מלתא דפסיקא \u0010c5\u0011\u0010y7\u0011ומניחה על פתח הסמוך לר\"ה מבחוץ אם הבית פתוח לרה\"ר מניחה על פתחו ואם החצר פתוח לר\"ה מניחה על פתחו \u0010c6\u0011ואם הוא דר בעלייה שאין לו פתח פתוח לר\"ה מניחה בחלון הסמוך לר\"ה \u0010c7\u0011\u0010y8\u0011ובשעת הסכנה שאינו רשאי לקיים המצוה מניחה על שולחנו ודיו וצריך נר אחר להשתמש לאורו ואם יש מדורה א\"צ נר אחר שיוכל להשתמש לאור המדורה ואם הוא אדם חשוב שאין דרכו להשתמש לאור המדורה צריך נר אחר אפי' אם יש מדורה \u0010c8\u0011\u0010y9\u0011מצוה להניחה למטה מי\"ט ואם הניחה למעלה מי' יצא \u0010y10\u0011אבל אם הניחה למעלה מכ' אמה אפי' בדיעבד לא יצא דלא שלטא ביה עינא וליכא פירסומי ניסא \u0010y11\u0011וכתב ה\"ר יואל הלוי דוקא כשמניחה בחוץ אבל כשמניחה בבית אפי' למעלה מעשרים אמה כשירה כדאמרינן גבי סוכה אם דפנות מגיעות לסכך אפי' למעלה מכ' אמה כשירה דשלטא ביה עינא ונ\"ל שאין הנידון דומה לראייה דהתם בעינן שתשלוט עינו בגג וכיון שמחיצות מגיעות לגג על ידם ישלוט עינו בגג אבל הכא שצריך שישלוט עינו בנרות כיון שהוא למעלה מכ' דלא שלטא ביה עינא מאי נפקא מינה בגג שהוא עדיין למעלה ממנו בשבילו לא שלטא ביה עינא טפי \u0010c9\u0011\u0010y12\u0011וה\"ר מאיר מרוטנבורק ז\"ל היה מדקדק להניחה למעלה מג\"ט ולמטה מי': \u0010y13\u0011ומצוה להניחה בטפח הסמוך לפתח משמאל \u0010y14\u0011כדי שתהא מזוזה מימין ונר חנוכה משמאל \u0010c10\u0011\u0010y15\u0011וכתב אבי העזרי שאם אין מזוזה בפתח מניחה מימין \u0010c11\u0011\u0010y16\u0011ובס\"ה הקטן כתב שאם מניחה בדלת עצמה יניחנה מחציו של כניסה לצד שמאל \u0010y17\u0011ובב\"ה מניחה \u0010y18\u0011לדרום זכר למנורה שהיתה בדרום ע\"כ: \u0010c12\u0011\u0010y19\u0011חצר שיש לה ב' פתחים מב' רוחות צריך להדליק בב' פתחים שלא יחשדוהו העוברים לומר כשם שלא הדליק בזה הפתח כך לא הדליק באחרת הילכך אם ב' הפתחים מרוח אחת שיכולין לראות כאחד די לו באחד מהן \u0010c13\u0011וכתב בעל התרומה לדידן שמדליקין בפנים אפי' בב' רוחות די לו באחד מהן שאין היכירא אלא לבני הבית והם יודעים ששני הפתחים של איש אחד \u0010c14\u0011ונראה שאין להקל ואף לדידן איכא חשש כיון שמדליקין בפתח הבית העוברין רואין שלא הדליק ואיכא חשד:",["ויען כי אירע הנס בנרות תקנו להדליק נרות בכל לילה כדי להזכיר הנס פשוט בפרק מדליקין (כא.): וצריך כל אדם ליזהר בהם מאד ואפי' עני המתפרנס מן הצדקה שואל או מוכר כסותו ולוקח שמן להדליקן כ\"כ הרמב\"ם וכתב ה\"ה דהיינו מדתנן בפ' ע\"פ (צט:) שאפילו עני שבישראל אל יפחתו לו מארבע כוסות של יין וטעמא משום פירסומי ניסא:","והזהיר בהם יהיו לו בנים ת\"ח בפ' במה מדליקין (שבת כג:) הרגיל בנר חנוכה ונר שבת הויין ליה בנים ת\"ח פירש\"י משו' דכתיב כי נר מצו' ותורה אור ע\"י נר מצו' דשב' ודחנוכ' בא אור התור':","\u0003וכמה נרות הם בליל ראשון מדליק אחד וכו'\u0004 שם (כא:) ת\"ר מצות נר חנוכה נר איש וביתו והמהדרין נר לכל א' ואחד והמהדרין מן המהדרין ב\"ש אומרים יום א' מדליק ח' מכאן ואילך הולך ופוחת וב\"ה אומרים יום א' מדליק אחד מכאן ואילך מוסיף והולך טעמייהו דב\"ש כנגד פרי החג א\"נ כנגד ימים הנכנסים וטעמייהו דב\"ה כנגד ימים היוצאים א\"נ משום מעלין בקודש ולא מורידין ומדברי הרמב\"ם נראה דמהדרין מן המהדרין עבדי נמי הידור ראשון דהיינו נר לכל א' וא' אם היו אנשי הבית עשרה בליל א' מדליק י' נרות ובליל ב' כ' ובליל ג' ל' אבל התוספות כתבו נראה לומר דב\"ש וב\"ה לא קיימי אלא אנר איש וביתו שיש יותר הידור דאיכא היכירא כשמוסיף והולך או מחסר כנגד ימים הנכנסים או היוצאים אבל אם יעשה נר לכל אחד אפילו יוסיף ליכא היכירא שיש לומר שכך יש ב\"א בבית עכ\"ל ונראה שהעולם שנוהגים להדליק בלילה הראשונה נר א' ומוסיף והולך בכל לילה עד שבאחרונה הם ח' ואפי' בני בית הרבה אינם עושים יותר דעתם כדעת התוספו' דאי כהרמב\"ם למה אינם עושים כמהדרין מן המהדרין:","נר שיש לו ב' פיות עולה בשביל שנים שם (כג.) נר שיש לו ב' פיות עולה לב' בני אדם פי' רש\"י עולה לב' בני אדם למהדרים העושים נר לכל א' וא' ורבי' לא כתב עולה לב' בני אדם מפני שאין אנו עושין נר לכל א' וא' שיצטרך נר זה לעלות לב' ב\"א וכתב שעולה בשביל ב' נרות וזהו שכתב כגון מליל ראשון ואילך כלומר דאילו בליל ראשון לא משכחת לדידן שיצטרך לעלות במקום שנים:","ואם מילא קערה שמן והקיפה פתילות אם כפה עליה כלי כל פתילה עולה בשביל נר א' לא כפה עליה כלי אפי' לנר אחד אינו עולה לפי שהוא כמדורה גז\"ש:","\u0003ומ\"ש בשם הרא\"ש מסתברא שלא הרחיקם זה מזה עד כאצבע וכו'\u0004 כ\"כ הר\"מ בשם בעל העיטור וכ\"כ שבולי הלקט בשם בעל הדברות:","\u0003ומ\"ש רבינו נ\"ל דאפילו הרחיקם אין להתיר בלא כפיית כלי וכו'\u0004 דברי טעם הם ומיהו י\"ל דשיעור הרחקת אצבע שאמרו בפתילות בינוניות ולפי אותו הערך צריך להוסיף ריחוק בגסות ולמעט ריחוק בדקות :","\u0003ומניחה על פתח הסמוך לר\"ה בחוץ וכו'\u0004 שם (כא:) ת\"ר נר חנוכה מצוה להניחה על פתח ביתו מבחוץ ואם היה דר בעלייה מניחה בחלון הסמוכה לר\"ה וכתבו התוספות מצוה להניחה על פתח ביתו מבחוץ מיירי דליכא חצר אלא ביתו עומד סמוך לר\"ה אבל אם יש חצר לפני הבית מצוה להניח על פתח החצר דאמרינן לקמן חצר שיש לה ב' פתחים צריכה ב' נרות ואמרינן נמי נר שיש לה ב' פיות עולה לב' בני אדם משמע לשני בתים ואם היו מניחין על פתח בתיהם היה לזה מימין ולזה משמאל אבל אי מניחם על פתח החצר אתי שפיר. אבל רש\"י פירש מבחוץ משום פירסומי ניסא ולא בר\"ה אלא בחצירו שבתיהם היו פתוחים לחצר ואם היה דר בעלייה שאין לו מקום בחצירו להניחו שם מניחו מבפנים כנגד החלון הסמוך לר\"ה ע\"כ ורבינו כתב כדברי התו' דמצוה להניח על פתח ביתו מבחוץ ולפיכך הוצרך לפרש דאם היה דר בעלייה מניחה בחלון הסמוכה לר\"ה בשאין לו פתח פתוח לר\"ה מיירי כלומר שאם היה פתח העלייה פתוח לר\"ה מניח' על הפתח ואם היה פתוח לחצר מניחה על פתח החצר שהוא פתוח לר\"ה אבל הכא מיירי כשהעלייה פתוחה לבית דהשתא כי מנח לה על פתח הבית או על פתח החצר לא מינכרא מלתא דמשום עלייה הוא ולפיכך מניחה בחלון הסמוך לר\"ה:","\u0003ומ\"ש ובשעת הסכנ' וכו'\u0004 עד צריך נר אחר אפי' אם יש מדור' שם:","מצוה להניחה למטה מי' טפחים שם תנן התם גץ היוצא מתחת הפטיש ויצא והזיק חייב גמל שטעון פשתן והוא עובר בר\"ה ונכנס פשתנו לתוך החנות ודלקה בנרו של חנוני והדליקה את הבית בעל הגמל חייב הניח החנוני את נרו מבחוץ החנוני חייב ר' יהודה אומר בנר חנוכה פטור אמר רבינא משמיה דרבא זאת אומרת נר חנוכה מצוה להניחה בתוך י' דאי ס\"ד למעלה מי' לימא ליה הוי לך להניחה למעלה מגמל ורוכבו ודלמא אי מטרח ליה טובא אתי לאימנועי ממצוה וכתב הר\"ן בשם ר\"ח דקי\"ל כרבינא דלא שבקינן מאי דפשיטא להו לרבא ורבינא ונקטינן מאי דאידחי בגמרא בדרך דלמא בעלמא וכ\"פ מהר\"י ולזה הסכים הרשב\"א ע\"כ וכ\"כ הרא\"ש וז\"ל אע\"ג דדחי ליה מצוה להניחה למטה מי' כדקאמר רבינא משמיה דרבא וגם איכא פירסום הנס טפי כשהיא למטה דדבר העשוי לאור אין דרך להניחה כ\"כ למטה וכן כתב בפי' רבינו חננאל ומצוה להניחה למטה מי' עכ\"ל וכן פסק סמ\"ק וסמ\"ג והרי\"ף והרמב\"ם השמיטו הא דמצוה להניחה למטה מי' משמע דס\"ל דכיון דדחו בגמרא להא דרבינא לא קי\"ל כוותיה ומ\"מ לענין מעשה נראה שצריך להניחה בתוך י' כיון דלהנך רבוותא מצותה בתוך י' ולרי\"ף והרמב\"ם מצותה בין בתוך י' בין למעלה מי' הלכך למעבד כמצותה אליבא דכ\"ע עדיף דהיינו בתוך י' ואע\"פ שהמרדכי כתב דעכשיו שהרגילו להניחה בפנים נראה דאין קפידא להניחה למעלה מי' (דלא) [דמוכח] פירסום מחמת שרבי' סתם דבריו משמע דלא שני ליה בין מניח מבפנים למניח מבחוץ וכן נהגו לעשות המדקדקים:","\u0003ומ\"ש אבל אם הניחה למעלה מכ' אמה אפילו בדיעבד לא יצא וכו'\u0004 גז\"ש אמר רב כהנא דרש רבי נתן בר מניומי משמיה דרב תנחום נר חנוכה שהניחה למעלה מכ' אמה פסולה כסוכה וכמבוי ופירש\"י פסולה דלא שלטא ביה עינא למעלה מכ' אמה וליכא פירסומי ניסא וכתבו התוס' שאם הניחה למעלה מכ' אמה ומיעטה והניחה כמו שהיא דולקת לא עשה כלום דהדלקה עושה מצוה אלא יכבנה וימעטנה ויחזור וידליקנה:","\u0003וכתב ה\"ר יואל הלוי דוקא כשמניחה בחוץ וכו'\u0004 ונ\"ל דאין הנידון דומה לראיה וכו' מצאתי כתוב בשם מוהר\"ר יצחק אבוהב ז\"ל נ\"ל שסברת רבינו יואל שכשיש בכאן אויר האויר הוא מזיק לעינים ואין האדם יכול להביט למעלה כל מה שירצה ולזה הביא ראיה מסוכה שאם הדפנות מגיעות לסכך אפי' למעלה מכ' כשירה ושלטא ביה עינא ובזה נראה שאין לו מקום לקושיית המחבר עכ\"ל:","והר\"ם מרוטנבורק היה מדקדק להניחה למעלה מג' טפחים ולמטה מי' כ\"כ המרדכי בפרק ב\"מ וטעמא משום דכל למטה מג' כארעא סמיכתא דמי והיה מניחה למטה מי' שהטעם שנתבאר דלא שבקינן מאי דפשיטא להו לרבא ורבינא ונקטינן מאי דאידחי בגמרא בדרך דלמא והיה לו לרבינו לכתוב הא דהר\"מ גבי הא דמצוה להניחה למטה מי' אלא דלא דק:","\u0003ומצוה להניחה בטפח הסמוך לפתח וכו'\u0004 מימרא שם (כב.) ופירש\"י מצוה להניחה בחצר או בר\"ה בטפח הסמוך לפתח שאם ירחיקנו להלן מן הפתח אינו ניכר שבעל הבית הניחו שם:","\u0003ומ\"ש שמניח משמאל כדי שתהא מזוזה מימין ונ\"ח משמאל מסקנא דגמרא שם:\u0004 ","\u0003ומ\"ש בשם אבי\"ה שאם אין שם מזוזה בפתח מניחה מימין כ\"כ בהגהות מרדכי בשם רבינו יקיר:\u0004 ","\u0003ובסמ\"ק כתב שאם מניחה בדלת עצמה יניחנה מחציו של כניסה וכו'\u0004 בסי' ר\"פ וכתב בשם מוהר\"ר יצחק אבוהב ז\"ל י\"מ מחציו של פתח כשנחלקנה לשנים נשים אותה בחציה של הכניסה שהוא לצד פנים ויהיה לצד שמאל אבל לשון ספר המצות היא יניחנה מחציו של כניסת הבית לצד שמאל ונראה שפירושו כך כשיכנס לבית יחלוק מפתן הבית לשנים ומחצי של כניסה הוא לצד שמאל יחשב מחלק השמאל בזה יהיה לצד שמאל עכ\"ל וזה ל' המרדכי ובטפח הסמוך לר\"ה וכן בדלת עצמו מניחה לצד שמאל של כניסה:","ומ\"ש שמניחין נר חנוכה בבה\"כ נראה שתקנו כן מפני האורחים שאין להם בית להדליק בו כמו שתקנו קידוש בבכה\"נ משום אורחים דאכלו ושתו בבי כנישתא וכ\"כ הכלבו וכתב טעם אחר שהוא כדי לפרסם הנס בפני כל העם ולסדר הברכות לפניהם לפי שיש בזה פירסום גדול לש\"י וקידוש שמו כשמברכים אותו במקהלות וז\"ל הריב\"ש בתשובה המנהג הזה להדליק בב\"ה מנהג ותיקין היא משום פירסומי ניסא כיון שאין אנו יכולין לקיים המצוה כתקנה להדליק כל א' בפתח ביתו מבחוץ מפני שיד העו\"ג תקיפה ומברכין ע\"ז כמו שמברכין על הלל דר\"ח אע\"פ שאינו אלא מנהג ומ\"מ באותה הדלקה של ב\"ה אין יוצא בה וצריך לחזור ולהדליק כ\"א בביתו עכ\"ל :","\u0003ומ\"ש שמניחה בדרום זכר למנורה וכו'\u0004 בתה\"ד כתב שיש מקומות שמסדרים אותם בין מזרח למערב ובמקומות אחרים מסדרים אותם בין צפון לדרום והא מלתא תליא בפלוגתא דתנאי בפרק שתי הלחם (מנחות צח:) נרות המנורה היאך היו מונחים והיה נראה דהלכה כר' מחבירו וכן פירש\"י אליביה בפי' החומש אמנם הרמב\"ם וסמ\"ג כתבו דמצפון לדרום היו מונחים וצריכים אנו לסדר הנרות כמו שהיו מסודרים במנורה למר כדאית ליה ולמר כדאית ליה ונהרא נהרא ופשטיה אמנם אם הייתי במקום שאין מנהג הייתי מנהיג כמו שראיתי ברוב מקומות וכרבי מחבירו עכ\"ל והמנהג פשוט לקבעם בכותל דרום ונמצאו מסודרים בין מזרח למערב :","\u0003חצר שיש לה ב' פתחים משתי רוחות צריך להדליק בשתי פתחים וכו'\u0004 עד די לו באחד מהם מימרא פרק ב\"מ (כג.) כתב הר\"ן ומסתברא דכיון שאינו מדליק אלא משום חשדא לא מברך אלא אחד פתחא וא\"ת מ\"ש מהא דאמרי' בפ\"ק (ח:) ובתרא דברכות (סא.) אסור לעבור אחורי בהכ\"נ בשעה שהצבור מתפללין ולא אמרן אלא דלית ליה פתחא אחריתי אבל אית ליה פתחא אחריתי לית לן בה דאמרי בפתחא אחריתי עייל והכא נמי נימא דאע\"ג דחזי דלא אדליק בחד פתחא לא אתי למיחשדיה דאמרי באידך פתחא אדליק וי\"ל דלענין תפלה שאני דכיון דאי לא מצלי הו\"ל פורק עול שמים מעליו כל היכא דאיכא פתחא אחריתי לא אתו למחשדיה משא\"כ לענין חנוכה ועי\"ל דהדלקת נ\"ח כיון דיש בה הפסד ממון אי איכא פתחא אחריתי אתו למחשדיה כי היכי דבהאי לא אדליק בהאי נמי לא אדליק אבל בתפלה דלית בה הפסד ממון כי איכא פתחא אחריתי לא אתו למחשדיה: וכתב בעל התרומות לדידן שמדליקין בפנים אפילו בב' רוחות די לו באחד מהם כ\"כ ג\"כ בסמ\"ג ומרדכי:"],["\u0003ויען כי אירע הנס בנרות וכו'\u0004 בפרק ב\"מ וקאמר דצריך להדליק הנרות בערב בכל לילה מימי חנוכה על פתחי הבתים כדי לגלות ולהראות הנס וז\"ל הרי\"ף והילכך מברכין אניסא כל יומא מתמניא יומי דחנוכה הואיל ובכל יום ויום היה הנס מתחדש באותו פך של שמן עכ\"ל:","והזהיר בהן יהיו לו בנים תלמידי חכמים בפרק ב\"מ ופירש\"י דכתיב כי נר מצוה ותורה אור על ידי נר מצוה דשבת וחנוכה בא אור תורה והא דלא קאמר איהו גופיה הוה צורבא מרבנן כדקאמר התם אמאן דדחיל מרבנן יש לפרש דקאמר אי לאו בר הכי הוא מ\"מ זוכה לבנים ת\"ח ואף על גב דלגבי מאן דדחיל רבנן קאמר ואי לאו בר הכי הוא לישתמען מוליה כצורבא מרבנן התם הוי טעמא כי היכי דלידחלו מיניה כמה דאיהו הוה דחיל מרבנן אבל הכא לא שייך למימר הכי:","\u0003וכמה נרות הם וכו'\u0004 שם תניא מצות נר חנוכה נר איש וביתו והמהדרין נר לכ\"א וא' והמהדרין מן המהדרין בש\"א יום א' מדליק ח' מכאן ואילך פוחת והולך ובית הלל אומרים יום ראשון מדליק אחד מכאן ואילך מוסיף והולך ומדברי הרמב\"ם יראה דמהדרין מן המהדרין עבדי נמי הדור ראשון דהיינו נר לכ\"א וא' אבל התוספות כתבו דב\"ש וב\"ה לא קיימי אלא אנר איש וביתו וכך הם דברי רבינו שכתב ואפי' רבים בני בית לא יעשו יותר כלומר לא יעשו אפילו להידור מצוה וכמ\"ש התו' והטעם דאם ידליק כל אחד וא' לא יהא מינכר הדור מצוה מה שמוסיף והולך דשמא הרבה בני אדם בבית מיהו מנהג שלנו כדעת הרמב\"ם ומנהג ספרד כדעת התוספות וכ\"כ הרמב\"ם שמנהג ערי ספרד אינן כמו שפסק הוא ז\"ל ומשמע מדבריו שאין לשנות מנהגם דאם לא כן לא הוה ליה לכתבו בסתם. ורא\"ם כתב על מנהג ערי ספרד שקשה עליו דלפי דעת הרמב\"ם אינו לא כפי מצותה ולא כפי המהדרין ולא כפי המהדרין מן המהדרין עכ\"ל ול\"ק מידי דברור הוא דאותו מנהג הוא על פי דעת התוס':","\u0003נר שיש לו ב' פיות וכו'\u0004 שם מימרא דרב הונא (דף כ\"ג) וקשה הא פשיטא היא ולא איצטריך לאשמעינן ונראה דהך נר אינה כצורות פמוטות שלנו שקורין אותו לאמפ\"א שכל נר יש לו חלל כמו מרזב בפני עצמו אלא כפרש\"י וז\"ל נר שיש לו ב' פיות שהנרות שלהן של חרס הן ומכוסין ועושין לו נקב בצידי כיסוי להכניס לו הפתילה והוא הפה ולמעלה בכיסוי יש נקב קטן וגם חלל יש למעלה מן הכיסוי וממלאו שמן והוא נכנס דרך הנקב מעט מעט אם יש בו נקבים שנים משני צדדים עולה לב' בני אדם למהדרין העושין נר לכל אחד ואחד עכ\"ל ולפי זה ניחא דאתא לאשמעינן דלא תימא כיון שב' הפתילות אינן מובדלין כלל כי אם בהנחתן בפה א\"כ דינו כאילו לא היה אלא נר אחד קמ\"ל דלא. ומ\"ש רבינו כגון מליל ראשון ואילך לאו דוקא דהוא הדין בליל ראשון עצמה לשני בני אדם שבשני בתים לדעת רבינו בסמוך וכדעת ר\"י בתוספות שמדליקין בפתח החצר הסמוך לרשות הרבים דאז הם מונחין לשמאל שניהם אבל לרש\"י שפירש שמדליקין על פתח בתיהם דוקא אי אפשר לפרש דעולה לשני בני אדם שבשני בתים דאם כן היה לזה מימין ולזה משמאל לפיכך פירש רש\"י עולה לשני בני אדם למהדרין והא דלא פי' רבינו למהדרין כפי' רש\"י טעמו דסבירא ליה כדעת ר\"י בתוספות דאפילו רבים בני הבית לא יעשו יותר כמ\"ש בסמוך ורש\"י פי' בגמרא לפי זמן התלמוד שהיו מקצתן מהדרין ופשיטא דלרש\"י נמי דמי שנוהג כמהדרין מן המהדרין דלא יעשה יותר וכדעת ר\"י אבל בדין הדלקה בפתח ודאי חולק רש\"י אר\"י דלרש\"י מדליקין אפתח הבית בדוקא שהרי כתב וז\"ל אלא בחצרו שבתיהם היו פתוחים לחצר אלמא דר\"ל שהיו מדליקין על פתח בתיהם וכך פי' הרא\"ם מיהו ה\"ר ירוחם כתב וז\"ל מניחם על פתח ביתו מבחוץ פירש רש\"י מבחוץ בפתח החיצון הסמוך לרשות הרבים אבל הנרות מבפנים. וי\"מ מבחוץ ממש ברשות הרבים עכ\"ל משמע דגם לפירש\"י היו מדליקין בפתח החצר וצ\"ע:","\u0003ואם מילא קערה שמן וכו'\u0004 שם מימרא דרבא ומ\"ש ונ\"ל דאפילו הרחיקם וכו' בהגהות החדשות לרי\"ף כתב ליישב זה דלפי השיעור מבית המקדש שהיו משערים לכל נר חצי לוג שמן שהוא ג' ביצים ללילי טבת הארוכים י\"ב שעות נמצא לד' שעות ביצה אחת הוי לחצי שעה שמינית הביצה ולפיהן צריך לעשות פתילות דקות כדי שלא תמהר הפתילה לכלות השמן קודם שיעור חצי שעה וע\"ד זה יהיה גבול אצבע שזכר ב\"ה עולה יפה דדבריו הם בנותן שעור המצומצם דאז ודאי צריך שיהיו הפתילות עשויות בשיעור שוה עכ\"ל ומכל מקום קשה מי יימר דשיעור אצבע הוא השיעור השוה ותו דבהרי\"ף פי' על הא דקאמר א\"נ לשיעורא כלומר שצריך ליתן שמן בנר כדי שתהא דולקת והולכת עד שתכלה רגל מן השוק יראה דאין שיעור לשמן עצמו כלל כיון דאין שיעור לפתילה דאם הפתילה גסה צריך שמן יותר מבדקה אלא דבמנורה שבב\"ה נתנו שיעור לשמן משום דהיה ג\"כ שיעור לפתילה שלא היו יכולות להיות אלא כשיעור פיות הנרות אלא דקשה על זה ממ\"ש הסמ\"ג בעשה קצ\"ג שי\"מ מ\"ש ביומא בן בכרי היה ממונה על הפקיעות פי' שהיה מפקיע פתילות לפי הלילות כי בלילות קצרות עושין אותם גסות כדי שיכלה כל השמן וכו' ע\"ש אלמא דגם במנורה היו הפתילות משתנות ופשיטא דפיות הנרות היו עשויין בשיעור שהיו מקבלין הפתילות שם וגסות ביותר בלילות קצרות ואיך שיהיה דבר זה מכל מקום נראה לע\"ד ליישב דעת ב\"ה דמפרש הא דקאמר בגמרא לא כפה עליה כלי עשאה כמין מדורה ואפילו לאחד אינו עולה היינו לפי שהאש מתחברת באמצעיתה ואינו דומה לנר וכמו שפירש רש\"י דלפי זה אם הרחיקם זה מזה גם באמצע ברוחב אצבע כסתם נר שיש לה פיות שאינו פחות מכאצבע אינו נעשה כמדורה ולא צריך כפיית כלי אלא בדלא הרחיקם זה מזה גם באמצע ברוחב אצבע דנעשה כמדורה באמצע ומיהו בתרומת הדשן משמע שהיה גורס בדברי ב\"ה דצריך להרחיק ב' אצבעות ע\"ש:","ומניחה על פתח הסמוך לרשות הרבים מבחוץ ברייתא שם ודברי רבינו בזה כמו שכתבו התוספות לשם וקצת קשה דהסמ\"ג בשם רבינו יצחק כתב כפירש\"י וכן כתב בהגהת מיימונית פ\"ד וזה סותר למ\"ש סתם תוספות שהם של ר\"י ואפשר דר\"י שכתב הסמ\"ג הוא ר\"י הבחור לא ר\"י הזקן בעל סתם תוספות. ומ\"ש בביאור הרא\"ם על דברי הסמ\"ג בשם ר\"י וז\"ל לפי' התוס' לא לפירש\"י עכ\"ל ט\"ס הוא וצריך להגיה לא לפי' התוספות אלא לפרש\"י:","\u0003ואם הוא דר בעלייה וכו'\u0004 שם בברייתא הקשה הרא\"ם לפי' התו' שהסכים רבינו עמהם למה ליה למתני דאם דר בעלייה מניחה בחלון השתא בפתח ביתו שהוא סמוך לעוברי דרכים מניחו ברשות הרבים בחלון שהוא גבוה מבעיא וכו' ואין כאן קושיא כלל דפשוט הוא דאיצטריך דלא תימא כיון דאין יכול להדליק בפתח הפתוח לרשות הרבים כמצוותה חייב להדליק בפתח העלייה משום חשדא דנכנסין ויוצאין בעלייה דעיקר מצותה היא להעמידה בטפח הסמוך לפתח משום הנכנסים וכו' קא משמע לן דלא אלא צריך להעמידה בחלון כדי שלא יחשדוהו העוברין ברשות הרבים לומר שלא הדליק:","\u0003ובשעת הסכנה שאינו רשאי לקיים המצות וכו'\u0004 שם ופירושו שגזרו שמד שלא לקיים המצות ולא כפירוש רש\"י שהיה להם לפרסיים יום איד וכו' דפשיטא דכיון דגזירת פרסיים לא היתה על ישראל בלחוד אלא גם על שאר אומות לא הוי גזירת שמד כמו שכתוב בנ\"י פרק בן סורר ומורה ואם כן היה קשה למה הצריכו רז\"ל להניחו על שלחנו ונכנסו בספק סכנה והלא אף מן השלחן היו נוטלין ומקפידין כדאיתא בפרק קמא דגיטין וכמ\"ש התו' בפרק ב\"מ אבל כשנפרש דבגזירת שמד קאמר ניחא דאפילו ערקאת' דמסאנא אסור לשנות בשעת שמד ולכן לא היו עוקרין מצות ההדלק' לגמרי אבל מה שהיו משנין להניחם על השלחן אין המצוה נעקרת בזה דאין זה שינוי בגוף המצוה רק שינוי המקום בלבד בכה\"ג שרי אפי' בשעת השמד כדמוכח בריש כתובות בתקנת נישואין ליום הרביעי דאפילו בשעת השמד משנין התקנה מיום זה ליום אחר כיון שאין עושין שינוי בגוף התקנה וה\"נ לענין מצות הדלקה דנר חנוכה גם הר\"ן פי' כמ\"ש רבינו ולא כפירש\"י וכן עיקר:","\u0003מצוה להניחה למטה מעשרה וכו'\u0004 בפרק ב\"מ ריש (דף כב) נר של חנוכה שהניחה למעלה מכ' אמה פסולה כסוכה וכמבוי ופירש\"י פסולה. דלא שלטא ביה עינא למעלה מכ' אמה וליכא פרסומא ניסא עכ\"ל ומשמע דאף בסוכה הוי טעמא דפסולה משום דלא שלטא ביה עינא וכדרבה ריש סוכה ונראה לע\"ד שעל פי' זה כתב ר' יואל הלוי דוקא כשמניחה מבחוץ וכו' דלרבה אמרינן התם להדיא דבדפנות מגיעות לסכך כשירה ואפי' למעלה מכ' וה\"ה בנר חנוכה ואע\"ג דאנן לא קיי\"ל כרבה אלא כרבא דבעינן דירת עראי ואפי' בדפנות מגיעות לסכך פסולה מ\"מ מדרבה בסוכה שמעינן לרבא בנ\"ח דלכ\"ע הוי טעמא בנ\"ח משום דלא שלטא ביה עינא הילכך בבית דשלטא ביה עינא אפילו למעלה מכ' כשרה וכדאמר גבי סוכה אליבא דרבה ומה שהשיג רבינו עליו ואמר דאין הנדון דומה לראייה וכו' קשיא לי לפי טעמו במבוי שהקורה מונחת ע\"ג כותלי המבוי אמאי פסולה היא למעלה מכ' אמה נימא נמי כיון שהמחיצו' מגיעות לקורה על ידם ישלוט עינו בקורה דהא התם לא בעינן אלא שישלוט עינו בקורה כמו בסוכה ויש ליישב. והר\"ן ז\"ל בריש פ\"ק דסוכה כתב וז\"ל ולא דמי לנר חנוכה וקורות מבוי דלא חשיבי היכר למעלה מכ' אמה אע\"פ שהקורה מונחת ע\"ג כתלים התם בקורת טפח דלא שליט ביה עינא כי היכי דשליט בסוכה דרויחא טפי עכ\"ל וכ\"כ התוס' לשם דלפי טעם זה נוחין דברי רבי' ונדחו דברי הר\"י הלוי: ומ\"ש הב\"י ע\"ש ר\"י אבוהב דסברת ר\"י הלוי דכשיש כאן אויר האויר הוא מזיק לעינים ואין האדם יכול להביט למעלה כל מה שירצה ולזה הביא ראיה מסוכה שאם הדפנות מגיעות לסכך אפי' למעלה מכ' כשרה דשליט ביה עינא ובזה נראה שאין מקום לקושיית הטור עכ\"ל נראה לפע\"ד שלא נעלמה סברתו זאת מדעת רבי' ואעפ\"כ השיג עליו דמנ\"ל לר\"י הלוי דסברא זו הלכה היא כיון שאין לו בזה ראייה ברורה מהך דסוכה דאפשר לדחות ולומר דשאני התם דבעינן שישלוט עינו בגג וכו' דאיכא למימר דהאויר לא מעלה ולא מוריד אלא עיקר הטעם דע\"י המחיצות ישלוט עינו בגג וכו' וזהו שדקדק בלשונו ואמר שאין הנדון דומה לראיה וכו' גם מדברי התוס' והר\"ן מבואר דנדחו דברי הר\"י הלוי ודברי רבינו עיקר והכי נקטינן:","\u0003והר\"מ מרוטנבורק היה מדקדק להניחה למעלה מג' טפחים וכו'\u0004 ותימה הא ניחא דאשמעינן דלא הניחה למטה מג' טפחים דלא איתמר ואתא לאשמעינן דאע\"ג דהניחה בכותל בטפח הסמוך לפתח כיון דפחות מג' כארעא סמיכתא דמי כאילו הניח בקרקע ואין ניכר שב\"ה הניחו שם כמו שפי' רש\"י היכא שהרחיקו מן הפתח שאינו ניכר שב\"ה הניחו לשם וה\"נ דכוותה אבל הא דדקדק שהניח למטה מי' ולא למעלה מי' דאיתמר בהדיא כמ\"ש לעיל מצוה להניחה למטה מי' לא איצטריך לאשמעינן משם מהר\"מ מרוטנבורק דדקדק בכך דהא דינא הכי הוא ונראה ליישב ע\"פ מ\"ש המרדכי דעכשיו שהרגילו להניח בפנים אין קפידא להניחה למעלה מי' דליכא פרסום ומביאו ב\"י השתא הך דינא שכתב רבי' מתחלה מצוה להניחה למטה מי' אינו אלא לזמן התלמוד דמניחו סמוך לרה\"ר לפרסומי ניסא אבל לאחר שהביא דברי הר\"י הלוי דלדידן דבמניחה בבית אפי' למעלה מכ' אמה כשרה והשיג עליו דאף לדידן פסולה למעלה מכ' אמה א\"כ סד\"א דמ\"מ א\"צ לדקדק לדידן ושרי להניחה אף לכתחלה למעלה מי' כיון דליכא פרסומי ניסא לדידן שמדליקין בפנים וכדכתב המרדכי ולכך הביא רבי' שהר\"מ מרוטנבור\"ק דקדק אף לדידן שמדליקין בפנים שלא להדליק למעלה מי' אלא למטה מי':","\u0003וכתב אבי העזרי שאם אין מזוזה וכו'\u0004 כתב בהג\"מ דהטעם הוא משום דכל מידי דמצוה ימין עדיף ואפי' תפילין קשירה בימין והנחה שאני דגלי לן קרא אבל כל שאר דוכתא ימין עדיף וכ\"כ בתשובת מהרי\"ל סימן מ' ועוד אפשר דכיון דצריך להדליק בפתח לפרסומי ניסא במקום שנכנסין ויוצאין וכל פינות שאדם פונה אינו אלא לימין הילכך צריך להדליק בימין ששם הכל פונין ונזכר לנס מיד כשרואה הנרות דולקות:","\u0003ובסמ\"ק כתב וכו'\u0004 כתב הב\"י משם הר\"י אבוה\"ב יש מפרשים מהחציו של פתח כשנחלקנה לשנים נשים אותה בחצי של הכניסה שהוא לצד פנים ויהיה לצד שמאל אבל לשון ס\"ה היא יניחנה מחציו של כניסת הבית לצד שמאל נראה שפירושו כשיכנס לבית יחלוק מפתן הבית לשנים ומחצי של כניסה הוא לצד שמאל יחשב מחלק השמאל ובזה יהיה לצד שמאל עכ\"ל ונסתבכו הלומדים בפירוש לשון זה ולא ידעו מהו ולעד\"נ די\"מ דלשון כניסה חוזר אל הדלת דהיינו צד פנימי של דלת ולשם יניח הנרות אבל הצד האחר לצד חוץ הוא ולא יניח הנרות לשם ומ\"ש מחציו של פתח כשנחלקנה לשנים הוא שנחלק כל שטח הדלת וצד הפנימי שהוא חציו של כניסה הוא חלק אחד וצד החיצון הוא חלק השני ומ\"ש לצד שמאל הוא ענין אחר דתרתי אשמעינן חדא שיניחו הנרות בדלת עצמה מחציו של כניסה דהיינו בפנים ואידך אשמעינן שישים הנרות לצד שמאל אבל ל' ספר המצות וכו' כלומר הלשון משמע דלשון כניסה חוזר אל האדם שנכנס בבית יחלק המפתן וכו' ולא אשמעינן אלא חדא מקום הנחתה בדלת עצמה מחציו של כניסת האדם דהיינו לצד שמאלו בבואו לפתוח הדלת אבל בענין הנחת הנרות בדלת בצד חוץ או בצד פנים מזה לא אמר הסמ\"ק כלום דזה תלוי במנהג ולדידן דמדליקין בפנים מדליק בדלת בפנים מחציו של כניסה בבואו לפתוח הדלת וליכנס וכן עיקר והכי נקטינן:","\u0003חצר שיש לה ב' פתחים וכו'\u0004 הקשה הב\"י דמ\"ש מהא דקאמרינן אסור לעבור אחורי בהכ\"נ בשעה שהצבור מתפללין דאי איכא פתחא אחריתא לא אתי למחשדיה דאימור בפתחא אחרינא יעול וה\"נ נימא באידך פיתחא אדליק ותירץ מה שתירץ ולפעד\"כ דליכא הכא קושיא דתפלה דלא עבר זמנה ודאי ליכא חשדא דאימור דבאידך פתחא יעול. אבל נר חנוכה דזמנה מסוף שקיעה עד חצי שעה דעבר זמנה תיכף ומיד איכא חשדא טפי וכן בענין פאה שהביאו בגמרא עלה התם נמי עבר זמנה מיד בגמר קצירו שהוא מכלה את הכל אתא לידי חשדא טפי ועי\"ל דבאחורי בהכ\"נ ודאי אפשר דבאידך פיתחא יעול ולא יהא נודע לשום אדם שנכנס הילכך ליכא חשדא אבל בנ\"ח אי איתא דבאידך פיתחא הדליק היה מפורסם ונודע לעוברים ושבים ומדלא נשמע ולא נראה שהדליק איכא חשדא:","\u0003וכתב בעל התרומות לדידן וכו'\u0004 עד והם יודעים ששני הפתחים של איש אחד איכא להקשות הלא לדידהו נמי ידעי שב' הפתחים של איש אחד ויחשדוהו כשם שלא הדליק בזה הפתח כך לא הדליק באחר ואין לפרש לדידהו איכא חשדא לפי שאינו חושש להדליק בב' פתחים כדי לינצל מן חשדא דהני דלא ידעי דב' הפתחים של איש אחד בודאי יאמרו כשם שלא הדליק וכו' אבל לדידן שאין היכירא אלא לבני הבית הני כולהו ידעי שב' הפתחים של איש אחד וליכא חשדא כלל דאם כן לדידהו כשב' הפתחים מרוח אחד נמי איכא חשדא מהני דלא ידעי אלא בע\"כ דלא חיישינן לחשדא דעלמא כלל אלא לחשדא דבני מתא וכדאיתא להדיא בגמרא וצ\"ל דה\"ק לדידהו אע\"פ שיודעים שב' הפתחים של איש א' מ\"מ כיון דלא ידעי דהדליק בפתח אחד איכא חשדא לומר כשם שלא הדליק וכו' אבל לדידן דהיכירא לבני הבית דידעי בהדליק בפתח אחד ליכא חשדא מפתח השנייה שלא הודלק שם שהרי הם יודעים שב' הפתחים של איש אחד ופשוט הוא מיהו בהג\"מ כתוב דברי סה\"ת ע\"ש רבי' שמחה ולא כתב שם והם יודעים אבל בסמ\"ק ובמרדכי כתב ג\"כ והם יודעים וכו':","\u0003ונראה שאין להקל וכו'\u0004 נראה דדברי רבי' הם לפי זמנו שהיו מדליקין בפתח הבית הסמוכה לחצר אלא שהיו מדליקין בפנים ולא שלפעמים פתוח איכא חשדא שהעוברים וכו' וכ\"כ סוף סימן תרע\"ב אבל למנהגינו שמדליקין בבתי החורף אין היכירא כלל לא לבני ר\"ה ולא לבני החצר וליכא חשדא וז\"ל ה\"ר ירוחם ועתה נוהגין להדליקה מבפנים לפתח הסמוך לר\"ה ויש שנוהגין להדליקה מבפנים לפתח הסמוך לחצר משום דשכיח גנבים ועוד שאין רגילין לקבוע מזוזה לפתח הפתוח לר\"ה שיטלו אותה ויש מזוזה לפתח הפתוח לחצר ויהיה מזוזה לימין ונ\"ח משמאל עכ\"ל אלמא דלא היו נוהגין כלל להדליק בבית החורף כמנהגינו אלא או בפתח הסמוך לרה\"ר או בפתח הסמוך לחצרו בפנים וכמ\"ש הר\"י הלוי לעיל:"]],["\u0010c0\u0011\u0010y0\u0011מצותה מסוף שקיעת החמה עד חצי שעה מן הלילה שאז העם עוברין ושבין ורואין בביתם ואיכא פירסומי ניסא הילכך צריך ליתן בה שמן כזה השיעור ואם נתן בה יותר יכול לכבות לאחר שיעבור זה הזמן וכן יכול להשתמש לאורה לאחר זה הזמן שעבר עיקר מצותה ומ\"מ עדיין זמנה כל הלילה \u0010c1\u0011ודלא כהרמב\"ם ז\"ל שכתב שכח או הזיד ולא הדליק עם שקיעת החמה מדליק עד שתכלה רגל מן השוק עבר זה הזמן אינו מדליק \u0010y1\u0011אבל אם עבר כל הלילה ולא הדליק לא ידליק ביום המחרת דשרגא בטיהרא מאי אהני וכן לא ישלים בלילה של אחריו שכבר עבר זמנו וכ\"כ ה\"ר יצחק ב\"ר יהודה והתוספות כתבו דלדידן א\"צ לדקדק בזמן שנתנו חז\"ל שיעור שלא נתנוהו אלא להם שהיו מדליקין בחוץ ולאחר זה הזמן אין עוברין ושבין אבל אנו שמדליקין בבית ואין היכירא אלא לבני הבית אין להקפיד על הזמן וכתב בס\"ה ומ\"מ נכון להדליק בעוד בני הבית נעורין ונראה שאף לדידן צריך לדקדק בשיעור שאע\"פ שמדליקין בפנים כיון שמדליקין בפתח הבית והוא פתוח יש היכירא לעוברים ושבים :",["\u0003מצותה מסוף שקיעת החמה עד חצי שעה מן הלילה וכו'\u0004 בפרק ב\"מ (כא:) תניא מצותה משתשקע החמה עד שתכלה רגל מן השוק וכתבו הרי\"ף והרא\"ש כשיעור שתכלה רגל מן השוק הוי כמו חצי שעה אחר שקיעת החמה ומפרש בגמרא דהיינו לענין דאי לא אדליק מדליק וא\"נ לשיעורא וכתב הרי\"ף והרא\"ש אי נמי לשיעורא כלומר שצריך ליתן שמן לתוכו כדי שתהא דולקת והולכת עד השיעור הזה אם היתה דולקת והולכת עד השיעור הזה ורצה לכבותה או להשתמש לאורה הרשות בידו ואהא דאמרינן דאי לא אדליק מדליק כתב הרא\"ש אבל מכאן ואילך עבר הזמן הלכך אע\"פ שמתרץ תירוץ אחר ראוי להחמיר ולהדליק נ\"ח בתחלת הלילה ומשמע מדבריו דהיינו לכתחלה אבל אם עבר ולא הדליק ידליק מספק וכן כתבו התוס' בשם ר\"י פורת ולא היה לו לרבינו לכתוב ודלא כהרמב\"ם שכתב עבר זה הזמן אינו מדליק מאוחר שאף לדברי האומר מדליק אינו מדליק אלא מספק:","ומ\"ש ואם עבר כל הלילה ולא הדליק לא ידליק ביום המחרת וכן לא ישלים בלילה שלאחריו וכו' ז\"ל המרדכי פרק ב\"מ השיב ר' מאיר בנר חנוכה שלא הדליק בלילה כך דעתי נוטה דכיון שלא הדליק שוב לא ידליק ודיחוי הוא כדתניא מצותה משתשקע החמה עד שתכלה רגל מן השוק דאי לא אדליק מדליק משמע שלא עשה מצוה מן המובחר וביום אין פירסום הנס ניכר וכ\"ש בשאר לילו' לא ידליק עכ\"ל. ומ\"ש בתשובה אשכנזית דלא בא הר\"מ לומר אלא דאותו לילה אין לה תשלומין אבל אלילות אחירות לא קאי דנס כל יומא איתיה ולית דין צריך בושש וכן איתא באגודה ולא דמי לעומר דהתם משום דכתיב תמימו' תהיינ' אבל הכא כל חדא מצוה באנפי נפש' היא ומה שמוסיפין משום הידור הוא ע\"כ וכ\"כ הרוקח וז\"ל אם לא הדליק לילה אחת לא ידליק למחר או ליל' האחרת מה שהי' לו להדליק אז ולא דמי לק\"ש ותפלה דאמרינן בפ' תפלת השחר (ברכות כו.) שיחזור ויקרא ויתפלל ובשבלי הלקט הביא תשובת הר\"מ ודבריו מבוארים שם כמו שכתבתי בשם תשובת אשכנזים וכתב בא\"ח מי שלא הדליק בליל ג' אלא ב' נרות או בליל רביעי אלא ג' זה היה מעשה בלוני\"ל והחמירו שידליק מה שחסר להדליק וא\"צ לברך פעם אחרת כי הברכה שעשה בתחלה על חיוב כל הנרות עשאן וכתב הרשב\"א בתשובה מי שלא הדליק בלילה א' מכל הלילות שוב אינו מדליק שכבר הוא דחוי עכ\"ל ונ\"ל שפירוש דברי הרשב\"א כמו שנתפרשו דברי הר\"מ דאנר דאותו לילה קאמר דאין לו תשלומין ואהא דתניא מצותה משתשקע החמה כתב הר\"ן לא למימרא שלא יהא רשאי להדליק קודם אלא עיקר מצותה קאמר ואם רצה להקדים מקדים אבל מדברי בה\"ג נראה דדוקא נקט משתשקע החמה עכ\"ל ודברי הרמב\"ם כדברי בה\"ג שכתב אין מדליקין נרות חנוכה קודם שתשקע החמה אלא עם שקיעתה לא מאחרין ולא מקדימין ונראה שדקדק רבינו לכתוב מסוף שקיעת החמה משום דתחילת שקיעת החמה עדיין היום גדול כמו שכתבו התוספו' בפ' במה מדליקין וכתב בשם מהר\"י אבוהב ז\"ל שכתוב בא\"ח מי שהדליק מבע\"י אפי' בחול מפני שהוא טרוד יצא והוא שיהיה בפלג מנחה האחרון דלא חמיר מהבדלה דאמרי' בה צלי של מוצאי שבת בשבת מיהו צריך ליתן בה שמן יותר משיעור הדלקה כדי שתדליק עד דכליא רגלא דתרמודאי עכ\"ל:"],["\u0003מצותה מסוף שקיעת החמה וכו'\u0004 משנה בפרק ב\"מ מצותה משתשקע החמה עד שתכלה רגל מן השוק ופי' רבינו דמסוף שקיעה קאמר וכ\"כ במרדכי הארוך פי' סוף שקיעה היינו צאת הכוכבים דשרגא בטיהרא מאי אהני וכן הא דקאמר כל תענית שלא שקעה עליו החמה לא שמיה תענית היינו צאת הכוכבים ומתחלת שקיעה עד צ\"ה ד' מילין כך פר\"י וכ\"כ בהגהת מרדכי שלנו ונראה דפירוש זה הוא לשיטת ר\"ת דשקיעת החמה היא קודמת למשתשקע כמ\"ש לעיל סי' רס\"א אבל להרא\"ם דמשתשקע משמע לשון הקדמה קודם שתשקע ה\"נ לגבי נר חנוכה וכ\"כ בספר יראים סוף ה' שבת וז\"ל והא דתניא בנר חנוכה מצותה משתשקע החמה בעוד יום קצת קאמר וכו' ומיהו לעיל בסי' רס\"א התבאר דרוב הגדולים תופסים דברי ר\"ת וכ\"כ מהרא\"י בת\"ה סימן ק\"ב וכ\"כ בספר צידה לדרך והכי משמע מל' הרא\"ש שכתב הלכך אעפ\"י שמתרץ תירוץ אחר ראוי להחמיר ולהדליק נ\"ח בתחלת הלילה וכו' מדנקט תחלת הלילה דהיינו צאת כוכבים כדאיתא ריש ברכות אלמא דאין להדליק קודם צ\"ה מיהו דוקא לכתחלה אבל אם הדליק מפלג המנחה האחרון ואילך יצא בדיעבד וכ\"כ בא\"ח הביאו ב\"י וכן הש\"ץ מדליק בבהכ\"נ בעוד היום גדול דכיון דא\"א כדיעבד דמי וכן בע\"ש לכל אדם וכדאי הוא הר\"א ממי\"ץ לסמוך עליו בשעת הדחק:","\u0003ומ\"ש ודלא כהרמב\"ם שכתב וכו'\u0004 שם בגמרא וכבתה אין זקוק לה ורמינהו מצותה משתשקע החמה עד שתכלה רגל מן השוק מאי לאו דאי כבתה הדר מדליק לה לא דאי לא אדליק מדליק ואי נמי לשיעורא ומפרש הרמב\"ם דלישני לא פליגי ומש\"ה פסק נמי כלישנא דאי לא אדליק מדליק דאלמא דלאחר שכלה רגל מן השוק שוב אינו מדליק כלל דאין לפרש דלאח\"כ נמי יכול להדליק אלא דלא עשה המצוה כתקונה דא\"כ לא הול\"ל דאי לא אדליק מדליק אלא הול\"ל לאדלוקי וכ\"כ ה\"ה מיהו בשאר מפרשים נראה שמפרשים ג\"כ כך ללשון ראשון ואע\"פ כן כתבו שיכול להדליק כל הלילה לפי שתופשים דהני לישני פליגי ובשל סופרים הלך אחר המיקל וכ\"כ ראבי\"ה שמצא בשם ר\"ת דבהני תרווייהו אזלינן לקולא בשיעורא ובדלא אדליק וזה דעת רוב פוסקים שיכול להדליק כל הלילה וכמ\"ש רבינו והכי נהוג: ולענין הלכה בשיעור השמן כתב בהגהת מיי' ובסמ\"ג בשם ר\"י דנהגו העם כלשון ראשון דלא בעינן שום שיעור והיינו כראבי\"ה בשם ר\"ת אבל לדעת הפוסקים דבעינן שיעור לשמן וכלשון שני ונראה דאף ר\"י לא להלכה אמר אלא ליתן טעם למנהג העולם כמבואר בסמ\"ג אבל מדינא צריך שיעור והכי נקטינן מיהו ה\"ר ירוחם כתב דיש מהגאונים שכתבו דאפי' אחר שיעור זה אסור להשתמש לאורה עכ\"ל ומהרש\"ל בתשובה כתב הטעם דאסור מפני הרואה שלא ידע לחלק אבל יכול לכבותם עכ\"ל ומיהו המנהג להחמיר שלא לכבותן ואסור להתיר להן וכמ\"ש רבי' לעיל בסי' תר\"ע ועוד נלע\"ד דכיון דאיכא תרי לישני ורוב פוסקים מפרשי' דפליגי ור\"י ור\"ת כתבו דנהגו כלשון ראשון וללשון ראשון אסור לכבותן או להשתמש לאורן לאחר שדלקו השיעור שהרי ללשון ראשון לא הוזכר שום שיעור והכל שוה א\"כ מדינא נמי אסור ואע\"ג דקי\"ל כלשון שני דצריך ליתן שמן בנר שידליק חצי שעה היינו דוקא להחמיר אנו תופסין כמותו אבל לא להקל ולכן יראה דאף לעצמו אין להקל לכבותן ואצ\"ל שלא יורה כך לאחרים ודלא כמ\"ש מהרש\"ל דיכול לכבותן וכ\"כ בספר צידה לדרך ויש מדקדקים שלא לכבותה ולא להשתמש לאורה הואיל ושם השמן למצוה עכ\"ל ובמסכת סופרים איתא להדיא ואין מגביהין ממקומו עד שיכבה ואע\"פ דבהגהת מיימונית מפרש דהיינו דוקא כשהשים בו שמן כשיעור מצומצם לא אתברר לן מנ\"ל לפרש כך להקל. ולקמן בס\"ס תרע\"ז יתבאר דאפי' לאחר שכבה מעצמו אסור: פסק נראה דאפי' ללמוד אסור משעה שהגיע זמן הדלקת הנרות שמא יטרד בלימודו וישכח מלהדליק וכדין בדיקת חמץ לעיל בסימן תל\"א ע\"ש ואפי' התחיל ללמוד פוסק ומדליק נרות וכמו שקבעתי ההלכה לשם ואפשר דאף לה\"ר יונה דמיקל בחמץ מודה בנר חנוכה דצריך להפסיק דהא לחד לישנא אם יעבור הזמן דרגל מן השוק שוב אין מדליק א\"כ הו\"ל מצוה עוברת ופשיטא דצריך להפסיק ע\"כ הפסק: כתוב במרדכי וכן הא דבעי הכא שיעורא דמשתשקע החמה עד שתכלה רגל מן השוק ה\"מ לדידהו שהיה צריך היכר גדול אבל אנן אין אנו חוששין כלל ע\"כ וזה כמ\"ש הסמ\"ג דמה שנהגו להקל בשיעור השמן דס\"ל דאין אנו צריכין לשיעור כגון שמדליקין בפנים ואין שם פרסום הנס אלא לבני הבית או שמא נהגו העם כלשון הראשון שתופסי' אותו עיקר דלא בעי' שום שיעור וז\"ל דרשות מהר\"ש מאוסטריי\"ך בספר המצות כתב שבזמן הזה אין שיעור לנרות חנוכה וכו' ומה\"ט אמר שמי שירצה יקח נרות קטנים אעפ\"י שאין דולקים כ\"א זמן מועט ואפי' הכי נכון ליקח מעט שיעור לנר עכ\"ל מיהו למאי שכתבנו דתופסין להלכה דצריך שיעור לשמן כלשון שני אין להקל בשעור השמן אף לדידן חדא דהסמ\"ג מסופק בזה ועוד דבהגה' סמ\"ק כתב וז\"ל ולשעורא פי' הש\"ר ר\"ש גם עכשיו והיה מצריך לעשות פתילות ארוכות עכ\"ל וכן מ\"כ ע\"ש ראב\"ן דיש לעשות קצת גדולות דסמכינן נמי אתירוצא דאי נמי לשיעורא: כתב בהגהות החדשות לרי\"ף דאם הדליקה בפני הרוח וכבתה צריך עוד לחזור ולהדליקה במקום שאין הרוח מצוי שהרי הואיל ואינה יכולה לעמוד בפני הרוח ה\"ה כמי שלא נתן בה שמן כשיעור עכ\"ל ונראה דמהאי טעמא כתב הא\"ז שאין לתחוב הנרות סמוכות זו לזו עד שמתחממות ונופלות או נוטפות דכיון דנופלות או נוטפות הוי כמי שלא נתן בה שמן כשיעור: ונראה שאף לדידן וכו' היינו דוקא לזמן רבינו שהיו מדליקין בפתח הסמוך לחצר אלא שהיו מדליקין בפנים אבל עכשיו שמדליקין בבית החורף אין צריך לדקדק כלל בשיעור אלא שידליק בעוד בני הבית נעורים וכמ\"ש בסוף סימן הקודם וכן כתב מהרש\"ל ופשוט הוא. צריך ליתן שיעור שמן כולו בנר קודם ההדלקה כדלקמן סי' תרע\"ה:"]],["\u0010c0\u0011\u0010y0\u0011כל השמנים והפתילות כשרים לה בין בחול בין בשבת אף הפסולים לנר של שבת מפני שאין אורן יפה ושאין השמן נמשך אחר הפתילה כשרים לה דלא חיישינן שמא תכבה ויחזור וידליקנה \u0010y1\u0011שאף בחול (עסי' תרע\"ב) אם כבתה קודם שעבר זמנה א\"צ לחזור ולהדליקה ולא חיישינן נמי שמא יטה מפני שאין אורן יפה שהרי אסור להשתמש לאורה \u0010c1\u0011\u0010y2\u0011ל\"ש תשמיש של קדושה כגון ללמוד ול\"ש שאר תשמיש ואפילו תשמיש עראי בעלמא כגון לעיין מעות לאורה אסור \u0010y3\u0011ובעל העיטור כתב דוקא תשמיש של חול אבל תשמיש של קדושה שרי \u0010c2\u0011ולא נהירא לא\"א הרא\"ש ז\"ל \u0010c3\u0011\u0010y4\u0011ומפני שאסור להשתמש לאורה מוסיפין נר אחד שאם ישתמש לאורה שיהא השימוש לאור אותו הנר \u0010y5\u0011שאלו לאחי ה\"ר יחיאל נרות חנוכה שמדליקין אחד יותר בסתם לשמש ולא פירש איזה מהם יכול אח\"כ לברור איזה שירצה להיות שמש אפילו הראשון או האמצעיות או דווקא האחרון והכי מסתברא תשובה נרות חנוכה אין להפסיק בהן הלכך האחרון יהיה שלא לשם נר חנוכה שאם ישתמש לאורן ישתמש לאור אותו הנר ואין שם שמש עליו כי השמש הוא המדליק בו הנרות ע\"כ: \u0010y6\u0011וה\"ר מאיר מרוטנבורק לא היה מדליק בנר של חרס אלא בשל מתכת וכשלא היה לו אלא של חרס היה לוקח חדשים בכל לילה וכשלא היה לו חדשים היה מסיקן באור דהוו כמו חדשים דהכי איתא במסכת סופרים אין מדליקין בנר ישן אין לו רק ישן מלבנו באור יפה וסתם נר שהוא של חרס הלכך בשל מתכת א\"צ חדש ושל זכוכית או חרס מצופה דינו כמתכת:",["כל השמנים והפתילות כשרים לה בין בחול בין בשבת אף הפסולים לנר של שבת פלוגתא דאמוראי בפ' במה מדליקין (שבת כא.) ומשמע בגמ' דהלכתא כרב דאמר פתילות ושמנים שאמרו חכמים אין מדליקין בהם בשבת מדליקין בהם בחנוכה בין בחול בין בשבת וכן פסקו הפוסקים והרוקח כתב שמן זית מצוה מן המובחר וגם המרדכי כתב שמהר\"ם היה רגיל להדליק בשמן זית : כתב הרשב\"א שאלת במ\"ש הרי\"ף בנר חנוכה שמותר להשתמש לאורה אחר עבור זמנה דא\"כ למה התירו בה שמנים ופתילות שאסרו חכמים להדליק בהם בשבת שהרי כל עצמן לא התירו אותן אלא מפני שאסור להשתמש לאורה קושיא זו אינה כלום שהרי לא הצריכו להוסיף בשמן שיהא הולך ודולק כל הלילה אלא כדי שיעורו ובתוך זמן הזה היה ראוי לחוש שמא יטה אבל כל שאסרו תוך זמנה מותר להדליק בהם ובשבת נותן באומד גם כפי שיעורו ולא בצמצום שא\"א כמו שא\"א ג\"כ שיעור איסור תשמישו שאינו נמנע מתשמישו שיעור זמן מצומצם ומאן לימא לן שהתירו להוסיף בשמן בשבת להדליק בשבת באותן שמני' עכ\"ל:","ומ\"ש שאף בחול אם כבתה קודם שעבר זמנה אין צריך לחזור ולהדליקה ולא חיישינן נמי שמא יטה מפני שאין אורה יפה שהרי אסור להשתמש לאורה שם אמר ר' ירמיה מ\"ט דרב קסבר כבתה אין זקוק לה ואסור להשתמש לאורה ופירש\"י כבתה אין זקוק לה. הלכך בחול שרי: ואסור להשתמש לאורה. שיהא ניכר שהוא נר מצוה וליכא למיחש להטייה: וכתב בת\"ה שאפי' כבתה בע\"ש קודם קבלת שבת שעדיין הוא מבע\"י אין זקוק לה וכתב הר\"ן נשאל הרשב\"א אם לאחר שהדליק בא לתקנה וכבה אותה בשוגג אם חייב לחזור ולהדליקה ואם מברך פעם שנית והשיב מסתברא שאינו חיוב להדליק דהו\"ל כבתה שאין זקוק לה והדלק' עושה מצוה וכבר הדליקה ואם בא להדליקה אינו מברך עליה דמצות הדלקה הא עבדא:","\u0003ומ\"ש ל\"ש תשמיש של קדושה כגון ללמוד ל\"ש שאר תשמיש וכו'\u0004 כ\"כ שם הר\"ן וז\"ל אסור להשתמש לאורה פירוש כל תשמישין ואפילו תשמיש מצוה דכיון שע\"י נס שנעשה במנורה תקנוה עשאוה כמנורה שאין משתמשין בה כלל והא דאמר שמואל לקמן אסור להרצות מעות כנגד נר חנוכה לאו למימרא דדוקא תשמיש דרשות אסור אבל תשמיש דמצוה שרי אלא לומר שאפילו רצוי מעות שהוא תשמיש קל אסור והכי מוכח בירושלמי וכך נראין דברי הרמב\"ם וזה שלא כדברי הרז\"ה עכ\"ל:","ומ\"ש בעל העיטור דוקא תשמיש של חול אבל תשמיש של קדושה שרי כ\"כ בשבולי הלקט דלקרות בספר לאורה מותר דליכא ביזוי מצוה אלא כבוד ולא נהיר' לא\"א הרא\"ש: כתב הרא\"ש א\"ר יהודה אמר רב אסי אסור להרצות מעות כנגד צר חנוכה ואע\"ג דאיפסיק לעיל דכל תשמיש אסור להשתמש לאורה צריכינן לההוא דהרצאת מעות דהא דאמרינן לעיל דאסור להשתמש לאורה היינו דוקא תשמיש קבוע דהרואה אומר לשם תשמיש זה הדליקה ולא לשם מצוה אבל תשמיש עראי לזה לא הדליקה ואשמעינן רב אסי דאף תשמיש עראי של גנאי כגון הרצאת מעות אסור לפי שידיו סמוכות לנר לעיין בהם יפה אסור וכן משמע לישנא דקאמר כנגד נר חנוכה ולא קאמר אסור להרצות מעות לאורה עכ\"ל נראה מדבריו דבתשמיש עראי שאינו של גנאי דהיינו שאינו צריך להיות ידיו סמוכות לנר שרי ולא ידעתי למה לא כתבו כן רבינו ורבינו ירוחם:","\u0003ומפני שאסור להשתמש לאורו מוסיפין נר אחר להשתמש לאורו וכו'\u0004 כ\"כ רבי' ירוחם וכתב עוד כשמניח נר א' להשתמש לאורה מניחין בפני עצמה שאל\"כ יאמר על כולן לצרכו הדליקן ובמקום שאינו רגיל להדליק שם נר א\"צ נר אחר להשתמש לאורו עכ\"ל ועכשיו אע\"פ שמדליקין בפתח שהוא מקום שאין ראוי להדליק שם נר מדליקין נר אחד מובדל משאר נרות ונראה שכך הנהיגו הראשונים מפני שאין הכל בקיאין לחלק בין מקום שרגיל להדליק שם נר למקום שאינו רגיל וכתב המרדכי מש\"ה נהגו לעשות השמש גדול יותר מהאחרות שאם בא להשתמש שישתמר בנר של חול:","\u0003שאלה לאחי ה\"ר יחיאל נרות חנוכה שמדליקין אחד יותר בסתם לשמש וכו'\u0004 כתוב בת\"ה סי' ר\"י שנשאל בני אדם הדליקו בבית א' ונתערב נר אחר בין שתי נרות שהם שמשי' אי שרי ע\"י ביטול ברוב ומותר ליהנות משלשתן והשיב יראה דלא בטיל משום דבר שבמנין שהרי מדליקין אותן במנין כל לילה :","והר\"ם מרוטנבורק לא היה מדליק בשל חרס אלא בשל מתכת וכשלא הי' לו אלא של חרס היה לוקח חדשים דהכי איתא במסכת סופרים וכו' עד מלבנו באור יפה כ\"כ בהגהות מיימון וגם במרדכי פרק במה מדליקין בשבלי הלקט: וכתוב עוד בשבלי הלקט אין חוששין לפתילות להחליפם עד שתכלה :"],["\u0003כל השמנים וכו'\u0004 פלוגתא דאמוראי בפרק ב\"מ ופסקו הפוסקים כרב דשרי מטעמא דכתב רבינו דלא חיישינן וכו' והרשב\"א בתשובה בסי' קע\"א כתב דבשבת אינו מותר אלא א\"כ אינו נותן בנר שמן רק כשיעור מצותו אבל יותר מזה כיון שמותר להשתמש לאורה יש לחוש שמא יטה וב\"י מביאו וכן פסק בהגהת ש\"ע מיהו למ\"ש בסי' שקודם לזה דאסור להשתמש לאורה אפי' לאחר שדלק השיעור בכל ענין שרי אפי' בשבת מיהו הנר שמדליק בו הנרות הנקרא שמש דמותר להשתמש לאורו אסור לעשותו משמני' ופתילות שפסולי' בשבת:","\u0003ומ\"ש ל\"ש תשמיש של קדושה וכו'\u0004 וב\"ה כתב דוקא תשמיש של חול וכו' פי' לסברא הראשונה כיון דאמרי' אסור להשתמש לאורה משמע כל תשמישין אסור אבל ב\"ה פוסק כשמואל דמדאמר אסור להרצות מעות כנגד נר חנוכה משמע דוקא ריצוי מעות דרשות הוא דאסור אבל דמצוה שרי וחולק אמ\"ד התם אסור להשתמש לאורה דמשמע דאסרו כל תשמישן ופסק כמאן דמיקל וא\"ת א\"כ לדידהו למה התירו להדליק בשבת בשמנים ופתילות הפסולים לנר של שבת הלא כיון דמותר להשתמש לדבר מצוה איכא שמא יטה וי\"ל דדבר מצוה דשכיח אינו אלא ללמוד תורה ובלאו הכי אסור ללמוד יחידי שמא יטה ואם אינו יחידי ליכא למיחש שמא יטה ומשום שאר תשמיש מצוה לאור הנר דלא שכיח לא גזרו:","ומ\"ש ולא נהירא לא\"א הרא\"ש ז\"ל אע\"ג דלא כ\"כ בפירוש מ\"מ מדפסק כמ\"ד דאסור להשתמש לאורו בסתם דאפילו בשל מצוה אסור ופסק נמי כמ\"ד דאסר להרצות מעות דאפילו תשמיש עראי אסור כמ\"ש להדיא אלמא דס\"ל דכל תשמיש אסור גם הרי\"ף פסק כדברי שניהם ובירר הרמב\"ן דדעתו לאסור כל תשמיש אפילו של מצוה וכך הסכימו הרמב\"ם והסמ\"ג והמרדכי ומיהו בדברי הרא\"ש משמע דתשמיש קל כגון הרצאת מעות דוקא אסור כיון שמקרב ידו אל הנר אבל שאר תשמיש עראי שרי ורבינו וה\"ר ירוחם לא הזכירו מזה כלום ותמה עליהן ב\"י ומהרש\"ל פסק להקל כהרא\"ש ומיהו הסמ\"ג והמרדכי והר\"ן כתבו בסתם לאיסור משמע דכל מידי אסור וכ\"כ סמ\"ק והכי נהוג ואין להקל. כתב בלקוטין השיב מהר\"ש אם כבה נר חנוכה שלא דלק שיעורו אע\"ג דא\"ז כתב דמי שחוזר ומדליקו שפיר עביד מ\"מ אין להדליקו מנר אחר עכ\"ל כלומר אלא מן השמש או שאר נר של חול ושמעינן מדבריו דמצוה לחזור ולהדליקו אעפ\"י שאינו חייב מן הדין וכ\"כ מהרש\"ל ונראה דמכ\"ש בע\"ש אם כבה בעוד היום גדול שצריך לחזור ולהדליקו אם כבה בשוגג ואע\"פ דמהרא\"י והרשב\"א כתבו דא\"צ לחזור ולהדליק מיהו לדעת הא\"ז מצוה מן המובחר לחזור ולהדליקן וכיוצא בזה כתב מהרש\"ל מיהו דבר פשוט דאסור לחזור ולברך. כתב בדרשות מהר\"ש מאוסטרייך גם א\"ל לקנות מן השמש שעוה שנטף מן הנרות בב\"ה לתקן מהן נרות לחנוכה עכ\"ל וטעמו כיון דאיתעביד ביה חדא מצוה ליעבד ביה מצוה אחריתי כדאמר גבי עירוב ומיהו בהגהת תשב\"ץ אוסר לעשות בו דבר מצוה ואפי' ללמוד בהן ע\"כ ונראה דה\"ה לנרות חנוכה דאסור וכ\"כ המרדכי ריש פרק ר' ישמעאל שכך קיבל הראבי\"ה מאביו ר\"י הלוי בין דנרות חנוכה או דב\"ה או של שבת וכן עיקר:","\u0003ומפני שאסור להשתמש לאורה וכו'\u0004 כתב בספר צידה לדרך ורגילין להוסיף נר א' ולא כסדר שאר הנרות כדי שלא ישתמש לאור של מצוה אם יבא להשתמש שם עכ\"ל משמע דאסור להשתמש כי אם לאור אותו נר בלבד וזה שכתב מהרא\"י דאם נתערב נר חנוכה אפילו באלף לא בטיל ואף על פי דהאלף כולן חול מכל מקום משתמש הוא גם לאור הנר שאסור להשתמש לאורו והא דאמרו בגמרא מניחה על שלחנו וכו' אין פירושו שמותר להשתמש לאור נר דחנוכה כיון דיש לשם נר של חול להשתמש בו דהא פשיטא דאסור אלא ה\"ק תלמודא כיון דבשעת הסכנה היא וצריך להניחו על שלחנו כי היכי דלתחזי דהאי נר לאו דמצוה היא וכיון שכן דמניח' על שלחנו על כרחו משתמש לאורו באיסור ולא מהני ליה נר אחר ואפ\"ה צריך לנר אחר לעשות היכר בדבר וז\"ש רש\"י דצריך נר אחר לעשות היכר לדבר ובר\"ן מפורש להדיא כדפרי' אבל בלא סכנה אסור להשתמש לאורה אעפ\"י שידוע שגם השמש בתוכם והכי משמע בהגה\"ת לרי\"ף שכתב יש מחכמי צרפת מצריכין שיניח הנר האחד למטה מנר חנוכה לא למעלה ולא כנגדה עכ\"ל ודעתם דהנר שמונח מלמטה ממנו יתפשט האור למעלה וממנו עיקר התשמיש וכיון שאסור להשתמש אלא לאותו הנר בלבד על כן יניחו אותו דוקא למטה ובהגהת ש\"ע כתב דאם ידוע שהשמש תוך הנרות מותר להשתמש אצלן כולן ושרי ליה מארי' דפשט התלמוד והפוסקי' לא משמע הכי כלל אלא כדפרי' ולענין הנחת השמש למטה יש חולקין וס\"ל כיון דעיקר מצות חנוכה להעמיד' למטה מי' במקום שאין שם תשמישו של אדם וניכר שלצורך מצוה הדליקוהו א\"כ צריך להעמיד הנר הנוסף למעלה מהם במקום תשמישו של אדם כדי שישתמש לאורו וכ\"כ במהרי\"ל שהי' מעמידן ונתן סימן שרפי' עומדים ממעל לו ונרא' שטעמו היה כמ\"ש וכן נוהגין ולפעד\"נ דמטעם זה נתפשט המנהג לעשות השמש גדול מנרות חנוכה דכשיבא לסדר הנרות בשוה זה א\"ז אז כשישתמש לאורן יפגע תחלה בנר הנוסף הזקוף בגובה למעלה מנרות חנוכה מיהו מי שמעמיד השמש למעלה מן הנרות כמ\"ש מהרי\"ל א\"צ לעשותו גדול יותר:"]],["\u0010c0\u0011\u0010y0\u0011מדליקין מנר לנר ודוקא בנר עצמו שיכול להדליק אחד מחבירו אבל אסור להדליק בה נר אחר של חול אפילו להדליק נר אחר של חנוכה \u0010c1\u0011כ\"ש שאין להדליק בה נר אחר של חול לצרכו ובספר התרומה התיר להדליק מנר לנר ע\"י של חול \u0010y1\u0011והשיב נר של שבת ושל ב\"ה כולם של מצוה שיכול להדליק מזה לזה וא\"א ז\"ל כתב כסברא ראשונה:",["\u0003מדליקין מנר לנר ודוקא בנר עצמו וכו'\u0004 בפרק במה מדליקין (שבת כב.) איתמר רב אמר אין מדליקין מנר לנר ושמואל אמר מדליקין אמר אביי כל מילי דמר עביד כרב לבר מהני תלת דעביד כשמואל וחד מינייהו מדליקין מנר לנר יתיב ההוא מדרבנן קמיה דרב אדא בר אהבה ויתיב וקאמר טעמא דרב משום ביזוי מצוה הוא אמר להו לא תציתו ליה טעמיה דרב משום מכחיש מצוה ופירש\"י מכחיש מצוה. ומחזי כמאן דשקיל נהורא ושואב קצת מלחלוחית שמנו מאי בינייהו דקא מדליק משרגא לשרגא מ\"ד משום ביזוי מצוה משרגא לשרגא מדליק מ\"ד משום אכחושי מצוה משרגא לשרגא נמי אסור ופירש\"י משרגא לשרגא. מביא נר אצל נר ושתיהם של מצוה ולא בקינסא ומותבינן בגמ' למ\"ד משום אכחושי מצוה ואסיקנא בקשיא ובתר הכי בעי תלמודא מאי הוי עלה ומהדרינן א\"ר הונא בריה דרב יהושע חזינן אי הדלקה עושה מצוה מדליקין מנר לנר ואי הנחה עושה מצוה אין מדליקין מנר לנר ואסיקנ' דהדלקה עושה מצוה וכ' הרא\"ש מאי קא מבעי' ליה מאי הוה עלה דלכאור' משמע דהלכה כשמואל מדעבד רבה כוותיה וכ\"ת אליבא דשמואל מבעי' אי אית ליה טעמא דביזוי מצוה ולא פליג אלא באכחושי הא איתותב לישנא דאכחושי וא\"כ בביזוי מצוה פליגי וי\"ל דמספקא ליה אי תיובתא גמורה היא או לא ופשיט רב הונא בריה דרב יהושע דלאו תיובת' גמורה היא ולחומרא אמר דפליגי באכחושי ושמואל אית ליה טעמא דביזוי מצוה הלכך אי הנחה עושה מצוה אין מדליקין מנר לנר והו\"ל כמו קינסא א\"נ מיבעי ליה אי סמכינן ארבה דעביד כשמואל או דלמא הלכתא כרב באיסורי ופשיט רב הונא בריה דרב יהושע דהלכתא כרב ובביזוי מצוה פליגי דלישנא דאכחושי איתותב והלכך אי הדלקה עושה מצוה מדליקין מנר לנר אבל אי הנחה עושה מצוה הו\"ל כמו קינסא ואין מדליקין להני תרי שנויי מדליקין משרגא לשרגא אבל לא ע\"י קינסא וכן דעת רי\"ף לכך לא הביא אלא לשון מחלוקתם מדליקין מנר לנר דמשמע בנר עצמו אבל לא ע\"י קינסא אבל בעל התרומ' מתיר אפי' ע\"י קינסא לפי דעתי משום דמ\"ד משום אכחושי מצוה עמד בקושיא ופליגי בביזוי מצוה והלכתא כשמואל כיון דרבה עביד כוותיה והר\"ן כ' מדליקין מנה לנר ואפילו ע\"י קינסא שרי דהא אסיקנא בגמרא דטעמיה דרב דאמר אין מדליקין משום בזוי מצוה ודוקא ע\"י קינסא הוא דאסור דאילו מנר לנר חנוכה בלא קינסא ליכא ביזוי מצוה ומינה דשמואל אפי' ע\"י קינסא שרי וזו היא השטה המחוור' בגמ' ולא כן דעת הרמב\"ן שכתב דלמסקנא ע\"י קינסא אסור והרמב\"ם כ' ומדליקין מנר חנוכה לנר חנוכה וכתב עליו הראב\"ד וע\"י קינסא ומחלוקת' תלוי בדקדוק סוגיית הגמרא וכתבתי בחידושי ואין כאן להאריך עכ\"ל והתו' כתבו ש\"מ הדלקה עושה מצוה וא\"כ מותר להדליק מנר לנר ומ\"מ כיון שנוהגין העול' להחמיר אין לשנות המנהג ע\"כ :","\u0003ומ\"ש רבי' והשיב נר של שבת ונר של ב\"ה כולם של מצוה וכו'\u0004 ז\"ל בעה\"ת הלכה כשמואל דאמר מדליקין מנר לנר דהא רבה עביד כוותיה א\"כ מותר להדליק קינסא או נר של חול מנר של מצוה הן בנרות שבת הן בנרות חנוכה הן בנרות ב\"ה מותר להדליק קיסם מנר של שבת כדי להדליק בה נ\"ח או איפכא או להדליק קיסם מנר של שבת כדי להדליק נר אחרת של שבת וכן בנרות חנוכה אבל נר של חול אסור להדליק מנר של מצוה אא\"כ מדליק מאותה נר של חול נר אחרת של מצוה כדמוכח ההיא (שם) דאין שוקלין כנגד מעשר שני דינרי זהב עכ\"ל ורבינו לא חשש להזכיר נר חנוכה משום דכיון דעלה קיימא ממילא משמע דכי קאמר כולם של מצוה שיכול להדליק מזה לזה דאנר חנוכה נמי קאי: כתוב בתה\"ד דאפילו למ\"ד מדליקין מנר לנר על ידי קינסא אם יש לחוש שיכבה הקינסא ברוח קודם שיגיע לאותו נר מצוה שרוצה להדליק מודה דאסור :"],["\u0003מדליקין מנר לנר וכו'\u0004 טעם מחלוקת זה מפורש בב\"י ומ\"ש חשיב נר של שבת וכו' כלומר בעה\"ת תרתי קולי מיקל חדא דמותר להדליק מנר לנר ע\"י של חול או ע\"י קינסא אידך דגם מותר להדליק של חנוכה או שאר נר של מצוה ע\"י של חול מנר של שבת או של ב\"ה אבל א\"א הרא\"ש ז\"ל אוסר מנר לנר ע\"י של חול וכ\"ש דאוס' ע\"י חול מנר של שבת או ב\"ה לנר חנוכה ולענין הלכה כתב הר\"ן דלפי סוגייא המחוורת אפי' ע\"י קינסא שרי וכבעה\"ת אבל התוס' כתבו וז\"ל ש\"מ הדלקה עושה מצוה וא\"כ מותר להדליק מנר לנר ומ\"מ כיון שנוהגין העם להחמיר אין לשנות המנהג עכ\"ל ובמרדכי הארוך הוסיף וז\"ל מיהו התוספות פירשו נהגו להחמיר שלא להדליק מנר לנר ואין לשנות המנהג וכתב בגליון הטעם משום דאין חיוב מצוה כ\"א בנר א' והאחרים אינן אלא משום הידור למהדרין או למהדרין מן המהדרין לכך נהגו העם להחמיר וה\"ר ישראל כתב הא דמדליקין מנר לנר זהו דוק' קודם שנעשית המצוה אבל כבתה כיון דקי\"ל אין זקוק לה אין להדליקה מנר של מצוה אחר להכחיש המצוה חנם עכ\"ל וכיוצא בזה כתבתי בסי' הקודם בשם מהר\"ש. ואם דלק השיעור דמותר להשתמש לאורה ללשון שני משמע דמותר נמי להדליק ממנו נר אחר מיהו לעיל בסי' תרע\"ב כתבנו דאין להשתמש לאורן כל זמן שהם דולקין לפ\"ז נמי אסור להדליק ממנו נר אחר ונר של שמש הוא נר של חול ואין להדליקו מנר חנוכה וכ\"כ בהגהת מיימונית אבל בב\"ה אין להקפיד שכולם נרות של מצוה וכ\"כ מהרש\"ל ופשוט הוא:","ומ\"ש וכל שכן שאין להדליק בו נר אחר של חול לצרכו נראה דוקא לשאר צרכיו אבל לצורך תלמוד תורה חשיב מצוה וכן להבדלה וז\"ל מהרש\"ל וגדולה מזו מצאתי וז\"ל מדליקין נר במ\"ש מנר ב\"ה כדי לילך לבית דהוה נמי מצוה כדאמר במדרש על מה זכה שאול למלוכה על שהאיר אביו במבואות האפילות נרות הרבה כך מצאתי ואח\"כ עיינתי במגילת סתרים דר\"נ גאון שכתב וז\"ל א\"ר לקיש שאול לא זכה למלוכה אלא ע\"י זקנו שהיה מדליק נרות לרבים ולכך נקרא שמו נר כתוב א' אומר ונר הוליד את קיש וכתוב אחר אומר קיש בן אכיש והוא אביאל וכו' אלא ע\"י זקנו שהיה מדליק נרות לרבי' נקרא נר ועוד האריך וכתב דבמבואות האפלי' היה מדליק ואפי' מבית לבית הספר היה מדליק בהן נרות להאיר לרבים עכ\"ל מהרש\"ל וכיוצא בזה כתב באגודה בפ' ב\"מ. ואיכא לתמוה על מה שנוהגין להדליק נר של הדיוט מנר של ב\"ה דבעודן דולקין למצותן אסור ואין היתר אלא כשצריך לכבותן כמ\"ש נ\"י ה' ציצי' מיהו להדליק נר לחולה או במ\"ש לילך באפילה ודאי שרי ורוב העולם אינן יודעין לחלק ומקילין וראוי למחות בידן ולהזהירן שזה אסור וזה מותר. ובהגהת ש\"ע לעיל ס\"ס קצ\"ד כתב טעם למנהג העולם ולא נהירא אלא מנהג זה טעות הוא וכתב מהרש\"ל ונר של הבדלה לאחר שהבדיל עליה כבר עבר מצותה ויכול להדליק ממנה עכ\"ל:"]],["\u0010c0\u0011\u0010y0\u0011הלכתא הדלקה עושה מצוה ולא הנחה שאם היתה מונחת במקומה שלא לשם מצות חנוכה מדליקה שם וא\"צ להסירה ולהניחה לשם מצות חנוכה \u0010y1\u0011הילכך עששית שהיתה דולקת כל היום לערב מכבה ומדליקה לשם מצוה \u0010y2\u0011ומכל מקום צריך שידליקנה במקום הנחתה שאם הדליקה בפנים והוציאה לחוץ לא יצא שהרואה אומר לצרכו הוא מדליקה וכן אם מדליקה ואוחזה בידו במקומה לא יצא שהרואה אומר לצורכו הוא אוחזה \u0010y3\u0011וכיון שעיקר המצוה בשעת ההדלקה צריך שיהא בנר שיעור שמן קודם שידליק אבל לא ידליק ויתן שמן אח\"כ \u0010c1\u0011\u0010y4\u0011ולא ידליקנה חרש שוטה וקטן \u0010y5\u0011אבל אשה מדלקת שאף היא היתה בנס וחייבת בה:",["הלכתא הדלקה עושה מצוה ולא הנחה הכי אסיקנא בגמ' פ' ב\"מ (כג.):","\u0003ומ\"ש הילכך עששית שהיתה דולקת וכו'\u0004 שם אריב\"ל עששית שהיתה דולקת והולכת כל היום כולו למוצאי שבת מכבה ומדליקה פי' רש\"י שהדליק למצות חנוכה מערב שבת למוצ\"ש צריך לכבותה ולהדליקה למצות הלילה:","ומ\"ש ומ\"מ צריך שידליקנה במקום הנחתה כלומר אע\"ג דאין הנחה עושה מצוה מ\"מ צריך שידליקנה במקום הנחתה וכדאיתא התם (כב:) אמר רבא הדליקה בפנים והוציאה לא עשה כלום מפני שהרואה אומר לצרכו הוא דאדלקה וכן אמר תו רבא שם היה תפוס נר חנוכה לא עשה כלום מפני שהרואה אומר לצרכו הוא דנקיט לה מ\"כ בשם מהרי\"א ז\"ל כתב בנמ\"י פעם אחת ראה בב\"ה שהדליק הנרות בכלי שהיו מדליקין כל השנה להאיר שבאותו כלי היו נרות מתוקנות לנ\"ח ואחר שהדליק המדליק נ\"ח היה מוליך החבל בידו להגביה הכלי להעמידה במקומו המיוחד לו כל השנה ומחה ביד המדליק שלא יעשה כן שאע\"פ ששמעו העומדים בב\"ה הברכה של חנוכה בשעת ההדלקה מ\"מ הרואה שלא היה שם באותה שעה יאמר לצרכו הוא שהדליקו לכך צוה שלא יגביהנה אלא שיניחנה למטה בפחות מי' ואמר (שעדים יש) [שעדיין יש לפקפק] ע\"ז לפי שעדיין משתמשים לאורה וכיון שהרגילו כל השנה להדליק לאורה אע\"פ שאינה במקומה כיון שאין נר במקום נ\"ח א\"א שלא ישתמש נר חנוכה לעומדים שם במקום הנר שהיו רגילין לכך לצורך החנוכה ראוי לחדש כלי אחר ע\"כ ונראה לי שמאחר שהדלקת נר בב\"ה אינו אלא משום מנהג שנהגו ואין חוששין שיהיה לפני הפתח אלא לפני ההיכל אין לדקדק בזה כל כך משום הנכנסים והיוצאים ועוד שאפילו בבית אין אנו מדליקין עכשיו אלא מפני בני הבית וא\"כ לפ\"ז אין לחוש לעוברים ושבים כ\"ש וכ\"ש בב\"ה שהרי כל הבאים לשם יודעים שאלו הנרות הם של חנוכה ועוד היה נראה לומר שמאחר שכבר הדליקן במקום שאינו ראוי דהו\"ל כבתה שאין זקוק לה עכ\"ל:","\u0003וכיון שעיקר המצוה בשעת ההדלקה צריך שיהיה בנר שיעור שמן קודם שידליק וכו'\u0004 כ\"כ הרא\"ש בפרק ב\"מ וז\"ל כיון דהדלקה עושה מצוה צריך שיתן שמן בנר כדי שיעור קודם הדלקה אבל אם בירך והדליק ואח\"כ הוסיף שמן עד כדי שיעור לא יצא י\"ח:","ולא ידליקנה חש\"ו שם בגמרא (כג:) והשתא דאמרינן הדלקה עושה מצוה הדליקה תש\"ו לא עשה כלום וכתב הר\"ן הילכך הדליקה חש\"ו אע\"פ שהניחה גדול לא עשה כלום מיהו כתב בעל העיטור דאם הגיע לחינוך מותר והכל תלוי במנהג כדאמרינן בירושלמי דמגילה מכאן ואילך התקינו שיהו קטנים קורין לרבים ע\"כ:","\u0003אבל אשה מדלקת וכו'\u0004 שם בגמרא אשה ודאי מדליקה דאמר ריב\"ל נשים חייבות בנר חנוכה שאף הן היו באותו הנס וכתב הר\"ן שגזרו העו\"ג על כל הבתולות הנשואות שיבעלו להגמון תחלה וע\"י אשה נעשה נס דאמרינן במדרש דבתו של יוחנן האכילה לראש העו\"ג גבינה לשכרותו וחתכה את ראשו וברחו כולם וע\"ז נהגו לאכול גבינה בחנוכה עכ\"ל :"],["\u0003הלכתא הדלקה עושה מצוה וכו'\u0004 עד שהרואה אומר וכו' איכא להקשות דבגמ' ה\"א איבעיא להו הדלקה עושה מצוה או הנחה עושה מצוה ת\"ש דאמר רבא הדליקה בפנים והוציאה לא עשה כלום אא\"ב הדלקה עושה מצוה הדלקה במקומה בעינן מש\"ה לא עשה כלום אא\"א הנחה עושה מצוה אמאי לא עשה כלום ופריק התם נמי הרואה אומר לצרכו הוא דאדלקה אלמא דלמאי דמסקינן הדלקה עושה מצוה א\"צ לטעמא דהרואה אומר לצרכו הוא דאדלקה אלא טעמא הוי משום דהדלקה במקומה בעינן וא\"כ למה כתב רבי' טעמא דהרואה וכו' דלא איתמר אלא למ\"ד הנחה עושה מצוה וברמב\"ם דקדק בזה שכתב הדליקו בפנים והוציאו דלוק והניחו על פתח ביתו לא עשה כלום עד שידליקנו במקומו אחז הנר בידו ועמד לא עשה כלום שהרואה אומר לצרכו עומד עכ\"ל הנה גבי הדליקו בפנים וכו' לא כתב טעמא דהרואה אלא לפי שצריך שידליקנו במקומו גם ברי\"ף ובהרא\"ש ובסמ\"ג איכא להקשות שכולם כתבו כדברי רבינו ונראה ליישב שהם מפרשים דלמאי דמשני וקאמר התם נמי הרואה הוא אומר לצרכו הוא דאדלקה משמע דלא ס\"ל הך טעמא דהדלקה במקומה בעינן לגבי הדליקה מבפנים אלא קושטא הכי הוא דאסור משום דהרואה וכו' וכאידך מימרא דרבא דאמר היה תפוס נר חנוכה וכו' דאין להעמידה אלא מטעם דהרואה וכו' למאי דקי\"ל הדלקה עושה מצוה א\"כ טעם זה ברור ומוכח טפי ובאידך דרבא דהדליקה בפנים נמי משום דהרואה וכו' ולא משום הדלקה במקומה בעינן כדקס\"ד מעיקרא אלא קי\"ל דלא בעינן הדלקה במקומה ונפקא מינה לענין נר של שבת ושל יו\"ט דלית בהו משום פרסומי ניסא כדי לחוש להרואה וכו' דמותר הוא להדליקה תחלה ולהניחה אח\"כ במקומה לאחר שכבר הודלקה דלא בעינן הדלקה במקומה אבל להרמב\"ם גם בשל שבת ושל יום טוב הדלקה במקומה בעינן וכן פסקו להדיא המרדכי והאגודה בפרק ב\"מ. וכבר היה אפשר לומר דלהרי\"ף ודעימיה נמי הדלקה במקומה בעינן ולא כתבו הך טעמא דהרואה וכו' אלא לאורויי דאף לדידן שמדליקין בפנים וההדלקה במקומה הוא אפ\"ה לא עשה כלום משום דהרואה וכו' אלא שקשה על זה דהיה להם להביא גם הך טעמא דהדלקה במקומה בעינן כיון ששניהם הלכה הילכך נראה עיקר כדפירש' דלהרי\"ף ודעימיה אידחי הך טעמא דהדלקה במקומה בעינן. ולענין הלכה נראה עיקר כדעת הרמב\"ם דהכי משמע פשט הסוגיא והמרדכי והאגודה נמי הכי ס\"ל כדפי' ודלא כש\"ע שכתב כל' רבינו ולא כתב הך טעמא דהדלקה במקומה בעינן ודו\"ק:","ולא ידליקנה חש\"ו פי' שלא יעשם שלוחים להדליק עליו אבל אשה מדלקת אף להוציא את האיש וכ\"כ הסמ\"ג להדיא בהלכות מגילה ואע\"ג דבמגילה אינה מוציאה את האיש ואע\"פ שגם לשם היו הנשים באותו נס שאני מקרא מגילה דהוי כקריאת התורה שאינה מוציאה את האיש וכן המנהג שהאיש סומך על אשתו שמדלקת עליו בביתו ואע\"פ שהיא עצמה מדלקת ולא ע\"י שכינו וז\"ש רבינו שאף היא חייבת בה כלומר מאחר שגם היא חייבת כמו האיש לכן יכולה להוציא את האיש וכ\"כ באגודה שאם אשה יודעת לברך תדליק היא ותפטור כל בני ביתה עכ\"ל ובמקצת ספרי רבינו כתוב שאף היא היתה בנס וחייבת בה:"]],["\u0010c0\u0011\u0010y0\u0011המדליק בליל ראשון מברך להדליק נר של חנוכה ושעשה ניסים ושהחיינו ואם לא בירך זמן בליל ראשון כ' א\"א הרא\"ש ז\"ל בתשובה דמברך בליל ב' או אימתי שיזכור מליל ראשון ואילך מברך שנים להדליק ושעשה נסים והרואה הנרות מברך בליל ראשון שתים שעשה נסים ושהחיינו מכאן ואילך אינו מברך אלא שעשה נסים לבד \u0010c1\u0011\u0010y1\u0011ודוקא שאינו עתיד להדליק \u0010c2\u0011ואין מדליקין עליו כגון שהולך בדרך ורואה הנרות בעיר אבל בענין אחר א\"צ לברך \u0010y2\u0011גרסינן במסכת סופרים \u0010c3\u0011המדליק אחר שהדליק אומר הנרות הללו אנו מדליקין על התשועות ועל הנסים ועל הנפלאות שעשית לאבותינו ע\"י כהניך הקדושים וכל שמונת ימי חנוכה הנרות הללו קודש הן ואין לנו רשות להשתמש בהן אלא לראותן בלבד כדי להודות לשמך על נפלאותיך ועל ניסיך ועל ישועתך וכן היה נוהג ה\"ר מאיר מרוטנבורק וא\"א הרא\"ש ז\"ל:",["\u0003המדליק בליל ראשון מברך להדליק נר ושעשה נסים ושהחיינו מליל א' ואילך מברך שתים וכו'\u0004 עד אינו מברך אלא שעשה נסים בלבד פשוט בפרק ב\"מ (כג.) כתוב בשבלי הלקט במטבע ברכות שטבע ה\"ר יוסף מצאתי ברכת חנוכה שטבעה להדליק טעות סופר הוא חדא דסגי ליה ע\"י שליח ועוד א\"כ מפני מה לא השיב רב פפי כשאמר לו רב פפא לא סגי דלאו איהו מהיל נהי דלא סגי דלאו איהו מהיל דהא נר חנוכה סגי על ידי שליח ומברכין להדליק ומפורש בפרק לולב הגזול ירושלמי כיצד מברך על נר חנוכה אקב\"ו על מצות הדלקת חנוכה עכ\"ל אבל נוסחת הפוסקים הוא להדליק וכן נהגו ומאי דסגי ליה ע\"י שליח י\"ל דכיון דצריך לאשתתופי בפריטי הו\"ל כאילו אינה יכולה להתקיים ע\"י אחר וכן כתב הר\"ן בפ\"ק דפסחים:","ומ\"ש ודוקא שאינו עתיד להדליק ואין מדליקין עליו שם כ' רש\"י בשם רבותיו דלא הוזקקה ברכה זו אלא למי שלא הדליק בביתו עדיין או ליושב בספינ' וכ\"כ הר\"ן וז\"ל מסתבר' שלא הוזקקה ברכ' זו אלא למי שלא הדליק עליו ולא הדליקו בתוך ביתו ואינו עתיד להדליק בלילה שלא מצינו יוצא במצוה שיתחייב לחזור ולברך על הראיה וכ\"כ המרדכי וכ\"כ הרא\"ש הרואה נר חנוכה צריך לברך פי' המהלך בספינה ורואה נרות שהדליקו בעיר והוא אינו מדליק: ומ\"ש בשם תשובת הרא\"ש שאם לא בירך זמן בליל ראשון מברך בליל ב' או כשיזכור כ\"כ בא\"ח ובשבלי הלקט והביא ראיה מדאמרינן בפ' בכל מערבין ה\"נ מסתברא דאי ס\"ד זמן זמן כל שבעה מי איכא הא לא קשיא דאי לא מברך האידנא מברך למחר וליומא אחרינא עכ\"ל מצאתי כתוב בתשוב' אשכנזי' הרואה שבירך זמן בליל א' ולא הדליק ובליל ב' או ג' בא להדליק אינו חוזר ומברך זמן דקי\"ל (עירובין מ:) זמן אומרו אפי' בשוק וא\"צ לחזור ולאומרו על הכוס:","\u0003גרסינן במס\"ס המדליק אחר שהדליק אומר הנרות הללו אנו מדליקין וכו'\u0004 כ' הרא\"ש בפ' ב\"מ וכ' ששמע שר\"מ היה אומר אותו וכ\"כ בהגהות מרדכי: כתב הרד\"א בשם ה\"ר יונה שבליל א' מברך שלשה ברכות אלו קודם ההדלקה דכל המצות מברך עליהם קודם עשייתן ובליל ב' מברך קודם ההדלקה להדליק ושעשה ניסים מברך לאחר שמדליק נר ראשון קודם שידליק נר שני שהוא נס אותו היום וכן בליל ג' קודם שידליק נר ג' וכן ברביעי וכן על כולם עכ\"ל נראה מדבריו שבנר שהתחיל להדליק בליל א' בה מתחיל בכל הלילות אבל מהר\"י קולון ז\"ל כתב בשורש קס\"ד מאחר שכתב המרדכי בפרק ב\"מ בשם רבינו מאיר שיש להתחיל לצד שמאל כדי לפנות לימין משום כל פינות שאתה פונה וכו' אם כן ראוי הוא להתחיל להדליק בליל ראשון בנר היותר ימיני ויברך ובליל שני כשיוסיף נר אחרת אצלו יתחיל ויברך על הנוסף שהוא יותר שמאלי כדי להפנות לימין כדברי רבי' מאיר וכן בליל ג' כשיוסיף עוד אחר סמוך לשתי נרות הראשונות יתחיל בו בנוסף ובו יתחיל הברכה ואח\"כ יפנה לצד ימין וכן בכל לילה ולילה נמצא שתמיד מברך על הנוסף שהוא מורה על הנוסף שהרי בתוספת הימים נתוסף הנס אבל אם היה מתחיל בליל הראשון להדליק בנר השמאלית גם בליל שני היה צריך להתחיל בו כדי להפנות לימין כדברי הר\"מ וכן בליל שלישי וכן כל הלילות ונמצא שאין מברך אלא על נר אחד כל ימי חנוכה עכ\"ל ואע\"פ שלדברי הר\"י לא שייכא קושיא זו מ\"מ קצת דוחק לומר דברכת שעשה נסים יברך ליל ראשון קודם הדלקה ובשאר לילות אחר הדלקה ובתה\"ד כ' דבני רינוס מתחילין להדליק בשני שהוא כנגד צד שמאל כדברי המרד' ובני אויסטרייך מתחילין לצד ימין ומדליקין כדרך שאנו בני ברית כותבין דאפשר דחשיב להו כה\"ג פונה דרך ימין ואף אם אינו פונה דרך ימין כה\"ג נראה ליישב המנהג משום דהאידנא אין להם מזוזות בבתי החורף שבהם מדליקין א\"כ צריכין להדליקן בימין הכניסה בצד הטפח הסמוך לפתח כדאיתא במרדכי וא\"כ אותו נר שהוא כנגד ימינו הוא הסמוך לפתח לעולם ובו צריך להתחיל עכ\"ל ונראה שמנהג בני רינוס הוא הנכון וכפי מה שכתבתי בשם מהר\"י קולון ואין לחלק בין היכא שהנרות בימין הכניסה להיכא שהם בשמאל הכניסה וכן אנו נוהגים:"],["\u0003המדליק בליל ראשון מברך להדליק וכו'\u0004 עד דמברך בליל שני או אימתי שיזכור אע\"ג דכל מידי דמזמן לזמן קאתי דאם עבר ולא בירך בהגיע הזמן שוב אינו מברך דעבר יומו בטל קרבנו היינו דוקא בדבר שאין זמנו נמשך אלא זמנו בעתה כגון בדיקת חמץ למ\"ד דצריך לברך שהחיינו דאם עבר ובדק ולא בריך שוב אינו מברך אבל הדלקת נרות חנוכה דזמנו נמשך ח' לילות אם לא בירך בליל ראשון מברך אח\"כ כל זמן שלא עברו ח' לילות ודלא כמהר\"ש בדרשות שא\"צ לברך שהחיינו גם מהר\"ם מ\"ץ כתב בתשובתו דצריך לברך שהחיינו בליל שנייה אם לא בירך בראשונה אבל בירך שהחיינו כשראה נ\"ח אע\"פ שלא הדליק באותה הלילה שוב אינו מברך זמן עכ\"ל ופשוט הוא מידי דהוה ארואה פרי חדש ובירך שהחיינו בראייה דשוב א\"צ לברך בשעת אכילה אלא שנהגו להמתין עד שעת אכילה כדלעיל בסי' רכ\"ה וקי\"ל נמי זמן אומרו אפי' בשוק וא\"צ לחזור ולאמרו על הכוס אבל אם לא בירך בליל ראשונה כלל צריך לברך בליל שנייה ואע\"פ שאשתו הדליקה עליו בליל ראשונה מ\"מ מידי ברכת שהחיינו לא נפטר ובסמוך יתבאר עוד. ואיכא למידק מ\"ש דאניסא מברך כל יומא ושהחיינו אינו מברך אלא חד יומא וראיתי בהג\"ה שכתב דהנס היה בכל לילה מספיק השמן אבל שהחיינו אין לברך בכל לילה אע\"פ שבכל לילה מתחדש הנס לפי שכבר ברכנו אותה לילה הראשונה על השמן ההוא ואין בשמן מתחדש דבר אלא נעשה בו נס שהספיק עכ\"ל ועוד י\"ל דברכת שהחיינו היא באה על שמחת לבו של אדם שהגיע לזמן הדלקת נ\"ח ושם הדלקת נרות א' הוא ותו דכל ח' יומא דחנוכה כחד יומא חשיבי אבל ניסא כל יומא אע\"פ שהזמן א':","\u0003ודוקא שאינו עתיד להדליק וכו'\u0004 פי' שאינו עתיד להדליק באותו לילה שאם דעתו להדליק בביתו באותו לילה אין צריך לברך על הראייה אלא מסדר כל שלשתן בשעה שידליק מידי דהוה אסוכה דמסדר להו לכולהו אכסא וכ\"כ בהגה\"מ בשם רבינו שמחה וראבי\"ה אבל באינו עתיד להדליק בביתו באותו לילה צריך לברך אראייה אע\"פ שדעתו לברך בביתו בליל שנייה דכל יומא ויומא מצוה בפני עצמה היא וז\"ל רש\"י בשם ר\"י בר יהודא שאמר בשם ר' יעקב דלא הוזקקה ברכה זו אלא למי שלא הדליק בביתו עדיין או ליושב בספינה וכו' משמע שלא בא למעט שלא יברך ברכה זו אלא למי שהדליק כבר ובירך בביתו אבל מי שלא הדליק בביתו אע\"פ שדעתו להדליק באותו לילה בביתו צריך לברך אראייה דאין להחמיץ המצוה ודלא כמ\"ש רבינו והג\"מ בשם ר\"ש וראבי\"ה מיהו במרדכי הביא לשון רש\"י בענין אחר מסכים עם רבינו ועם ר\"ש וראבי\"ה וז\"ל שלא הוזקקה ברכה זו אלא למי שלא הדליק בביתו עדיין ושאין דעתו להדליק בעצמו כגון אכסנאי שלא שמע הברכה דלקמן מסיק קא מדלקי עלאי בגו ביתאי ומ\"מ צריך לראות כדאמר הרואה יומא קמא מברך ב' מכאן ואילך א' וכן אומר שנהגו בני אדם שהיו הולכין בגייר\"ש ליריד ולא היה גר יהודי באותו העיר ומדליקין בבית עו\"ג עכ\"ל ואולי חסר בספרי רש\"י שבידינו אלא שבהג\"מ העתיק לשון רש\"י כמו שהוא בספרי רש\"י שבידינו:","\u0003ומ\"ש ואין מדליקין עליו וכו'\u0004 כתב הסמ\"ג דר\"ל דאינו נשוי שתדליק אשתו עליו בביתו דאילו היה נשוי אעפ\"י שהולך בדרך א\"צ לברך על הראייה כיון דאשתו מדלקת עליו ותימה דמה שמדליקין עליו בביתו אינו בא אלא לפטור אותו מחיוב המוטל על ממונו להדליק נרות לפרסם הנס ברבים אבל ההודאה על הנס וברכת שהחיינו הוא בחיוב על גופו ומזה לא נפטר כשמדליקין עליו אם לא שעמד שם בשעת ברכה וענה אמן וכך מבואר ממ\"ש המרדכי בשם רש\"י דבסמוך שלא בא למעט אלא למי שכבר הדליק בביתו או עתיד להדליק בעצמו בביתו באותו לילה אבל מלבד זה חייב לברך על הראייה שמדליקין עליו בביתו והכי משמע מלשון הרא\"ש והסמ\"ק והאגודה שכתבו בסתם דהמהלך בספינה ורואה נרות שהדליקו בעיר והוא אינו מדליק מברך על הראייה אלמא דכיון שהוא עצמו אינו מדליק אעפ\"י שאשתו מדלקת עליו בביתו צריך לברך על הראייה והא דנקטו ספינה משום דבלא ספינה יכול להדליק באושפיזו מקום שלן שם והכי משמע ממ\"ש הרי\"ף והרמב\"ם בסתם לברך על הראייה שוב ראיתי שהר\"ר ירוחם כתב וז\"ל יש מהגדולים שכתבו שאם הדליקו עליו בביתו אין צריך לברך כשרואה נר חברו ויש מהן שכתבו שאפילו הדליקו עליו בביתו שצריך לברך כשרואה ומ\"מ אם הדליק הוא בעצמו בביתו א\"צ לברך כשרואה נר חברו ולפ\"ז הסברא האחרונה אכסנאי שנשתתף בפרוטה צריך לצאת ולראות כדי שיברך עכ\"ל ונראה היינו דוקא כשלא שמע הברכה מבעה\"ב כשהדליק דאי שמע הברכה וענה אמן הו\"ל כאילו בירך הוא עצמו דשומע כעונה וסברא זו האחרונה היא עיקר והכי נקטינן דלא כמ\"ש בש\"ע כלשון רבינו:","\u0003המדליק אחר שהדליק וכו'\u0004 הלשון משמע שאומר כן קודם שיברך שעשה נסים וכ\"כ מהרי\"ש והכי משמע במ\"ס ובהגהת מיימוני פ\"ג הלכה ד' מיהו בתשובת מהרי\"ל סי' קמ\"ה כתב דאנו אין לנו אלא תלמודא דידן דכל הברכות צריך עובר לעשייתן כמו שעושין בקריאת מגילה ונטילת לולב ואיכא למימר דמ\"ס סובר כמ\"ד בירושלמי דמברך בשעת עשייתן ותו דאין בו מנהג פשוט לאמרו והיאך נפסיק בטפל לבין העיקר עכ\"ל: כתב מהרי\"ק בשורש קפ\"ג דלדעת הר\"ם כשמדליקין בשמאל יתחיל בנר היותר ימיני ובליל ב' יוסיף נר אחד סמוך לו ויברך על הנוסף וכו' וא\"כ לפ\"ז כשאין מזוזה בפתח ומדליקין בימין מתחיל בליל ראשון בנר היותר ימיני ובליל ב' יוסיף נר אחד סמוך לו ויברך על הנוסף וקשה שהרי צריך הוא להדליק בטפח הסמוך לפתח ונר הראשון שמברכין עליו הוא עיקר מצות ההדלקה ולמהרי\"ק אם מדליק בשמאל לא ידליק בטפח הסמוך לפתח כ\"א בליל אחרון וכשמדליק בימין לא ידליק בטפת הסמוך לפתח כ\"א בליל ראשון לכן נראה עיקר כמהרא\"י בת\"ה דלעולם הוא מתחיל בטפח הסמוך לפתח וכשמדליק בשמאל מתחיל בכל לילה בנר שהוא היותר בטפח הסמוך לפתח ופונה דרך ימין וכשמדליק בימין מתחיל בכל לילה בנר היותר ימיני ומדליק כדרך שאנו בני ברית כותבין ואעפ\"י שאינו פונה דרך ימין אין לחוש כיון שצריך להדליק בטפח הסמוך לפתח מיהו כבר יש מהנדסי' לומר אדרבה כשמדליק כדרך שאנו בני ברית כותבין זהו נקרא פונה דרך ימין וכו' כדכתב בתשובת מהרי\"ל סי\"מ ומהרא\"י בסימן ק\"ו עד בני אוסטרייך ע\"ש. מצאתי בהגה\"ה אדם שהדליק נר חנוכה יכול להדליק לאשה ולברך וכגון שעומדת אצלו בשעת הברכה אבל בענין אחר נראה למהר\"ח שאין לברך עכ\"ל ונ\"ל דוקא דבר המוטל על גוף האדם ולא על דבר הנתחייב ברכה וראיה מחלה ותרומה שהשליח מברך בלא המשלח ע\"כ מצאתי כתב הרא\"ם בביאוריו כשאחר מברך יברך על הדלקת נר חנוכה ושכן מצא בגליון תוס' ונ\"ל דהיינו כשהשליח כבר הדליק לעצמו אבל בשנשתתף עם זה בפריטי יברך להדליק וב\"י בתחלת סימן זה הביא בשם שבולי לקט דיש לברך על מצות הדלקת נר חנוכה דה\"א בירושלמי ונראה דהיינו כשאחר מברך כדפי':"]],["\u0010c0\u0011\u0010y0\u0011אכסנאי חייב להדליק בפ\"ע ואינו יוצא בשל בעל הבית ומיהו בפרוטה שיתן לו וישתתף עמו סגי ואם מדליקין עליו בביתו א\"צ יותר ואם יש לו פתח פתוח לעצמו אינו יוצא במה שמדליקין בביתו ולא במה שישתתף עם בע\"ה אלא צריך להדליק בפתחו \u0010c1\u0011\u0010y1\u0011כתב אדוני אבי הרא\"ש ז\"ל בתשובות בן האוכל אצל אביו או האוכל אצל חבירו ויש לו בית מיוחד לשינה צריך להדליק שכיון שיש לו בית מיוחד לשינה והעולם רואין אותו נכנס ויוצא בו איכא חשדא אם אינו מדליק שאין העולם יודעין שאוכל במקום אחר \u0010c2\u0011ואפילו לדידן שאנו מדליקין בפנים ומסתמא בני חצר יודעין שאוכל במקום אחר אפ\"ה שייך חשד כי השכנים עוברים ושבים לפני פתח הבית ורואים שאינו מדליק ע\"כ. \u0010c3\u0011כתב רב שר שלום אנשים הרבה הדרים בחצר אחד שורת הדין שמשתתפין כולן בשמן ויוצאין כולן בנר אחד אבל להידור מצוה כל א' וא' מדליק לעצמו על פתח ביתו ואי פתח חד בבא לנפשיה חייב לאדלוקי משום חשדא. \u0010c4\u0011\u0010y2\u0011הנותר מן השמן והפתילות בליל ראשון מוסיף עליו ומדליק בליל ב' נותר בליל ב' מוסיף עליו ומדליק בג' וכן בכל הלילות נותר ממנו בליל ח' עושה לו מדורה ושורפו בפ\"ע שהרי הוקצה למצותו ואם נתערב ממנו בשמן אחר ואין ששים לבטלו כתב ה\"ר מאיר מרוטנבורק שאין להוסיף עליו כדי לבטלו ולא דמי לעצים שנשרו מן הדקל לתוך התנור בי\"ט שמרבה עליהם עצים מוכנין ומבטלן דשאני התם שאין נהנה מהן עד אחר ביעורן אבל הכא נהנה ממנו בשעה שהנר דולק ואסור ג\"כ לשהותו לשנה הבאה לנר של חנוכה דחיישינן שמא יבא ליהנות ממנו כיון ששוהה אותו לזמן מרובה ואפילו אם נותנו בכלי מאוס חיישינן הלכך אין לו תקנה:",["אכסנאי חייב להדליק בפני עצמו ואינו יוצא בשל בע\"ה ומיהו בפרוטה שיתן לו וישתתף עמו סגי ואם מדליקין עליו בביתו וכו' עד אלא צריך להדליק בפתחו פשוט בפרק במה מדליקין (שבת כג:) והטעם דכשיש לו פתח פתוח לעצמו צריך להדליק בפתחו הוי משום חשדא והא דאמרינן דאם מדליקין עליו בביתו א\"צ כתב המרדכי ומ\"מ צריך לראות כדאמרינן בסמוך הרואה יומא קמא מברך שתים מכאן ואילך א' וכן אומר ר\"י שנהגו בני אדם שהיו הולכין ליריד ולא היה דר יהודי באותו עיר ומדליקין בבית העו\"ג ע\"כ:","כתב א\"א ז\"ל בתשובות בן האוכל אצל אביו או אצל חבירו ויש לו בית מיוחד לשינה וכו' הרשב\"א כתב בתשובה דא\"צ להדליק אבל צריכים להשתתף כדין אכסנאי וכתב מהרי\"א ז\"ל בשם א\"ח בן גדול בבית אביו ואינו סומך על שולחן אביו הרי הוא כאכסנאי וצריך להשתתף וה\"ה בחתניו היכא דאין להם בית שידליקו בעבורם עכ\"ל: כתב בתה\"ד דאכסנאי שהוא נשוי אם רצה להדליק ולברך משום הדור ש\"ד ול\"נ דאין לסמוך על זה לברך ברכה שאינה צריכה : כתוב בא\"ח קטן שהגיע לחינוך מדליק כיון שמצוה דרבנן היא מצאתי כתו' בשם מהרי\"א ז\"ל בלשון הזה כתוב בא\"ח שמי שהלך לכפר שאין בו ישראל ולן שם בליל חנוכה אע\"פ שאין לו בית מיוחד שמענו שהרבי' משולם היה נוהג להדליק ולברך זכר לנס ע\"כ עוד שם מי שבא בספינה או שהוא בבית עו\"ג מדליק בברכות ומניחם על שולחנו ולא דמי לאכסנאי דאמרינן דאי מדליקין עליו בגו ביתיה לא בעי לאשתתופי דשאני התם שיש פירסום הנס בהדלקת אושפיזו עכ\"ל וכ\"כ המרדכי :","\u0003הנותר מן השמן והפתילות בליל ראשון מוסיף עליו ומדליק בליל ב' וכו'\u0004 עד שהרי הוקצה למצותו כ\"כ הרא\"ש בפ' ב\"מ בשם שאלתות דרב אחאי והמרדכי בשם ילמדנו ופסיקתא רבתי וא\"ת והרי כתב רבינו בסימן תרע\"ב צריך ליתן בה שמן כזה השיעור ואם נתן בה יותר יכול לכבותה אחר שעבר זה הזמן וכן יכול להשתמש לאור' לאחר זה הזמן שעבר עיקר מצותה וגם הרי\"ף והרא\"ש כתב כן בפרק הנזכר ודברים אלו סותרים זא\"ז וכ\"כ הר\"ן שהגאונים שאומרים שאם כבת' ונשאר שמן ביום הראשון מוסיף עליו ומדליק ביום שני וכו' נשאר בה ביום אחרון עושה לו מדורה ושורפו במקומו שהרי הוקצה למצותו הם חולקים על מ\"ש הרי\"ף שאם היתה דולקת והולכת עד כשיעור הזה ורצה לכבותה או להשתמש לאורה הרשות בידו אבל אין נראה כן מדברי הרא\"ש שאע\"פ שכתב סברא זו דעושה לו מדורה בשם השאלתות אם איתא שהיה סובר שהיא חולקת על הסברא הראשונה הו\"ל לכותבן סמוכות זו לזו ורבי' פשוט הוא שסובר שאין חולקו' שהרי כתבן לשתיהן סתם ומצאתי כתוב בשם מהררי\"א ז\"ל שיש לחלק ביניהם שכשנתן השמן בנר ולא הקצהו אלא לשיעור זמן הדלקה יכול אחר כך להסתפק ממנו אם ירצה אבל כשנתן השמן בנר בסתם אז הוקצה למצות נר חנוכה וצריך לעשות לו זה התיקון עכ\"ל ול\"נ לחלק ביניהם בענין אחר שמ\"ש בסימן תרע\"ב מיירי שנתן בה שמן יותר מכשיעור ואחר שדלק כשיעור מותר ליהנות ממנו דלא הוקצה למצוה אלא כדי שיעור הצריך בלבד ומ\"ש בסימן זה מיירי בשנותר מהשמן הצריך לשיעור הדלקה הוא הוקצה למצותו ולפיכך צריך לעשות לו מדורה דכיון דמשיעור הדלקה הוא הוקצה למצותו ואסור ליהנות ממנו וכ\"כ בהגהות מיימוניות ואיכא למידק למה צריך לעשות מדורה למותר השמן והפתילות מ\"ש מעצי סוכה ונוייה דשרי אחר החג כבר תירץ הר\"ן דהתם לא מקצה להו אלא לימי החג לפי שעשויין להשאר אחר החג ולא מקצה להו למצותה לגמרי אבל שמן ופתילה שעשויה להתבער לגמרי כי יהיב להו בנר לגמרי מקצה אותן למצוה דאין אדם מצפה אימתי תכבה נרו ואם נשתיירו הרי הן אסורין שהרי הקצה אותן למצותן לגמרי ודומה לעצי סוכה ונוייה שנפלו בחג שאסורין כדמוכח בפ' המביא כדי יין (ביצה ל:) ולא דמי לנר של שבת שעשויה להיות כולה למצוה ואפילו הכי נהנין אחר השבת מן השמן ומן הפתילה משום דהתם אף בעודו דולק לעצמו למצותו נהנין ממנו משא\"כ בנ\"ח וכיוצא בזה כתבו התו' בפ' כירה (שבת מד:): ואם נתערב ממנו ואין ס' לבטלו כתב הר\"מ שאין להוסיף עליו כדי לבטלו וכו':"],["\u0003אכסנאי חייב להדליק וכו'\u0004 כתב באגודה שמעתי מי ששיתף עם חבירו לנר חנוכה צריך להוסיף מה שיתן לו חבירו ע\"כ וטעמו דאם לא ניכר שהוסיף בשביל חבירו איכא חשדא לומר שלא נשתתף ולפ\"ז אפי' לא הוסיף כל מה שנתן לו אלא מקצת נמי סגי דניכר דנשתתף במה שהוסיף על מה שהיה רגיל ואם יש לו פתח וכו' כך פסק הרי\"ף בפ' ב\"מ ופי' הרמב\"ם דאף כשמדליקין עליו בביתו אינו יוצא דכיון שיש לו פתח פתוח לעצמו איכא חשדא וכך הם דברי רבינו:","\u0003וכתב הרא\"ש בתשובה בן האוכל אצל אביו וכו'\u0004 נראה דהרא\"ש כתב כך לזמנו שהיו מדליקין על כל פתח מפתחי הבתים שבחצר וכדמשמע מפירש\"י וכדלעיל בסימן תרע\"א ולכן צריך להדליק בפתח הבית שבחצר המיוחד לשינה דאיכא חשדא דעוברים ושבים לפני פתח הבית כשאינן מבני חצר ומ\"ש רבינו אח\"כ בשם רב שר שלום הוא לאותן הזמן שהיו מדליקין בפתח החצר וכולם יוצאים בנר אחד כשמשתתפים יחד ולשם א\"צ להדליק בבית המיוחד לשינה דאף בפתחי הבתים שבחצר לא היו מדליקין כי היו יוצאים בנר א' שהשתתפו בו ומדליקין בפתח החצר מיהו למ\"ש רב שר שלום דלהידור מצוה מדליק לעצמו וכו' א\"כ לפי זה צריך הוא ג\"כ להדליק על פתח בית שהוא ישן שם דאיכא חשדא וכדכתב הרא\"ש:","\u0003ומ\"ש הרא\"ש ואפילו לדידן וכו'\u0004 היינו כדפי' בסי' תרע\"א ותרע\"ב שהיו מדליקין בפתח הבית הסמוך לחצר אלא שהיו מדליקין בפנים ואיכא חשדא מעוברים ושבים בחצר כשאין מבני החצר והפתח פתוח ולא הדליק אבל לדידן שמדליקין בבית החורף בפנים ליכא חשדא אלא מבני הבית והם יודעים שמדליק במקום שאוכל מיהו דוקא כשאוכל בקביעות במקום א' אבל מי שסועד בסעודה אצל חבירו בהא ודאי איכא חשדא מבני ביתו כשלא הדליק בביתו במקום שרגיל להדליק ולכך צריך לילך תחלה לביתו ולהדליק ולחזור לסעודתו ומיהו אם אשתו מדלקת עליו א\"צ לילך לביתו כמ\"ש בסוף סימן תרע\"ה. ואעפ\"י דצריך לכתחלה לעמוד אצל מי שמדליק עליו מ\"מ אינו מעכב ומדינא יוצא אפי' אינו עומד אצלו דעיקר החיוב על ממונו להדליק נרות לפרסומי ניסא והא ודאי דצריך לברך על הראייה במקום שסועד אצל חבירו כיון שלא עמד בביתו בשעה שהיו מדליקין עליו כדלעיל בסימן תרע\"ו ומ\"מ מצוה מן המובחר שילך לביתו וידליק בעצמו דכל מצוה מצוה בו יותר מבשלוחו כדאיתא ר\"פ האיש מקדש דהא רבא מלח שיבוטא:","\u0003כתב רב שר שלום וכו'\u0004 ויוצאין כולן בנר א' פי' דמשתתפי' ומדליקין בפתחי החצר בנר אחד בשביל כל בני החצר והוא ע\"פ שיטת התוספות בד\"ה מצוה להניח ומ\"ש אלא להידור מצוה וכו' פי' כ\"א שיש לו בית בפני עצמו מדליק על פתח ביתו ג\"כ נר אחד אבל לא ידליקו כל בני בית אחד אפי' הם רבים ואפי' להידור מצוה כדלעיל בסי' תרע\"ה:","\u0003הנותר מן השמן וכו'\u0004 מה שקשה דדברים אלו סותרים למ\"ש בסימן תרע\"ב דמותר להשתמש לאורה לאחר שדלק חצי שעה ויכול נמי לכבותה תירץ ב\"י דהכא מיירי כשלא דלק השיעור דאסור בהנאה הכל כיון דאין ששים כנגד השמן שהוקצה למצותו אבל אם דלק כבר השיעור מה שנשאר הוא חולין גמורה וכ\"כ בהגהת מיימוני ובמרדכי בשם מהר\"ם גם הר\"ן ומהר\"י אבוה\"ב שמחלקין דכשנתן השמן סתם אז הקצה כל השמן כולו למצות נר חנוכה ואסור אבל אם לא הקצהו אלא לשיעור זמן ההדלקה לא הוקצה למצותו אלא כדי שיעור הצריך בלבד הוא טעם נכון והני תרתי שינויי הלכתא נינהו ולכן אפילו דלק השיעור ואח\"כ כבה כל השמן הוא אסור כיון שנתן השמן בסתם למצות ההדלקה ולא פירש וכך יראה להדיא בהגה\"ת מיימונית סוף הלכות חנוכה המתחלת בשאלתות ע\"ש:"]],["\u0010c0\u0011\u0010y0\u0011מי שאין ידו משגת לקנות נר חנוכה ונר של שבת יקנה של שבת ולא של חנוכה יש לו של שבת ואין לו לקנות של חנוכה ויין לקידוש היום יקנה נרות ולא יין :",["\u0003מי שאין ידו משגת לקנות נר חנוכה ונר שבת וכו'\u0004 כל סימן זה פשוט בפרק ב\"מ (כג:) והטעם שמקדים נר שבת לנר חנוכה מפרש בגמרא משום שלום ביתו כלומר משום דאמרינן ותזנח משלום נפשי זו הדלקת נר שבת שבני ביתו מצטערים לישב בחושך והטעם שמקדים נר חנוכה לקידוש היום משום פירסומי ניסא ואע\"ג דקידוש היום דאורייתא ונר חנוכה דרבנן כיון דאפשר לקדושי בפת אקדומי שמן לנר חנוכה עדיף:"],["\u0003מי שאין ידו משגת וכו'\u0004 מפרש בגמרא דנר שבת קודם לנר חנוכה משום שלום ביתו ונר חנוכה קודם כיון של קידוש משום פרסומי ניסא וכתב ב\"י דאע\"ג דקידוש היום דאורייתא ונר חנוכה דרבנן כיון דאפשר לקדושי בפת אקדומי שמן לנר חנוכה עדיף עכ\"ל ולשון זה כתבו הר\"ן ומשמע דסבירא ליה דקידוש דאורייתא היא על היין או על הפת ולא נהירא דקידוש דאורייתא אינו אלא בפה בלא פת ובלא יין דזכור את יום השבת לקדשו זכרון דברים קאמר וכ\"כ המרדכי פ' מי שמתו ובסמ\"ג עשין סי' כ\"ט ולפי זה אפילו אין לו לא יין ולא פת לקדש עליו נר חנוכה קדים דכיון דשניהם מד\"ס מוטב להקדים נר חנוכה שיש בו זכרון הנס וכ\"כ הרמב\"ם והא דכתב רבינו בסי' רצ\"ו דנר חנוכה קודם ליין דהבדלה משום דאפשר לאבדולי בתפלה ולא קאמר משום דפרסומי ניסא עדיף כדקאמר הכא גבי קידוש דאעפ\"י דהבדלה דאורייתא כדאיתא במכילתא זכרהו מלפניו ושמרהו מלאחריו וכמ\"ש הרמב\"ם אין זה אלא להבדיל בפה כמו שצריך לקדש בפה מדאורייתא אבל להבדיל על היין אינו אלא מד\"ס לד\"ה דלא עדיף מקידוש ויש ליישב דמ\"ש רבינו דאפשר לאבדולי בתפלה ר\"ל דאפשר לאבדולי בהזכרה בפה בלא יין כגון בתפלה ולאו דוקא תפלה קאמר אלא משום דקבעוה בתפלה ועל הכוס נקט תפלה כלומר בלא כוס וע\"ד זה אפשר לומר דמ\"ש הר\"ן וב\"י דלא מידחיא קידוש דאורייתא דאפשר לקדושי אריפתא לאו דוקא אריפתא קאמר אלא ר\"ל דאפשר לקדושי בהזכרה בפה בלא יין וה\"ה בלא ריפתא נמי ולא נקטו ריפתא אלא לפי שאם אין שם יין תקנוה אריפתא:"]],["\u0010c0\u0011\u0010y0\u0011כתב בה\"ג נר של שבת ושל חנוכה ידליק של חנוכה ברישא דאי מדליק של שבת ברישא איתסר ליה לאדלוקי של חנוכה דהא קבליה לשבת והתוספות כתבו שאין הקבלה תלויה בהדלקה ויכול להדליק של שבת תחלה ואח\"כ של חנוכה כל זמן שלא קבלו לשבת:",["\u0003כתב בה\"ג נר של שבת ונר של חנוכה ידליק של חנוכה ברישא וכו'\u0004 הר\"ן בפ' ב\"מ כתב שהרמב\"ן הקשה על דברי בה\"ג והוא ז\"ל השיב על דברי הרמב\"ן והעמיד דברי בה\"ג וכ\"נ מדברי המרדכי שם אבל הרא\"ש כתב שם דמשמע בגמרא שקבלת שבת אינה תלויה בהדלקת הנר וכתב רבינו ירוחם שכן עיקר וכן נראה שהוא דעת הרב המגיד שכתב בסוף הלכות חנוכה על דברי בה\"ג וכבר השיבו עליו הרמב\"ן והרשב\"א ז\"ל ואמרו שאין הדלקת שבת קבלה אוסרת והביאו ראיה לזה ולא מצאתי בדברי רבינו קבלה אוסרת בע\"ש עכ\"ל ובסי' רס\"ג הארכתי בזה ולענין מעשה נראה לי דמדליק של חנוכה תחלה דאף לדברי החולקים על בה\"ג אם רצה להדליק של חנוכה תחלה רשאי : וכתוב בתה\"ד סימן ק\"ב אע\"פ שמדליק מבעוד יום מברכין עליה משום דאי אפשר בע\"א חשובה הכשר מצוה והביא ראיה לדבר:"],["\u0003כתב בה\"ג נר של שבת ושל חנוכה ידליק של חנוכה ברישא וכו'\u0004 כ\"כ לעיל בסימן רס\"ג ונראה דדעת התו' אינו אלא לומר דאם הדליק של שבת תחלה יכול להדליק אח\"כ של חנוכה לאפוקי מה\"ג דאוסר אבל לכתחלה ודאי דגם התוס' מודים דיש להדליק של חנוכה תחלה א\"נ סבירא ליה להתוספות כיון דאין קבלת שבת תלוי בהדלקה עדיף טפי להקדים של שבת דתדיר ושאינו תדיר תדיר קודם ועוד דנר של שבת מצוה לאקדומי ונר של חנוכה מצוה לאחורי דמצותה מסוף שקיעה ומיהו העולם נהגו כבה\"ג:"]],["\u0010c0\u0011\u0010y0\u0011בליל שבת צריך ליתן שום דבר לחוץ בין הנרות לפתח בשביל הרוח שלא יכבה הנרות כשפותח הדלת דנר שאחורי הדלת אסור לפתוח ולנעול כנגדו כתב הר\"ם מרוטנבורק כשהייתי בצרפת ראיתי את מורי ה\"ר שמואל שלא היה לו מקום אחורי הדלת להדליק נרות של חנוכה והיה קובע אותם בדלת עצמה אחורי הדלת ונתן הוא טעם לדבר דכיון שהדלת בטלה לגבי בית חשיבא כמחובר לקרקע ולא חשיב כמטלטל הנר כשפותח ונועל הדלת ואין לומר כשפותח או נועל מטה השמן או השעוה אל הפתילה או מרחיקה ממנו ונמצא מכבה או מבעיר דהא נר שעל הטבלא מנער את הטבלא והוא נופל ולא חיישינן להא שמטה השמן לפניו או לאחריו דלא שייך כי האי גוונא מכבה או מבעיר ואפילו אי שייך דבר שאין מתכוין מותר ולאו פסיק רישיה הוא ע\"כ \u0010c1\u0011ולפי מה שפי' ר\"י בההוא דנר שאחורי הדלת אסור לנעול ולפתוח הוא אסור שפירש שהנר תקוע באחורי הדלת ובפתיחתו ובנעילתו מרחיק השמן מן הפתילה או מקרבה אליה וההיא דנר שעל הטבלא מעמיד כשאין בו שמן דחשיב ליה פסיק רישיה אם יש בו שמן:",["בליל שבת צריך ליתן שום דבר לחוץ בין הנרות לפתח בשביל הרוח שלא יכבה הנרות כשפותח הדלת דנר שאחורי הדלת אסור לפתוח ולנעול כנגדו כל דברי סימן זה נתבארו בסימן רע\"ז:"],["\u0003בליל שבת צריך ליתן שום דבר לחוץ בין הנרות וכו'\u0004 הך דנר שאחורי הדלת דאסור לפתוח כנגדו נתבאר לעיל סי' ר\"ע דתלתא פירושי נינהו ולפרש\"י ופירוש ר\"ח אין אסור אלא לפתוח אבל לנעול ליכא איסורא ולפר\"י אסור גם לנעול ורבינו שכתב כאן דנר שאחורי הדלת אסור לפתוח ולנעול כנגדו לא כתב כן אלא לפר\"י ומיהו נראה דדוקא לדידהו שהיו מדליקין בפתחי הבתים הסמוכים לחצר אלא שהיו מדליקין בפנים איכא לחוש דבפתיחתו יכבה אבל לדידן שמדליקין בבית החורף ובית לפני בית החורף אין לחוש לכיבוי דאפי' יכבה בפתיחתו אין זה פסיק רישא אלא דבר שאין מתכוון אם לא שפתח בית החורף מכוון נגד פתח הבית הסמוך לחצר או לר\"ה דצריך ליזהר שלא יפתח פתח בית החורף אא\"כ נעול פתח הבית הסמוך לחצר או איפכא דאם שניה' פתוחים איכא פסיק רישיה וכן אם הנרות קבועים בכותל שאחורי דלת אסור נמי לדידן דבפתיחתו תהא הדלת נוקשת על הנרות ותכבנו כמו שפי' ר\"ח וכדלעיל בסימן רע\"ז ואצ\"ל אם הנרות קבועים בדלת עצמן דאסור לפתוח ולנעול לפר\"י דאף לדידן אסור אלא דאם הנרות הם כנגד פתיחת הדלת וקרוב לדלת כמו שהוא לפירש\"י לשם איכא לחלק דלדידן לא הוי פסיק רישיה כדפי' ועיין במ\"ש בסימן רע\"ז: ומ\"ש ונתן הוא טעם לדבר וכו' פי' הר\"מ נתן טעם לפסק של ה\"ר שמואל רבו עיין בהגה\"ת מיימונית פ\"ה דהלכות שבת:","\u0003ומ\"ש ולפי מה שפי' ר\"י וכו'\u0004 ומיהו בסמ\"ג בדין המכבה פסק כר\"י ואעפ\"כ כ' דאין אסור אלא בפותח ונועל כדרכו אבל בנחת בנחת ונזהר בשעה שפותח ובשעה שהוא נועל מותר וכ\"כ הרמב\"ם עכ\"ל וכ\"כ במרדכי פרק כל כתבי וזה היה טעמו של ה\"ר שמואל שעשה מעשה להתיר דס\"ל דכיון דפותחו בנחת ונזהר לאו פסיק רישיה הוא אלא דבר שאין מתכוון ושרי אבל רבינו שהשיג על ה\"ר שמואל ממה שפי' ר\"י לא ס\"ל לחלק בין פותח כדרכו לפותחו בנחת שהרי לעיל פסק בסתם דאסור אף כשהנר קבוע בכותל שאחורי הדלת ולא התירו בפותחו בנחת כל שכן כשקבוע בדלת עצמו ותו דהא קי\"ל דבמדורה אסור לפתוח הדלת כנגדה אפי' ברוח מצויה גזירה אטו שא\"מ וה\"ה דיש לגזור לפתוח בנחת אטו פותח כדרכו ולענין הלכה יראה דהעיקר כהרמב\"ם דראייתו ברורה מדנקט תלמודא פותח ונועל כדרכו ועלה קאמר לייט עלה רב וכו' משמע דוקא עלה דההיא דפותח כדרכו לייט עלה אבל בפותחו בנחת לא והאחרונים מרדכי וסמ\"ג וסמ\"ק ואגודה הביאו דבריו לפסק הלכה מיהו נראה דוקא כשקובע הנרות בכותל אחורי הדלת מותר לפתוח בנחת אבל בדלת עצמה יש להחמיר ובירושלמי מקללין למאן דעביד כן יכרת ה' לאיש אשר יעשנה ואע\"ג דאיכא לפרש דהך קללה אינה אלא למי שפותח כדרכו ותדע דהא הרמב\"ם דאוסר אף לנעול בע\"כ מפרש הנרות קבועים בדלת עצמו כפר\"י ואפ\"ה התיר בפותח ונועל בנחת וכמ\"ש לעיל בסימן רע\"ז ולא חייש להך קללה משום דאינה אלא בפותח כדרכו נראה דאעפ\"י דדינא הכי מ\"מ יש להחמיר וכ\"כ בהגהת מיימוני דמכח ההיא דירושלמי צריך ליזהר שלא להניח נר חנוכה על הדלת מה\"ט ע\"ש:"]],["\u0010c0\u0011\u0010y0\u0011ירושלמי במ\"ש אין מבדילין בנר של חנוכה שאין נהנין לאורו ואין מברכין על הנר עד שיאותו לאורו:",["\u0003ירושלמי במוצאי שבת אין מבדילין בנר של חנוכה וכו'\u0004 כתוב בתה\"ד סימן ס' דמדליקין נר חנוכה בבית הכנסת קודם הבדלה כדי לאחר אפוקי יומא והרב רבי' דוד אבודרהם כתב שיש מדליקין אותה אחר שמבדילין על הכוס ואח\"כ יאמר יפתח ה' (אלהיך) לך וגומר :"],["\u0003ירושלמי במ\"ש אין מבדילין בנר של חנוכה וכו'\u0004 נראה דדוקא כשיברך תחלה על הדלקת נר חנוכה אין להבדיל עליהן אח\"כ אבל יכול לברך תחלה על הנר להבדלה ולכבותה ולחזור ולהדליקה למצות נר חנוכה ועדיף טפי למיעבד הכי דכיון דעביד ביה מצוה חדא ליעבד ביה מצוה אחריתי אלא דכיון דקי\"ל דלאחורי אפוקי יומא עדיף טפי נוהגים להדליק נר חנוכה תחלה ושוב אי אפשר להבדיל עליו אפילו לאחר שדלק כשיעור כדקבעינן הילכתא לעיל דאסור להשתמש לאורה אף לאחר שדלק כשיעור:"]],["\u0010c0\u0011\u0010y0\u0011כל ח' ימי חנוכה מזכיר של חנוכה פירוש על הניסים בתפלה ובברכת המזון ואומרו בתפלה בברכת מודים ובבה\"מ בברכת הארץ \u0010y1\u0011ואם לא אמרו אין מחזירין אותו \u0010c1\u0011\u0010y2\u0011ור\"ת היה חוזר אם נזכר שלא אמרו קודם שעקר רגליו \u0010c2\u0011ואינו נראה לר\"י וכן דעת א\"א הרא\"ש ז\"ל \u0010y3\u0011ומ\"מ אם נזכר באותה ברכה כל זמן שלא הזכיר השם אפי' בין אתה לשם חוזר \u0010y4\u0011ובמוסף של שבת ור\"ח שבחנוכה צריך להזכיר נס של חנוכה אע\"פ שאין מוסף בחנוכה. \u0010y5\u0011יש שא\"א כשם שעשית וכו' לפי שא\"א תפלה בהודאה וי\"א כיון שצורך רבים הוא יכולין לאומרו כמו יעלה ויבא שאומר בעבודה אע\"ג דלא ישאל אדם צרכיו בג' ראשונות וג' אחרונות אלא כיון שצורך רבים הוא שפיר דמי ובסדר רב עמרם ישנו וא\"א הרא\"ש ז\"ל לא היה אומר אותו אלא היה מסיים ועשית להם ניסים וגבורות בימים ההם בעת הזאת:",["כל ח' ימי חנוכה מזכיר של חנוכה פי' על הנסים בתפלה ובבה\"מ ואומרו בתפלה בברכת מודים ובבה\"מ בברכת הארץ בפ' ב\"מ (כד.) ומפרש טעמא משום דבין בתפלה בין בבה\"מ צריך לאומרו בברכת הודאה משום דכוליה מלתא דחנוכה עיקר' הודאה כתוב בא\"ח יוחנן הוא חשמונאי כמו שאומר בס' יוסיפון וי\"א חשמונאי ע\"ד יאתיו חשמנים והוא דרך גדולה וכתב עוד שם י\"א הרשעה בחירק הרי\"ש והביאו לזה מה שמצאו בזכריה זאת הרשעה פירוש בעלת הרשעה כי מלת רשעה הוא שם דבר כמו כי בערה כאש רשעה אבל יותר נכון לקרות הרשעה בחטף פתח תחת הרי\"ש ע\"ד הפסוק ביחזקאל מדרכו הרשעה והוא שם תואר וא\"ת למה אומר זדים ביד עוסקי תורתך ולא אומר דבר והפוכו כמו שאמר בכל האחרים וי\"ל כי דרך הפסוק לקח דכתיב זדים הליצוני עד מאד מתורתך לא נטיתי עכ\"ל :","ומ\"ש רבינו ואם לא אמרו אין מחזירין אותו כך למדו הרי\"ף והרא\"ש והתוס' בפרק ב\"מ מהברייתא השנויי' שם וכתבו דהכי איתא בהדיא בתוספתא כל יום שאין בו קרבן מוסף כגון חנוכה ופורים בערבית שחרית ומנחה מתפלל י\"ח ואומר מעין המאורע ואם לא אמר אין מחזירין אותו וטעמא משום דלאו דאורייתא נינהו וכן נהגו ודלא כדברי אבי\"ה שכתב המרדכי דהשתא כיון דנהגו כולי עלמא להזכיר וגם בירך ע\"מ להזכיר שוויה עליו כחובה וחוזר:","ומ\"ש ורבינו תם היה חוזר אם נזכר שלא אמרו קודם שעקר רגליו ואינו נראה לר\"י וכן דעת א\"א ז\"ל נתבאר בסי' רצ\"ד:","ומ\"ש ומ\"מ אם נזכר באותה ברכה כל זמן שלא הזכיר השם אפילו בין אתה לשם חוזר פשוט הוא כתב הכלבו שאם שכח מלאמרו בבה\"מ ונזכר קודם שסיום כשיגיע להרחמן יאמר הרחמן יעשה נסים ונפלאות כשם שעשית לאבותינו בימים ההם ובזמן הזה בימי מתתיה וכן יעשה בפורים:","ובמוסף של שבת ור\"ח שבחנוכה צריך להזכיר גם של חנוכה אע\"פ שאין מוסף בחנוכה כך היא מסקנא דגמרא בפרק ב\"מ שם וכתוב שם בהגהות המרדכי נראה שאם לא הזכיר של חנוכה במוספין מחזירין אותו ונראה מדבריו שם שיש חולקין בדבר וכל דבריו על שיטת ראבי\"ה שכתבתי לעיל בסמוך דאילו לדידן מאי איריא מוספין אפי' ערבית שחרית ומנחה נמי אין מחזירין והרשב\"א כ' שאלת מי שלא הזכיר בתפלה בשבת של חנוכה מחזירין אותו אע\"פ שאין בחנוכה קרבן מוסף מי אמרי' דהוי כר\"ח שחל בשבת שאם טעה בבה\"מ חוזר משום דבשבת ע\"כ אכיל ואע\"ג דבר\"ח דעלמא אינו חוזר הכא ל\"ש או דילמא אינו חוזר תשובה אינו חוזר ואינו דומה לההיא דר\"ח שאני שחוזר אפי' בחול בתפלה לפי שיש לו מצד המאורע בעצמו קרבן מוסף אלא לא חייבוהו לחזור אלא בטעה במקומות המחוייבים בתפלה אבל לא בבה\"מ דאינו מחוייב לאכול וכיון שכן בשבת דע\"כ אכיל תזרת אכילתו מחוייבת לו והלכך בשבת תוזר בתפלה שזה וזה היום חובה עליו אבל בחנוכה דאפילו בתפלה המחוייבת אינו חוזר אף באכילה המחוייבת אינו חוזר ע\"כ:","\u0003יש שאין אומרים כשם שעשית וכו'\u0004 זה ל' התוס' בפ\"ק דמגילה (ג.) יש שאין אומרים כשם לפי שאמרו חכמים לעולם לא ישאל אדם צרכיו לא בג' ראשונות ולא בג' אחרונות ושטות הוא שהרי האי טעמ' לא הוי אלא למתפלל בל' יחיד אבל בשביל הצבור שרי אבל נראה שאין לאמרו מטעם אחר משום דאמרו חכמים דכל דבר דהוי להבא תקנו בלהבא ובדבר דהודאה הוי לשעבר ובא\"ח כתב אמנם כך היא הנוסחא ברוב התפלות וכן נוסחת הרמב\"ם וכ\"כ במ\"ס הלכך דעבד כמר עבד ודעבד כמר עבד :"],["\u0003כל ח' ימי חנוכה וכו'\u0004 ואם לא אמרו אין מחזירין אותו כ\"כ כל הפוסקים זולתי במרדכי פ' ב\"מ כ' וז\"ל ימים שאין בהם קרבן מוסף מכאן פסק בסמ\"ג דאם שכח ולא אמר ע\"ה בחנוכה ובפורים אין מחזירין אותו וכו' עד הדא דתימא בר\"ח אבל לא בשבת וי\"ט וחנוכה ופורים שאי אפשר בלא אכילה חוזר ומזכיר ונראה לראבי\"ה אע\"ג דמסיק הכא דהזכרת חנוכה רשות היא בברכת המזון מיהו כיון דנהוג כולי עלמא להזכיר וגם בירך ע\"מ להזכיר שויה עליו כחובה וחוזר וראיה מדפסק בה\"ג דאפי' למ\"ד תפלת ערבית רשות וכו' עכ\"ל ומלבד שכתב הפך משמעות התלמוד וכל הפוסקים שאין מחזירין והוא ז\"ל פוסק דחוזר ומזכיר עוד דבריו הם סותרים דבתחלה אמר דאין מחזירין ובסוף אמר דמחזירין וכבר ראיתי מהרבה גדולים שהוגה בספריהם והעבירו קולמוס על ובחנוכה ופורים שכתב בסוף דבריו ומהרש\"ל גם הוא הגיה וחילק דדוקא בסעודת פורים חייב להחזיר ואין כל זה מתיישב לעניות דעתי אלא נראה דדוקא בתפלה קאמר תחלה דאין מחזירין ובתוספתא ובירושלמי דמייתי ראיה מינייהו נמי בתפלה קאמרי אבל ב\"ה שא\"א בלא פת כיון שנקרא י\"ט כדאיתא במגלת תענית דחנוכה ופורים לא בטלו עיקרן ובי\"ט א\"א בלא פת כמו שהוכיח הרא\"ש בפ\"ג שאכלו הילכך צריך לחזור ולפי שקשה על זה הא דמסיק תלמודא אב\"ה דחנוכה א\"ר הונא אינו מזכיר ואם בא להזכיר מזכיר בהודאה דאלמא רשות הוא לזה כתב ראבי\"ה דאע\"ג דרשות הוא כו' עד שויה עליו כחובה וחוזר כו' אך קשה לפי זה דתחלת דבריו דאין מחזירין בתפלה קאמר אמאי כתב המרדכי מכאן פסק בסמ\"ג וכו' חדא דבסמ\"ג לא הביא ראיה מתוספתא זו לענין תפלה אלא לענין ב\"ה כמפורש לשם בהלכות תפלה וב\"ה וגם הרי\"ף והרא\"ש לא הביאו ראייה מתוספתא זו אלא לענין ב\"ה ותו קשה דדין תפלה תני בהדיא בתוספתא זו דאין מחזירין בחנוכה ופורים וא\"כ מאי חדושיה דסמ\"ג הא תניא לה בהדיא ולא הו\"ל למימר מכאן פסק בסמ\"ג מיהו כבר נודע דהרבה לשונות מגומגמים נמצא בספר זה באשר מועתק מלפנים בכמה פנים זה מאריך וזה מקצר וכיון שהענין מובן אין לדקדק אחר הלשון כל כך ופי' דבריו כדאמרן וז\"ש הדא דתימא וכו' הוא מלשון המרדכי עצמו כי לא מצא לשון זה לא בתוספתא ולא בירושלמי ובא לחלק בין ר\"ח ובין שבת וי\"ט וחנוכה ופורים שאלו כולם נקראים י\"ט וחוזר וראבי\"ה נתן טעם ע\"ז דאע\"ג וכו' ולפי זה הא דכתב ב\"י ז\"ל וכתב בהגה\"ת מרדכי נראה שאם לא הזכיר של חנוכה במוספין מחזירין אותו ונראה מדבריו שם דיש חולקין בדבר וכל דבריו על שיטת ראבי\"ה דבסמוך דאילו לדידן מאי איריא מוספין אפי' ערבית ושחרית ומנחה נמי אין מחזירין עכ\"ל אינו נכון דאינו ענין לשיטת ראבי\"ה דודאי מודה ראבי\"ה בתפלה דאין מחזירין אותו כדתני בתוספתא ולא שייך לומר הכא שויה עליה חובה דודאי כל אדם בעמדו להתפלל דעתו כתקנות רז\"ל להזכיר לכתחלה ואם ישכח א\"צ לחזור אלא דוקא בב\"ה דאסיקנא בתלמודא דרשות היא ואפי' לכתחלה א\"צ להזכיר קאמר ראבי\"ה כיון דבדידיה תליא ובירך מתחלה ע\"ד להזכיר שויה עליו חובה אבל ר\"ש בן ר\"ב בהגהת מרדכי דשבת בענין תפלה קאמר שאפי' בתפלה חוזר משום חנוכה בשבת במוספים דכיון דמשום שבת צריך לחזור ה\"ה דחוזר משום חנוכה דיום הוא שנתחייב בד' תפלות ולא מפלגינן בינייהו במידי ולפי טעם זה ה\"ה ערבית שחרית ומנחה בשבת שבחנוכה נמי חוזר והא דנקט מוספין לרבותא נקט הכי דאעפ\"י שאם אין שבת אין מוסף כלל בחנוכה אפ\"ה חייב לחזור ומכ\"ש ערבית ושחרית ומנחה ולדעתו אפי' הזכיר של שבת אלא שלא הזכיר של חנוכה נמי צריך לחזור כמו בשבת ור\"ח לגבי ברכת המזון שצריך לחזור משום ר\"ח אפילו הזכיר של שבת דיום הוא שנתחייב בד' תפלות וכל התפלות שוות בדין זה חנוכה כמו שבת זו היא דעת ר\"ש בן ר\"ב בהגהת מרדכי ולא כמה שעלה על דעת ב\"י ואין ספק דתקפה עליו משנתו בעיון זה. ולענין הלכה נראין דברי ראבי\"ה נכונים מטעם שכתב דשויה עליה חובה ותו דלמנהגינו דלא קי\"ל כמהר\"ם בסעודת חנוכה דרשות הן אלא קי\"ל די\"ט הוא וסעודת מצוה היא ולא סגי בלא פת א\"כ דינו לענין חזרה בב\"ה כמו בשבת וי\"ט אבל בתפלה א\"צ לחזור וכר\"ת ורוב גאונים דלא כר\"ש ב\"ר ברוך:","\u0003ור\"ת היה חוזר וכו'\u0004 ונראה דלשון חוזר ואינו חוזר בסתם משמע לר\"ת דמיירי כשסיים התפלה ועקר רגליו אבל בעומד בתפלה ולא עקר רגליו אין זה נקרא חזרה אם נזכר שלא אמרו וחזר ואמרו ולפ\"ז אם סיים מודים ולא אמר ע\"ה חוזר לעבודה כדאמר בפ' א\"ע טעה באחרונות חוזר לעבודה וכן כתב במרדכי ס\"פ ת\"ה שכך אמר ר\"ת וכן מבואר בתו' לשם דר\"ת חזר דוקא קודם שעקר רגליו אבל ממ\"ש הרא\"ש לשם יראה דלר\"ת אפי' עקר רגליו חוזר דמפרש אין מחזירין אינו חייב לחזור ואם יצא חוזר וכמ\"ש רבינו לעיל סוף סי' רצ\"ד דלפי פי' זה אפי' עקר רגליו נמי יכול לחזור והוא סותר למ\"ש רבי' כאן:","\u0003ומ\"ש ואינו נראה לר\"י וכו'\u0004 פי' דר\"י סובר דברכה לבטלה היא אם חוזר בדבר שאין מחזירין אותו ואצ\"ל אם פתחו בברכה שלאחריה ולא ק' למה לא יחזור אותה ברכה בתור' נדבה דהא פשיטא כיון דעיקר התפלה הוא חובה אין לו להפסיק בברכת נדבה בין ברכות של חובה דהוי הפסק באמצע התפלה ומיהו דוקא בלא עקר רגליו אבל עקר רגליו יכול לחזור ולהתפלל בתורת נדבה ועיין בכל זה לעיל סי' רצ\"ד ולענין הלכה נקטינן כר\"י והרא\"ש שבאו אחר ר\"ת והחמירו שלא לחזור ועוד דספק ברכות להקל כמ\"ש התוס' דעמא דבר כר\"ת הילכך מיד שסיים אותה ברכה אינו חוזר ואם עקר רגליו יכול לחזור ולהתפלל בנדבה חוץ בתפלת מוסף שאינה באה בנדבה כדלעיל בסי' ק\"ז מיהו בדברים המחזירים אותם אפי' אם סיים אותה ברכה אומרה במקום שנזכר כ\"ז שלא פתח בברכה שלאחריה ולא הוי הפסק כיון שחייבוהו חכמים לחזור:"]],["\u0010c0\u0011\u0010y0\u0011כל ח' ימי חנוכה גומרין הלל ודין קריאתו כתבתי מקצתן בהלכות ר\"ח ומקצתו בהלכות סוכה:",["כל ח' ימי חנוכה גומרים את הלל בפ\"ב דערכין (י:) מימרא דר' יוחנן משום ר\"ש בן יהוצדק וכתוב בשבלי הלקט שהטעם משו' דחלוק בנרותיו כל יום חלוק משלפניו הרי הוא כחג שחלוק בקרבנותיו ועוד טעם אחר לפי שהנס נתחדש בכל יום ועוד שהרי קוראים בנשיאי' ובכל יום נשיא שלו חלוק משל חבירו אם כן כל נשיא צריך לגמור ההלל על קרבנותיו ואין ראוי לחדש קריאה בלא קריאת ההלל:"],["כל ח' ימי חנוכה גומרים ההלל טעמו דבכל יום ויום היה הנס מתחדש ועוד נאמרו בו טעמים עיין בבית יוסף:"]],["\u0010c0\u0011\u0010y0\u0011וקורין בפרשת נשא בנשיאים ג' בכל יום ומפרש בפסיקתא משום שנשלם מלאכת המשכן בכ\"ה כסליו ומתחילין בויהי ביום כלות משה ויש מקומות שמתחילין בברכת כהנים ומנהג יפה הוא לפי שנעשה הנס על ידי כהנים וכן הסדר ביום הראשון מתחיל ביום כלות משה וקורא אותו עם כהן לוי ישראל קורא ביום הראשון ביום השני קורא כהן וביום השני עד פר אחד בן בקר ולוי עד וביום השלישי וישראל חוזר וקורא וביום השני וכן בכל יום ביום השמיני מתחילין ביום השמיני וגומרין כל הסדר ויש מקומות שקורין עד פרשה ראשונה של בהעלותך כדי להשלים של חנוכה בסדר הנרות ומנהג יפה הוא ושבת שבחנוכה מוציאין ב' ספרים באחד קורא עניינו של יום ובשני של חנוכה ומפטיר בנרות דזכריה רני ושמחי ואם חל בו ב' שבתות מפטירין בשנייה במלכים בנרות של שלמה \u0010y1\u0011ואם חל ר\"ח טבת בשבת מוציאין שלשה ספרים וקורין ששה בעניינו של יום ובשנייה קורא אחד של ר\"ח ומתחיל וביום השבת ובשלישית קורא ומפטיר בשל חנוכה ומפטיר בנרות דזכריה \u0010y2\u0011ואם חל ר\"ח בחול מוציאין ב' ספרים וקורין באחד ג' בענין ר\"ח ובשנייה קורא אחד בענין חנוכה:",["וקורין בפרשת נשא בנשיאים משנה בפ' בני העיר (מגילה לא.) בחנוכה בנשיאים ומפטיר בנרות דזכריה רני ושמחי ואם חל בו ב' שבתות מפטירין בשניי' במלכים בנרות של שלמה פשוט בפ' בני העיר (שם) וכתב הר\"ן אע\"ג דנרות דשלמה קדימי אפ\"ה עדיפי לן דזכריה משום דנבואות עתיד נינהו:","ואם חל ר\"ח טבת בשבת מוציאין ג' ספרים בפ' בני העיר (מגילה כט:) ומפטיר בנרות דזכריה בפ' ב\"מ אהא דבעי רבא (כג:) נר חנוכה וקידוש היום איזה מהם עדיף קידוש היום עדיף דתדיר או דלמא נר חנוכה עדיף משום פירסומי ניסא כתב הרא\"ש משמע אי לאו משום פירסומי ניסא תדיר קודם אפי' לדחות את שאינו תדיר ויש לדקדק מזה כשחל ר\"ח טבת בשבת שמפטירין ההפטרה של ר\"ח ולא בנרות דזכריה דתדיר קודם דלא שייך פירסומי ניסא בהפטרה דהא קורין בתורה דר\"ח קודם ואח\"כ דחנוכה ואי שייך פירסומי ניסא בקריאה אפי' לדחות פירסומי ניסא עדיף כ\"ש להקדים וליתא להך סברא דהך סברא היכא דא\"א לקיים פירסומי ניסא עדיף אבל להקדים תדיר עדיף דאיכא לפרסומי ניסא באחרונה כמו בתחלה הלכך קריאת התורה דאפשר לקיים שניהם תדיר קודם אבל מהפטרה שאין מפטירין אלא א' פירסומי ניסא עדיף ועוד דכיון דקורא בשל חנוכה באחרונה יש להפטיר במאי דסליק ליה ועוד דקריאת התורה אין כ\"כ פירסום אבל בנרות דזכריה איכא פירסום הלכך מפטירין בנרות דזכריה עכ\"ל וכ\"כ שם התו' והמרדכי דמפטירין בנרו' דזכרי' ולא בהשמים כסאי:","ואם חל ר\"ח בחול מוציאין ב' ספרים וקורין ג' בא' בענין ר\"ח ובשניה קורא א' בענין חנוכה מסקנא דגמרא בפ' בני העיר (שם) כתב הרוקח פעם א' שכח וקרא ד' בפרשת החדש שבא בחנוכה ואמר אם לא היה הס\"ת מבחוץ לא היינו צריכים לקרות חמישי בשל חנוכה דהא אמרינן אין משגיחין בחנוכה כל עיקר כלומר אם לא יקרא כל עיקר אין לחוש אחר כי קרא בתורה אסור לקראה פעם שנית אלא כהן בלבד קורא במקום לוי עכ\"ל וזה לשון שבלי הלקט מצאתי בשם רבינו שלמה מעשה בא לפני ר\"ש ששכח החזן וקרא ד' אנשים בפ' ר\"ח שבא בחנוכה כמו שרגילין לקרות בשאר ר\"ח ואומר רבי' אם לא היה מוציא ס\"ת לא היה צריך לקרות יותר דהא אמרינן אין משגיחין בחנוכה ור\"ח עיקר אבל עכשיו שהוציא ב' תורות משום פגמו של ס\"ת שני צריך לקרות חמישי בשל חנוכה ואין לומר שרביעי עצמו יקרא בשל חנוכה קודם שיחתום בס\"ת הראשון בפ' ר\"ח דהו\"ל מדלג ואין מדלגין בתורה בשני ענינין אלא מאחר שהד' התחיל לקרות בשל ר\"ח יחתום ויברך ויבא חמישי אחריו ויקרא בס\"ת השניה בשל חנוכה ומוטב שיבטל הא דאמרי' (כא.) בר\"ח ארבע אין פוחתין מהם ואין מוסיפין עליהם ואל יפגם ס\"ת עכ\"ל וזה לשון התוס' בפ' הקורא עומד (מגילה כג.) אם הוא י\"ט וקרא כל המניין שהוא צריך ושכח לקרות בחובת היום יחזור ס\"ת ויקרא אחר בחובת היום ואחרון שקרא קודם הוי כמאן דליתיה אבל בשבת של חנוכה או בר\"ח של חנוכה א\"צ כדאיתא בילמדנו דחנוכה דלהלכתא אין משגיחין בחנוכה כל עיקר עכ\"ל:"],["וקורין בפ' נשא בנשיאים בפ' בני העיר כתב רש\"י בחנוכה בנשיאים דהוי נמי חנוכת המזבח ורבינו כתב הא דמפרש בפסיקתא כדי ליתן טעם להתחלת ויהי ביום כלת משה שזהו לפי שביום כ\"ה לכסלו נשלם מלאכת המשכן ע\"כ מתחילין בו: ומ\"ש וכן הסדר וכו' אבל מנהגינו עכשיו בסדר אחר כמפורש בדברי האחרונים נהרא נהרא ופשטיה והרשב\"א בתשובה סימן תע\"א כתב על זה ע\"ש:"]],["\u0010c0\u0011\u0010y0\u0011סדר הפרשיות ר\"ח אדר שחל להיות בשבת קורין פרשת שקלים שהיא כי תשא שהוא מענין השקלים עד ועשית כיור נחושת ומפטיר ביהוידע בן שבע שנים ומוציאין ג' ספרים בא' קורין ו' בעניינו של יום בשני קורא אחד בשל ר\"ח ובשלישי קורא מפטיר בפרשת שקלים ובשבת שנייה מוציאין ב' ספרים וקורא באחד מעניינו של יום והמפטיר קורא בשני זכור את אשר עשה לך עמלק עד סוף סדרא ומפטיר כה אמר ה' פקדתי ובשבת שלישית שהוא ט\"ו באדר מפסיקין ובשבת רביעית שהוא כ\"ב בחדש פרשת פרה אדומה באחד קורא הסדר ובשניה קורא המפטיר פרשת פרה ומפטיר ביחזקאל וזרקתי עליכם מים טהורים ובשבת חמישית שהוא כ\"ט בחודש פרשת החדש הזה לכם ומפטירין בראשון באחד לחדש. חל ר\"ח אדר הסמוך לניסן בתוך ימי השבוע ואפילו בע\"ש מקדימין לקרות פרשת שקלים בשבת שלפניו ומפסיקין בשנייה כדי שתהא פרשת זכור בשבת הסמוכה לפורים מלפניה ואם חל פורים בע\"ש מקדימין לקרות פרשת זכור בשבת שלפניו ואז משתנה הסדר והנני מפרש הסדר לפי הימים שראוי לקבוע בהם אדר והם ד' ימים שבת ויום שני ויום רביעי ויום ששי וסימן זבד\"ו ואם חל ר\"ח אדר בשבת אז הסדר כמו שכתבתי לעיל ואם חל ר\"ח אדר ביום השני מקדימין וקורין פרשת שקלים בשבת שעברה שהוא כ\"ט בשבט ובשבת שנייה שהיא ששה באדר מפסיקין ובשבת שלישית שהיא י\"ג בו פרשת זכור ובשבת הרביעית שהיא כ' בו פרשת פרה ובשבת חמישית שהיא כ\"ז בו פרשת החדש ואם חל ר\"ח אדר ברביעי מקדימין וקורין פרשת שקלים בשבת שעברה שהיא כ\"ז בשבט ובשבת שנייה שהיא ד' באדר מפסיקין ובשבת שלישית שהוא י\"א בו פרשת זכור ובשבת רביעי שהוא י\"ח בו פרשת פרה ובשבת חמישי' שהיא כ\"ה בו פרשת החודש ואם חל ר\"ח אדר ביום ו' מקדימין וקורין פרש' שקלים בשבת שעברה שהיא כ\"ה בשבט בשבת שנייה שהיא ב' באדר מפסיקין ובשלישית שהיא ט' בו פ' זכור וברביעית שהיא י\"ו בו מפסיקין ובה' שהוא כ\"ג בו פרשת פרה ובוי\"ו שהיא ר\"ח ניסן פ' החדש סי' זט\"ו ב\"ו ד\"ד ובי\"ו פירוש כשחל ר\"ח אדר בשבת אז מפסיקין ט\"ו בו וסי' זט\"ו וכשחל ביום ב' אז מפסיקין ו' בו וסימן ב\"ו וכשחל ביום ד' אז מפסיקין בד' בו וסימן ד\"ד וכשחל ביום ו' אז מפסיקין ב' בו וי\"ו בו וסימן ובי\"ו פרשת שקלים כשחל להיות בשבת שבואתה תצוה במקום שהמפטיר עולה למנין שבעה מוציאין ספר אחד וקורין מואתה תצוה עד ועשית כיור נחושת ובמקום שאין המפטיר עולה למנין שבעה קורא מואתה תצוה עד סוף סדרא והשביעי שהוא מפטיר חוזר וקורא מכי תשא ואם חל בשבת שבכי תשא עצמה במקום שהמפטיר עולה למנין ז' קורין ו' מכי תשא עד סוף סדרא והשביעי שהוא המפטיר חוזר וקורא כי תשא עד ועשית כיור ובמקום שאין המפטיר עולה למנין ז' קורין ז' מכי תשא עד סוף הסדרא והמפטיר חוזר וקורא מכי תשא עד ועשית כיור \u0010y1\u0011ולפי חילוק סדרים שלנו לא יבא כך לעולם:",["סדר הפרשיות פירוש ד' פרשיות שתקנו חכמים לקרות מר\"ח אדר עד ר\"ח ניסן כמו ששנינו בפרק בני העיר (מגילה כט:) ובגמ' פירשו שם טעם קריאת ד' פרשיות אלו בשבתות אלו וכתבו בתוס' דר\"פ היה קורא דיש פרשיות המחוייבין לקרות דאורייתא כמו פרשת זכור ופרשת פרה אדומה : ר\"ח אדר שחל להיות בשבת קורין פרשת שקלים שהיא כי תשא וכו' כל סימן זה מבואר בפ' בני העיר (שם) והסי' שכתב זט\"ו ב\"ו ד\"ד ובי\"ו מבואר שם בדברי הרי\"ף והרא\"ש:","ומ\"ש ולפי חילוק סדרים שלנו לא יבא כך לעולם פי' דלדידן לא מתרמי פרשת שקלים לא בפרשת ואתה תצוה ולא בפרשת כי תשא:"],["\u0003סדר הפרשיות וכו'\u0004 בפ\"ק דמגלה אסיקנא דהלכה כרשב\"ג דבשנה מעוברת קורין הפרשיות באדר השני ולא בראשון וכתבו רבינו בסוף סימן תרפ\"ח ובמקצת ספרי רבינו לשם נמצא טעות סופרים ע\"ש. כתבו בתו' בפרק שני דמגילה כל התורה בכל לשון נאמרה פי' בקונטרס שניתנה לקרות בכל לשון שרוצה להקרות בס\"ת וקשה שהרי קריאת התורה אינו מן התורה רק מדרבנן לבד מפ' זכור דהוי דאוריית'. ונראה דה\"פ כל קריאה שבתורה כגון מצות חליצה ופ' עגלה ערופה ווידוי מעשר ובכורים וכל אלו השנויין פ' אלו נאמרין עכ\"ל וכיוצא בזה כתבו התוס' בפ' היה קורא והוסיפו לשם פ' פרה אדומה דהוא נמי דאורייתא וצ\"ע מנא להו הא בשלמא פ' זכור ודאי משמע פ\"ב דמגלה דהוי דאורייתא מדאמר התם דהא דכתיב כתוב זאת זכרון בספר האי זכירה קריאה היא דכתיב זכור את אשר עשה לך עמלק יכול בלב כשהוא אומר לא תשכח הרי שכחת הלב אמור הא מה אני מקיים זכור בפה הרי לך דזכירה בפה לקריאה בס\"ת קאמר וכ\"כ הסמ\"ק שזהו בשבת שלפני פורים שמזכירין פ' זכור אבל פ' פרה שוה לפ' שקלים ופ' החדש ומה שתופסין התוס' בפשיטות דקריאת התורה אינה מן התורה אלא מדרבנן ועזרא הוא דתקון איכא לתמוה נמי דבפ' מרובה אמרו מרע\"ה תיקן במדבר שיהו קורין בתורה אלא שבא עזרא ותקן תלתא ובירוש' נמי איתא משה תיקן להם לישראל שיהיו קורין בתורה בשבתות וי\"ט ור\"ח ובחש\"מ שנאמר וידבר משה את מועדי ה' אל בני ישראל ומביאו הרי\"ף בפ' הקורא עומד השתא לפי זה ודאי כל קריאה בשבתות מן התורה כפירש\"י אלא שלא היה סדר מיוחד לכל קריאה מלבד פ' זכור ובא עזרא ותיקן הסדר לכל הקריאות ואפי' לפי זה נראה דצריך ליזהר טפי בפ' זכור שהיא מצוה מיוחדת ומפורשת בתורה משא\"כ שאר קריאות שאינה אלא בעל פה מפי משה רבינו ע\"ה ועיין בתרומות הדשן סי' ק\"ח. שנינו במס' סופרים בא' באדר משמיעין על השקלים ולמה בא' באדר שהיה צפוי וגלוי וידוע לפני מי שאמר והיה העולם שהיה המן עתיד לשקול על ישראל לפיכך הקדים ואמר למשה שיהיו ק' שקלי ישראל קודמין לשקלי המן וצריכין ישראל לתת שקליהם לפני שבת זכור ואסור לומר עליהם לשם כופר אלא לשם נדבה וצריכין להספיק מים ומזון לאחיהם עניים משום מתנות לאביונים ויש שמספיקין לחם ויין ויש שמספיקים לחם ודגים מ\"מ לא יפחות מב' מתנות ואפי' חטים ופולין ע\"כ: כתב מהרש\"ל דממ\"ש מהרא\"י בת\"ה סי' ק\"ח דצריך טפי שישמע קריאת פ' זכור בצבור ממקרא מגלה יראה להדיא שאין הקטן עולה למפטיר בפ' זכור ואע\"פ שהש\"ץ קורא בתורה מה בכך בעינן בר חיובא לעלות והוא ג\"כ קורא בתורה אלא שהש\"ץ קורא בקול רם שלא לבייש וכו' ואף בפ' פרה ראוי להזהר מאחר שבאותן תוספות יראה שאף פ' פרה דאורייתא הוא וכמדומה שכך מצאתי בחידושי מרדכי עכ\"ל ואינו נכון דבקטן היודע למי מברכין ודאי שרי אע\"פ שהקטן קורא בקול רם דהא קטן עולה למנין ז' וקריאת ס\"ת בכל שבת היא דאורייתא מוידבר משה את מועדי ה' כדאמרינן בירושלמי שהבאתי לעיל ואפי' בקטן שאינו יודע למי מברכין לא ידעתי למה לא יצאו השומעין בקריאת הש\"ץ פ' זכור מן הס\"ת דמאי נפקא מינה בעולה לס\"ת אם הוא גדול או קטן עיקר החיוב הוא שישמעו לקריאת התורה מהקורא מתוך ספר התורה:"]],["\u0003הלכות מגילה \u0004\n\u0010c0\u0011\u0010y0\u0011גרסינן במגילת תענית את יום י\"ד ויום ט\"ו באדר יומי פוריא אינון דלא למיספד בהון ודלא למגזר בהון תעניתא ואע\"ג דקי\"ל בטלה מגילת תענית בחנוכה ופורים לא בטלה וא\"כ לפניהם ולאחריהם נמי אסור \u0010y1\u0011כדאיתא במסכת תענית דבכ\"מ שנאמר דלא למספד בהון לפניהם ולאחריהם נמי אסור \u0010y2\u0011אפ\"ה נוהגין להתענות בי\"ג דלא עדיף לפניהם ולאחריהם דחנוכה ופורים משאר יומי דמגילת תענית וכיון ששאר הימים בטלו עיקרן ומותר להתענות בהן אע\"ג דחנוכה ופורים לא בטלו עיקרן לפניהם ולאחריהם מיהא מותר \u0010c1\u0011\u0010y3\u0011\u0010y4\u0011ועוד יש סמך מיהא דאיתא בגמרא י\"ג זמן קהילה לכל היא פי' שהכל מתקבצין לתענית אסתר ובאין בני הכפרים לעיירות לומר סליחות ותחנונים לפי שבו נקהלו לעמוד על נפשם והיו צריכין רחמים ואנו עושין כמו שהם היו עושין בימי מרדכי ואסתר \u0010c2\u0011וכשחל פורים ביום א' מקדימין התענית ביום ה' שלפניו לפי שרגילין להרבות בו בסליחות ותחנונים ולא יתכן לעשות כן בע\"ש שלא יוכלו להכין צרכי שבת ויש מתענין ג' ימים באדר והכי איתא במסכת סופרים רבותינו שבמערב מתענין באדר ג' תעניות של אסתר אע\"פ שאותן היו בניסן לא היו רוצין להתענות בניסן לפי שבו נגאלו אבותינו ממצרים והוקם בו המשכן:",["גרסינן במגילת תענית יום י\"ד ויום ט\"ו באדר יומי פוריא אינון דלא למספד בהון ודלא למגזר בהון תעניתא הכי איתא בסוף פ\"ב דתענית (יח:) ופירש\"י בספ\"ק דר\"ה (יח:) מגילת תענית ימים טובים שקבעו חכמים על ידי נסים שאירעו בהם ואסרום בתענית ויש מהם אף בהספד וכתבו במגילת תענית אילין יומיא דלא להתענאה בהון:","ומ\"ש כדאיתא במס' תענית דבכל מקום דנאמר דלא למספד בהון לפניו ולאחריו נמי אסור כלומר דתנן בפ\"ב דתעניו' (טו:) כל הכתוב במגילת תענית דלא למספד לפניו אסור ולאחריו מותר רבי יוסי אומר לפניו ולאחריו אסור דלא להתענאה בהון לפניו ולאחריו מותר רבי יוסי אומר לפניו אסור ולאחריו מותר ופירש\"י כל הכתוב במגילת תענית דלא למספד. דאית יומין דלא להתענאה ומקצתן דחמירי טפי דלא למספד ואותן שהן חמורים ואסורים בהספד לפניו נמי אסור בהספד דלמא אתי למעבד בי\"ט גופיה ולאחריו מותר דכיון שעבר יום לא חיישי' ואותן שאינן חמורים ליאסר בהספד אלא דלא להתענאה בין לפניו וכו' ואפסיקא הלכתא בגמ' כר' יוסי ולא היה צריך רבי' לכתוב דבכל מקום שנא' דלא למספד בהון לפניו אסור דאפילו אם לא נאמר בפורים אלא דלא להתענאה היה אסור להתענות ביום שלפניו כיון דקי\"ל כרבי יוסי וכן לא היה צריך לכתוב לפניהם ולאחריהם נמי אסור דלענין מה שהוא ר\"ל דביום שלפני פורים אסור להתענות הוה סגי ליה דלימא דלפניהם אסור להתענות אלא דקושטא דמלתא קאמר דכיון שכתוב דלא למספד לפניו ולאחריו אסור:","אפ\"ה נוהגין להתענות בי\"ג דלא עדיף לפניהם דחנוכה ופורים משאר ימים דמגילת תענית כן כתב הרא\"ש בפ\"ק דמגילה וכ\"כ התוס' בפ\"ב דתענית (יח:) דהא דאמרי' חנוכה ופורים לא בטלו ר\"ל בדינים שלהם לעשותן י\"ט ודלא להתענאה בהון אבל בדינים שלפניהם בטלו ותירצו עוד דכיון דיום שלפני הפורים נתבטל מי\"ט דידיה שהיו רגילים לעשות בו ונתבטל י\"ט שלו ה\"נ יש לנו לומר שיבטל משום טעם יום שלפני הפורים דה\"נ אמרינן בסמוך גבי יום שלפני נקנור וכו' וכן גבי י\"ט טוריינוס דכיון דבטלו מיום שלהם לא יאסרו משום י\"ט הבא אחריהם והר\"ן הקשה על זה בפ\"ב דתענית וכתב שהרז\"ה תירץ דכיון דפורים דברי קבלה ודברי קבלה כמו דברי תורה והו\"ל כשבתות וי\"ט דתניא הם אסורים לפניהם ולאחריהן מותרין לפי שהם ד\"ת וד\"ת א\"צ חזוק ובשם הרב אלברצלוני אמרו דכיון דקי\"ל דבטלה מגילת תענית אלמא דעתן של חכמים להקל ולבטל ולפיכך אע\"פ שלא בטלו חנוכה ופורים אין לנו להחמיר בהם ודי לנו לפסוק כשמואל שפסק בגמרא הלכה כרשב\"ג דאמר לפניהם ולאחריהם מותר עד כאן והרא\"ש כתב בפ\"ב דתענית כדברי הרז\"ה: כתב הרמב\"ם בפי\"א מהלכות אבל מותר לספוד לפני חנוכה ופורים ולאחריהם והוא מהטעם שכתבתי ובהגהות מיימוניות כתוב בריש הלכות תענית רבי' שב\"ט כתב דחנוכה ופורים לפניהם ולאחריהם מותר דחנוכה מפרסמא ניסא גם מנהג כל ישראל להתענות ביום שלפני פורים מיהו אין זה ראיה דתענית אסתר שמא שאני דחשיב לן כתענית חובה כיון דהוי מדברי הגאונים ומנהג כל ישראל אבל תענית רשות לעולם אסור עכ\"ל ומיהו לפי התירוצים שכתבתי לעיל תענית רשות נמי שרי והכי נקטינן :","ועוד יש סמך מהא דאיתא בגמרא י\"ג זמן קהילה לכל היא כלומר עד השתא קאמר דליכא איסורא להתענות ביום שלפני פורים והשתא קאמר שיש סמך לומר שראוי להתענות בו וכ\"כ הרא\"ש והר\"ן בריש מגילה אהא דאמרינן י\"ג זמן קהילה לכל היא ופי' רש\"י זמן מלחמה ור\"ת הקשה עליו ופי' דזמן קהילה לכל היא היינו לומר שהכל מתאספין לתענית אסתר ובאים בני הכפרים לעיירות לומר סליחות ותחנונים לפי שבו נקהלו לעמוד על נפשם והיו צריכים רחמים וכן מצינו במשה שעשה תענית כשנלחם בעמלק דכתיב ומשה אהרן וחור עלו ראש הגבעה ודרשינן במס' תעניות מכאן לתענית צבור שצריך ג' מכאן נראה לר\"ת סעד לתענית אסתר שאנו עושים כמו שעשו בימי מרדכי ואסתר שנקהלו היהודים לעמוד על נפשם ולא מצינו לו סמך בשום מקום אלא מכאן ומה שאנו מקדימין התענית ליום ה' היכא שחל פורים להיות במ\"ש ולא עבדי' ליה בע\"ש נמצא בתשובת הגאונים לפי שרגילין בתענית להרבות בסליחות ותחנונים ולא יתכן לעשות כן בע\"ש לפי שלא יוכלו לטרוח לכבוד השבת ובמסכת סופרים שרבותינו שבמערב מתענין באדר ג' תעניות של אסתר אע\"פ שאותם היו בניסן לא היו רוצין להתענות בניסן שנגאלו בו אבותינו והוקם המשכן עכל הרא\"ש ואח\"כ הביא הא דאמרינן בספ\"ק דר\"ה דאע\"ג דבטלה מגילת תענית חנוכה ופורים לא בטלו וכתב עליו אית דבעי למימר כיון דלא בטלו אוקמי אדינייהו ולפניהם ולאחריהם אסור ואית דאמר לא עדיף לפניהם ולאחריהם משאר יומי מגילת תענית וכן מסתבר ולכן נהגו להתענות בי\"ג באדר ולמאי דפרישית לעיל זמן קהילה לכל היא הוי תענית אסתר תקנת חכמים אף קודם שבטלה מגילת תענית עכ\"ל וגם המרדכי האריך שם לתת טעם למה מתענים ערב פורים:","ומ\"ש ומה שאנו מקדימין התענית ליום ה' היכא שחל פורים להיות במ\"ש היינו לומר דלא תימא אם איתא דתעני' זה נתקן מפני שהתענו בימי מרדכי בי\"ג שהוא יום המלחמה כשחל פורים במ\"ש היה לנו להתענות בע\"ש כדי לסומכו לי\"ג כל מה שאפשר ומדחזינן שאנו מתענין ביום ה' נראה שאין טעמו של תענית זה מפני שהתענו בימי מרדכי בי\"ג שהוא יום המלחמה אלא מטעם אחר אנו נוהגים להתענות לכך כתב דלעולם מטעם זה אנו מתענין וכשחל פורים במ\"ש בדין הוא שיתענו בו ביום ששי אלא מפני שרגילין בתענית בסליחות ומשום דקשיא ליה א\"כ שאנו מתענין תענית זה זכר לתענית מרדכי ואסתר למה אין אנו מתענין הג' תעניות שהתענו הם בניסן לכך כתב רבותינו שבמערב היו מתענין אותם ואנו שלא נהגו כן נראה שהטעם כדי שלא להכביד על הצבור וזה שכתב כשחל פורים ביום א' מקדימים ומתענין ביום ה' שלפניו כן כתב הרוקח בשם השאלתות: כתוב בשבלי הלקט מצאתי בשם רש\"י מעשה היה ואירע פורים בא' בשבת וקדמו הצבור להתענות בה' כמנהג ובאת אשה אחת שהיתה צריכה לרכוב אצל השלטון ושאלה לרבי' אם היא יכולה להתענות למחר ולאכול היום מפני טורח הדרך ואמר רבינו תענית זה אינו לא מדברי תורה ולא מדברי סופרים אלא מנהג בעלמא שהרי תענית אסתר ומרדכי היו בימי הפסח ואם נפש אדם לומר דברי הצומות וזעקתם זה אין פי' אלא כך פירש' על דבר הצומות והצעקות שעברו עליהם בימי המן קבלו עליהם ימי הפורים לזכר להם לדורות הנס ואעפ\"כ אסור לו לאדם לפרוש מן הצבור משום לא תתגודדו ויש מהפרושים שמתענים עם הצבור יום ה' וחוזרים ומתענין יום ו' כדי לסמוך התענית לפורים ורבי' קורא עליהם הכסיל בחשך ילך דכל עצמו של תענית אינו אלא מנהג ומחמיר זה במקומו כאילו הוא קבוע מן התורה וכיון שנהגו רבים להתענות בה' דיינו בכך עכ\"ל וכל זה כתוב ג\"כ בא\"ח כתב הרמב\"ם בפ\"ה מהלכות תעניות נהגו כל ישראל בזמנים אלו להתענות בי\"ג באדר זכר לתענית שהתענו בימי המן שנאמר דברי הצומות וזעקתם ואם חל י\"ג באדר להיות בשבת מקדימין ומתענין בחמישי שהוא י\"א וכתב ה\"ה הטעם לפי שא\"א לאחר עד יום ראשון לפי שהוא פורים וכן אין מתענין בע\"ש מפני כבוד השבת ואע\"פ שנפסקה הלכה בע\"ש מתענה ומשלים דוקא כשבא זמנו הקבוע לו בע\"ש אבל כשהוא נדחה מזמנו אין קובעין לו בע\"ש וכן מפורש בתשובת הגאונים עכ\"ל:"],["\u0003גרסינן במגילת תענית את יום י\"ד וכו'\u0004 בספ\"ב דתענית ואיתא התם אמר רבא לא נצרכה אלא לאסור של זה בזה ושל זה בזה כלומר דלא צריכנא למיכתב במגלת תענית לאסור לבני י\"ד בי\"ד ולבני ט\"ו בט\"ו דהא קרא כתיב בהדיא להיות עושים וגו' אלא לאסור של בני ט\"ו בי\"ד ושל בני י\"ד בט\"ו וא\"כ הא דאמר בפ\"ק דר\"ה דאע\"ג דבטלה מגלת תעני' בחנוכ' בפורים לא בטלה היינו לומר דבפורים לא בטל ואסור של זה בזה דאילו הן עצמן לאו ממגילת תענית נינהו. וא\"כ לפניהם ולאחריהם נמי אסור וכו' לאו בניחותא קאמר אלא כלו' לא תימא כיון דלא בטלה א\"כ ממילא לפניהם ולאחריהם נמי אסור כדתנן במסכת תענית דהא ליתא אלא אפ\"ה נוהגין להתענות בי\"ג משום דלא עדיף וכו' דהשתא כל לפניהם ולאחריהם מותר וכ\"כ ה\"ר ירוחם בפירו' והם מדברי הרא\"ש ספ\"ק דמגילה:","\u0003ומ\"ש ועוד יש סמך וכו'\u0004 כלומר דלמ\"ש תחלה ולא עדיף וכו' מתיישב שאין איסור במה שנוהגין להתענות בי\"ג ולפ\"ז ודאי מפני הטורח או מצטער בעלמא יכול הוא שלא להתענות וכמ\"ש בשבולי הלקט הביאו ב\"י אבל יש עוד סמך וכו' דאלמא דתקנת חכמים היא אף קודם שבטלה מגלת תענית להתענות בי\"ג ולא מנהג בעלמא שנהגו אחר שבטלה מגילת תענית ובסגנון זה הם דברי הרא\"ש לשם ומיהו סמך זה אינו אלא לפר\"ת בפי' זמן קהילה לכל היא וכן הסכים הרא\"ש לפי' ר\"ת דלא כפרש\"י ומכל מקום אף לדידהו יש להקל למעוברות ומניקות ויולדות אחר ז' וכואבי עינים ויפרעו יום אחר כדקי\"ל דבמקום חולה אפי' אין בו סכנה לא גזרו רבנן וכ\"כ באגודה לפי פי' ר\"ת ומשמע מדברי האגודה דלמאן דמפיק ליה תענית זה מדכתיב דברי הצומות וזעקתם אפי' מעוברות והדומין להם מחוייבין להתענות דד\"ק כד\"ת ולפ\"ז תענית זה חמיר טפי מד' צומות דבזמן הזה דאין שמד ואין שלום דתלו ברצו ומקילין בם למעוברות כדלעיל בסימן תקנ\"ד אבל כאן כתיב וכאשר קבלו על נפשם דברי צומות וזעקתם משמע דצום זה קבוע מד\"ק וכ\"נ דעת הרמב\"ם בפ\"ה מה\"ת וכ\"כ הר\"ן בפ\"ב דתענית משם הראב\"ד דמפיק לה מדברי הצומות ונראה דזהו דעת ספר א\"ח בשם הראב\"ד לקרות המגילה מבע\"י כדי להקל על האנושים והמעוברות שלא להתענות יותר מדאי דאלמא דאפילו האנושים והמעוברות חייבים להתענות ויש להקל בשבילם דאם לא היו חייבין להתענות שלא כדין עושים דמתענין ולא היה לנו להקל בקריאה מבע\"י כדי בשבילם מיהו דעת שאר הפוסקים יראה דאין בתענית זה לכל היותר אלא תקנת חכמים ולאו דברי קבלה והכי נהוג להקל למעוברות ולמניקות וכיוצא בהם: והא דכתב רבינו דלפניהם ולאחריהם מותר להתענות לאו למידק מיניה דבהספד מיהא אסור וכה\"ר אפרים שהביאו הרז\"ה ספ\"ק דמגילה וכן נמצא במקצת ספרי הרי\"ף לשם הא ליתא דאילו ה\"ר אפרים סובר דאפי' לפניהם ולאחריהם לא בטלה בחנוכה ובפורי' אבל רבינו דסבר דבטלה אין חלוק דאף לספוד נמי שרי ולא נקט להתענות אלא לפי שעיקר דעתו להחזיק המנהג שמתענין בי\"ג ואה\"נ דלספוד נמי שרי לפי שטתו ואפשר עוד כיון דאיכא ימים דמותר לספוד בהן ואסור להתענות כדתנן בפ\"ב דתענית א\"כ כשכתב רבינו דמותר להתענות לפניהם שמעי' במכ\"ש דמותר לספוד בהן וכ\"כ הרמב\"ם פי\"א דהלכות אבל דמותר לספוד בהן. ואיכא להקשות לדעת רבינו דאפילו לכתחלה יכולין לגזור תענית בלפניהם ולאחריהם כיון דבטלום וזה סותר מ\"ש הרא\"ש ע\"ש הראב\"ד בסתם דאין גוזרין תענית לכתחלה אע\"פ שבטלום ואפשר דדוקא בעיקרן קאמר שאין גוזרין אבל בלפניהם מודה דיכולין לגזור ומה שצריך הראב\"ד לישב מה שמתענין בי\"ג אע\"ג דהוה לפניהם היינו משום דס\"ל דחנוכה ופורים לא בטלו כל עיקר ואפי' בלפניהם כמבואר מלשונו ע\"ש אבל לרבינו והיא מסקנת הרא\"ש ספ\"ק דמגלה דעיקרן דחנוכה ופורים דוקא הוא דלא בטלו אבל לפניהם בטלו א\"כ ממילא נמי יכולין לגזור תענית בהן. ולענין הלכה בפורים בלפניהם הכל מודים דמתענין ואצ\"ל דמספידין אבל בלאחריו פליגי דלה\"ר אפרים יום ט\"ו בעצמו הוא יום שלאחר הפורים לבני עיירות ובו אסור אבל בי\"ו שרי ולשאר גאונים יום י\"ו הוא יום שלאחריו וכן נראה עיקר שהרי יום ט\"ו גופיה י\"ט הוא ממגלת תענית וכדאמר רבא לא נצרכה אלא לאסור של זה בזה וא\"כ יום י\"ו הוא יום שלאחריו לבני עיירו' אבל לבני כרכים אין איסור בי\"ו דכיון דיום ט\"ו לאו ממגלת תענית הוא אלא מד\"ק שהוא כד\"ת א\"צ חזוק וכ\"כ הרז\"ה בטעם תענית יום י\"ג לבני עיירות והעלה שיום י\"ג אסור בתענית לבני כרכים ולא נהגו כמותו שהרי כל הגאונים כתבו שנהגו הכל להתענות בי\"ג משמע מלשון הכל בין עיירות בין כרכים עוד כתב הרז\"ה לפסק הלכה דבלאחריהם מותרין בין בהספד בין בתענית כר' יוחנן והוא דעת הר\"ן בפ\"ב דתענית ושלא כדברי ה\"ר אפרים אבל בלפניהם פסקו הרז\"ה והר\"ן שאסור וראייתם ברורה מסוגיית התלמוד וכ\"נ להורות לאסור בלפניו דחנוכה דאף הרא\"ש ורבינו שכתבו דלא עדיף וכו' והכי מסתברא אינו אלא לתת טעם למנהג שמתענין בי\"ג שלא נמצא בתלמוד וכיון דבמסקנא הסכימו לפי' ר\"ת בזמן קהילה לכל היא דתקנת חכמים היא להתענות בי\"ג אף קודם שבטלה מגלת תענית א\"כ אין צורך להך סברא דלא עדיף וכו' והדברים כפשטן בתלמיד דלא בטלו כל עיקר אפי' בלפניהם אלא שהרז\"ה סובר דבלפניו דחנוכה אעפ\"י שאסור להתענות מותר בהספד ע\"ש והכי נקטינן לאסור תענית בלפניו דחנוכה ומותר בהספד אבל בלאחריו הכל שרי ודלא כמ\"ש בש\"ע בחנוכה ופורים מותרים להתענו' לפניהם ולאחריהם ודו\"ק:","\u0003וכשחל פורים ביום א' וכו'\u0004 משמע דוקא הכא אין להתענות בערב שבת מפני שמרבים בסליחות הא לאו הכי שרי וכ\"כ לעיל סי' רמ\"ט ס\"ג אבל לפי מ\"ש ה' המגיד פ\"ב מהלכות תענית משמע דטעמו הכא כיון דתענית זה נדחה מזמנו אין קובעין לו מע\"ש מפני כבוד השבת שלא יכנס לשבת כשהוא מעונה גם שלא יצום בהכנסת שבת דמקצת ע\"ש כשבת והא דקי\"ל בסוף בכל מערבין הלכה מתענה ומשלים היינו כשבא זמנו הקבוע לו בע\"ש ולפי זה מי שרגיל להתענות בערב ר\"ח אם חל ר\"ח ביום א' אין להתענות ביום ו' אלא ביום ה' דכיון דנדחה מיום השבת שהוא זמנו אין קובעין לו מערב שבת וכ\"כ מהרי\"ו והכי נמי כתב המרדכי בתענית מי שנשבע להתענות בע\"ש ה\"ז כשבועת שוא דמקצת שבת כשבת וכ\"כ ברוקח סי' ל\"ו והא דאמרינן בעירובין הני בר בי רב דיתבי בתעניתא במעלי דשבתא איכא למימר דאה\"נ דלאו שפיר עבדי אלא כיון שנהגו כך קמבעיא להו מהו לאשלומי וע\"ל בסי' רמ\"ט במ\"ש לשם בס\"ד:"]],["\u0010c0\u0011\u0010y0\u0011אמר ריב\"ל חייב אדם לקרוא את המגילה בלילה ולשנותה ביום והיא מצות עשה מדברי סופרים ומברכים עליה כמו שמברכין על מצוה דרבנן \u0010y1\u0011וצריך אדם ליזהר שלא לבטל קריאתה \u0010c1\u0011שהרי אפי' כהנים צריכין לבטל מעבודתן כדי לשמוע מקרא מגילה ואפילו ת\"ת ששקולה כנגד כל המצות מבטלין אותה לשמוע מקרא מגילה כ\"ש שאר המצות \u0010c2\u0011ואין לך דבר שאין נדחה מפני מקרא מגילה אלא קבורת מת מצוה בלבד \u0010c3\u0011שהמוצא מת מצוה קוברו ואח\"כ קורא אבל שאר כל המצות נדחין מפניה הלכך צריך אדם ליזהר בה והנני מסדר הלכותיה זמן קריאתה ומי הם שחייבים לקרותה והכשר קריאתו והכשר תיקונה וברכותיה וסדר היום ומצות סעודתו ומתנות עניים ושלוח מנות ואיסורו בהספד ותענית ובעשיית מלאכה:",["אמר ריב\"ל חייב אדם לקרוא את המגילה בלילה ולשנותה ביום בפ\"ק דמגילה (ד.) וכתב רש\"י ולשנותה ביום זכר לנס שהיו צועקין בימי צרתם יום ולילה כתוב בא\"ח בשם הראב\"ד נהגו לקרותה מבע\"י ליל י\"ד כדי להקל על האנושים והמעוברות שלא להתענות יותר מדאי עכ\"ל : והיא מצות עשה מדברי סופרים ומברכין עליה כמו שמברכין על מצות דרבנן פשוט הוא:","וצריך אדם ליזהר שלא לבטל קריאתה שהרי אפי' כהנים צריכים לבטל מעבודתן בפ' קמא דמגילה (ג.) משפחה ומשפחה למה לי א\"ר יוסי בר חנינא להביא משפחות כהונה ולויה שמבטלין מעבודתן ובאין לשמוע מקרא מגילה תנ\"ה כהנים בעבודתם ולוים בדוכנן וישראל במעמדם כולן מבטלין מעבודתן ובאין לשמוע מקרא מגילה בעי רבא מת מצוה ומקרא מגילה הי מינייהו עדיף בתר דבעיא הדר פשטה מת מצוה עדיף דאמר מר גדול כבוד הבריות שדוחה את לא תעשה שבתורה וכתב הר\"ן שמבטלין מעבודתן ובאין לשמוע מקרא מגילה אע\"פ שיש שהות ביום לעבוד עבודה ואח\"כ לקראה אפ\"ה מבטלין מעבודתן ובאין לשמוע מקרא מגילה בצבור ומיהו דוקא בשיכולים אח\"כ להשלים העבודה הא לאו הכי ודאי אין מבטלין העבודה מדאורייתא משום מגילה דרבנן וכתב מהור\"ר אליה המזרחי ז\"ל על דברי הר\"ן וכ\"נ גם מדברי הרמב\"ם שכתב חוץ ממת מצוה שאין לו קוברין שהפוגע בו קוברו בתחלה ואח\"כ קורא דמשמע אי איכא שהות אין ואי לא לא דאל\"כ ואח\"כ קורא למה לי עכ\"ל וכך פי' דבריו כיון שהרמב\"ם סבור שמה שאמרו דמת מצוה ומקרא מגילה מת מצוה עדיף הוא לענין קדימה אבל לא שתתבטל מקרא מגילה מפני מת מצוה א\"כ ה\"ה דכשאמרו מבטלין מעבודתן בשביל מקרא מגילה לא ביטול ממש קאמר אלא קדימה וכן הוא דעת התוספות שכתבו מבטלין כהנים מעבודתן לשמוע מקרא מגילה וקשה אמאי מבטלין והלא אחר הקריאה יש הרבה שהות לעבודה י\"ל דכיון דמשהאיר היום הוי זמן עבודה והך מניחין אותם בשביל הקריאה משום הכי קרי ליה ביטול וא\"ת ויעשו עבודתן מיד ואחר כך יקראו המגילה לבדם וי\"ל דטוב לקרות עם הצבור משום דהוי טפי פירסומי ניסא:"],["\u0003אמר ריב\"ל וכו'\u0004 בפ' קמא דמגלה ואיכא למידק דכיון דכאן כתב דמצוה לקרותה בלילה ובסוף סי' תרפ\"ח כתב דין חזרת קריאתה ביום לאיזה צורך הביא הך דריב\"ל וי\"ל לפי שבזמנו היו מזלזלין בקריאתה ביום ובלילה וכמ\"ש בסמוך ע\"כ הביא לשון התלמוד דהחיוב שוה ביום ובלילה ולכן צריך ליזהר שלא לבטל קריאתה בשום פעם ולומר כבר קראתיה בלילה או יאמר למחר אקרא אותה ביום:","\u0003ומ\"ש שהרי אפי' כהנים וכו'\u0004 שם משפחה ומשפחה למה לי אריב\"ח להביא משפחת כהונה ולויה שמבטלין מעבודתן ובאין לשמוע מקרא מגלה. ומ\"ש ואפי' ת\"ת וכו' שם מכאן סמכו של בית רבי שמבטלין ת\"ת ובאין לשמוע מקרא מגלה ק\"ו מעבודה ומה עבודה שהיא חמורה מבטלינן ת\"ת לא כ\"ש ומסיק הא דעבודה חמור' מת\"ת היינו ת\"ת של יחיד כלומר שאינו ת\"ת של כל ישראל ותימה על לשון רבינו שכתב אפי' כהנים וכו' אפי' ת\"ת וכו' דהול\"ל כו' אפי' ת\"ת ואח\"כ אפילו כהנים דהוי לא זו אף זו כיון דעבודה חמורה וי\"ל דכיון דת\"ת לא אתיא אלא בק\"ו מעבודה לפיכך כתב תחלה ואפי' כהנים דילפינן לה מקרא משפחה ומשפחה ואח\"כ ואפילו מת\"ת דילפינן לה בק\"ו מעבודה ולזה נתכוין רבינו לפרש בעצמו דבריו שמ\"ש ואפי' מת\"ת דלא נתכוין לומר ואפי' מת\"ת ומכ\"ש עבודה דהא עבודה חמורה אלא ה\"ק ואפי' מת\"ת וכ\"ש שאר מצות ואכתי קשה למה האריך בלשונו וכתב וצריך כל אדם ליזהר וכו' הלכך צריך כל אדם ליזהר בה ולמה לא כתב הדינים בסתם כמ\"ש הרמב\"ם והסמ\"ג ושאר הפוסקים ונראה דלפי שבדורותיו לא היו נזהרין לקרות המגלה בב\"ה עם הצבור ביום ובלילה או מפני טרדת הכנת סעודת פורים שהיא מצוה ועוסק במצוה פטור מן המצוה או מפני אשתו וילדיו ובניו שקשה עליהם לבא לב\"ה בפרט בלילה ולכן היו קורין המגילה בבתיהם בעשרה וכך היו נוהגין בזמנו של האור זרוע כדמוכח בהגהת אשיר\"י בפרק קמא דמגלה ועל כן כתב רבינו וצריך ליזהר שלא לבטל קריאתה ר\"ל קריאתה עם הצבור בבית הכנסת ולא יחוש למצות הכנת סעודת פורים או שאר מצות שהרי אפי' כהנים וכו' פי' אע\"פ שהיו יכולין לעבוד עבודתם תחלה ואח\"כ לקרות המגלה בעשרה ואפ\"ה צריכין לבטל מעבודתן כדי לשמוע מ\"מ בצבור ברוב עם משום דהוי טפי פרסומי ניסא וכמ\"ש התוס' פ\"ק דמגלה א\"כ כל שכן שאר יחידים ואמר עוד ואפילו ת\"ת וכו' כלומר ועוד יש להביא ראיה מת\"ת ששקולה כנגד כל שאר מצות מבטלין משום מ\"מ מכ\"ש שאר מצות והלכך צריך כל אדם אפי' עסק במצוה רבה ליזהר בה ביום ובלילה לקרותה ברוב עם עם הצבור ולבוא עם אשתו וילדיו לב\"ה וכ\"כ הר\"ן דההיא דמבטלין עבודה ושל בית רבי איירי אפי' היו יכולין לקרות בעשרה היו מבטלין העבודה ות\"ת כדי לקרות עם הצבור משום ברוב עם וגומר ולקמן בסימן תר\"צ הבאתי דבריו:","\u0003ואין לך דבר וכו'\u0004 עד שהמוצא מת מצוה קוברו ואח\"כ קורא כך הוא לשון הרמב\"ם בפ\"א מה' מגילה ומשמע מלשון זה דמיירי בדאיכא שהות לקרות לאחר הקבורה הא ליכא שהות קורא תחלה וכ\"כ הרא\"ם בביאוריו לסמ\"ג ולפ\"ז הא דכהנים מבטלין עבודתם לשמוע מקרא מגלה היינו נמי בדאיכא שהות להשלים העבודה דאי לאו הכי אין מבטלין העבודה דאורייתא משום מגילה דרבנן וכ\"כ הר\"ן וב\"י ואין להקשות מת מצוה נמי דאורייתא היא מולאחותו לא ליבטול אפי' בדליכא שהות לקריאת מגילה דיש לומר הא פשיטא היא דיכול לקיים קבורת מת מצוה אחר קריאת מגילה עכ\"פ דאף עפ\"י שיהא שעה מועטת מעוכבת המצוה מ\"מ לא תהא נידחית לגמרי וכיון דקריאת מגילה תהא נדחה לגמרי אם יהא עוסק בקבורה תחלה כיון דליכא שהות קורא תחלה שהרי עכשיו אתה יכול לקיים שניהם אבל בדאיכא שהות מת מצוה קודם משום כבוד הבריות שלא יהא מונת בבזיון אפי' זמן מועט אבל בעבודה ושאר מצות הדין בהפך דבאיכא שהות מגילה קודם כדדרשינן משפחה ומשפחה אבל בדליכא שהות עבודה קודמת כיון שהיא דאורייתא ומגילה דרבנן נדחה מפניה כיון דאי אפשר לקיים שניהם כל זה כתבנו לדעת הר\"ן והרא\"ם וכן פסק בש\"ע אבל יש לפרש הא דכתב רבינו קוברו ואח\"כ קורא דלאו דוקא בדאיכא שהות אלא אפילו בדליכא שהות לקריאת מגילה אחר הקבורה נמי קבורת מ\"מ קודם דהכי משמע מסתמא דתלמודא דבכל גוונא דחי קבורת מ\"מ למקרא מגילה שלא יהא מונח כלל בבזיון ואפי' זמן מועט ורבינו שאומר קוברו ואח\"כ קורא רבותא קמ\"ל דלא תימא כיון דאיכא שהות לקיים שניהם נקדים מקרא מגילה דמצותה להקדים משום פרסומא ניסא קמ\"ל דלא אלא מת מצוה קודם וקוברו ואח\"כ קורא וכן ראיתי כתוב בשם מהרש\"ל ולענין הלכה צ\"ע:","\u0003ומ\"ש רבינו שהמוצא מת מצוה וכו'\u0004 נקט לשון מוצא לאורויי דאיירי במ\"מ שמצא בדרך שאין לו קוברין ומפני כבוד הבריות שלא יהא מוטל בבזיון בלי קבורה לפיכך קבורת מ\"מ קדים אבל אם יש לו קוברין כגון בעיר אין המגילה נדחית והכי משמע להדיא מסוגיא דתלמודא וכ\"כ בשלטי הגבורים:"]],["\u0010c0\u0011\u0010y0\u0011מגילה נקראת בי\"א בי\"ב בי\"ג בי\"ד בט\"ו \u0010y1\u0011והאידנא אינה נקראת אלא בי\"ד \u0010y2\u0011אלא שהכרכים המוקפים חומה מימות יהושע בן נון קורין בט\"ו אפילו אם הם בח\"ל \u0010c1\u0011\u0010y3\u0011וכן הכפרים הסמוכים להן אפילו אינם נראים עמהם כגון שהם בעמק או שנראין עמהם אפי' אינם סמוכין כגון שהם בהר ובלבד שלא יהו רחוקים יותר ממיל \u0010y4\u0011ואפילו הכרך אינה מוקפת חומה עתה אם היתה מוקפת בימי יהושע קורין בט\"ו \u0010c2\u0011\u0010y5\u0011וכיון שהיתה מוקף אפי' אין בו י' בטלנין שמשכימין תמיד לב\"ה קורין בט\"ו \u0010c3\u0011\u0010y6\u0011ואין קרוי מוקף חומ' אא\"כ הוקף חומה תחלה ואח\"כ נתיישב אבל נתיישב ואח\"כ הוקף אין קורין אלא בי\"ד \u0010y7\u0011ופי' הר\"ם מרוטנבורק דלא מקרי ישב ואח\"כ הוקף אלא כשישב תחילה אדעתא שלא להקיפו אבל אם ישב תחלה על דעת להקיפו מקרי שפיר הוקף ולבסוף ישב. \u0010c4\u0011\u0010y8\u0011כרך שהוא ספק אם הוקף בימי יהושע אם לאו קורין בי\"ד ובט\"ו ולענין ברכה כתב אחי הר\"י ז\"ל מסתברא שיקראו בלא ברכה בשני הימים ביום ט\"ו לא יברכו דשמא אינה מוקפת חומה וביום י\"ד לא יברכו דשמא היא מוקפת ועדיין לא הגיע זמנה והויא ברכה לבטלה וכיון דברכה לא מעכבה למה יכניס עצמו בספק ברכה לבטלה והרמב\"ם כתב שמברכין בי\"ד כיון שהוא זמן קריאה לרוב העולם ובשושן קורין בט\"ו אע\"פ שאינה מוקפת חומה מימות יהושע הואיל ונעשה בו הנס. \u0010c5\u0011\u0010y9\u0011בן עיר שהלך לכרך ובן כרך שהלך לעיר אם כשהלך היה דעתו לשוב לביתו בליל י\"ד קודם שיאור היום קורא כבני מקומו אף אם נתעכב שם ואם אין דעתו לשוב עד שיאור יום י\"ד קורא כבני המקום שהלך שם כיצד בן כרך שהלך לעיר אם היה דעתו לשוב למקומו בליל י\"ד קורא כבני מקומו אפילו אם נתעכב אח\"כ בעיר אבל אם דעתו לעמוד שם מקצ' י\"ד כיון שדעתו לעמוד שם מקצת היום של זמן קריאתו חל עליו זמן חובת קריאתן וקורא עמהן וכן בן עיר שהלך לכרך אם דעתו לשוב לביתו בליל י\"ד קודם שיאור היום קורא כאנשי מקומו אבל אם היה דעתו לעמוד שם מקצת י\"ד כיון שלא היה דעתו לשוב למקומו בזמן חוב' אנשי מקומו נסתלק מעליו חובת קריאת אנשי מקומו ונחשב כבני המקום שעמד שם להתחייב בזמן קריאתם: \u0010c6\u0011\u0010y10\u0011פורים שחל להיות בשבת \u0010y11\u0011כגון ט\"ו לבני כרכים דאילו י\"ד לא יבא לעולם בשבת אין קורין את המגילה בשבת אלא \u0010y12\u0011מקדימין לקרותה בע\"ש וכדי שיזכרו ענין היום דורשין בעניינו: \u0010c7\u0011\u0010y13\u0011שדרו ממתיבתא היכא דנפיק בשייר' או נפיק בספינתא קורא בי\"ד וכל תקנה שיכול לעשות כדי שיקרא בי\"ד יעשה ואם אין יכול לעשות קורא אותה בי\"א בי\"ב בי\"ג אבל בעשירי ומי' ולמטה אינו יכול לקרותה וכ\"כ רע\"ם ז\"ל וכתב שמברך לפניה ולאחריה כשקורא אותה מי\"א ולמעלה וב\"ה ז\"ל כתב שהאידנא אין קורין אותה כלל אלא בי\"ד אפילו מי שיוצא בשיירא וטוב לקרותה בלא ברכה \u0010c8\u0011\u0010y14\u0011וקורין אותה בלילה וחוזרים וקורין ביום \u0010y15\u0011ושל לילה זמנה כל הלילה ושל היום זמנה כל היום \u0010y16\u0011מהנץ החמה עד סוף היום ואם קראה משעלה עמוד השחר יצא \u0010c9\u0011קראוה באדר ראשון ואח\"כ ראו לעבר השנה קורין אותה באדר שני אבל הפרשיות שעשו באדר ראשון א\"צ לחזור לעשותן בשני:",["\u0003מגילה נקראת בי\"א בי\"ב וכו'\u0004 משנ' בריש מגילה (ב.) מגילה נקראת בי\"א בי\"ב בי\"ג בי\"ד בט\"ו לא פחות ולא יותר כרכין המוקפין חומה מימות יהושע בן נון קורין בט\"ו כפרים ועיירות גדולות קורין בי\"ד אלא שהכפרים מקדימין ליום הכניס' ופירש\"י אלא שהכפרים מקדימין ליום הכניסה. כלומר מאחר שהמוקפין קורין בט\"ו ושאין מוקפין קורין בי\"ד הרי הכל בכלל תו היכי משכחת י\"א י\"ב י\"ג אלא שהכפרים נתנו להם חכמים רשות להקדים קריאתה ליום הכניסה יום שני בשבת שלפני י\"ד או חמישי בשבת שהוא יום הכניסה מתכנסין לעיירות למשפט לפי שבתי דינים יושבים בעיירות בשני ובה' בתקנת עזרא והכפרים אינם בקיאים לקרות וצריכים שיקראנה להם א' מבני העיר ולא הטריחום חכמים להתאחר ולבא ביום י\"ד ופעמים שיום הכניסה בי\"ג ופעמים שהוא בי\"א:","ומ\"ש והאידנא אינה נקראת אלא בי\"ד אלא שהכרכים המוקפים חומה מימות יהושע בן נון קורין בט\"ו שם על משנה זו אמר רבה בר בר חנה א\"ר יוחנן זו דברי ר\"ע סתימתאה אבל חכמים אומרים בזמן הזה הואיל ומסתכלין בה אין קורין אותה אלא בזמנה ופירש\"י הכל צופין למקרא מגילה ואומרים יום י\"ד באדר קרינן מגילה נשארו לאדר ט\"ו יום וט\"ו של ניסן עושין פסח ואם תקדים קריאתה יעשו פסח לסוף שלשים יום של קריאה ונמצאו אוכלין חמץ בימים אחרונים של פסח והרי\"ף פירש הואיל ומסתכלין בה כלומר הואיל ועיניהם של עניים נשואות למקרא מגילה כדי לחלק להם מעות פורים אין קורין אותה אלא בזמנה ויש שגורסים בזמניהם היו קוראין אותה בי\"א בי\"ב בי\"ג אבל בזמן הזה אין קוראין אותה אלא בזמנה שהוא י\"ד וט\"ו ונראה שזו היתה גירסתו של הרמב\"ם שכתב בד\"א שמקדימין וקורין ביום הכניסה בזמן שיש לישראל מלכות אבל בזמן הזה אין קורין אותה אלא בזמנה שהוא יום י\"ד ויום ט\"ו בני הכפרים ובני עיירות קוראין בי\"ד ובני כרכין קורין בט\"ו:","ומ\"ש רבינו שהכרכין המוקפין חומה מימות יהושע בן נון קורין בט\"ו אפי' אם הם בחוצה לארץ כתב הר\"ן דאיכא מ\"ד דכיון דבמוקפין חומה תלינן ביהושע דוקא בארץ אבל בחוצה לארץ אפילו מוקפין חומה מימות יהושע קורין בארבעה עשר דמה ענין יהושע בח\"ל אבל בתוס' הביאו ראיה שאפילו בח\"ל קורין בט\"ו מדאמרינן (ה:) רב אסי קרא מגילה בהוצל בי\"ד ובט\"ו מספקא ליה וכו' והוצל בח\"ל היתה כדאמרי' בסוף כתובות (קיא.) ואין זו ראיה לפי שכתוב במקצת נוסחאות רב אסי קרא מגילה בהוצל דבנימין אבל הרמב\"ן כתב דמשמע דמוקפים דח\"ל קורין בט\"ו דהא לרבי יהושע בן קרחה דאמר כל המוקפין חומה מימות אחשורוש אפילו בח\"ל קורין בט\"ו ומדר' יהושע בן קרחה נשמע לרבנן במוקפין חומה מימות יהושע בן נון דהא לא פליגא אלא בזמן דרבנן תלו לה בזמן יהושע בן נון וריב\"ק תלי לה בזמן אחשורוש אבל בעיירות שבח\"ל לא נחלקו גם זו אינה ראיה דאיכא למימר דהא בהא תליא אלא שהוא ז\"ל הביא עוד ראיה מדגרסינן בירושלמי הכרך שחרב ונעשה של עו\"ג וכו' ואם הירוש' מתפרש כך יש ללמוד ממנו שהכרכין מוקפין חומה שבח\"ל קורין בט\"ו וכן דעת הגאונים ו\"ל עכ\"ל וכ\"כ הרמב\"ם שכרך המוקף חומה מימות יהושע בן נון קורא בט\"ו אף אם הוא בח\"ל. ואיכא למידק למה חלקו מצוה זו לימים חלוקים וקבעו יום מיוחד לפרזים ויום מיוחד לכרכין משא\"כ בשאר המצות ותירץ הר\"ן שמפני שהיהודים היושבים בערי הפרזות והיהודים שבשושן לא נחו מאויביהם ביום א' שהרי היהודים הפרזים נחו בי\"ד והיהודים שבשושן כחו בט\"ו ועשו כל אחד ביום מנוחתו משתה ושמחה לפיכך כשקבעו עליהם י\"ט לדורות קבעוה לכל א' ביום שנח בו והושוו כל הכרכים המוקפין חומה לשושן שמפני שבה היה עיקר הנס וכ\"ת תינח לר' יהושע בן קרחה דאמר דבמוקפין חומה מימות אחשורוש תליא מלתא אבל לדעת תנא דמתניתין דאמר מימות יהושע בן נון הא לא דמי לשושן ומה ראו לקבוע להם יום ט\"ו וי\"ל דהיינו טעמא כדי לחלוק כבוד לא\"י כדאיתא בירוש' ופירוש הענין שכיון שהוצרכו לחלוק בין מוקפין לשאין מוקפין כשם שנחלקה שושן משאר עיירות אילו תלו הדבר מימות אחשורוש היתה א\"י שהיתה חרבה באותם הימים נדונית כפרזים והיה גנאי בדבר ולפיכך תלו הדבר בימות יהושע בן נון כדי שתהא נדונית ככרכים שאע\"ג שעכשיו אין להם חומה כיון שהיתה מוקפת מימות יהושע בן נון הרי דינה כאילו יש בה חומה כדאמרינן בגמרא עכ\"ל וק\"ל על דבריו מדאמרי' בגמרא (ב:) ותנא דידן יליף פרזי פרזי כתיב הכא ע\"כ היהודים הפרזים וכתיב התם לבד מערי הפרזי הרבה מאד מה להלן מימות יהושע בן נון אף כאן מימות יהושע בן נון ופריך אלא שושן דעבדא כמאן ופירש\"י אי ילפינן הך ג\"ש היאך עשו אותם שבשושן בט\"ו הא פרזי הוא ולא ידעינן בה שהוקפה מימות יהושע אמר רבא שאני שושן הואיל ונעשה בה נס ופירש\"י הואיל ונעשה בה נס שנתן להם גם מחר לעשות כדת היום להרוג ב' ימים על כרחן לא נחו עד ט\"ו וכן קבעו לדורות ואם כדברי הר\"ן מאי פריך אלא שושן דעבדא כמאן הא כל עיקרן של מוקפין לא עבדי בט\"ו אלא להדמות לשושן ורבא אמאי קאמר שאני שושן הואיל ונעשה בה נס. דמשמע דאי לאו האי טעמא היו בני שושן קורין בי\"ד ומוקפין כדקיימי קיימי בט\"ו ואילו לדברי הר\"ן אם לא היו בני שושן קורין בט\"ו גם המוקפין לא היו קורין בט\"ו שהרי לא קבעו בט\"ו למוקפין אלא כדי לדמותן לשושן ולפיכך נ\"ל דנהי דטעמא דרבי יהושע בן קרחה הוי כדכתב הר\"ן שקבעו ט\"ו למוקפין כדי לדמותן לשושן וכדאיתא בהדיא בגמרא מ\"ט דרבי יהושע בן קרחה כי שושן מה שושן מוקפת מימות אחשורוש וכו' לתנא דידן לא הוי טעמא משום הכי אלא היינו טעמא כיון דמצוה זו הוקבעה בזמן חרבנה של א\"י ראו חכמים שבאותו הדור לעשות וכר לא\"י בנס זה וכדאמר בפרק בתרא דר\"ה דאית לן למעבד זכר למקדש ולפיכך תקנו שמוקפין חומה מימות יהושע יקראו בט\"ו ושאר העיירות יקראו בי\"ד ואילו לא היו מחלקין ביניהם לא היה לא\"י זכר בנס זה ויש קצת סעד לזה בדברי הרמב\"ם שכתב כל מדינה שהיתה מוקפת חומה מימי יהושע קורין בט\"ו וכל מדינה שלא היתה מוקפת חומה מימי יהושע קורין בי\"ד ושושן הבירה אף על פי שלא היתה מוקפת חומה מימות יהושע קורין בט\"ו שבה היה הנס שנאמר ונוח בט\"ו בו ולמה תלו הדבר בימי יהושע כדי לחלוק כבוד לא\"י שהיתה חרבה כדי שיהו קורין כבני שושן ויחשבו כאילו הן כרכין המוקפים חומה אע\"פ שהן עתה חריבין הואיל והיו מוקפין חומה בימי יהושע קורין בט\"ו ויהיה זכרון לא\"י בנס זה ע\"כ ומאחר שכתב דין המוקפין קודם שכתב דין שושן הבירה משמע דטעמא דמוקפין בט\"ו לא תלו בשושן ומ\"ש כדי שיהיו חורין כבני שושן לאו למימרא דמוקפין תלו בבני שושן אלא הוי כאומר שיהו קורין בט\"ו ומ\"ש ולמה תלו הדבר בימי יהושע ה\"פ למה חלקו מוקפות מימות יהושע משאינן מוקפות והיינו דמסיים בה כדי שיהיה זכרון לא\"י בנס זה ואם איתא שסבת חלוק מוקפין משאינן מוקפין היא מטעם א' וטעם כדי לחלוק כבוד לא\"י אינו אלא לומר למה תלו בימות יהושע ולא בימות אחשורוש מאי ויהיה זכרון לארץ ישראל בנס זה דקאמר","\u0003וכן הכפרים הסמוכים להם אפילו אינם נראים עמהם וכו'\u0004 בפ\"ק דמגילה (ג:) אמר ריב\"ל כרך וכל הסמוך לו וכל הנראה עמו נדון ככרך ועד כמה א\"ר ירמיה כמחמתן לטבריה מיל ובתר הכי תנא סמוך אע\"פ שאינו נראה נראה אע\"פ שאינו סמוך בשלמא נראה אע\"פ שאינו סמוך משכחת לה כגון דיתבא בראש ההר אלא סמוך אע\"פ שאינו נראה היכי משכחת לה א\"ר ירמיה ביושבת בנחל ומשמע דשיעור מיל לא אתמר אלא לסמוך ואינו נראה אבל נראה אפילו רחוק כמה נידון ככרך ויש לתמוה על לשון רבינו שנראה שהוא סובר דשיעור מיל שאמרו קאי גם לנראה אע\"פ שאינו סמוך א\"כ למה הוזכר נראה שאם אין ביניהם יותר ממיל הרי הוא סמוך ואע\"פ שאינו נראה עמו הרי דינו כמוהו ואם הוא רחוק יותר אע\"פ שנראה עמו הא אמרת דאין נדון כמוהו והרמב\"ם כתב כדברי רבינו ותמה עליו הרה\"מ והעלה שעיקר הנוסחא בדבריו היא כרך וכל הנראה עמו וכל הסמוך לו אם אין ביניהם יותר על אלפים הרי זה ככרך וקורין בט\"ו דהשתא אם אין ביניהם לא קאי אלא אסמוך בלבד וזה דבר מוכרח בגמרא עכ\"ל ודוחק ג\"כ לשבש נוסחות רבי' ומיהו אפשר לדחוק ולומר דובלבד שלא יהיו רחוקים יותר ממיל דקאמר לא קאי אלא ארישא דהיינו הסמוכים להם אפילו אינם נראים עמהם אבל אסיפא דהיינו נראים עמהם לא קאי דהא בהדיא קאמר בהו אפי' אינם סמוכים ועי\"ל שהרמב\"ם ורבי' מפרשים דכי בעי ועד כמה לאו אסמוך בעי דסמוך מסתמא סמוך ממש דהיינו בתוך עיבורה של עיר אלא אנראה בעי דאין סברא לומר שאפי' רחוק כמה פרסאות מן הכרך לפי שהוא נראה מן הכרך יהא נידון כמוהו אבל הר\"ן כתב י\"מ דנראה וסמוך דקאמר היינו דמתחשב מתחומי העיר והכי דייק לישנא דקאמר נראה אע\"פ וכו' ולא קאמר רואין אותו מן העיר מיהו הא והא נמי איתא דרואין אותו מן העיר בעינן א\"נ אפשר דכי אמרינן ועד כמה אמר רבי ירמיה כמחמתן לטבריה מיל אכולה מלתא מהדר בין לנראה עמו בין לסמוך ומ\"מ אינו נראה שאם היה רחוק כמה פרסאות מפני שרואין אותו מן הכרך יהא נידון ככרך עכ\"ל והשתא לפי מה שכתב דאפשר דכי יהבינן שיעורא דמיל קאי גם לנראה מוקשה דאם כן נראה עמו למה הוזכר דאם אין ביניהם יותר ממיל אע\"פ שאינו נראה נדון ככרך כמ\"ש וצריך לדחוק ולומר דכי בעי ועד כמה בין אסמוך בין אנראה קאי וכי אמר ר' ירמיה כמחמתן לטבריה מיל קאי אתרוייהו ומיהו הא כדאיתא והא כדאיתא דבאינו נראה משחינן המיל במדת הליכה בקרקע ובנראה דהיינו יושבת בראש ההר לא משחינן המיל בקרקע אלא ע\"י שנותנין החבל מעיר לעיר באויר ואם אין במשך אותו חבל יותר ממיל נדון ככרך דהשתא הוי טובא טפי ממיל במדת קרקע : וביאור דברי הר\"ן כך הם י\"מ דנראה וסמוך דקאמר היינו כשתחשב מתחומי העיר כלומר שכפר זה נחשב מכלל תחום אותו כרך אבל אם אינו נחשב כמתחום אותו כרך אע\"פ שהוא נראה מן הכרך וגם אינו רחוק ממנו מיל אינו נדון ככרך וכשהוא נחשב מתחום אותו כרך אם הוא סמוך דהיינו שהוא בתוך מיל או אם הוא נראה אע\"פ שהוא רחוק ממיל כיון דנחשב מתחומי הכרך נדון ככרך א\"נ אפשר דכי אמרינן ועד כמה אכולה מלתא מהדר וכו' כלומר דגם בנראה עמו בעינן שלא יהא רחוק ממנו יותר ממיל אבל לומר שהוא רחוק כמה פרסאות עד שאינו נחשב מתחומי העיר שאם נראה מהכרך יהא נדון כמוה זה דבר שאינו נרא' לאמרו וזהו שכתב ומ\"מ אינו נראה שאם היה רחוק כמה פרסאות מפני שרואים אותו מן הכרך יהא נדון ככרך:","ומה שכתב רבי' אפילו הכרך אינה מוקפת חומה עתה אם היתה מוקפת בימי יהושע קורין בט\"ו פשוט בפרק קמא דמגילה (ב:) וכבר נתבאר טעמו של דבר שהוא כדי לחלוק כבוד לארץ ישראל:","\u0003וכיון שהיה מוקף אפי' אין בו י' בטלנים וכו'\u0004 קורין בט\"ו שם (ג.) אמר ריב\"ל כרך שאין בו עשרה בטלנים נדון ככפר והכריחו שם התוס' והרא\"ש דלא איירי ריב\"ל במוקף חומה בימי יהושע כסתם כרך האמור בכל מקום לענין מקרא מגילה אלא כשאינו מוקף מימות יהושע איירי והוי כסתם כרכין האמורים בכל התלמוד שהן עיירות גדולות אבל במוקף בימות יהושע בן נון אין צריך עשרה בטלנים וכן נראה שהוא דעת הרמב\"ם ז\"ל וכתב הרה\"מ ומ\"מ שטה אחרת יש בזה דאפילו בכרך המוקף בימות יהושע בעי עשרה בטלנים ואם לאו הרי זה כעיר וזהו דעת הרמב\"ן והרשב\"א ז\"ל ע\"כ ולא נתחוורא שטה זו בעיני הר\"ן ומ\"מ כתב שמה שנהגו עכשיו בא\"י לקרות בט\"ו אע\"פ שברוב המקומות אין שם עשרה בטלנים שיהו בטלנים ממלאכה לעמוד בבית הכנסת אפילו לאותה שטה יש ליישב אותו מנהג דלאו דוקא בטלנים אלא כל שדרים שם י' בני אדם שהולכים בוקר וערב לב\"ה הרי הוא כאילו יש שם י' בטלנים:","ואין קרוי מוקף אא\"כ הוקף חומה תחלה ואח\"כ נתיישבה אבל נתיישבה ואח\"כ הוקף אין קורין אלא בי\"ד שם אמר ריב\"ל כרך שישב ולבסוף הוקף נדון ככפר מ\"ט דכתיב ואיש כי ימכור בית מושב עיר חומה שהוקף ולבסוף ישב ולא שישב ולבסוף הוקף פירוש דמושב נקוד פת\"ח והוא סמוך ומשמעו בית מושב של עיר החומה ומשמע שהחומה היתה שם תחלה וכתב הר\"ן שסובר רש\"י דדוקא לענין בית בבתי ערי חומה הוא דבעינן הוקף ולבסוף ישב אבל לענין מגילה לא ואינו נראה כן מדברי הרי\"ף שהביא בהלכותיו ואף הלשון בעצמו מוכיח שאף לענין מקרא מגילה איתמר דאי לא הול\"ל נדון כבתי ערי חצרים:","ומ\"ש רבי' בשם הר\"מ מרוטנבורק דלא מיקרי ישב ואח\"כ הוקף אלא כשישב תחלה אדעתא שלא להקיפו וכו' והר\"ן כתב וא\"ת כיון דאמרינן דכרך שישב ולבסוף הוקף נדון ככפר עיר המוקפת מימות יהושע בן נון היאך קוראין בא\"י בט\"ו ניחוש דלמא ישבה ולבסוף הוקף י\"ל דישיבת העו\"ג אינה ישיבה ונמצא שבשעה שכבשה יהושע היה בה חומה ולא ישבה עד שנתיישבו בה ישראל וא\"ת והרי בכל הערים המוחפות חומה קורין בט\"ו ואפי' בח\"ל ואי אמרת דישיבת העו\"ג אינה ישיבה הרי הן כאילו לא היו מוקפות חומה מימות יהושע בן נון לפי שלא היה בהם זמן ישיבה כלל י\"ל דכי אמרי' ה\"מ בא\"י משום דכיון דלענין בתי ערי חומה דינן כמוקפין מימות יהושע בן נון מפני שישיבת העו\"ג אינה ישיבה אף לענין קריאת מגילה נדונית כמוקפת חומה אלא דאכתי איכא למידק בעיירות המוקפות חומה שבח\"ל ניחוש דלמא קדמה ישיבתן לחומתן ונמצא שהרי הן כאילו אין להם חומה אלא איכא למימר שהולכין אחר הרוב שעל הרוב קודמת חומתן לישיבתן שכן דרך רוב המדינות מקיפים חומה תחלה ואח\"כ מיישבין אותן עכ\"ל:","כרך שהיא ספק אם הוקף בימי יהושע אם לא קורין בי\"ד ובט\"ו וכ\"כ הרמב\"ם ז\"ל וטעמו מדאמרי' בפ\"ק דמגילה (ה:) חזקיה קרי בטברי' בי\"ד ובט\"ו מספקא ליה אי מוקפת חומה מימות יהושע בן נון הוא אי לא רב אסי קרי מגילה בהוצל בי\"ד ובט\"ו מספקא ליה אי מוקפת חומה מימות יהושע אי לא אבל הר\"ן כתב שהורו הגאונים דעיירות המסופקות אם הם מוקפות חומה מימות יהושע הולכין בהן אחר רוב עיירות שמא אינן מוקפות חומה מימות יהושע וקורין בי\"ד ועוד שאפילו תאמר שהוא ספק שקול הו\"ל ספק של דבריהם לקולא ונמצא פטורות בשניהם ומבטל ממנו בודאי מקרא מגילה לפיכך קורא בראשון ופטור בשני ודאמרינן בגמרא אטברי' והוצל שהיו קורין בי\"ד ובט\"ו במדת חסידות היו נוהגין כן משום ספקא דטבריה דתליא במגניא ומכסיא ובהוצל מפני שהיו נחלקין בה בקבלתן זה אומר מוקפת וזה אומר אינה מוקפת והיו קורין בה בלא ברכה דספק דדבריהם לא בעי ברוכי כדאיתא בפרק במה מדליקין (שבת כג.) אלא שראוי לברך בי\"ד מפני שהולכים אחר רוב העולם וה\"ה הזכיר סברא זו וכתב עוד שי\"מ שלא חשו לספק זה אלא בא\"י שהיו ידועות בשעת התקנה מחמת דין בית בבתי ערי חומה אבל בח\"ל מעיקרא כך התקינו שכל שהוא ספק לא יקראו אלא בי\"ד וי\"מ שהיו סוברים ונוהגים כדברי רבינו וכן ראוי לעשות וכן נהגו העולם לעשות כדברי הרמב\"ם ז\"ל וראיתי לה\"ר יוסף אביו ז\"ל שהיה קורא תגר על המנהג שנוהגים בכל עיר מוקפת חומה לקרות בי\"ד וט\"ו ודע\"כ לא קאמר הרמב\"ם שקורין בב' הימים אלא בכרך שהוא ספק דהיינו שקצתם אומרים מוקפת היא מימות יהושע וקצתם אומרים אינה מוקפת מימות יהושע אבל כל שאין יודעים בה כלל לא מיקרי ספק והיה מביא ראיה ממ\"ש הרמב\"ם בפ\"ח מהלכות שגגות אינו חיוב באשם תלוי עד שיהיה שם איסור קבוע כיצד אכל חלב וספק אם היתה כזית או פחות מכזית או שהיתה לפניו חתיכת חלב וחתיכת שומן ואכל אחד מהם ואינו יודע אי זה מהם אכל (אבל) אם היתה לפניו חתיכה אחת ספק שהיא חלב ספק שהיא שומן ואכלה פטור שהרי אין כאן איסור הרי דלא מיקרי ספק להתחייב אשם תלוי עד שיהיה שם איסור קבוע ומינה נשמע לענין קריאת מגילה דסתם עיר המוקפת חומה ואין יודעין בה אם היא מוקפת חומה מימות יהושע אם לאו דלא באה לכלל ספק כלל ואין קורין בה אלא בי\"ד בלבד שהוא זמן קריאה לרוב העולם ול\"נ שאין הנידון דומה לראיה דא\"כ אפילו אם נחלקו בקבלתם זה אומר מוקפת חומה וזה אומר אינה מוקפת חומה לא יקראו בי\"ד ובט\"ו דכל כה\"ג לא מחייב אשם תלוי ומבואר מדברי הרמב\"ם אבל אם היתה לפניו חתיכה אחת ספק חלב ספח שומן ואכלה פטור וא\"א לומר כן דא\"כ הא דכתב הרמב\"ם עיר שהיא ספק קורין בה בשני הימים היכי משכחת לה ועוד דמההיא דאשם תלוי ליכא למיגמר דשאני התם דכתיב מכל מצות וקרינן מצות בלשון רבים ויש אם למקרא כדאיתא בכריתות (יז:) והלכך לא ילפינן מינה דהתם לאו משום דלא הוי ספק הוא אלא משום דגזירת התורה הוא דלא ליחייב עד דליקבוע איסור ומיהו יש לקיים דבריו ממ\"ש הר\"ן בשם הגאונים דטבריה והוצל שהיו קורין בהם בי\"ד ובט\"ו במדת חסידות היו נוהגים כן משום ספיקא דטבריה דתלי במגניא ומכסיא בהוצל מפני שהיו נחלקים בקבלתה זה אומר מוקפת וזה אומר אינה מוקפת משמע מדבריו דדוקא בכה\"ג הוא דהויא ספק וקורין בי\"ד ובט\"ו לדברי הגאונים ממדת חסידות ולדברי הרמב\"ם מדינא אבל כל שאין מחלוקת בקבלתן אלא שאין אנו יודעים אם היא מוקפת מימות יהושע אם לאו לא נכנסה לכלל ספק ואין קורין בה אלא בי\"ד לדברי הכל והעולם שנוהגים לקרות בי\"ד ובט\"ו בכל העיירות המוקפות מן הסתם נראה שסוברים שכיון שאנו רואין אותה שהיא מוקפת באה לכלל ספק אם הוא מוקפת מימות יהושע והיא בכלל מ\"ש הרמב\"ם עיר שהוא ספק קורין בה בשני הימים ובליליהן אבל אין מברכין עליה אלא בי\"ד הואיל והוא זמן קריאה לרוב העולם אח\"כ בא לידי ספר אשכנזי וכתב בו קשה לי עיירות דידן מנא לן שלא היו מוקפות חומה למה אין אנו קורין נמי בט\"ו מספק תשובה כל כרכים דידן קורים בי\"ד אי לאו דקים לן שמוקפות מימות יהושע בן נון וספיקא דטבריה משום דמספקא ליה לחזקיה אי היקף חומה חשיב אי לא כדאיתא התם כך פי' רבינו משה הגאון בתשובה עכ\"ל וכן מצאתי כתוב בתשובות בשם גאון :","בן עיר שהלך לכרך ובן כרך שהלך לעיר אם כשהלך היה דעתו לשוב לביתו בליל י\"ד קודם שיאור היום וכו' בפרק ב' דמגילה (יט.) תנן בן עיר שהלך לכרך ובן כרך שהלך לעיר אם עתיד לחזור למקומו קורא כמקומו ואם לאו קורא עמהם ובגמרא (שם) אמר רבא לא שאנו אלא שעתיד לחזור בליל י\"ד אבל אינו עתיד לחזור בליל י\"ד קורא עמהם דכתיב על כן היהודים הפרזים היושבים בערי הפרזות מכדי כתיב היהודים הפרזים ל\"ל למכתב היושבים בערי הפרזות הא קמשמע לן דפרוז בן יומו נקרא פרוז ומדפרוז בן יומו נקרא פרוז מוקף בן יומו נקרא מוקף וכתב הרא\"ש פירש\"י דרבא קאי אבן כרך שהלך לעיר דאם אין עתיד לחזור בליל י\"ד אלא ישאר בעיר עד אור היום חל עליו חובת קריאת היום והרי הוא כבן עיר והוא פרוז יום וה\"ה בן עיר שהלך לכרך ואינו עתיד לצאת משם בלילי ט\"ו שהוא ככרך כשהאיר היום הו\"ל מוקף יום וקורא בליל ט\"ו וביום ט\"ו אפילו יחזור לעירו יקרא ביום ט\"ו בעירו אבל אם הוא ידוע שעתיד לצאת בליל ט\"ו קורא בי\"ד כדין בני עירו ולא רצה לפרש מילתיה דרבא גם בבן עיר שהלך לכרך דלא מסתברא למימר שאם ישנו בכרך ביום י\"ד שחלה עליו חובת קריאת מוקפין וישאר שם יום ט\"ו ויקרא עמהם או אף אם יחזור לעיר יקרא בט\"ו כיון דעדיין לא הגיע זמן קריאת מוקפין למה תחול עליו חובת קריאתן זהו סברת רש\"י מיהו לישנא דתלמודא משמע דרבא קאי אכולה מתני' וכמו שמועיל לבן כרך להיות כבן עיר כשעמד שם ליל י\"ד ומקצת היום שהוא זמן קריאתה של בני העיר וחלה עליו חובת קריאתן כמו כן מועיל לבן עיר שהלך לכרך ועמד שם מקצת יום י\"ד כיון שבזמן חיוב קריאת בני מקומו אינו עמהם נסתלק מעליו חובת קריאת אנשי מקומו ונכלל עם בני הכרך להתחייב בזמן קריאתם וקרינן ביה מוקף בן יומו כיון שהוא בכרך בזמן קריאת בני עירו ונסתלק מעליו חובת מקומו הקוראים ביום י\"ד וקרינן ביה מוקף בן יומו ואף אם יחזור לעירו יקרא ביום ט\"ו והרי\"ף כתב ל\"ש אלא שעתיד לחזור בליל י\"ד ונתעכב ולא חזר ואשמעי' שהדבר תלוי בכוונתו בשעה שיצא מביתו אם היה בדעתו להיות ליל י\"ד בביתו הרי הוא כמקומו אף אם נתעכב שמה אבל אם אינו עתיד לחזור בליל י\"ד קורא עמהם עכ\"ל הרא\"ש ז\"ל ורבינו סתם דבריו כדעת הרא\"ש ותחלה אמר הדין דרך כלל שאם דעתו לחזור בי\"ד קאי אכולה מתניתין ואח\"כ בא לפרש היכי קאי לכל חלוקה וחלוקה וזהו שכתב כיצד בן כרך שהלך לעיר וכו' לכאורה הוה משמע לפרושי דרבא קאי ארישא לומר דבן עיר שהלך לכרך אזלינן בתר יום י\"ד שהוא יום קריאת אנשי מקומו ומינה נשמע לבן כרך שהלך לעיר דאזלינן בתר יום ט\"ו שהוא יום קריאת בני מקומו ופרוז בן יומו פירוש בן כרך שביום קריאת בני מקומו דעתו להתעכב בעיר מיקרי פרוז וקורא בי\"ד וכן פירוש מוקף בן יומו אלא דמשום דבגמרא אמרי' דמדפרוז בן יומו מיקרי פרוז ילפינן מוקף בן יומו מיקרי מוקף אלמא מבן כרך שהלך לעיר ילפינן לבן עיר שהלך לכרך וא\"כ היכי אפשר דרבא אמר מלתיה על בן עיר שהלך לכרך ומיניה יליף לבן כרך שהלך לעיר שמע מיניה דליתיה להאי פירושא ואפשר דמש\"ה כתב רבינו בתחלה בן עיר שהלך לכרך וכו' ובן כרך שהלך לעיר וכי אתא לפרושינהו נקטינהו איפכא שכתב כיצד בן כרך שהלך לעיר וכן בן עיר שהלך לכרך כלומר עיקר מלתא בבן כרך שהלך לעיר כתיב ומיניה ילפינן לבן עיר שהלך לכך ומשום הכי א\"א לפרושי דבן עיר שהלך לכרך אזלינן בתר יום י\"ד ובבן כרך שהלך לעיר אזלינן בתר יום ט\"ו דא\"כ רבא כי אמרה למלתיה על בן כרך שהלך לעיר הו\"ל למימרא ומיהו מתניתין דאקדמה בן עיר שהלך לכרך לבן כרך שהלך לעיר ל\"ק מידי דאיכא למימר אורחא דמלתא נקט שדרך בני עיירות ללכת לכרכים יותר מבני כרכים לעיירות אבל מרבא דמייתי דרשה דקרא קשה ואפשר לומר עוד דבן כרך שהלך לעיר כל הפוסקים שוים בה דאזלינן בתר יום י\"ד ומש\"ה נקטה רבינו ברישא ובתר הכי כתב בן כרך שהלך לעיר (בן עיר שהלך לכרך) דלדעת הרא\"ש אזלינן ביה נמי בתר יום י\"ד: ולפי פי' הרא\"ש פי' דמוקף בן יומו הוי מוקף לא דמי לפי' דפרוז בן יומו הוי פרוז דמוקף בן יומו פירושו שאיבד יום עירו שהוא יום י\"ד דהיינו שהיה דעתו להתעכב שם ביום י\"ד מקרי מוקף ונסתלק מעליו חובת אנשי מקומו ופרוז בן יומו פירושו שנתעכב בעיר יום י\"ד שהוא יום קריאת המקום שהלך שם חל עליו חובת יום קריאת מקום זה ודברי הרמב\"ם סתומים ופירשם ה\"ה כדברי רש\"י וכ\"פ הר\"ן ג\"כ דברי הרי\"ף שכתב וזהו לשונו ל\"ש אלא שעתיד לחזור בליל י\"ד אבן כרך שהלך לעיר בלחוד קאי וה\"ק שאם עתיד לחזור למקומו בליל י\"ד קודם זמן השחרית א\"צ לקרות עמהם כיון שלא יעכב כאן ביום י\"ד א\"נ אפי' נתעכב כיון שנתעכב שלא מדעתו וכ\"ד הרי\"ף שכתב ונתעכב ולא חזר אבל אם אין דעתו לחזור בליל י\"ד כלומר שלא היה בדעתו לחזור למקומו באותו לילה אלא להתעכב כאן ביום י\"ד ונתעכב קורא עמהם ביום י\"ד שנעשה פרוז בן יומו ומיהו אם חזר למקומו בליל ט\"ו קורא עמהם וגדולה מזו אמרו בירושלמי בן עיר שעקר דירתו ליל ט\"ו נתחייב כאן וכאן ומדפרוז בן יומו נקרא פרוז מוקף בן יומו נקרא מוקף כלומר דבבן עיר שהלך לכרך נמי אמרינן שאם היה דעתו בליל י\"ד לחזור למקומו בליל ט\"ו לא יהא נעשה מוקף בן יומו וקורא באותה העיר עצמה בי\"ד בלילה וביום י\"ד במקומו אבל אם דעתו בליל י\"ד להתעכב שם ליל ט\"ו וקצת מן היום א\"צ לקרות בליל י\"ד וביום י\"ד כמקומו אלא ממתין עד ט\"ו וקורא עמהם דכי היכי דפרוז בן יומו נקרא פרוז ה\"נ מוקף בן יומו נקרא מוקף ובן יומו היינו בליל ט\"ו וקצת מן היום עכ\"ל:","פורים שחל להיות בשבת בריש מגילה (ד.) א\"ר יהושע בן לוי פורים שחל להיות בשבת שואלין ודורשין בעניינו של יום:","\u0003ומ\"ש כגון ט\"ו לבני כרכין וכו'\u0004 כן כתב שם הרי\"ף והרא\"ש ז\"ל והוא בירושל' פ\"ק דמגילה משום דאם י\"ד בשבת יבא י\"ה בע\"ש:","ומ\"ש מקדימין לקרותה בע\"ש (ב.) שם במשנה ומצאתי כתב שמנהג ירושלים לגבות מעות מתנות עניים ולחלקם בו ביום ואין אומרים בו על הניסים ואין מוציאין בו ס\"ת ויום שבת שלפניו שהיה ח' לאדר קוראים פרשת זכור ומפטירין פקדתי ובשבת יום ט\"ו שהוא יום פורים אומרים על הניסים ומוציאין בו שני ס\"ת וקורים בשני ויבא עמלק ותמהני למה לא יאמר על הניסים ביום ששי שבו קורין המגילה : וכתב הר\"ן בפ\"ק דמגילה על מה שכתב הרי\"ף שם הירושלמי סעודת פורים מאחרין ולא מקדימין כשחל י\"ד להיות בע\"ש שעיירות גדולות ומוקפות חומה קורין בו ביום שאין מוקפין חומה עושין סעודה עד אחד בשבת וגרסינן בירושלמי ויעשו אותה בשבת א\"ל לעשות אותם ימי משתה כתיב את ששמחתו תלויה בבית דין יצא זה ששמחתו בידי שמים דשמחת (שבת) אינה מתקנת מרדכי אלא בידי שמים:","\u0003שדרו ממתיבתא היכא דנפיק בשייר' או נפיק בספינה וכו'\u0004 כ\"כ בספר הרוקח וז\"ל אדם שהולך בספינה או במדבר אם יכול למצוא מגילה יקח עמו ואם לאו יקרא בי\"א בי\"ב בי\"ג (שהתינוקות) [שהכפרים] קורין ולא יברך לפניה ולאחריה והמרדכי כ' בריש מגילה תניא בתוספתא פ\"ק דמגילה היוצא בשיירא והמפרש בספינה קורין בי\"ד וכ\"כ בה\"ג ויש מרבותינו אומרים שאם אין בידם מגילה מוטב שיקדימו ויקראו ממה שלא יקראו כלל וכ\"נ בעיני דגרסי' בירושלמי פ\"ק דמגילה תניא כל החודש כשר לקריאת מגילה שנאמר והחודש אשר נהפך להם מיגון לשמחה אמר רבי חלבו ובלבד עד ט\"ו הא דתימא כל החדש כשר לקריאת מגילה בשביל הולכי דרכים שאין בידם מגילה אבל הסעודה אין עושין אלא בט\"ו ואפי' קודם י\"א נ\"ל מדלא אמר רבי חלבו בלבד מי\"א עד ט\"ו וההיא דתוספתא בדאפשר לו לקרות עמהם ראבי\"ה עכ\"ל וכ\"כ בהג\"א בשם א\"ז שאם יודע שלא יהיה לו מגילה בי\"ד חייב לקרותה קודם שיצא לדרך אפי' מתחלת החודש והר\"ן כתב בפ\"ק וז\"ל כתוב בספר המאור תניא בברייתא המפרש לים והיוצא לדרך קורין בי\"ג כ' עליה ה\"ר אפרים דהא דרב ודרב אסי דאית להו קריאה שלא בזמנה כגון שחל י\"ד בשבת לבני עיירות או ט\"ו לבני כרכים אבל בי\"א וי\"ב ליכא קריאה כלל דהא בטלי להו וברייתא זו לא הזכירה אלא בי\"ג בלבד אלו דברי הרב ז\"ל ואני אומר הוא הדין לי\"א וי\"ב וכדאי הוא ר\"ע סתימתאה לסמוך עליו בשעת הדחק כגון מפרש לים ויוצא בשיירה שמאחר שהתירו לו בי\"ג ה\"ה לי\"ב וי\"א ובירושל' גרסי' רבי אבא בשם ר' יהודה כל שאמרו ידחה ממקומו ובלבד בעשרה ותו גרסינן בירושל' מפרשי ימים והולכי מדברות קורין כדרכן וברייתא פליג עליה במשמע' א\"נ י\"ל הא דאפשר ליה הא דלא אפשר ליה עכ\"ל וכ\"כ בא\"ח בשם הרא\"ה דבי\"א וי\"ב וי\"ג יכול לקרותה ע\"כ ונ\"ל דההיא דירושלמי דכל החודש כשר לקריאת מגילה לא ס\"ל לתלמודא דידן מדלא מייתי לה ומ\"מ בשעת הדחק שא\"א בענין אחר כלל כדאי הוא הירושלמי לסמוך עליו ומיהו כל שקרא שלא בזמנה אם נזדמנה לו מגילה בזמנה חוזר וקורא כדין בן כפר שהקדים ליום הכניסה שאם היה בעיר בי\"ד חוזר וקורא עמהם : כתב שבלי הלקט בן עיר שהיה בא בספינה או בדרך ולא היה עמו מגילה ונזדמנה לו בט\"ו קורא אותה בט\"ו והה\"ר יעקב הביא ראיה לדבריו מדגרסינן בירושלמי כל החודש כשר למגילה ובלבד עד ט\"ו ואם יש מי שמסתפק בדבר יקרא בלא ברכה ע\"כ:","\u0003וקורין אותה בלילה וחוזרין וקורין אותה ביום מימרא דריב\"ל בפ\"ק (ד.) וכבר כתבה רבי' בסי' תרפ\"ז:\u0004 ","ומ\"ש ושל לילה זמנה כל הלילה ושל יום זמנה כל היום פרק שני (כ.) תנן כל היום כשר לקריאת מגיל' זה הכלל דבר שמצותו ביום כשר כל היום ודבר שמצותו בלילה כשר כל הליל':","\u0003ומ\"ש מהנץ החמה עד סוף היום ואם קראה משעלה עמוד השחר יצא משנה שם:\u0004 קראוה באדר ראשון ואח\"כ בא לעבר השנה קורין אותה באדר שני משנה פרק קמא (ו:) ודייק מינה בגמרא הא לענין סדר פרשיותיה זה וזה שוין כלומר שאם קראו הד' פרשיות בראשון א\"צ לחזור ולקרותן בשני: \u0005ב\"ה מני מתני' לא ת\"ק ולא ר\"א בר\"י ולא רשב\"ג ומסיק דמתני' רשב\"ג היא דאמר אפי' סדר פרשיות אי קרי בראשון קרי בשני ופסק רי\"ו הלכה כרשב\"ג ולכן הנוסחא האמיתית כדברי רבי' וכן הפרשיות שעשו באדר א' צריך לחזור ולעשותן בשני ולאפוקי מספרים דגרסי איפכא ומ\"מ יש לתמוה וכו':\u0006 ויש לתמוה על רבינו למה הוצרך לכתוב זה דכיון שאנו קובעין ע\"פ החשבון לא שייך למימר קראו את המגילה באדר א' ואח\"כ ראו לעבר השנה ואפשר שכתב כן ללמדנו שאם טעו בני העיר וחשבו שהיתה שנה פשוטה וקראו המגילה והפרשיות באדר הראשון ואח\"כ נודע להם שהיא מעוברת חוזרין לקרות המגילה באדר השני ואינם צריכים לחזור לקרות הפרשיות :"],["\u0003מגילה נקראת בי\"א וכו'\u0004 משנה רפ\"ק דמגיל' ופירש\"י דהיינו מפני בני הכפרים שמתכנסים לעיירות למשפט ביום ב' וה' וצריכין שיקראו להם א' מבני העיר וכו' והתוס' בפ\"ק דיבמות הקשו דא\"כ הו\"ל ב\"ד א' בעיר א' פלג מורין כב\"ש ופלג מורין כב\"ה ואיכא משום לא תתגודדו ופי' בשם רבינו חיים כהן דלא כפירש\"י אלא בעירם היו מתכנסים בב' וה' והיו קורין ולא בעיירות והרא\"ש לשם פי' כפירש\"י דהיו מתכנסין בעיירות אלא שבני הכפרים היו קורין לעצמן ומה שלא היו קורין בכפר שלהן לפי שלא היו מתקבצין יחד אלא בעיירות וא\"כ הו\"ל כשני בתי דינין בעיר אחת ועוד תירץ שאפי' היה קורא להן בן עיר בעיירות ליכא משום לא תתגודדו וכו' וכדכתב גם הר\"ן בפ\"ק דמגלה עיין עליהן ועיין עוד בסמ\"ג הלכות מגלה ורבינו לא הזכיר מזה כלום כיון דהאידנא אינה נקראת אלא בי\"ד וליכא קושיא כלל: כתב ב\"י איכא למידק למה חלקו מצוה זו לימים חלוקים וקבעו יום מיוחד לפרזים ויום מיוחד לכרכים משא\"כ בשאר מצות ותירץ הר\"ן שמפני וכו' וק\"ל על דבריו מדאמרי' וכו' ואילו לדברי הר\"ן אם לא היו בני שושן קורין בט\"ו גם המוקפין לא היו קורין בט\"ו וכו' וסוף דבריו דלא כפי' הר\"ן דקבעו ט\"ו למוקפין להדמות לשושן ואי לאו טעמא דשאני שושן הואיל ונעשה בה נס היו אנשי שושן קורין בי\"ד ומוקפין בט\"ו ותימה דלפי זה הדרא קשיא לדוכתא למה חילקו מצוה זו לימים חלוקים משא\"כ בשאר מצות דכדי לעשות זכר לא\"י בנס אינו מספיק לשיעשוה בימים חלוקים שהרי בשאר מצות לא חשו לזה כלל לכך ודאי העיקר כדכתב הר\"ן שמפני שההנחה מאויביהם היו בימים חלוקים והוצרכו לחלק בין פרזים שאינן מוקפים ובין כרכים המוקפין בחרו יותר לתלות הדבר בימות יהושע כדי לחלוק כבוד לא\"י וסמכום על היקש דפרזי פרזי והמקשה שהקשה ואמר אלא שושן דעבדא כמאן עבדא הכי קאמר דמאחר דשושן דעבדא בט\"ו ליכא למימר דמכח הך ג\"ש אתיא לה א\"כ ה\"ה שאר המוקפין ליכא למילף מהך ג\"ש כיון דעיקרא דשאר מוקפין בט\"ו אינן אלא כדי לדמותן לשושן ומשני רבא שאני שושן וכו' כלומר לעולם הך ג\"ש ילפותא גמורה הוי לשאר מוקפין ואעפ\"י דלא שייכא הך ג\"ש לגבי שושן לית לן בה דכיון דבשושן ע\"כ בט\"ו הוא כיון דנעשה בה הנס הוה ליה עדיף טפי מג\"ש ושפיר נוכל ללמוד שאר מוקפין בהך ג\"ש אע\"ג דלא שייכא בשושן גופיה כנ\"ל:","\u0003ומ\"ש וכן הכפרים הסמוכים להם וכו'\u0004 בפ\"ק אריב\"ל כרך וכל הסמוך לו וכל הנראה עמו נדון ככרך ועד כמה א\"ר ירמיה כמחמתן לטבריא מיל וכ\"כ הרי\"ף גם הרמב\"ם כתב כלשון הזה ומשמע דלעולם שיעורו עד מיל אבל יותר על מיל אין קורין בט\"ו אלא בי\"ד בין נראה ובין אינו נראה וכ\"כ הר\"ן בפירוש וכבר תמה הרב המגיד על זה ואמר דאם כן נראה עמו למה הוזכר אלא האי עד כמה הכי קאמר עד כמה חשיב ליה סמוך וכן פי' רש\"י ז\"ל אבל בנראה עמו אפילו ביותר ממיל נדון ככרך אבל לפע\"ד יראה דיש ליישב הקושיא שהקשה הרב המגיד אדברי הרי\"ף והרמב\"ם והוא דודאי האי עד כמה אכולה מילתא קא מהדר דבין נראה ובין אינו נראה אינו קורא בחמשה עשר אלא כשהוא עד מיל אבל יותר ממיל אינו קורא בחמשה עשר ולא קשיא כלל למה הוזכר נראה עמו דאיכא למימר להכי תני ליה כי היכי דלא תימא דוקא בסמוך ואינו נראה שיעורו עד מיל אבל בנראה עמו אפי' ביותר ממיל להכי תני וכל הסמוך לו וכל הנראה עמו לאורויי לן דבנראה עמו דינו שוה לסמוך לו ודוקא עד מיל אין טפי לא וה\"ק כרך וכל הסמוך לו ואינו נראה וכן כל הנראה עמו דינם שוה דנידון ככרך ועד מיל קשה דבסוגיא קאמר תנא סמוך אע\"פ שאינו נראה נראה אע\"פ שאינו סמוך הרי מבואר דבנראה לא בעינן סמוך ודוחק לפרש דהרי\"ף והרמב\"ם סוברים דהברייתא פליגא אדריב\"ל ופסקו כריב\"ל דהא פשטא דברייתא משמע אינה אלא לפרש ועוד שהרי הרא\"ש הביא ברייתא זו בפסקיו וכן רבי' כתב בלשונה ואפי' הכי משמע מדבריו דאפילו בנראה עד מיל אין טפי לא ואפשר לומר דברייתא דתנא נראה אעפ\"י שאינו סמוך כדי נקטה ולאו דוקא דעיקרה אינה אלא לפרש דלא בעינן סמוך ונראה אלא אפי' סמוך ואינו נראה אבל סמוך מיהא בעינן אפי' נראה וברייתא לא דייקא בסיפא ואגב דנקט ברישא סמוך אף על פי שאינו נראה נקט בסיפא נראה אף על פי שאינו סמוך וכהאי גוונא איכא טובא בתלמודא ולפי דהברייתא לא דייקא בסיפא לכך דקדקו הרי\"ף והרמב\"ם והשמיטוה מלשונם. ועוד נראה לי לפי לשון רבינו דסבירא ליה לפרש דעד כמה אנראה ואינו סמוך קאי ואמר עד מיל טפי לא אבל בסמוך ואינו נראה צריך שיהא סמוך תוך מיל ומשום הכי אמר רבינו ובלבד שלא יהו רחוקים יותר ממיל דמשמע דאנראה עמה אפי' הם רחוקים קאי ואמר ובלבד שלא יהו רחוקים יותר ממיל דאילו הוה קאי אסמוכים הו\"ל למימר ובלבד שיהו סמוכים עד מיל אלא ודאי דאנראה קאי ואמר שלא יהו רחוקים יותר ממיל אבל מיל גופיה שפיר דמי אבל בסמוך ואינו נראה צריך שיהו סמוכין תוך מיל אבל מיל גופיה אין קורין בחמשה עשר ובספר צידה לדרך כתב בהדיא בזה הלשון וכן כפרים הסמוכים לה אפי' אינן נראין או שנראין עמה אפי' הם רחוקים והוא שלא יהו יותר רחוקים ממיל עכ\"ל ועוד נראה לומר דסמוך לא מיקרי אלא סמוך לעיר ממש וכן מבואר במשנה פרק המביא איזהו קרפף כל שסמוך לעיר דברי ר\"י ר' יוסי אומר כל שנכנסין לו בפותחת ואפי' בתוך תחום השבת ופי' רש\"י סמוך לעיר ממש והר\"ן בשם הרשב\"א כתב לשם דתוך עיבורה הוי סמוך ולפ\"ז נמי עד כמה אנראה ואינו סמוך קאי וכן עיקר וכן בפרק אין צדין דמסיק הא בגנה הסמוכה הא בגנה שאינה סמוכה פירשו בו דבתוך עיבורה הוי סמוך ונראה דטעמו מאחר דקי\"ל דשיעור מיל הוה לבד עיבורה של עיר א\"כ כל היכא דקאמר סמוך תוך עיבורה קאמר כך נראה לי וכבר האריך בזה הב\"י: ואפילו הכרך אינה מוקפת חומה עתה וכו' שם ברייתא אשר לא חומה אעפ\"י שאין לו עכשיו והיה לו קודם לכן פירוש מדכתיב לא באל\"ף:","\u0003וכיון שהיתה מוקף אפילו אין בו עשרה בטלנים וכו'\u0004 שם אריב\"ל כרך שאין בו עשרה בטלנים נדון ככפר והכריחו שם התוספות והרא\"ש דלא איירי ריב\"ל בכרך המוקף מימות יהושע אלא בעיירות גדולות קאמר שאין בו עשרה בטלנים נדון ככפר ונקראת ביום הכניסה ולא קשיא למה לא כתב רבינו אותו הדין דאיכא למימר כיון דהאידנא כל כפר בעולם קורין בארבעה עשר כמ\"ש בתחלת סימן זה א\"כ לא נפקא לן מידי בהאי דינא אבל הרמב\"ם ז\"ל כתבו כי כותב כל דין ודין אעפ\"י שאינו נוהג עכשיו:","ואין קרוי מוקף אלא א\"כ הוקף חומה תחלה שם מימרא דריב\"ל מ\"ט דכתיב ואיש כי ימכור בית מושב עיר חומה ופי' הר\"ן דמושב נקוד פתח והוא סמוך ומשמעו בית מושב של עיר החומה ומשמע שהחומה היתה תחלה עכ\"ל ואפשר לומר דמושב קרא יתירא לגמרי הוא דהו\"ל למיכתב בית עיר חומה שפירושו בית בתוך עיר המוקפת חומה וכתב בית מושב משמעו דנתיישבה העיר בתוך החומה והיינו שהוקף החומה תחלה ולבסוף ישב נ\"ל ואעפ\"י דמקרא זה לענין בתי ערי חומה כתיב ילפינן מקרא מגלה מבתי ערי חומה כ\"כ התוספות והרא\"ש ודלא כפירוש רש\"י:","\u0003כרך שהוא ספק וכו'\u0004 בפ\"ק דמגילה חזקיה קרי בטבריה בי\"ד ובט\"ו מספקא ליה אי מוקפת חומה מימות יהושע בן נון וכו' והרי\"ף והרא\"ש השמיטו דין זה אבל הרמב\"ם כתבו בפ\"א ואחריו נמשך רבינו ועיין בדברי הב\"י נתבאר שורש שני הסברות ולענין ברכה כתב אחי ה\"ר יחיאל מסתברא שיקראו בלא ברכה בב' הימים וכו' כתב מהר\"ש לוריא וז\"ל ותימה ולמה אין מברכין עליה בב' הימים כשאר ספיקא דיומא בי\"ט לענין ברכה ודוחק לומר ולחלק בין י\"ט דאורייתא למקרא מגלה דרבנן בשלמא בלא ספק הוקף איכא להקשות אמאי לא נקראת המגילה בארבע עשר ובחמשה עשר משום ספיקא דיומא כשופר ולולב דכבר תירץ המרדכי משום דכתיב ולא יעבור מאחר שאנן בקיאין בקביעא דירחא אבל בספק ממש לא שייך לומר ולא יעבור דשמא היום עיקר זמנה ולמה לנו למיחש לספק ברכה לבטלה יותר מספיקא דיומא לענין י\"ט ויש לחלק דהתם קדושת היום גורם לחייבו אף בברכה מכח ספיקא שאם לא תנהוג בו קדושת היום אף לענין ברכה א\"כ אתה עושה חול ועוד קדושת המועדות תלוי בב\"ד והם כך קבלו עליהם וק\"ל עכ\"ל:","\u0003בין עיר שהלך לכרך כו'\u0004 בפ\"ב דמגילה משנה וגמרא ועל פי פירושו של הרא\"ש שלא כפירש\"י וכבר האריך בו הב\"י ומבואר בדברי הרא\"ש דבן כרך אינו נחשב כבני העיר אא\"כ שהיה דעתו לעמוד שם ליל י\"ד ומקצת יום י\"ד שהוא זמן קריאתן של בני העיר אבל אם לא היה דעתו לעמוד שם מקצת יום י\"ד אף על פי שהיה דעתו לעמוד שם בליל י\"ד קורא כבני מקומו ורבינו לא הזכיר זה בביאור בדין בן כרך אלא בדין בן עיר ואפשר מאחר שכתב תחלה דרך כלל אם כשהלך היה דעתו לשוב לביתו בליל י\"ד קודם שיאור היום כו' אכולה מתניתין שוב לא חש לבאר בפרט והדבר פשוט דמ\"ש אם כשהלך היה דעתו לשוב לביתו בליל י\"ד קודם שיאור היום היינו לומר שדעתו לעקור רגליו מן העיר קודם שיאיר היום אף עפ\"י שלא ישוב לביתו כל יום י\"ד דעיקר הדין תלוי במה שאינו עומד בעיר עד שיאור היום:","\u0003פורים שחל להיות בשבת וכו'\u0004 כתב הב\"י בשם הירושל' שהסעודה עושין באחד בשבת שהוא יום י\"ו וכן פסק בש\"ע אבל ה\"ר לוי חביב בתשובתו האריך בראיות שהסעודה היא בשבת ועשה כן מעשה בירושלים וגם המשלוח מנות זמנם הכי כי המנות הם מהסעודה וכתב שם עוד שהקריאה בתורה ויבא עמלק הוא בשבת ומפטירין פקדתי ואע\"ג שמפטירין בה בשבת הקודם בפרשת זכור אין חשש בזה כלל וע\"ש בסימן ל\"ב:","\u0003שדרו ממתיבתא כו'\u0004 טעם סברות אלו נתבאר בספר בית יוסף ע\"ש:","\u0003וקורין אותו בלילה וכו'\u0004 מימרא דריב\"ל בפ\"ק ומפיק לה מדכתיב במזמור למנצח על אילת השחר שדרשוהו רז\"ל על אסתר אלהי אקרא יומם ולא תענה ולילה ולא דומיה לי וקריאת המגילה זכר לנס שהיו צועקים בימי צרתם יום ולילה:","\u0003קראוה באדר ראשון כו'\u0004 משנה פ\"ק ויש נוסחאות מוטעות בספרי רבינו שכתוב בה דהפרשיות שעשו באדר הראשון אין צריך לחזור לעשותן בשני וכן היתה הנוסחאות לפני הב\"י ומפני זה כתב שפסק זה הוא מהסוגיא שאמרה הא לענין סדר הפרשיות זה וזה שוין כלומר שאין צריך לחזור ולעשותן בשני ואין פסק זה אמת דהא אסיקנא בגמרא א\"ר יוחנן הלכה כר' שמעון ב\"ג שאמר משום ר' יוסי ומבואר בסוגיא דרשב\"ג ס\"ל דצריך לחזור ולעשותן בשני וכ\"כ הר\"ן והסמ\"ג אלא כך היה הנוסחא האמיתית בספרי רבינו וכן הפרשיות שעשו באדר הא' צריך לחזור ולעשותן בשני שזה עולה כפי המסקנא. שוב ראיתי בסוף ספר בדק הבית להב\"י שכתב באורך והגיה הטעות שכתב בספרו ב\"י ע\"ש וז\"ל הרא\"ש קראו את המגלה באדר הא' ונתעברה השנה קורין אותה באדר הב' אין בין אדר הא' לאדר הב' אלא מקרא מגלה ומתנות לאביונים נראה לומר דסיפא ארישא קיימא היכא דקראו המגילה בי\"ד ונתעברה השנה אז אין בין אדר ראשון לשני אלא מ\"מ ומתנות לאביונים דאעפ\"י דעשאוה בראשון צריכין לחזור ולעשותן בשני אבל כל שאר דברים שעשאוה בראשון ושוב נתעברה השנה אין צריכין לחזור ולעשותן בשני דאילו נתעברה השנה קודם אדר הראשון אז הוי אדר כמו שבט ואהא קאמר תלמודא הא לענין פרשיות זה וזה שוין כלומר שאם קראו באדר הראשון כל הד' פרשיות ושוב ראו שיש צורך לעבר השנה א\"צ לחזור ולעשותן בשני אבל לא מיסתבר כלל שבכל השנים המעוברות יקראו הפרשיות בב' אדרים ושוין בהספד ובתענית שאסורין בזה ובזה פירוש אם קראו המגלה בי\"ד ובו ביום עברו השנה אסור בהספד ובתענית אבל בשאר שנה מעוברת נ\"ל שמותר בהספד ובתענית כנ\"ל לפרש השטה ומוקמינא מתניתין כרשב\"ג וה\"ק אין בין י\"ד של אדר הראשוי לי\"ד של אדר השני אלא מקרא מגלה ומתנות לאביונים הא להספד ותענית שניהם שוין וכן הלכה עכ\"ל הרא\"ש והנה הרואה דברים אלו ישפוט בתחלה הדעת שהרא\"ש פוסק שהפרשיות אין צריך לחזור ולעשותן בשני כמו שכתב בפירוש אולי מכאן בא הטעות בספרי רבינו לגרוס שם שאין צריך לחזור ולעשותן בשני והא ודאי ליתא כדפרישית ואף דברי הרא\"ש ישרים וברורים למוצאי דעת שזה שכתב הרא\"ש ואהא קאמר תלמודא הא לענין פרשיות זה וזה שוין כלומר שא\"צ לחזור ולעשותן בשני לא כתב כן ע\"פ המסקנא אלא כל כונתו לאוכוחי מינה לפרש השטה כולה להיכא שקראוה באדר הראשון דאהא קאמר תלמודא בתחלת הסוגיא הא לענין פרשיות זה וזה שוין שאילו היינו מפרשין הסוגיא בכל השנים המעוברות ואם כן בעל כרחך היינו צריכין לפרש מאי דקאמר הא לענין פרשיות זה וזה שוין שיקראו הפרשיות בב' אדרים וזה ודאי אין סברא כלל וממילא נמי מאי דקתני בברייתא ושוין בהספד ותענית שאסורין בזה ובזה פירושו נמי בכה\"ג היכא דקראו בי\"ד ובו ביום וכו' אבל בשאר שנים מעוברות נראה שמותר בהספד ובתענית באדר הא' כי היכי שאין קורין בו הפרשיות וכן כל שאר דברים אינו נוהג בו דהו\"ל אז אדר הראשון כמו שבט כל זה כתב לפרש השיטה ואח\"כ כתב המסקנא דמוקמי מתניתין כרשב\"ג וה\"ק אין בין י\"ד וכו' אבל בסדר הפרשיות דלא שייכי לי\"ד לא איירי מתניתין כלל ואה\"נ דאי עשאום באדר ראשון צריך לחזור ולעשותן בשני כרשב\"ג אלא דלא איירי בהכי וכך הלכה כדפסק ר' יוחנן זו היא דעת הרא\"ש וכל מה שכתב תחלה לפרש השיטה אינו אלא לומר דסיפא ארישא קיימא וממילא לפי המסקנא נמי בשאר שנים מעוברות אינו אסור בהספד ובתענית באדר הא' ואצ\"ל לענין הפרשיות וכל זה ברור למוצאי דעת:"]],["\u0010y0\u0011הכל חייבין בקריאת מגילה כהנים לוים וישראלים \u0010y1\u0011עבדים חלל ממזר נתין טומטום ואנדרוגינוס \u0010y2\u0011ומחנכין נמי הקטן בה \u0010c0\u0011\u0010y3\u0011ונשים נמי חייבות בקריאתה \u0010y4\u0011ופירש\"י שמוציאות לאנשים ידי חובתן ובה\"ג כ' אע\"ג שחייבות במקרא מגילה אינן מוציאות לאנשים \u0010c1\u0011\u0010y5\u0011וב\"ה ז\"ל כ' מסתברא כי היכי דנשים מזמנות לעצמן ואינן מצטרפות לברכת הזימון ה\"נ אינן מצטרפות לי' לכתחלה \u0010c2\u0011\u0010y6\u0011ואנדרוגינוס מוציא מינו ולא שאינו מינו \u0010c3\u0011וטומטום ומי שחציו עבד וחציו בן חורין אפי' מינו אינו מוציא: \u0010c4\u0011\u0010c5\u0011\u0010y7\u0011חש\"ו אפי' הגיע לחינוך אינן מוציאין אחרים ידי חובתם ור\"י מכשיר בקטן כיון שהגיע לחינוך וב\"ה ז\"ל פסק כוותיה \u0010y8\u0011וא\"א ז\"ל הביא המשנה כצורתה וא\"כ דעתו לפסוק כת\"ק וכ\"כ בה\"ג \u0010y9\u0011ירוש' ריב\"ל הוה מכניש בני ביתיה וקרי קמיהון מכאן נוהגין במקצת מקומות להביא קטנים וקטנות לשמוע מקרא מגילה:",["הכל חייבים בקריאת מגילה כהנים לוים וישראלים ברייתא בריש ערכין (ד:) ופריך התם פשיטא אי הני לא מחייבי מאן מחייב ומשני לא צריכא ליבטל מעבודתן כדאמר רב יהודה אמר שמואל כהנים בעבודתן ולוים בדוכנן וישראל במעמדן מבטלין מעבודתן ובאים לשמוע מקרא מגילה:","\u0003ומ\"ש רבינו עבדים חלל וממזר וכו'\u0004 אפשר דכל הני איתנייהו בתוס' ומשום דנקט כהנים לוים וישראלים איצטריך למינקט הני כי היכי דלא תימא כהנים לוים וישראלים דוקא הוא דמחייבי: ומ\"ש ועבדים בעבדים משוחררים מיירי וכדכתבו הרמב\"ם וסמ\"ג דאילו עבדים שמלו וטבלו לשם עבדות מדין נשים שהזכיר אח\"כ הוא נלמד דכל מצות שהאשה חייבת בהן העבד נמי חייב בהן ואע\"פ שאין חיוב האשה במצוה אלא מטעם שאף הן היו באותו הנס הא מההוא טעמא איכא לחיובי עבדים שגם הם היו בספק סכנה כיון דמולים היו ומיהו לדברי המפרשים דאף הן היו באותו הנס היינו לומר שע\"י אשה נעשה הנס אפשר דאין ללמוד מנשים לעבדים וכיון דהוי מצות עשה שהזמן גרמא עבדים פטורים:","\u0003ומ\"ש ומחנכין נמי הקטן בה כ\"כ הרמב\"ם ופשוט הוא:\u0004 ","ומ\"ש ונשים נמי חייבות בקריאתה בריש מגילה (ד.) אמר ריב\"ל נשים חייבות במקרא מגילה שאף הן היו באותו הנס:","ומ\"ש ופירש\"י שמוציאות לאנשים י\"ח בריש ערכין כתב כן אהא דקאמר התם הכל כשרים לקרות את המגילה תנא לאתויי מאי לאתויי נשים וטעמו משום דעיקר הנס היה ע\"י אשה וכתב הרב המגיד שכן נראה שהוא דעת הרמב\"ם:","ומ\"ש רבינו בשם בה\"ג כתבוהו התוס' בריש ערכין ובריש מגילה והרא\"ש כ' בריש מגילה דברי רש\"י ודברי ה\"ג ולא הכריע ומ\"מ דבריו נוטים כדעת בה\"ג אבל הר\"ן כתב על דברי בה\"ג ואין זה מחוור אלא שראוי לחוש להחמיר והמרדכי כתב שראבי\"ה פסק כבה\"ג וראיה מתוספתא דמגילה נשים ועבדים וקטנים פטורים מלקרות המגילה ובה\"ג גרס הכי אריב\"ל נשים חייבות במשמע מגילה והכי איתא בירושלמי בפ\"ב אמר בר קפרא צריך לקרותה בפני נשים וקטנים שאף הן היו באותו הנס בספק וכו' ועתה לא תקשה לריב\"ל מהתוס' דהא נשים חייבות בשמיעה ולא בקריאה וההיא דערכין י\"ל לפי פירוש ה\"ג דהא דקאמר נשים כשירות במקרא מגילה פי' להוציא נשים כמותן ונראה לראבי\"ה דנשים מברכות על משמע מגילה ואפי' אי קרי לעצמן מספקא לראבי\"ה אי קטן מצי לאפוקי נשים דשמא אע\"ג דתרוייהו פטורים מקריאה וחייבים בשמיעה דלמא אין חיובן בשוה כדאיתא בפרק מי שהחשיך (שבת קנג.) גבי חרש שוטה וקטן הי מינייהו עדיף עכ\"ל: וב\"ה כתב כי היכי דנשים מזמנות לעצמן ואינן מצטרפות לברכת הזימון ה\"נ אינן מצטרפות לעשרה לכתחילה הר\"ן בפרק שני דמגילה אמתניתין דהכל כשרים לקרות את המגילה חוץ מחרש שוטה וקטן כתב סברא זו וכתב עליה דא\"א דהתם הוא שאינן מוציאות אנשים בברכתן אבל כאן היאך אפשר שמוציאות אנשים ידי קריאה ואין מצטרפות עמהם למנין אלא ודאי מצטרפות:","ואנדרוגינוס מוציא מינו ולא שאינו מינו וטומטום ומי שחציו עבד וחציו בן חורין אפילו מינו אינו מוציא תוספתא כתבה הרא\"ש בפ\"ק דמגילה וכבר נתבאר בסי' תקפ\"ט לענין תקיעת שופר ואפשר שמשם למד לענין מקרא מגילה וכבר נתבאר שם דחציו עבד וחציו בן חורין אפילו עצמו אינו מוציא ולא חשש רבינו לכתוב כאן לפי שסמך על מ\"ש שם ומיהו אם הוא סובר דעבדים שמלו וטבלו לשם עבדות חייבין במקרא מגילה כשם שנשים חייבות אתי שפיר שלא הזכיר כאן דאינו מוציא את עצמו וגם בתוספתא שהביא הרא\"ש לא הוזכר משום דכיון דלא שייך למימר ביה לא אתי צד עבדות ומפיק צד חירות דהא צד עבדות נמי חיובי מחייב מוציא הוא את עצמו וא\"ת מהאי טעמא יוציא ג\"כ את מינו וי\"ל אע\"פ שמשני צדדיו הוא חייב מ\"מ מאחר שהוא מורכב מעבדות וחירות כיון דאין צד עבדות ניכרת לעצמו וצד חירות לעצמו אינו ראוי להוציא את אחרים אפי' אם אותם אחרים מורכבים ג\"כ מעבדות וחירות וע\"כ צ\"ל טעם זה לדעת רש\"י שסובר דנשים מוציאות את האנשים ואפ\"ה טומטום אינו מוציא מינו וטעמא משום דטפי עדיף כשהמוציא הוא ודאי אשה והשומע זכר מכשהמוציא הוא טומטום אפי' אם השומע נקיבה ואפי' אם השומע טומטום דסד\"א כיון דתרוייהו חד מינא נינהו נפקי אהדדי ידי חובתן קמ\"ל דלא משום דבעינן שהמוציא את אחרים י\"ח יהא ניכר אם הוא זכר או אם היא נקיבה ולא תיקשי מאנדרוגינוס שמוציא את מינו דהתם שאני שכבר הוא ניכר שהוא בריה בפני עצמו:","חרש שוטה וקטן אפי' הגיע לחינוך אינן מוציאין אחרים י\"ח ורבי יהודה מכשיר בקטן משנה בפ\"ב דמגילה (יט:) הכל כשרים לקרות את המגילה חוץ מחרש שוטה וקטן ור' יהודה מכשיר בקטן וכתבו התוס' דע\"כ בקטן שהגיע לחינוך מיירי דאי בשלא הגיע לחינוך מ\"ט דר\"י וא\"ת אי הכי מאי טעמייהו דרבנן דכיון דמקרא מגילה דרבנן ליתי דרבנן ונפיק בדרבנן כדאמרינן בפרק מי שמתו (ברכות ך:) גבי בן מברך לאביו אע\"פ שהוא קטן ויוצא בברכתו ומוקי לה התם בדאכל שיעורא דרבנן ואתי הקטן שחיובו דרבנן ומפיק ליה וה\"נ נימא הכי כבר תירצו דלא דמי דקריאת מגילה ליכא חיובא אפי' בגדולים אלא מדרבנן וקטן אינו מחוייב אלא מדרבנן בשאר מצות ובגדול ליכא אלא חד דרבנן במגילה ולא אתי תרי דרבנן ומפיק חד דרבנן:","ומ\"ש רבינו שדעת הרא\"ש לפסוק כת\"ק כך נראה שהוא דעת הרי\"ף והרמב\"ם ואהא דתנן חוץ מחרש כתב הר\"ן האי חרש דהכא אפי' במדבר ואינו שומע ואע\"ג דסתם חרש בכ\"מ שאינו שומע ואינו מדבר אבל מדבר ואינו שומע או שומע ואינו מדבר ה\"ז כפקחים לכל דבריהם כדאיתא בפרק מי שאחזו (גיטין עא.) אפ\"ה חרש המדבר ואינו שומע לא חזי למקרא דאתיא לה כר\"י דאמר בפ' היה קורא (ברכות טו.) הקורא את שמע ולא השמיע לאזנו לא יצא וכיון דאיהו לא נפיק גופיה לאחריני נמי לא מפיק עכ\"ל ודבריו מבוארים בגמרא דקאמר מאן תנא חרש דיעבד נמי לא אמר רב מתנה ר' יוסי היא דתנן הקורא את שמע ולא השמיע לאזנו יצא ר' יוסי אומר לא יצא ולפ\"ז לא קיימא לן כי האי מתני' דהא בפ' היה קורא איפסיקא הלכתא שם בגמרא דלא כרבי יוסי וא\"כ חרש המדבר ואינו שומע מוציא את אחרים ידי חובתם ודלא כמתני' ולפיכך יש לתמוה על הרמב\"ם שפסק בפ\"א מהלכות מגילה שאם היה הקורא חרש השומע ממנו לא יצא וכן יש לתמוה על הרי\"ף והרא\"ש שכתבו המשנה כצורתה ומשמע דס\"ל דהלכה היא ואפשר לדחוק ולומר שהם סוברים דאע\"ג דתלמודא מוקי מתניתין כרבי יוסי היינו אי אמרינן כי היכי דפליגי בק\"ש פליגי במגילה אבל כיון דחזינן דרבי בפרק היה קורא גבי ק\"ש סתם ר' הקורא את שמע ולא השמיע לאזנו יצא רבי יוסי אומר לא יצא דמשמע דסבר דיצא ומש\"ה קתני לה בסתם ורבי יוסי דפליג הוה יחידאה וגבי מגילה קתני סתם לא יצא ולא כתב שום חולק בדבר אית לן למימר דס\"ל דמגילה שאני דבעינא בה פירסומי ניסא וכל שלא השמיע לאזנו ליכא פירסומי ניסא ומ\"מ הדבר דחוק כיון דחזינן דתלמודא משמע ליה דמגילה וק\"ש שוים הם מנין לנו לחלק ביניהן ובא\"ח כתוב שהרמב\"ם לא הוציא מכלל המוציאין אלא שוטה וקטן לבד ולא הוציא חרש נראה שנוסחאות ספר הרמב\"ם שבידו מוחלקת משלנו: כתב הר\"ש בר צמח בתשובה בירושל' אמרינן אמתני' לית כאן חרש ולפי גמרא דידן מיירי במדבר ואינו שומע ואתיא כמ\"ד צריך שישמיע לאזניו ולא דומיא דשוטה וקטן הוא דאינהו אפי' בדיעבד קריאתם פסולה אבל חרש המדבר ואינו שומע יוצאין אחרים בקריאתו אבל בשופר אינו מוציא וטעמא משום דבשמיעה תליא מילתא דהא מברכים על השמיעה וכיון שאינו שומע אינו מחוייב בדבר ולא מפיק אבל במגילה דבקריאה תליא מלתא כיון דיודע לקרות בר חיוב הוא אבל שומע ואינו מדבר יוצאים בתקיעתו עכ\"ל: וכתב בא\"ח השומע מגילה ממי שהוא מודר הנאה ממנו יצא דומיא דשופר: וכתב עו\"ש מקום שאין מנין אם יש שם ד' או ה' אחד מהם יודע המגילה ואחרים אינם יודעים אחד פוטר את כולם אבל אם כולם יודעים יקראו אותה לעצמם עכ\"ל:","\u0003ירושלמי ריב\"ל הוה מכניש בני ביתיה וקרי קמיהון בפרק בתרא דמגילה:\u0004 "],["\u0003הכל חייבין וכו'\u0004 תוספתא הכל חייבין בקריאת מגילה כהנים לוים וישראלים ועבדים משוחררים חללים נתינים ממזרים סריס אדם סריס חמה פצוע דכא וכרות שפכה כולן חייבין ומוציאין את הרבים ידי חובתן אנדרוגינוס מוציא את מינו ולא את שאינו מינו טומטום אינו מוציא לא את מינו ולא את שאינו מינו מי שחציו עבד וחציו ב\"ח אינו מוציא לא את מינו ולא את שאינו מינו נשים ועבדים וקטנים פטורין ואינן מוציאין את הרבים י\"ח א\"ר יהודה קטן הייתי וקריתיה לפני ר' טרפון בלוד וקלסני כו' ובריש ערכין פריך הכל חייבין במ\"מ כהנים לוים וישראלים פשיטא לא צריכא לבטל מעבודתם וכו' ומאי דצריך למינקט עבדים משוחררים וכל הני נראה בעיני דמדכתיב משפחה ומשפחה ולמדינן מיניה להביא משפחות כהונה ולויה סד\"א דוקא אותן משפחות שכשרין ומיוחסין המשיאין לכהונה אותן מוציאין הרבים ידי חובתן אבל עבדים משוחררים וחללים דפסולין לכהונה ונתינים ודכוותייהו דפסולין אף לקהל סד\"א דלא קמ\"ל דכולן מוציאין את הרבים י\"ח:","ונשים נמי חייבין בקריאתם בריש ערכין הכל חייבין במקרא מגלה והכל כשרין לקרות את המגלה לאתויי מאי לאתויי נשים ופי' רש\"י כשרות לקרותה ולהוציא זכרים י\"ח והתוס' כתבו שם דבה\"ג לא פסק כן ומביא ראייה מן התוספתא ולדידיה צריך לפרש מאי דאמרו בערכין דנשים כשרות להוציא אחרים י\"ח היינו נשים כמותן אבל אנשים לא וכ\"כ הרא\"ש בפ\"ק דמגילה ולדעת רש\"י צריך לומר דסיפא דתוספתא משבשתא היא ואיכא למידק למה כתב רבינו עבדים בסתם ובתוספתא תני עבדים משוחררים וכן ברמב\"ם ובסמ\"ג נקטו עבדים משוחררים ואפשר שכיון שרבינו כתב אח\"כ מחלוקת הגאונים בנשים אם מוציאות לאנשים לפיכך סתם דבריו בעבדים דהשתא לפירש\"י נשים מוציאות לאנשים וה\"ה עבדים שמלו וטבלו לשם עבדות ולבה\"ג דנשים אינן מוציאות לאנשים וה\"ה עבדים נמי לא אא\"כ עבדים משוחררים ודעת הסמ'\"ג נשים אין מוציאות לאנשים כמבואר בדבריו לפיכך כ' עבדים משוחררים אבל ברמב\"ם צריך עיון דכיון דמשמע מדבריו דנשים מוציאין לאנשים וכמו שפירש ה' המגיד א\"כ מ\"ש עבדים שאינן משוחררים דלא ואפשר דכיון דבקריאת התורה בעינן עשרה משוחררים משום ונקדשתי בתוך בני ישראל כל דבר שבקדושה לא יהא פחות מעשרה כדאיתא פ' ב' דמגילה ה\"ה נמי בקריאת המגילה דמיא בהא לקריאת התורה ואף על פי שהקילו במגילה יותר מבתורה לענין אשה שמוציאה לאיש במגיל' מה שאין כן בתורה שאני התם דכיון דאפי' בקריאת התורה היתה אשה עולה למנין אלא שאמרו חכמים אשה לא תקרא בתורה מפני כבוד הצבור כדתניא התם הלכך במגלה לא חשו לכך מאחר שאף הם היו באותו הנס אבל עבדים שאינן משוחררים שאינן כלל מישראל אינן כשרין לקרות כנ\"ל ליישב דעת הרמב\"ם והעומדים בשטתו. והא פשיטא דלדברי הכל עבדים עצמן אף על פי שאינן משוחרים חייבין לקרותה:","\u0003וב\"ה כתב מסתברא וכו'\u0004 נראה מבואר דב\"ה סובר כרש\"י דנשים מוציאות לאנשים אלא שהחמיר בצירוף ונראה דס\"ל לב\"ה כהראב\"ד שהביא רבינו לעיל בסי' קפ\"ו דנשים מוציאות לאנשים בברכת המזון ואפי' הכי קי\"ל דמזמנות לעצמן ואינן מצטרפים עם האנשים בזימון דהיינו בשני אנשים ואשה אחת ומשכחת לה דאשה מוציאה לאנשים בב\"ה היכא דאיכא ג' אנשים ואשה אחת דהאנשים מצטרפים לזימון והאשה יכולה להוציא לאנשים בברכת המזון דעיקר קפידא בצירוף משום פריצותא וה\"נ בקריאת המגלה אף על פי דאשה מוציאה לאנשים אפי' הכי אינן מצטרפין לעשרה לכתחלה משום פריצותא אלא בעינן עשרה אנשים בלא נשים והר\"ן ז\"ל השיג על דברי ב\"ה ואמר דשאני התם שאינה מוציאה לאנשים בברכתם וכו' ונראה שהוא סובר עיקר כאינך גאונים דאשה אינה מוציאה לאנשים בברכת המזון ואין זה השגה כיון דיש דעות שמוציאין לאנשים כדפרי':","אנדרוגינוס מוציא מינו ולא את שאינו מינו בתוספתא הנזכר והיינו דסבירא ליה דבריה בפני עצמו הוא עיין במ\"ש לעיל בסי' תקפ\"ט בהלכות שופר:","\u0003וטומטום וכו'\u0004 איכא למידק לפירש\"י דנשים מוציאות לאנשים א\"כ טומטום אמאי לא והסמ\"ג הוכיח מכאן דנשים אינן מוציאות לאנשים ונראה לי דלפירש\"י האי תוספתא דלאו כהלכתא ואה\"נ דטומטום מוציא אפי' לזכרים דבעל כרחך צריך לומר לפירוש רש\"י דסיפא דתוספתא דתני דנשים פטורות דלאו כהלכתא כמו שכתבתי למעלה ורבי' לפי שתופס לחומרא בפלוגתא דרבואתא לכך כתב התוספתא דטומטום אינו מוציא אפי' מינו ומהאי טעמא נמי מי שחציו עבד וחציו בן חורין אפי' מינו אינו מוציא דכיון דיש בו צד עבדות שהוא כדין נשים אינו מוציא לצד חירות של אחרים ומכל מקום לעצמו הוא מוציא מאחר שצד עבדות שבו מחוייב בקריאת מגלה ואינו דומה לשופר שצד עבדות שבו פטור לגמרי הילכך אפילו לעצמו אינו מוציא ודו\"ק:","\u0003חש\"ו אפילו הגיע לחינוך וכו'\u0004 בסוף פרק שני דמגלה תנן הכל כשרים לקרות המגלה חוץ מחרש שוטה וקטן ור\"י מכשיר בקטן ואיכא תרי אוקימתי בגמרא לאוקימתא קמייתא מתניתין ר' יוסי היא דאמר הקורא את שמע ולא השמיע לאזניו לא יצא והלכך חרש הקורא את המגלה כיון שלא השמיע לאזנו לאו בר חיובא הוא ואינו מוציא אחרים ידי חובתן כדין שוטה וקטן ואוקימתא בתרייתא למסקנא דגמרא דקאמר השתא דאתית להכי אפילו תימא ר' יהודא וכו' מתני' כולה ר\"י היא דאמר הקורא את שמע ולא השמיע לאזנו יצא וחסורי מחסרא והכי קתני הכל כשרים לקרות את המגלה חוץ מחרש שוטה וקטן שלא הגיע לחינוך אבל קטן שהגיע לחינוך אפילו לכתחלה מוציא אחרים ידי חובתן שר' יהודה מכשיר בקטן ולפי זה חרש שוטה וקטן לאו חד דינא אית להו דחרש לכתחלה לא אבל דיעבד שפיר דמי דסבירא ליה לא השמיע לאזנו יצא אבל שוטה וקטן אפילו דיעבד לא יצא והתוספות פי' דלאוקימתא קמייתא הא דסבירא ליה לת\"ק דקטן אפי' דיעבד לא היינו אפי' הגיע לחינוך דמדר\"י דמכשיר בקטן אפילו לכתחלה דמיירי בהגיע לחינוך נשמע לת\"ק דאפילו בהגיע לחינוך לא ע\"ש והנה מ\"ש רבינו וב\"ה פסק כותיה נראה טעמו דסבירא ליה דאוקימתא דברייתא עיקר דהיא מסקנא דתלמודא וכולה ר' יהודה היא וליכא מאן דפליג עליה במתניתין אבל הרא\"ש שהביא המשנה כצורתה נראה ממנו דסבירא ליה כאוקימתא קמייתא שפסק כתנא קמא דהוא סתם ואף על פי שאחריו מחלוקת ורבי יהודא אין זה סתם ואחר כך מחלוקת אלא האי סתם חשיב כרבים לגבי יחיד כמו שפירשו התוספות בריש ביצה ובפרק החולץ (יבמות דף מ\"ד) בד\"ה ודילמא אלא שקשה לפי זה חרש אפילו דיעבד לא וכרבי יוסי וזה הפך המסקנא דפרק היה קורא הקורא את שמע ולא השמיע לאזנו יצא ואפשר לומר דאע\"ג דמתניתין ר' יוסי היא ואנן לא קי\"ל כר' יוסי בהקורא את שמע ולא השמיע לאזנו מ\"מ במגילה בחרש הקורא קיי\"ל כר' יוסי ובכה\"ג אית לן למימר נראין דברי ר\"י בקורא את שמע וסתם לן כוותיה ונראין דברי ר' יוסי בחרש הקורא במגלה וסתם לן כותיה והיינו טעמא דהקורא שמע אע\"ג דלא השמיע לאזנו מ\"מ בר חיובא הוא כיון שהיה אפשר לו להשמיע לאזנו אם היה רוצה אבל חרש הקורא המגלה כיון דלאו בר שמיעה הוא כל עיקר לאו בר חיובא הוא ואינו מוציא אחרים ידי חובתו ולפ\"ז מי שאינו חרש וסותם את אזניו אע\"ג דאינו שומע מוציא אחרים י\"ח כיון דבר חיובא הוא וז\"ל הרמב\"ם א' הקורא וא' השומע מן הקורא יצא י\"ח והוא שישמע מפי מי שהוא חייב בקריאתה לפיכך אם היה הקורא חרש או קטן או שוטה השומע ממנו לא יצא עכ\"ל הנה דתלי ליה האי דינא במאי שאינו בר חיובא וכדפי' וכה\"ג קי\"ל לענין הגדת עדות מפי כתבם דשאני אלם שאינו ראוי להגיד כדכתבו התוס' בשם ר\"ת בפ' ד' אחין כל זה יראה לדעת הרא\"ש כפי מה שהביא רבינו שדעתו לפסוק כת\"ק וכדעת בה\"ג והרמב\"ם אכן דעת הרי\"ף ז\"ל אינו כן שאע\"פ שגם הוא הביא המשנה כצורתה מ\"מ בפרק היה קורא הביא מחלוקת ר\"י ור' יהודא בק\"ש בלא השמיע לאזנו ואח\"כ הביא דברי רב יוסף מחלוקת בק\"ש אבל בשאר מצות ד\"ה יצא דתניא לא יברך אדם ברהמ\"ז בלבו ואם בירך יצא דהשתא מאחר דקיי\"ל כרב יוסף בע\"כ אית לן למימר דמתני' דהכל כשרים לקרות את המגלה חוץ מחש\"ו פירושא דהא כדאיתא והא כדאיתא חרש לכתחלה הוא דלא הא דיעבד שפיר דמי שוטה וקטן דיעבד נמי לא והכי מוכחת הסוגיא התם דלרב יוסף בק\"ש בלחוד הוא דפליג ר' יוסי ואמר דלא יצא אפילו בדיעבד אבל כל שאר המצות לפחות בדיעבד יצא וכך פי' בעל המאור לדעת הרי\"ף ז\"ל והרמב\"ם ז\"ל לא חלק עליו ע\"ש פרק היה קורא ובזה מתיישב מה שהביא הרי\"ף דברי רב יוסף דלכאורה כיון דהלכתא כר' יהודה דאפי' בק\"ש יצא א\"כ לא היה צריך להביא דברי רב יוסף כמו שהקשה ה\"ר יונה לשם אבל למאי שכתבתי אתי שפיר דמדהביא דרב יוסף שמעינן פירושא דמתניתין דהכל כשרין לקרות את המגילה שהביא הרב ז\"ל בהלכותיו בצורתה פ\"ב דמגילה ולפי דעת הרי\"ף מתניתין לאו כולה כרבי יהודה היא דמאי דדחיק תלמודא לאוקמי מתניתין כולה כר' יהודה וחסורי מחסרא הוא היינו משום דקיי\"ל כר' יהודא בק\"ש ולא השמיע לאזנו יצא הילכך דחקינן לאוקומא סתמא דמתניתין אליבא דהילכתא כדכתבו התוס' בפרק היה קורא ובפ\"ב דמגילה וכיון דלרב יוסף בשאר מצות ד\"ה דיצא א\"כ סתמא דמתני' בחרש הקורא המגלה דלכתחלה לא אבל דיעבד יצא ד\"ה היא ולא פליגי אלא בקטן ובהגיע לחינוך ורבי יהודה מכשיר בקטן ולית הילכתא כוותיה וכך פסק בעל המאור בפרק היה קורא והב\"י נמי הביא ספר אורחות חיים שכתב בשם הרמב\"ם דוקא שוטה וקטן הוא דאינו מוציא אחרים י\"ח וכן יראה עיקר ואפשר דאף דעת הרא\"ש כך היא והילכך נקטינן דחרש מוציא אחרים י\"ח דיעבד וקטן אפי' הגיע לחנוך אינו מוציא אפי' דיעבד נ\"ל:"]],["\u0010c0\u0011\u0010y0\u0011הקורא המגילה עומד או יושב יצא משמע בדיעבד אבל לכתחלה לא יקרא יושב ובירושלמי קאמר דאפילו לכתחלה \u0010c1\u0011והרמב\"ם ז\"ל כתב אבל לא יקרא לכתחלה יושב בצבור מפני כבוד הצבור \u0010c2\u0011\u0010y1\u0011ואפי' שנים ואפי' עשרה יכולין לקרותה ביחד \u0010c3\u0011\u0010y2\u0011וצריך לקרותה כולה \u0010c4\u0011\u0010y3\u0011ומתוך הכתב ואם קראה ע\"פ לא יצא \u0010y4\u0011הלכך צריך שתהא כתובה כולה לפניו \u0010c5\u0011\u0010y5\u0011ודוקא לכתחלה אבל דיעבד אם השמיט בה הסופר תיבות אפי' עד חציה וקראה הקורא על פה יצא אבל ביותר מחציה אפילו הן כתובות אלא שהם מטושטשות ואין רישומן ניכר פסולה: \u0010y6\u0011קראה סירוגין פי' שפסק ושהה בה ואח\"כ חזר למקום שפסק אפילו שהה כדי לגמור את כולה יצא : קראה סירוסין פירוש שקרא פסוק הראשון ודילג השני וקרא שלישי ואח\"כ חזר וקרא הב' לא יצא דהוה ליה למפרע והקורא למפרע לא יצא \u0010c6\u0011\u0010y7\u0011הלכך אם דילג הקורא פסוק לא יקרא לפניו ויחזור ויקרא הפסוק שדילג אלא יתחיל מהפסוק שדילג ויקרא משם ואילך \u0010y8\u0011מגילה נקראת בכל לשון ובלבד שיבין אותו הלשון ושתהא כתובה באותו לשון אבל אם אינו מבין בלשון שקורא בו או שאינה כתובה באותו הלשון לא יצא \u0010y9\u0011ובלשון הקודש הכל יוצאים בו אע\"פ שאין מבינים בו \u0010y10\u0011ור\"ע ז\"ל כתב שלשון יוני ג\"כ כשר לכל וכ\"כ הרמב\"ם ז\"ל וב\"ה ואין דעת רי\"ף ז\"ל כן ולזה הסכים א\"א הרא\"ש ז\"ל. \u0010c7\u0011\u0010y11\u0011קראה מתנמנם פירוש נים ולא נים תיר ולא תיר יצא: \u0010y12\u0011היה כותב שקורא פסוק וכותבו יצא ובלבד שתהא כתובה כולה לפניו \u0010c8\u0011וכן אם היה מגיהה ודורשה שקורא פסוק ודורשו יצא \u0010y13\u0011והוא שיכוין לקרותה כראוי ולא כמי שקורא להגיה ולא יפסיק בה בענינים אחרים כשדורשה \u0010y14\u0011וצריך שיכוין הקורא לצאת בקריאתו וגם להוציא לכל השומעים וגם צריך שיכוין השומע לצאת \u0010y15\u0011והא דבעינן שיכוין הקורא על השומע בפרט להוציאו היינו דוקא יחיד הקורא אבל ש\"צ מסתמא דעתו על הכל דתנן היה עובר אחורי בה\"כ ושמע קול מגילה אם כיון לבו יצא: \u0010y16\u0011ירושלמי אין מדקדקין בטעיותיה ר' יצחק בר אבא ור\"ח הוו יתבו קמיה דרב חד קרי יהודים וחד קרי יהודיים ולא הדר חד מנהון \u0010y17\u0011וי\"מ דוקא בטעות כי האי שהלשון והענין אחד אבל טעות אחר לא שא\"כ לא קראה כולה \u0010c9\u0011\u0010y18\u0011וצ\"ל עשרת בני המן בנשימה אחת \u0010y19\u0011ירושלמי צריך לאומרם בנפיחה אחת ועשרת עמהם: \u0010c10\u0011\u0010y20\u0011לרבי נתן ז\"ל הקורא מגילת אסתר בקהל צריך לסדרה כאחד מפני שהיא איגרת אבל בנשימה אחת א\"צ אלא עשרת בני המן ועשרת בלבד הלכך אם מפסיק בין פסוק לפסוק הרשות בידו ושיעורו בין פסוק לפסוק ובין באמצע הפסוק כדי נשימה לבד: \u0010y21\u0011ירושלמי צריך שיאמר ארור המן ברוך מרדכי ארורה זרש ברוכה אסתר ארורים כל הרשעים ברוכים כל הצדיקים א\"ר פנחס וצריך שיאמר וגם חרבונה זכור לטוב \u0010c11\u0011\u0010y22\u0011כתב רב האיי ז\"ל מנהג דחזי לן מאן דקרי לה למגילה פושט וקורא כאיגרת אבל כס\"ת לא חזי לן ורב נטרונאי ז\"ל כתב הוו יודעין שבב' ישיבות שבבית רבינו שבבבל ובכ\"מ ישראל קורין וכורכין כס\"ת ונוהגים בספרד ובאשכנז וצרפת כרב האיי: \u0010c12\u0011\u0010y23\u0011מגילה בזמנה שהוא בי\"ד שהוא עיקר זמנה קורין אותה אפי' ביחיד לרי\"ף ור\"ת כתב אפי' לחזר אחר י' א\"צ אלא לכתחלה קורין אותה ביחיד \u0010c13\u0011ובה\"ג פסק ודוקא בעשרה \u0010c14\u0011ור\"ע ז\"ל כתב צריך לחזר אחר עשרה ואם אי אפשר בעשרה אז קורין אותה ביחיד ולזה הסכים א\"א ז\"ל :",["הקורא את המגילה עומד או יושב יצא ר\"פ (כא:) וכתב הר\"ן דיצא לאו דוקא דאפי' לכתחילה נמי:","ומ\"ש רבינו אפי' שנים ואפי' י' יכולין לקרותה ביחד משנה וברייתא שם ואף ע\"ג דבתורה אין קורא אלא א' מגילה שאני דכיון דחביבא להו יהבי דעתייהו ומשתמעי כל הנך קולות:","וצריך לקרותה כולה בפ\"ב דמגילה (יט.) תנן מהיכן קורא אדם את המגילה ויוצא בה י\"ח ר' מאיר אומר כולה רבי יהודה אומר מאיש יהודי רבי יוסי אומר מאחר הדברים האל' ואיפסיקא הלכתא בגמרא כדברי האומר כולה:","ומ\"ש ומתוך הכתב ואם קראה על פה לא יצא פשוט שם במשנה (יז.):","ומ\"ש הלכך צריך שתהא כתוב' כולה לפניו שם (יט.) הלכה כדברי האומר כולה ואפי' למ\"ד מאיש יהודי צריכה שתהא כתובה כולה:","\u0003ומ\"ש ודוקא לכתחלה אבל בדיעבד אם השמיט בה הסופר תיבות וכו'\u0004 שם (יח:) ת\"ר השמיט בה הסופר אותיות או פסוקים וקראן הקורא כמתורגמן המתרגם יצא מיתיבי היו בה אותיות מטושטשות או מקורעות אם רישומן ניכר כשירה ואם לאו פסולה לא קשיא הא בכולה הא במקצתה וכתב הרמב\"ם היו בה אותיות מטושטשות או מקורעות אם רישומן ניכר אפי' היה רובה כשירה ואם אין רישומן ניכר אם היה רובה שלם כשירה ואם לאו פסולה נראה מדבריו שהוא מפרש דמיעוטא קרוי מקצתה ורובה קרוי כולה וכדאמרינן בכל דוכתא רובו ככולו וכך הם דברי רבינו וכ\"כ בא\"ח וכתב ע\"ז בשם הרא\"ש וה\"ה באמצעיתה והוא שלא תהא חסירה ענין: וכתב הר\"ן אהא דת\"ר השמיט בה הסופר אותיות או פסוקים וכו' הקשה הרשב\"א דהכא משמע דחסרה מקצת כשירה ואילו לקמן אמרינן הלכה כדברי האומר כולה ואפי' מאן דאמר מאיש יהודי צריך שתהא כתובה כולה אלמא אם חסרה מראשה עד איש יהודי פסולה דנהי דאמרינן צריך שתהא כתובה כולה משמע דלעכב אמרינן הכי מדפרכינן לקמן בגמרא אלא דכתיב פסוקא פסוקא וקרי ליה והא אמר רבי חלבו הלכה כדברי האומר כולה ואפי' למ\"ד מאיש יהודי צריך שתהא כתובה כולה לפניו ואם איתא דלכתחלה בלחוד קאמר מאי קושיא ותירץ דהכא בשתחלת המגילה וסופה כתובה אלא דבאמצע היא חסירה ומש\"ה כל היכא דלא מיחסרא רובה כשיר' דאינה נראית כספר חסר אלא כספר מלא שלם שישבו טעיות ומגילה כיון דנקראת איגרת אין מדקדקין בה לפסלה בכך אבל כשחסר ממנה מראשה עד איש יהודי אע\"פ שהוא מעוטה נראה כספר חסר וצריך שיקרא אותה מספר שלם עכ\"ל כתב הרשב\"א בתשובה (סימן תסז) אני אומר שכל מי שתופס בידו מגילה שאינה כשירה לקרות בה פירוש לקרות בה עם ש\"צ גריעא טובא משנים שקראו אותה מפני שנותן דעת בקריאתו באותה מגילה ע\"כ: וזה לשון שבלי הלקט כתב הרב רבי בנימין שכשהחזן קורא את המגילה צריכים הצבור לשתוק ולכוין דעתם בקריאתו ואסור להם לקרות עמו במגילות שאינם כתובים בגליון דכיון שאינם כתובים כתקנן הו\"ל כקורא על פה וכן הפסוקים שנהגו הצבור לענות כולם יחד הקורא חוזר עליהם וקורא מתוך הספר לפי שבקריאת הצבור לא יצאו ידי חובתם שהרי קראו אותם ע\"פ וכן מנהג עכ\"ל ואע\"ג דתניא השמיט בה הסופר פסוקים וקראה על פה יצא ה\"מ בדיעבד אבל לכתחלה צריך לקרותה כולה מן הכתב: וכתב בא\"ח נהגו לגעור במי שמסייע לחזן ע\"פ והטעם שמא יתן לב השומע לזה שקורא ע\"פ ולא לקריאת החזן :","\u0003קראה סירוגין וכו'\u0004 משנה שם (יז.) קראה סירוגין יצא ומפרש בגמ' (יח:) דהיינו שקורא מעט ופוסק מעט ואמרינן תו התם רבי מונא אומר משום ר\"י אם שהה כדי לגמור את כולה חוזר לראש ואסיקנא דלית הלכתא כוותיה אלא אפי' שהה כדי לגמור את כולה יצא: קראה סירוסין וכו' ברייתא שם:","\u0003ומ\"ש הלכך אם דילג הקורא פסוק לא יקרא לפניו וכו'\u0004 פשוט הוא ולא צריך רבינו לכתבו דהיינו ממש קראה סירוסין אלא מפני שהוא שנוי שם בברייתא לפיכך כתבו:","\u0003מגילה נקראת בכל לשון ובלבד שיבין אותו הלשון ושתהא כתובה באותו הלשון וכו'\u0004 שם משנה קראה על פה קראה תרגום בכל לשון לא יצא אבל קורין אותה ללועזות בלעז והלועז ששמע אשורית יצא ובגמרא (יח:) קראה תרגום ה\"ד אילימא דכתיבא מקרא וקרי לה תרגום היינו ע\"פ לא צריכא דכתיבא תרגום וקרי לה תרגום ואמאי דתנן אבל קורין אותה ללועזות בלעז פריך והא אמרת קראה בכל לשון לא יצא ואסיקנא הא לא דמיא אלא להא גיפטית לגיפטיים עברית לעבריים עילמית לעילמים וכו' יצא כלומר דכיון שהם מבינים באותו לשון יוצאין ידי חובתן והוא שתהא כתובה באותו לשון דאל\"כ הו\"ל קורא ע\"פ וכדאמרינן גבי היתה כתובה תרגום והרמב\"ם כתב בלשון הזה היתה כתובה תרגום או בלשון אחרת מלשונות העו\"ג לא יצא י\"ח בקריאתה אלא המכיר אותו הלשון בלבד והוא שתהיה כתובה בכתב אותו הלשון אבל אם היתה כתובה בכתב עברי וקרא ארמית לארמיים לא יצא שנמצא זה קורא ע\"פ וכיון שלא יצא י\"ח הקורא לא יצא השומע ממנו עכ\"ל וראיתי מי שהיה רוצה לדייק מדכתב והוא שתהיה כתובה בכתב אותה הלשון דתרתי בעינן חדא שתהא כתובה באותו לשון והב' שתהא כתיבתה המיוחד לבני אותה לשון לאפוקי אם היתה כתובה בל' גיפטית וכתב עילמית ואין זה כלום דאנן לא קפדינן אלא שלא תהא כתובה בל' אחר כדי שלא יהא כקורא ע\"פ אבל כל שכתובה באותו לשון אע\"פ שכתובה בכתב אחר ל\"ל בה ומדברי הרמב\"ם עצמו משמע דהא דקאמר והוא שתהי' כתובה בכתב אותה הלשון לא אכתב קפיד אלא אלשון דהא מסיים בה אבל אם היתה כתובה בכתב עברי וקראה ארמית לארמ' לא יצא שנמצא זה קורא ע\"פ אלמא דמאי דקאמר והוא שתהא כתובה בכתב אותו הלשון לא אכתב קפיד אלא אלשון דבלשון הוא דשייך למימר שהוא קורא על פה או שאינו קורא ע\"פ ולא בכתב וראיתי שכתב הריב\"ש וז\"ל דהשתא אין יוצאין ידי חובתן במגילה הכתובה בלשון לעז ואפי' קראה ללועזים המכירים באותו ל' משום דאמרינן בגמ' אטו אנן אחשתרנים בני הרמכים מי ידעינן ואף על פי שאנו לועזי' לושפוטרו\"ש פיגו\"ש דילא\"ש ייגוא\"ש אין ידוע שזה לעז של תיבות הללו דאי חכמי התלמוד לא ידעי אנן מנא ידעינן ול\"נ דשפיר מצי נפיק בה ידי חובתיה בה ויקראנה כולה בלעז מתוך הכתב הכתוב בלשון לעז וכשיגיע לאותם התיבות יאמרם בלשון המקרא האחשתרנים בני הרמכים ואע\"פ שהשומע אינו מכיר ל' הקדש יצא כדבסמוך ואף על פי שנמצא שקראה בב' לשונות לא אשכחן שיפסל מקרא מגילה בכך ולענין כתיבת תיבות הללו במגילה אפי' הן כתובות בלעז לית לן בה דלא גרע מהשמיט בה הסופר אותיות או פסוקים וקראן הקורא ע\"פ דיצא אחר שכתבתי זה ראיתי תשובת הר\"ן להריב\"ש ע\"ז וכתב בסוף דבריו אין ספק כי הלעז ההוא משובש ופוסל הקריאה לגמרי ע\"כ ולא הזכיר שום תיקון בדבר וגם מהטעם שיבא בסמוך כתב למחות מלקרותה לנשים בלעז וכן ראוי לעשות וכתב ה\"ה שנראה מדברי רש\"י שאע\"פ שיודע אשורית ויודע לעז אילו רצה לקרותה בלעז יוצא י\"ח וכ\"נ מדברי הרמב\"ם אבל אין נראה כן מן הירושלמי שאמרו יודע לעז ויודע אשורית מהו שיוציא אחרים בלעז יבא כהדא כל שאינו מחוייב בדבר אינו מוציא את הרבים ידי חובתן אלמא פשיטא להו שמי שיודע אשורית ולעז הוא עצמו אינו יוצא בלעז ע\"כ בחידושי הרשב\"א וכ\"כ הרמב\"ן ז\"ל עכ\"ל והר\"ן בפ\"ב דמגילה האריך להשיב על דברי הרמב\"ן ובסוף כתב שראוי לחוש לדבריו ובתשובת הר\"ן שהביא הריב\"ש בתשובה האריך לפרש הירושלמי ע\"פ דעת הרמב\"ן ואעפ\"כ על דברי הריב\"ש שכתב שלא היו בקיאין בלעז האחשתרנים בני הרמכים ואפי' אם היו בקיאין בו לא היה ראוי לקרותה לנשים בלעז משום ההיא דהרמב\"ן כתב כלשון הזה רואה אני דבריך טובים ונכונים שאפי' בעסקי העולם כל משכיל בוחר לנפשו הדרך היותר בטוח והמשומר מכל נזק ומכשול ואפי' באפשר רחוק עאכ\"ו שיש לנו לעשות כן בדרכי התורה והמצות שהם כבשונו של עולם ואיך נניח הדרך אשר דרכו בה רבותינו הקדושים ונכניס עצמינו במקום צר ובמשעול הכרמים עכ\"ל:","ומ\"ש רבינו ובלשון הקדש הכל יוצאין בו אע\"פ שאינם מבינים משנה כתבתיה בסמוך הלועז ששמע אשורית יצא ופריך בגמרא והא לא ידע מאי קאמרי ומשני מידי דהוה אנשים ועמי הארץ מתקיף לה רבינא אטו אנן אחשתרנים בני הרמכים מי ידעינן אלא מצות קריאה ופירסומי ניסא ה\"נ מצות קריאה ופירסומי ניסא:","ומ\"ש בשם ר\"ע שלשון יוני ג\"כ כשר כלומר אע\"פ שאינו מבין אותו הכי אית' בגמרא שם רב ושמואל דאמרי תרוייהו לעז יוני לכל כשר כלומר ואפילו לשאינו מכיר בו והא קתני בברייתא יונית ליונים ליונים אין לכ\"ע לא אינהו דאמור כרשב\"ג דתניא רשב\"ג אומר אף בספרים לא התירו שיכתבו אלא יונית וכתב הרא\"ש הרי\"ף לא הביא הא דרב ושמואל אף על גב דליכא מאן דפליג עלייהו ואפשר דס\"ל דלאו אליבא דנפשייהו קאמרי אלא אליבא דרשב\"ג ולית הלכתא כרשב\"ג והרמב\"ם כתב כדברי רב ושמואל שאם היתה כתובה יונית ושמעה יצא אף על פי שאינו מכיר אפי' היה השומע עברי ובפ\"א מהלכות תפילין כתב אין כותבין תפילין ומזוזה אלא כתב אשורית והתירו בספרים לכתוב אף ביונית בלבד וכבר נשתקע יונית מעולם ונשתבש ואבד לפיכך אין כותבין היום שלשתן אלא אשורית ע\"כ לומר שבהלכות מגילה העתיק דברי רב ושמואל להודיענו דהלכה כוותייהו בעיקר הדין וסמך על מ\"ש בה' תפילין שכבר נשתקע יוני מעולם ונשתבש ואבד וא\"כ אין יתרון לבעלי הלשון היוני המצוי היום משאר לשונות ונראה שמפני כך השמיט הרי\"ף הא דרב ושמואל וכתב בברייתא דיונית ליונים דמשמע דוקא ליונים אבל לא למי שאינו מכיר באותו הלשון וכ\"כ הר\"ן שזה היא דעתו של הרי\"ף ז\"ל:","קראה מתנמנם יצא משנה שם(יז.) ובגמ' (יח:) ה\"ד מתנמנם נים ולא נים תיר ולא תיר דקרו ליה ולא ידע לאהדורי סברא כתב המרדכי ירושלמי מנשה הוה יתיב קומי רבי זירא וקא מתנמנם א\"ל חזור בך דלא כוונת ואיכא למימר דלא פליג אמתני' דאם קראה מתנמנם מאחר שהוציאה מפיו יצא אבל אם שמעה מתנמנם לא יצא וכ\"כ שבלי הלקט בשם רבינו שמחה:","היה כותב שקורא פסוק וכותבו ג\"ז משנה (שם יז) היה כותבה דורשה ומגיהה אם כיון לבו יצא ואם לאו לא יצא ומוקי לה בגמרא (יח:) כגון דכתיבא כולה קמיה וקרי פסוקא פסוקא במגילתא דמנחא קמיה וכתב לי' דאפי' למ\"ד מאיש יהודי צריכה שתהא כתובה כולה לפניו וכתב הרא\"ש ודורשה אע\"פ שאסור להפסיק במגילה כדאיתא בפ\"ב דברכות (יד.) והכא כשמשמיע הדרשה לרבים או דורש בינו לבינו נמצא שמפסיק בקריאתה מ\"מ יצא א\"נ כיון שאינו דורש אלא בעניינו של מגילה אין זה חשיב הפסק והכי איתא בירושלמי ודורשה ובלבד שלא יפליגו דעתם לעניינים אחרים עכ\"ל וז\"ש רבינו ולא יפסיק בה בענינים אחרים:","ומ\"ש והוא שיכוין לקרות כראוי לא כמי שקורא להגיה היא מדתנן בפ\"ב דברכות (יג.) היה קורא והגיע זמן המקרא אם כיון לבו יצא ואם לאו לא יצא ואיתמר עלה בגמרא ש\"מ מצות צריכות כונה ודחי מאי אם כיון לבו לקרות והא קא קרי בקורא להגיה והרבה פרושים נאמרו בה וכתבתיו בסי' ס' ודברי רבינו כאן נראה שהם כדברי התוס' שכתבתי שם:","וצריך שיכוין הקורא לצאת בקריאתה רבינו סתם דבריו כאן כדעת הרא\"ש שהוא סובר כדעת האומרים מצות צריכות כוונה וכמו שנתבאר בסי' תקפ\"ט ואיכא למידק דכיון דהא דאוקמא למתניתין דאם כיון לבו יצא בקורא להגיה היינו כי היכי דלא תפשוט מינה דמצות צריכות כונה אבל למאן דסבר צריכות כוונה אפי' בקורא כדרכו מתוקמא דאפ\"ה לא יצא עד שיכוין לצאת מאחר שרבינו סותם דבריו כמ\"ד צריכות כוונה לא היה לו לכתוב ולא כמו שקורא להגיה וצ\"ל דמ\"מ כיון שאף לדברי האומר אינן צריכות כוונה שלא יקרא כמי שקורא להגיה אע\"פ שהוא סותם כמ\"ד צריכות כונה כתב כן לומר בהא כולי עלמא מודו:","ומ\"ש והא דבעינן שיכוין הקורא על השומע בפרט להוציאו היינו דוקא יחיד הקורא אבל ש\"צ מסתמא דעתו על הכל כדתנן כבר נתבאר בסימן הנזכר:","\u0003ירושלמי אין מדקדקין בטעיותיה רב יצחק בר אבא ורב חננאל הוו יתבי קמיה דרב וכו'\u0004 וכתבוהו הרא\"ש והר\"ן ואיכא למידק דהול\"ל ולא אהדר מאן דאמר יהודיים דההוא הוא דטעי אבל ההוא דאמר יהודים דשפיר קאמר לא הו\"ל למהדריה וי\"ל דלא נחת השתא תלמודא לאשמעינן הי מינייהו שפיר קאמר אי מאן דאמר יהודים או מאן דאמר יהודיים אלא לאשמועינן דלא אהדר למאן דטעי ומש\"ה קאמר ולא הדר חד מינייהו ואפשר דאיכא פלוגתא אי אקרינן יהודים או יהודיים וההוא דקאמר האי עובדא לא ידע היכי הוה קושטא דמלתא ומיהו רב ודאי הוה ידע מדלא אהדר חד מינייהו אלמא אין מדקדקין בטעיותיה:","ומ\"ש רבינו שי\"מ דוקא בטעות כי האי שהלשון והענין היה אחד כ\"כ הר\"ן ואע\"פ שיש לדחות דכל שקרא התיבה אע\"פ שלא קראה כתקנה קראה כולה מקרי וכתב בא\"ח י\"א דוקא יהודים יהודיים אבל אם אומר מיושב ישב או מנופל נפל וכדומה ודאי חוזר וכ\"נ עכ\"ל:","וצ\"ל י' בני המן בנשימה אחת בספ\"ק דמגילה (טז:) ומפרש טעמא משום דכולם בהדי הדדי נפקן נשמתייהו וכתבו התוס' נראה דהיינו מתחלה אבל בדיעבד יצא :","ירושלמי צריך לאמרם בנשימה אחת ועשרת עמהם בפרק בני העיר וכתוב בא\"ח שצריך לאומרו עם עשרת בני המן איש שלפניה ועשרת הכל בנשימה אחת:","\u0003לר\"נ הקורא מגילת אסתר וכו'\u0004 אבל בנשימה אחת א\"צ כלומר א\"צ לקרות כל סוף פסוק ותחלת פסוק בנשימה אחת דאילו כולה בנשימה אחת לא הוה צ\"ל שא\"צ שהרי מלתא דלא אפשר הוא והרוקח כתב מנהג שלא לנשם בין פסוק לפסוק לפי שנקראת אגרת ובשבלי הלקט שרבי' ישעיה דקדק מדמשמע בברייתא בגמרא שהיו מתרגמין אותם שהיו קורין פסוק אחד עד סופו ומתרגם וחוזר וקורא אחר ולא כמו שאנו נוהגים שלא לעמוד בסוף הפסוק והראב\"ע כתב בפי' אסתר בעבור עזרא הסופר הפסיק הפסוקים ולא היה אחר שנים רבות צוו אבותינו עליהם השלום שלא יפסיק הקורא הפסוק בסוף עכ\"ל:","\u0003ירושלמי צריך שיאמר ארור המן וכו'.\u0004 בפרק בני העיר:","כתב רב האי ז\"ל מנהג דחזי לן מאן דקרי לה למגילה דברי רבינו האיי כתבוה הרי\"ף והרא\"ש בפ\"ק דמגילה וכ\"כ הרמב\"ם ג\"כ והמרדכי בפ\"ב דמגילה כ' ב' הסברות: כתב בא\"ח כשמזכיר הקורא שם המן ובניו מנקשין התינוקות באבנים או בלוחות עץ שבידם וכתוב בהם שם המן ובניו וע\"י הניקוש הם נמחקים ולמנהג הזה יש שורש בהגדה דאמרינן כי מחה אמחה את זכר עמלק אפי' מעל העצים ומעל האבנים לכן אין להלעיג על המנהגים כי לא לחנם נקבעו והמנהג הזה נוהגים בצרפת ובפרובינציא ונותנים טעם ע\"ש ושם רשעים ירקב עכ\"ל:","מגילה ני\"ד שהוא עיקר זמנה קורין אותה אפי' ביחיד לרי\"ף בפ\"ק דמגילה (ה.) אמר רב מגילה בזמנה קורין אותה ביחיד שלא בזמנה בי' ורב אסי אמר בין בזמנה בין שלא בזמנה קורא אותה בי' הוה עובדא וחש לה רב לדרב אסי והאי פלוגתא דרב ורב אסי איכא לפרושי דלכתחל' היא אבל בדיעבד מודה רב אסי דיצא ואופשר לפרושי דבדיעבד פליגי אבל לכתחלה מודה רב דבי' ואפשר דבתרוייהו פליגי דלרב אפילו לכתחל' ביחיד ולרב אסי בדיעבד נמי לא יצא ור\"ת פירש דבתרוייהו פליגי דלרב אפי' לכתחיל' ביחיד ולרב אסי בדיעבד נמי לא יצא ואע\"ג דחש ליה רב לדרב אסי פסק כרב משום דקאי רבי יוחנן כוותיה דאמר בפ\"ב (יט:) גבי קורא במגילה הכתובה בין הכתובים לא יצא לא אמרו אלא בציבור אלמא דקורין ביחיד וכרב ור\"ע היה אפשר לומר דמפרש פלוגתייהו בדיעבד אבל לכתחילה מודה רב דצריך לחזר אחר י' ופסק כרב משום דקאי רבי יוחנן כוותיה כמו שכתבתי או אפשר דר\"ע מפרש פלוגתייהו בלכתחילה אבל בדיעבד מודה רב אסי דיצא ומדחש לה רב לדרב אסי אלמא הילכתא כוותיה ולא חיישינן לדרבי יוחנן דהו\"ל חד לגבי תרי וכ\"כ הרא\"ש לדעת רב עמרם וז\"ל בסדר ר\"ע פסק כר' אסי מדחש ליה רב לדרב אסי וכן מסתבר והא דר\"י אינה ראיה דאף לרב אסי קריאה ביחיד כדפירש\"י דמצוה לחזר אחר י' אם לא מצא י' אינו פטור מקריאתה אלא קורא ביחיד ע\"כ ובה\"ג נראה שמפרש דבדיעבד פליגי ופסק כרב אסי מדחש לה רב ורבינו נסתפק בדברי הרי\"ף אם דעתו כדעת ר\"ת וכמו שפי' הר\"ן וכיון דפסק כרב א\"צ לחזר אחר י' או אם מפרש כפירוש קמא שכתבתי לדעת ר\"ע דבדיעבד פליגי אבל לכתחילה מודה רב דצריך לחזר אחר י' ולפיכך כתב בתחלת דברי הרי\"ף סתם כלומר אלו הם דברי הרי\"ף והם סתומים ואפשר לפרשם כדברי ר\"ת או כדברי רב עמרם לפי הפירוש הא' שפירשתי בו כנ\"ל לפרש דברי רבינו ואפשר לומר דפשיטא ליה לפרש דברי הרי\"ף כדברי ר\"ת וה\"ק דברי הרי\"ף הם סתומים ודברי ר\"ת הם מפורשים ובה\"ג חולק על פסק זה שסובר דבדיעבד פליגי והלכה כרב אסי ור\"ע סבר כבה\"ג בחדא שפוסק הלכה כרב אסי וסבר כפר\"ת בחדא דלכתחלה פליגי ומ\"מ אינו סובר לגמרי כוותיה דר\"ת סבר דבדיעבד נמי פליגי ור\"ע סבר דבדיעבד מודה רב אסי דיצא ולשטה זו אתי שפיר שכתב סברת רב עמרם אחר סברת בה\"ג וגם מפרש דברי ר\"ע כמו שפי' הרא\"ש ז\"ל וא\"ח כתב הראב\"ד הכריע ואמר דלעולם בעינן י' מיהו במקום שיש ציבור שקראוה בי' אם יש שם יחיד או יחידים שלא קראוה עמהם יוכלו לקרותה ביחיד כיון שהיה בעיר פירסום דקריאת הציבור עכ\"ל . ומ\"ש רבינו בזמנה שהוא י\"ד שהוא עיקר זמנה לאו דוקא דה\"ה לט\"ו לבני הכרכים אלא דחדא מינייהו נקט ושלא בזמנה פי' הר\"ן דהיינו בשחל יום י\"ד לבני עיירות או ט\"ו לבני כרכים להיות בשבת שמקדימין וקורין בע\"ש כתב המרדכי בשם ר\"ג יחיד הקורא את המגילה לא יברך לא לפניה ולא לאחריה דאמר רב אסי מגילה בי' וכיון דצריך י' יחיד לא מחייב לקרות דהיכי מברך הא הו\"ל מוציא שם שמים לבטלה וכ\"כ בא\"ח שכן דעת מקצת גאונים ושהר\"מ כתב שמברך אפי' ביחיד עכ\"ל ומתוך מה שנתבאר יתבאר לך שדעת כל הפוסקים חוץ מבה\"ג היפך דעת מרדכי הילכך נקטינן כדברי הר\"מ שמברך אפילו ביחיד : תנן בס\"פ ראוהו ב\"ד (ראש השנה כח.) הי' עובר אחורי בהכ\"נ או שהיה ביתו סמוך לבהכ\"נ ושמע קול שופר או קול מקרא מגילה אם כיון לבו יצא ואם לאו לא יצא וכתב הר\"ן דקשיא לתוספות היכי נפיק הא מגילה בעיא י' בין בזמנה בין שלא בזמנה ולאו קושיא היא דהא דבעינן י' דמגילה היינו משום פירסומי ניסא ובמקום קריאתה הוא דבעינן י' משום פירסומי ניסא והא איכא ואע\"ג דהאי שמע לה במקום דליכא י' קריאתה מיהא בי' הוא וממקום דאיכא משום פרסומי ניסא שמע לה ומשום הכי יצא ע\"כ ואמאי דתנן ואם לאו לא יצא כתב הירושלמי א\"ר יוסי בר חנינא לא אמרן אלא בעובר אבל בעומד חזקה כיון: כתב בת\"ה בני היישובים שאין להם מנין ורוצים ללכת לקהילות הסמוכים להם לימי הפורים כדי לשמוע מקרא מגילה בציבור צריכים להקדים ביאתם גם לשבת הסמוך לפורים כדי שישמעו פ' זכור בי' כלומר מפני שהיא מן התורה כמו שנתבאר בסי' קמ\"ו:"],["\u0003הקורא את המגילה עומד או יושב יצא ר\"פ הקורא עומד.\u0004 ומ\"ט משמע בדיעבד וכו' פי' דביושב דיעבד אין לכתחילה לא ומאי דקתני נמי הקורא דמשמע דיעבד משום יושב נקט הכי וה\"ק הקורא את המגילה יוצא בדיעבד כשיושב כמו בעומד אבל עומד ודאי אפי' לכתחילה דאי אפשר בלי עומד או יושב ומ\"מ קשה ל\"ל לתנא למיתני עומד ויושב כיון דדין עומד אינו כדין יושב ונראה דתני הכי למידק מיניה דבמגילה דוקא הוה דינא הכי משא\"כ בתורה דעומד דוקא וכדתניא משא\"כ בתורה מנה\"מ א\"ר אבהו דאמר קרא ואתה פה עמוד עמדי אבל יושב אפי' דיעבד לא וצריך לחזור ולקרות מעומד נ\"ל. ומ\"ש ובירושלמי קאמר דאפי' לכתחילה כ\"כ הרב המגיד וכ\"פ הר\"ן וכן ודאי עיקר:","\u0003ומ\"ש והרמב\"ם כתב אבל לא יקרא לכתחילה יושב בצבור כו'\u0004 פירוש דגם הוא סובר דאפי' לכתחילה קורא יושב אלא שסובר דבצבור לכתחלה הוא דאינו קורא יושב מפני כבוד הצבור וטעמו דלכל מילי דחיישינן לכבוד צבור בקריאת התורה ה\"ה במגילה דהא טעם שניהם אחד ולפ\"ז יראה דאע\"פ דלדעת הרמב\"ם נשים מוציאות לאנשים במקרא מגילה ואפ\"ה בצבור לכתחילה לא תקרא אשה מפני כבוד הציבור כמו בקריאת התורה:","\u0003ומ\"ש ואפי' שנים משנה שם.\u0004 ומ\"ש ואפי' י' ברייתא שם ומסיים בברייתא מ\"ש כיון דחביבא יהבי דעתייהו ושמעי וצריך לפרש דודאי אפשר לתרי קלי דמשתמעי בכ\"מ אלא שאין השומעין מכוונין לקול שני הקוראים מפני עירוב ב' הקולות אבל מגילה מגו דחביבה להו יהבי דעתייהו למשמע דהא אפשר הוא אבל אי אפשר לפרש דא\"א לתרי קלי דמשתמעי דא\"כ במגילה נמי אמאי יצאו וכן פי' הרא\"ם ובדרך זה הם דברי הגהת אשיר\"י בפרק ראוהו ב\"ד לענין שופר ועי' במ\"ש למעלה בסי' תקפ\"ט:","ומ\"ש וצריך לקרותה כולה בפ\"ה דמגילה תנן מהיכן קורא אדם את המגילה ויוצא בה י\"ח ר\"מ אומר כולה ר\"י אומר מאיש יהודי ובגמרא אמר רב הלכה כדברי האומר כולה ואפי' למ\"ד מאיש יהודי צריכה שתהא כתובה כולה:","\u0003ומ\"ש ומתוך הכתב וכו'\u0004 משנה שם קראה על פה לא יצא:","\u0003ומ\"ש ודוקא לכתחלה וכו'\u0004 ת\"ר השמיט בה הסופר אותיות או פסוקי' וקראן הקורא כמתרגם יצא. מיתיבי היו בה אותיות מטושטשות או מקורעות אם רישומן ניכר כשרה ואם לאו פסולה ל\"ק הא בכולה הא במקצתה והדבר פשוט דמקצתה דכשרה היינו פחות מרובא דכל שהוא רובא לאו מקצתה מקרי וכן מבואר ברמב\"ם ובאשר\"י וז\"ל האשיר\"י במאי דמסיק ואפי' למ\"ד מאיש יהודי צריכה שתהא כתובה כולה פירוש לכתחילה צריכה שתהא כתובה כולה אבל בדיעבד הא אמרינן לעיל אם השמיט בה הסופר פסוקים עד רובה ולא רובה בכלל וקראוה על פה יצא עכ\"ל וכך הם דברי רבי' ואיכא למידק מדאמר התם בגמרא אהא דתנן היה כותבה אם כיון לבו יצא ה\"ד אי דקא מסדר פסוקא פסוקא וכתב ליה כי כיון לבו מאי הוה ע\"פ הוי אלא דכתב פסוקא וקרי ליה ומי יצא והא\"ר הלכה כדברי האומר כולה ואפי' למ\"ד מאיש יהודי צריכה שתהא כתובה כולה אלא דמנחה מגילה קמיה וקרי לה מינה פסוקא פסוקא וכתב ליה אלמא דמאי דקאמרינן דצריכה שתהא כתובה כולה לעכב אמרינן הכי דאם איתא דלכתחילה בלחוד קאמר מאי קושיא ונראה ליישב דודאי דלכתחלה בעינן שתהא כתובה כולה אבל בדיעבד יצא בשכתובה רובה כדכתב הרא\"ש והתם הכי דייקינן אלא דכתב פסוקא פסוקא וקרי ליה ומי יצא הא ודאי כל מאי דקרי לה עד חציה קורא על פה הוה כיון דאכתי לא כתב לה רובה ומאי דקרי לה בתר הכי כדכתב רובה נמי אינו יוצא בה י\"ח דהלכה כדברי האומר כולה וכל מאי דקרי לה מקמי הכי לאו כלום הוא דאנן בעינן שתהא כתובה כולה ולפחות בדיעבד בעינן רובא והכא אפי' רובא לא הוי כדפי' והר\"ן ז\"ל בשם הרשב\"א פסק מכח האי שקלא וטריא דאפי' חסרה מיעוטא מתחלתה אינו יוצא בה אפי' דיעבד ודלא כהרא\"ש ומביאו ב\"י ולפע\"ד נראה כדעת הרא\"ש ורבינו:","\u0003הילכך אם דילג וכו'\u0004 נראה דאשמעינן דלא תימא דוקא בדילג פסוק אחד ואח\"כ קוראו באמצע שלא במקומו הוא דהוה בכלל הקורא למפרע אבל בכהאי גונא שקורא הדילוג לבסוף לית לן בה קמ\"ל דאפ\"ה לא יצא:","קראה מתנמנם יצא משנה שם ובגמרא ה\"ד מתנמנם נים ולא נים תיר ולא תיר דקרי ליה ועני ולא ידע לאהדורי סברא וכי מדכרי ליה מידכר וכתבו התוספות ספ\"ק דתענית נים ולא נים שייך לומר בתחילת שינה תיר ולא תיר שייך לומר בסוף שינה שבא להקיץ משנתו והקשו ע\"ז מפרק ערבי פסחים ופירשו דהכל בתחילת שינה אלא דסד\"א דתיר הוי טפי מנים וכן להיפך סד\"א דנים הוי טפי מתיר הילכך איצטריך למימר תרווייהו וכן היא דעת הר\"ן בפ\"ב דמגילה דהכל בתחילת שינה ע\"ש ומשמע לפ\"ז דלא יצא בקראה מתנמנם אלא בדקרא' בתחילת שינה אבל בסוף שינה לא יצא והך דירושלמי דהוה יתיב קמיה דר' זעירא וקא מתנמנם וא\"ל חזור בך דלא כיונת היינו לומר שהיה קורא מתנמנם בסוף שינה אבל אם היה קורא בתחילת שינה יצא אבל המרדכי ושבולי הלקט כתבו דהך דירושלמי איירי דשמעה מתנמנם התם הוא דלא יצא כיון שלא הוציאו מפיו אבל קראה מתנמנם דהוציא מפיו יצא ומביאו ב\"י ומיהו דוקא בתחילת שינה כדפי' והכי נקטינן:","ומ\"ש וכן אם הי' מגיהה ודורשה פי' או שדרש' שקורא פסוק ודורשו והוא משנה שם דרשה ומגיה אם כיון לבו יצא ואם לאו לא יצא וסובר רבינו דהאי אם כיון לבו לצדדין קתני בדורשה דודאי קורא אותו בקריאת' קאמר דצריך שיכוין לבו לצאת בקריאתו דמצות צריכות כוונה כדלעיל בסי' תקפ\"ט ובמגיהה קאמר דצריך ג\"כ שיכוין לקרותה כראוי ולא כמי שקורא להגיה שמדקדק לקרות ע\"פ המסורת בחסרות ויתרות ככתיבתן שזה לא קראה כולה ודוקא בטעות דיהודים לית לן בה אבל שאר קורא בטעות לא יצא וכ\"נ בירושלמי דאיתא התם ומגיה תני אין מדקדקין בטעיותיה רב יצחק כו' נראה מבואר דמדתנן במגיה אם כיון לבו יצא למדנו ממנו דאין מדקדקין בטעיותיה שהרי כל מגיה אינו קורא התיבות בקריאתו אלא ע\"פ המסורת ואפ\"ה יצא ואחר זה הביאו ההוא עובדא דיהודיים לאורויי לן דדוקא בטעיות שהענין והלשון אחד ולפ\"ז יש לתמוה קצת בדברי רבינו שהביא הירושלמי וכתב עליו וי\"מ דוקא בטעות כי האי כו' והלא כל עצמו של פסק דינו שכתב תחילה והוא שיכוין לקרותה כראוי ולא כמי שקורא להגיה אינו אלא מטעם שמפרש הירושלמי בדוקא בטעיות כי האי כו' שאילו היה מפרשו בכל טעיות א\"כ אף בקורא להגיה נמי יצא וא\"כ מאי י\"מ דקאמר דמשמע דאיהו אינו תופס אותו פי' ועיין בתשובת הרשב\"א שכתבתי סוף סי' תרצ\"א:","וצריך לומר עשרת בני המן בנשימה אחת בספ\"ק דמגילה אמר רב אדא דמן יפו עשרת בני המן ועשרת צריך למימרינהו בנשימה אחת מ\"ט כולהו בהדי הדדי נפקו נשמתייהו ופי' רש\"י עשרת בני המן ועשרת הזכרת שמותן ותיבה הסמוכה אחריהן וכך העתיקו הרי\"ף והרא\"ש ושאר מחברים ואיכא לתמוה בדברי רבינו שלא כתב רק דצ\"ל עשרת בני המן בנשימה אחת דיראה מדבריו שלא היה גורס בגמרא עשרת בני המן ועשרת ועוד דמדהביא גם הירושלמי ופשיטא דאין חילוק בין נשימה לנפיחה בע\"כ צ\"ל שהביאו בשביל שמוסיף ועשרת עמהם וא\"כ בתלמודנו לא היה גורס ועשרת:","לרבי נתן הקורא מגילת אסתר בקהל צריך לסדרה כאחד מפני שהיא אגרת ר\"ל שלכתחלה לא יקראנה סירוגין שישהה בקריאתה מעט אלא יסדרנה כאחד כאגרת אבל בנשימה אחת א\"צ וכו' כלומר שהמנהג שנוהגין לומר כל סופי פסוקים וראשי פסוקים בנשימה אחת דלהוי כאגרת זה אין צריך אפי' לכתחילה ותדע מדקאמרינן ועשרה מכלל דשאר ראשי פסוקים א\"צ אלא עשרת בני המן ועשרת בלבד הילכך כו' ומ\"ש ושיעורו בין פסוק לפסוק כו' נראה טעמו שכן דרך קוראי אגרת לקרותה כולה כאחד ולהפסיק במקום שצריך כדי נשימה לבד ובהגה\"מ פ\"ב דהל' מגילה כתב בשם מהר\"מ כדברי ר\"נ והעלה שא\"צ לומר חמש מאות איש ואת פרשנדתא בנשימה אחת דבגמרא קאמר דוקא בעשרת בני המן משום דכולהו בהדי הדדי נפקי נשמתייהו וחמש מאות איש לא שייכי בהאי טעמא וכו' והב\"י העתיק על שם א\"ח שצ\"ל איש שלפניהם בנשימה אחת ואפשר לחלק דדוקא חמש מאות איש לא צריך אבל כל מה שהוא בכלל השירה דהיינו איש לבד צ\"ל ובמהרי\"ל כתב בשם הרוקח דטעמא דחמש מאות איש צריך בנשימה א' היינו משום שי' בני המן היו שרי חמשים על אותן חמש מאות איש עכ\"ל וכן נוהגין לאמרם בנשימה אחת:","\u0003כתב רב האי מנהג דחזי לן מאן דקרי לה למגילה פושט וקורא כאגרת וכו'\u0004 לשון זה משמע דפושטו קודם הקריאה וכן המנהג אבל בכל שאר המחברים שהעתיקו דברי רב האי כתוב קורא ופושט כאגרת משמע דקודם הקריא' אינו פושט אלא בשעת קריאה כל מה שקרא מניח פשוטה עד אחר גמר הקריא' וכבר האריך בזה בתשובת מהרי\"ל בסימן נ\"ו ומסקנא לפושטו קודם הקריא' ומ\"מ כתבו על שמו דווקא הקורא בציבור להוציא אבל היחידים שיש להם מגילות אינן צריכין לפשוט עיין בדרשותיו וכ\"כ מדברי הרמב\"ם שכתב קורא ופושט כאגרת להראות הנס ואין זה אלא בקורא בציבור להוציא:","\u0003מגילה בזמנה וכו'\u0004 פ\"ק דמגילה ריש דף ה' אמר רב מגילה בזמנה קורין אותה אפי' ביחיד שלא בזמנה בי' רב אסי אמר בין בזמנה בין שלא בזמנה בי' הוה עובדא וחש לה רב להא דרב אסי ופירש\"י בזמנה בי\"ד מתוך שהוא חובה בו ביום על כל יחיד ויחיד קורין אותה אפי' ביחיד דהכל קורין בו ואיכא פרסום נס שלא בזמנה כגון כפרים המקדימין ליום הכניסה אין קורין אותה אלא בי' דבעינן פרסומי ניסא ורב אסי אמר בין בזמנה ובין שלא בזמנה מצוה לחזר אחר י' משום פרסומי ניסא אבל אי לא אשכח י' לא אמר רב אסי דלא ליקרי שאין איסור קריאתה ביחיד אלא מצוה לקרות' בי' וחש ליה רב להא דרב אסי וחזר על י' וקיבצן עכ\"ל רש\"י וכן הסכים בעל המאור והביא ראי' ממה שלא מנו מקרא מגילה עם אותן שהם בי' דקתני להו בפ' הקורא המגילה עומד אין פורסין על שמע וכו' וכיון דבמסכת מגילה קיימינן אם איתא דלעכובא בעי י' הו\"ל למנותה עמהם ואמאי לא אותבינן מינה לרב אסי אלא ודאי דלכ\"ע אם קראה ביחיד יצא וכן משמע הלשון דקאמר קורין אותה בי' ולא אמר אין קורים אותה אלא בי' ש\"מ דמצוה לכתחילה להדורי אבי י' אבל אם קראה ביחיד יצא א\"כ היכא דלא אשכח בי י' קרי לה ביחיד אפי' לכתחילה אבל הרי\"ף כתב וז\"ל ואע\"פ דחש לה רב להא דרב אסי קיי\"ל כרב דהא ר' יוחנן קאי כוותיה דאמר לקמן ריש פ' שני א\"ר יוחנן הקורא את המגילה בין הכתובים לא יצא לא אמרו אלא בציבור אבל ביחיד יצא ושמעינן מינ' דקורין אותה ביחיד כרב דאמר בזמנה קורין אותה ביחיד עכ\"ל נראה מדבריו דס\"ל דלרב אסי אפילו בדיעבד לא יצא דאי בדיעבד יצא א\"כ מאי מייתי ראיה מר' יוחנן הא לא קאמר אלא הקורא וכו' דמשמע דיעבד וכן פי' הרמב\"ן לדעת הרי\"ף בספר מלחמותיו וז\"ל וסעד לדברי רבי' שאלמלא לא היה רב אסי מחמיר אלא למצוה לאהדורי אבי י' על מה חשש רב להא דרב אסי כיון דלא ס\"ל כוותיה אלא ודאי לדברי רב אסי דיעבד נמי לא יצא ומש\"ה חש ליה לרב להחמיר ואלמלא כן הוי אמרי בגמרא מצותה בי' א\"כ הוו מפרשי בהדי' לא מצא י' קורין אותה ביחיד ומאי דקשה דהו\"ל למנותה בהדי דאין פורסין על שמע וב\"י תירץ דכל אותם דחשיב התם חובת צבור הם ואין עושין אותם אא\"כ בעשרה או רובם מחוייבין בדבר כגון שלא שמעו קדיש וברכו אבל במגלה לא בעינן י' אלא משום פרסומי ניסא הילכך אפי' בשביל יחיד קורין אות' בי' אע\"פ שיצאו הם כיון שהיחיד לא יצא ונראה לפע\"ד מלשון רב שאמר מגילה בזמנה ביחיד ושלא בזמנה בי' דלכתחלה קאמר דבזמנה אפי' ביחיד דומיא דשלא בזמנה דכי היכי דהתם בי' לכתחלה ה\"נ בזמנה ביחיד לכתחלה וא\"כ להרי\"ף דהלכה כרב אפי' לכתחלה כך הוא ההלכה וכך מבואר בדברי הר\"ן דאפי' לכתחיל' קאמר רב דבזמנה ביחיד ומה שהביא הרי\"ף ראייה מר' יוחנן אע\"פ דר' יוחנן לא מיירי אלא דיעבד אינו מביא ראיה ממנו אלא לדחות דברי רב אסי דאפי' בדיעבד לא יצא דליתא וא\"כ ממילא משמע דנדחו דבריו מהלכה לגמרי והלכה כרב אפילו בלכתחלה וכ\"נ מדברי הרא\"ש שכתב ל' הרי\"ף וכתב שכן פסק ר\"ת ורבינו העיד שר\"ת כתב שאפי' לכתחיל' א\"צ לחזור אחר י' וא\"כ ממילא אף דעת הרי\"ף כך היא גם דעת הסמ\"ג שכתב שר\"ח ור\"ת פסקו כרב מכח ההיא ראיה דרבי יוחנן קאי כוותיה כדכתב הרי\"ף כונתו לומר דאפי' לכתחיל' ודלא כמה שעלה על דעת מהר\"ם בביאוריו דדוקא בדיעבד מפני שסובר דמכח הראי' דר' יוחנן קאי כותי' דלא מיירי אלא בדיעבד משמע דרב נמי מיירי בדיעבד וכבר כתבתי שאין זה כלום דפשיטא דרב מיירי בלכתחיל' ולפ\"ז מ\"ש רבי' מגילה בזמנה קורין אפי' ביחיד לרי\"ף ור\"ת כ' וכו' דנראה מהלשון שהם שני סברות הוא שלא בדקדוק שהרי ר\"ת גופיה שפסק כרב לא פסק הכי אלא מכח ההיא ראי' דרבי יוחנן שהביא הרי\"ף כמבואר בסמ\"ג ובמרדכי ואפשר דכיון שמצא רבינו לר\"ת שכתב כן בפירוש שא\"צ לחזר אחר עשרה עשה מדבריו בבא מיוחדת דאע\"פ שגם מדברי הרי\"ף מוכח כן כדפי' לא כתב כן בפי' אלא שא\"כ הו\"ל לכתוב וכתב ר\"ת מאחר שדברי ר\"ת הם כמו פי' לדברי הרי\"ף ויותר נכון בעיני שהספר מוטע' וכך צריך להיות קורין אותה ביחיד לרי\"ף ור\"ת ואפי' לחזר אחר י' א\"צ וכו' דהשתא הוה ממש כמ\"ש הרא\"ש ושאר מחברים דהרי\"ף ור\"ת ור\"ת תופסים שטה אחת והכי משמע ודאי דאין כאן אלא ג' דעות דעת רי\"ף ור\"ת דלכתחיל' קורין אותה ביחיד ודעת בה\"ג דאפי' דיעבד לא יצא אלא בי' ודעת רב עמרם דלכתחיל' צריך לחזר אחר עשרה ואם אי אפשר קורין אותה ביחיד ויצא בה בדיעבד:","ומ\"ש ובה\"ג פסק ודוקא בי' טעמו שהוא פוסק כרב אסי וכ\"כ בסמ\"ג וז\"ל ובה\"ג פוסק כרב אסי וכ\"כ הרמב\"ן בספר מלחמותיו ומפרש דברי רב אסי אפילו בדיעבד לא יצא אלא בי' כמו שפירש הרי\"ף ולפיכך פסק דוקא בי' אפי' בדיעבד:","\u0003ומ\"ש ור\"ע כתב צריך לחזר כו'\u0004 איכא לתמוה טובא דבמרדכי משמע שר\"ע סובר דאפילו בדיעבד בעינן י' כדעת ר\"ג מ\"ה ובאגודה מפורש כך וז\"ל רבינו שמואל ור\"ח ור\"ת פסקו כרב ור\"ע גאון ור\"נ פסקו כרב דיחיד לא מברך עכ\"ל ונראה ליישב דלפי שרבינו ראה בדברי הרא\"ש שכתב דברי הרי\"ף ושכן פסק ר\"ת ואח\"כ כתב ובסדר רב עמרם פסק כרב אסי מדחש לי' רב לרב אסי וכן מסתבר והא דר' יוחנן אינה ראי' דאף לרב אסי קראה ביחיד יצא כדפי' רש\"י וכו' הבין רבינו שכל זה הם דברי ר\"ע וליתא דר\"ע לא כתב רק דהלכ' כרב אסי והרא\"ש הסכים עמו בזה וכתב שכן מסתבר מדחש לה רב לדרב אסי וכמו שפסק ר\"ע אבל בפי' דברי רב אסי אינו מסכים לדברי רב עמרם דאילו רב עמרם מפרשם דאפילו בדיעבד בעי י' ויחיד אינו מברך עליה כמ\"ש באגודה בפירוש וכמו שפי' הרי\"ף דברי רב אסי אבל הרא\"ש סובר פירוש דברי רב אסי כפי' רש\"י ובעל המאור ומכחה דחה ראי' הרי\"ף וז\"ש והא דרבי יוחנן אינה ראיי' וכו' הוא מלשון הרא\"ש עצמו לא מלשון רב עמרם וכתב הר\"ן וא\"ת והא דרשי' מדכתיב משפחה ומשפח' להביא משפחות כהונה שמבטלין מעבודתן וכו' ומכאן סמכו של בית רבי וכו' ולרב אמאי והא איהו דאמר דבזמנה קורין אותה ביחיד לכתחיל' י\"ל דאפי' רב מודה דמצוה מן המובחר לקרות עם הציבור משום פרסומי ניסא ולפיכך בשעה שהציבור קורין מבטלין עבודה ות\"ת ובאין לשמוע עם הציבור ואף ע\"פ שיש בבית המדרש אפי' ק' כשל בית רבי מיהו משום דברוב עם הדרת מלך ס\"ל לרב שלא הטריחוהו חכמים לכנוס י' כדי לקרותה עכ\"ל ועל דרך זה הם דברי המרדכי שכתב שר\"ת ור\"ח פסקו כרב דנקראת שפי' שלא בציבור ומיהו מצוה בי' ורצה לומר דודאי לא הטריחוהו חכמים לכנוס י' כדי לקרות' אלא נקראת שפיר אף לכתחיל' ביחיד אלא מיהו מצוה מן המובחר לקרות' בי' אם אפשר וה\"ה שאפי' יש שם י' מצוה מן המובחר לקרותה ברוב עם. ולענין הלכה כבר התבאר דהרי\"ף ור\"ח ורבינו שמואל ור\"ת ורבינו שמחה במרדכי פסקו כרב דאפילו לכתחיל' א\"צ לחזר אחר י' ורב עמרם ובה\"ג ור\"ג מ\"ה פסקו כרב אסי ופירשו דאפי' בדיעבד לא יצא ביחיד ויחיד הקורא את המגילה לא יברך ובעל המאור והרא\"ש ז\"ל פסקו דלכתחיל' צריך לחזר אחר י' אבל בדיעבד יצא ביחיד ופירשו דהיינו דרב אסי ויחיד הקורא מברך עליה ומיהו האגודה כתב ונוהגין לברך בזמנה אפי' קורא לנשים ובדרשות מהרי\"ל כתב מי שקורא לחולה או ליולדת מברך לפניה ולאחריה אע\"פ שיצא כבר י\"ח בבהכ\"נ כדקיי\"ל במסכת ר\"ה כל הברכות אע\"פ שיצא מוציא וכו' ואפי' במקום שאין שם י' יכול אחד לפטור כולן אפי' ליודעין לקרות בעצמן ומכ\"ש אם אחד יודע והשאר אינן יודעין כדקיי\"ל סופר מברך ובור יוצא עכ\"ל ומצאתי בהגהות על שם האגודה דמי שכבר יצא וקורא מגילה לנשים ולבני ביתו יברך על משמע מגילה ע\"כ וזה ע\"פ שיטת ראבי\"ה עיין במרדכי פ\"ק דמגילה:"]],["\u0010c0\u0011\u0010y0\u0011היתה כתובה בסם בסיקרא בקומוס ובקנקנתום על הדיפתרא ועל הנייר פסולה עד שתהא כתובה על הספר ובדיו וקלפין שלנו כשרין אע\"פ שאינן מעופצין \u0010y1\u0011וצריכה שירטוט \u0010y2\u0011ור\"ת ז\"ל כתב כיון דנקראת ספר נותנים לה כל דין ס\"ת חוץ ממה שמפרש בהדיא דהיינו שאם הטיל בה ג' חוטי גידין כשרה אבל לכל שאר הדברים היא כספר תורה לענין עיבוד לשמה והיקף גויל וחטוטרת חתי\"ן ותליית ההי\"ן וקופי\"ן וכל גופות האותיות כצורתן וזיונן של שעטנז ג\"ץ ובחסירות ויתרות \u0010y3\u0011וצריכה עמוד בראשה וחלק בסופה כדי להקיפה בו הכל כס\"ת \u0010c1\u0011והרמב\"ם ז\"ל כתב שאין צריכה עיבוד לשמה \u0010y4\u0011ואם כתבה מין או עו\"ג פסולה ובעל ה\"ג כתב שאין צריכה תגין: \u0010c2\u0011\u0010y5\u0011עשרת בני המן צריך לכתבם כשירה ולא כשאר שירות שחלק ע\"ג כתב אלא מניח חלק בין כתב לכתב כזה את פרשנדתא ואת דלפון וקאמר בירושלמי שהיא פסולה אם לא עשה כן וצריך להאריך וי\"ו דויזתא \u0010c3\u0011\u0010y6\u0011ירושלמי א\"ר יוסי בר בון צריך שיהא איש בריש דפא ואת בסופה שניץ ונחיץ כהדין קנטירא \u0010y7\u0011נקראת ספר שאם תפרה בחוטי פשתן פסולה ונקראת איגרת שאם הטיל בה ג' חוטי גידים כשרה ובלבד שיהו משולשין משום שיש בו פירושים שונין צריך לצאת ידי כולם לעשות א' בראש היריעה וא' באמצעיתו וא' בסופו וא' בחלק רביעי מכאן וא' בחלק רביעי מכאן \u0010y8\u0011וצריך להיות שיור בראש היריעה ובסופה כשתופרה ביחד שלא יתפור הכל ובמשהו סגי \u0010y9\u0011וצריך שיהא כתובה לבדה שלא תהא מחוברת עם הספרים ואם היא מחוברת עמהם וקרא בה ביחיד יצא בלבד שתהא נגללת כס\"ת אבל בצבור לא יצא ואם יריעותיה עודפות מעט על שאר היריעות שבספר או חסירות מעט אפילו בצבור יצא בה \u0010y10\u0011כתב ב\"ה ז\"ל הא דאמרי' בצבור לא יצא פי' בב\"ה שהוא מקום צבור ובעי פרסומי ניסא אבל שלא בב\"ה אפילו בי' יצא ולי נראה דכל י' מקרי צבור לכל דבר ואין חילוק אם הם בב\"ה או לא \u0010c4\u0011\u0010y11\u0011ואם אין מגילה כשירה יש מתירין לקרותה בחומש כדאמר לענין לולב שיוצא ביבש בשעת הדחק \u0010y12\u0011כתב ב\"ה ז\"ל שאם קרא במגילה גזולה יצא:",["\u0003היתה כתובה בסם בסיקרא וכו'\u0004 עד על הספר ובדיו משנה ברפ\"ב (יז.) ודיפתרא מפרש בגמרא דמליח וקמיח ולא עפיץ וכתבו התוס' והרא\"ש בקלפים שלנו אע\"ג דלא עפיצי תיקון שלנו חשיב כמו עפצים שלהם:","וצריכה שירטוט מימרא בספ\"ק (טז:) וכתב בא\"ח דדי בשירטוט שיטה ראשונה :","\u0003ור\"ת כתב כיון דנקראת ספר נותנין לה כל דיני ס\"ת וכו'\u0004 כ\"כ המרדכי בפ\"ב דמגילה בשמו וכ\"כ ג\"כ הגה\"מ וכ\"כ א\"ח בשם הר\"מ ולשון רבינו אינו מכוון דמשמע דר\"ת אתא לאיפלוגי על שום דבר שנזכר לעיל ואינו כן וא\"כ לא הול\"ל אלא כתב ר\"ת כיון דנקראת ספר: כתב הרשב\"א בתשובה (סי' ע) על מגילה שהיא נקודה מחמת הניקוד איני רואה שתפסל בכך וכתב עוד (סי' ק\"ו) מגילה שיש בדף הראשון ברכות ופיוטים דבר פשוט שהיא כשרה ע\"כ והמרדכי כתב בפרק בני העיר בשם אבי\"ה דאין לכתוב ברכות במגילה דאיתקש לס\"ת ולא דמי למגילה הכתובה בין הכתובים עכ\"ל ואע\"פ שנראה מדבריו דמפסיל נמי פסיל לה על דברי הרשב\"א יש לסמוך להכשירה בדיעבד :","ומ\"ש רבינו וצריכה עמוד בראשה וחלק בסופה כדי להקיפה בו הכל כס\"ת נראה דהיינו מדתניא בפ\"ק דבתרא (יג.) הרוצה לדבק תורה נביאים וכתובים כאחד עושה לראשו כדי לגול עמוד ולסופו כדי היקף ופי' רש\"י כדי לגול עמוד. מניח קלף חלק לגלול ע\"ג עמוד של עץ שהספר נגלל עליו: ולסופו כדי לגלול היקף. בסופו מניח חלק גדול כדי לגלול בו כל הקיפו שאין עושה שני עמודים לגוללו לאמצעי כמו שאנו עושין לס\"ת אלא גוללו מתחלתו לסופו וכרך החלק על כל ההיקף עכ\"ל ולפ\"ז מ\"ש הכל כספר תורה בשאר דברים הוי כספר תורה ממש ולענין עמוד בראשה וחלק בסופה הוי כספר תורה המדובק עם נביאים וכתובים וקשה שמנהג העולם הוא בהפך שהם עושים עמוד בסופה וחלק בראשה כדי להקיפה בו ונראה שהטעם הוא מפני שהתוספות הקשו על גירסא זו מדתניא התם בסמוך כל הסתרים נגללים לתחילתן ואמרינן נמי ספר עזרא לתחילתו הוא נגלל וגבי מזוזה אמרינן (מנחות לא:) נמי שכורכין אותה מאחד כלפי שמע דהיינו לתחלתו ע\"כ נראה לר\"י דגרסינן ועשה בראשו כדי היקף ובסופו כדי לגלול עמוד וכ\"נ בספר התרומות סי' ר\"ב כדברי התוס' וכתב אח\"כ א\"כ במגילה שיש לה דין שאר ספרים יש לה להיות עמוד אחד בסוף וכדי היקף בתחלת' בלא עמוד והגהת מיי' כשכתבו דברי ר\"ת כתבו ומניח בסופה כדי לגלול עמוד ובתחלתה לגלול היקף והרא\"ש כתב בפי' המשנה פ\"ג דמסכת ידים אהא דתנן התם גליון שבספר שלמעלה ושלמטה שבתחלה ושבסוף מטמא את הידים רבי יהודה אומר שבסוף אינו מטמא עד שיעשה לו עמוד שבתחלה ושבסוף כדאמרינן בפ\"ק דב\"ב עושה לו כדי לגלול עמוד בתחלתו וכדי היקף בסופו וק' דהכא משמע שהעמוד היה בסוף הספר והכי מסתבר דאם היה כדי היקף בסופו א\"כ הספר נגלל מתחלתו לסופו ונמצא כשירצה לקרות בו צריך לגוללו לתחלתו ועוד דבההיא שמעתא גופא גרסינן תני כל הספרים נגללים לתחלתן אע\"פ שרש\"י פירש שם מתחלתן לסופן אין לשון הגמרא מוכיח כן עוד אמרו התם ספר העזרא לתחלתו נגלל ועוד מסתבר דומיא דמזוזה שנכרכת כלפי שמע וכן בירושלמי פ\"ק עושה עמוד לספר בסופו הילכך נראה דגרסינן התם עושה כדי היקף בתחלתו וכדי עמוד בסופו ויש לקיים גירסת הספרים דהתם במדביק תורה נביאים וכתובים כאחד ואם היה גוללו לתחלתו היתה תורה למעלה ואינו כבוד התורה להיותה כמו שומר לנביאים וכתובים אבל התורה נגללת לתחלתה עכ\"ל וכ\"כ רבי' שמשון שם ואף לפי מ\"ש לקיים גירסת הספרים משמע דס\"ל דעמוד דמגילה הוי בסופה וכדי היקף בתחלתה וכדמשמע מכל הני שהביא בתחלת דבריו דלא אמר דמדביק תורה נביאים וכתובים כאחד עמוד בתחלתו וכדי היקף בסופו אלא משום כבוד התורה שלא תהא כשומר לנביאים וכתובים אבל המגילה דליכא למיחש להכי הרי הוא ככל הספרים שנגללין מסופן לתחלתן ויש לתמוה על רבינו היאך סתם דבריו היפך דעת התוס' והרא\"ש ורבינו שמשון ודוחק לומר שלא ראה דבריהם ואפשר שמאחר שראה שהרא\"ש ורבינו שמשון כתבו לקיים גירסת הספרים ומגילה דינה כס\"ת ואין לדמותה לס\"ת שאין בו אלא תורה בלבד שהוא צריך ב' עמודים ומגילה די לה בעמוד אחד מדמינן לה לס\"ת המדובק עם נביאים וכתובים דאין לו אלא עמוד אחד וכי היכי דהתם הוי עמוד בראשו וכדי היקף בסופו הכי נמי במגילה ומכל מקום אין דבריו נראין מהטעם שכתבתי בסמוך דשאני מדביק תורה נביאים וכתובים משום כבוד התורה נגעו בה אבל במגילה דליכא האי טעמא מודו הרא\"ש ורבינו שמשון שדינה ככל שאר ספרים שנגללין מסופן לתחלתן ועוד שבספר התרומה כתב קיום לגרסת הספרים בענין שכתבו רבינו שמשון והרא\"ש וסתם אותו הילכך מכל הני טעמי פשט המנהג לעשות במגילה עמוד בסופה וכדי היקף בתחלתה וכן עיקר והרמב\"ם כתב שאינה צריכה עיבוד לשמה כלום ודלא כר\"ת וכתב הרב המגיד זה פשוט שלא נזכר בו עיבוד ואינה כס\"ת אלא לדברים שהשוה לו וסמ\"ג כתב על דברי הרמב\"ם נ\"ל ראייתו מדקרינן במגילה הכתובה בין הכתובים ביחד ובא\"ח כתב שהגאון רב אחא והרא\"ש והר\"י מקורבי\"ל והר\"ת כתבו שצריכה עיבוד לשמה :","ומ\"ש אם כתב המין או עו\"ג פסול ג\"ז מדברי הרמב\"ם ובה\"ג כ' שאין צריכה תגין כלומר ודלא כר\"ת וזה ל' שבלי הלקט כתב בעל היראים כל הלכות בי\"ת בה וצריך שיהיו אותיות שעטנ\"ז ג\"ץ מזויניים ג' זיינים ושתהא כל אות מוקסת גויל מד' רוחותיה ובעל הדברות כתב שאין צריך לזיין האותיות וכ\"נ בעיני דגריעא מגילה מס\"ת ומעשים בכל יום שקורין במגילה שאינה מזויינת ולא ראינו כן מקומינו מעולם לזיין מגילה עכ\"ל:","\u0003עשרת בני המן צריך לכתב' כשירה ולא כשאר שירות וכו'\u0004 בס\"פ קמא וכו' (טז: ) כל השירות כולן ככתבות אריח ע\"ג לבינה ולבינה ע\"ג אריח חוץ משירה זו ומלכי כנען שאריח ע\"ג אריח ולבינה ע\"ג לבינה מאי טעמא שלא תהא תקומה למפלת' ופירש\"י אריח הוא הכתב לבינה הוא חלק שהוא כפליים מן הכתב והאריח חצי לבינה שלא תהא להם תקומה להרחיב צעדיו תחתיו וכ' הר\"ן שיותר נראים דברי ר\"ת שכמו שאריח הוא מן הכתב כמו כן לבינה הוא מן הכתב וה\"פ כל השירות אריח ע\"ג לבינה וכו' וקורא השיטה הארוכה לבינה והקצרה אריח כעין שכתובות שירת הים ושירת דבורה חוץ משירה זו שאריח ע\"ג אריח ואת ואת ואת שהן תיבות קצרות זו למעלה מזו ולבינה קורא לשמות שהם ארוכות והם ג\"כ זה למעלה מזה ומאי דקאמר שלא תהא תקומה למפלתן טעמו של דבר שכשהחומה שוה בשני ראשים ואין בה בליטות אין להוסיף עליה ולחזקה כמו שהיו יכולים אם היו שם בליטות ושיני החומה שאז יוכלו להוסיף על הבנין ולחזקו וכגון זה שירת הים משא\"כ זו שהעמיד הצד שלה כל א' שוה מב' צדדיו ושירת האזינו נמי כיוצא בזו היא שעמודיה שוים מפני שיש בה מפלתן של רשעים כדכתיב מראש פרעות אויב וכתיב כי דם עבדיו יקום ונקם ישיב לצריו ומיהו כל שיטותיה ארוכות כדמוכח במסכת סופרים ולא תקשי לך הא דאמרינן כל השירות כולן אריח ע\"ג לבינה וכו' דה\"ק כל השירות שיש בהם אריח ולבינה הם נכתבים אריח ע\"ג לבינה לבינה ע\"ג אריח חוץ מזו שאע\"פ שיש בהם אריח ולבינה הם נכתבים אריח ע\"ג אריח ולבינה ע\"ג לבינה אבל שירת האזינו אין אריחין כלל עכ\"ל וכתב המרדכי בירושל' בעיא כדין לעכב או למצוה ומסיק לעכב וצריך להאריך וי\"ו דויזתא גם זה שם וי\"ו דויזתא צריך לממתחי' בזקיפא מאי טעמא דכולהו בחדא זקיפא איזדקיפו וכ' הר\"ן י\"ל דלאו למימרא דבעי לאורוכי טפי משאר ווי\"ן שהרי לא מצינו שנימנית במסורה באותיות גדולות אלא לפשוט ראשו הכפוף והיינו ל' מתיח' שהוא זקוף מל' זקיפה ואחרים פי' שצריך להאריך בה בקריאתה ולא יחטוף אותה והרא\"ש כתב יש מפרשים מותח בקריאתה ויש מפרשים בכתיבתה והיא מאותיות גדולות ע\"כ וז\"ל א\"ח פירש הרא\"ש צריך לממתחיה לזקוף ראשו הכפוף וכל המאריכו אינו אלא טועה לפי שלא מצינו ויו זה בתוך אותיות גדולות עכ\"ל ירושלמי א\"ר יוסי ב\"ר בון צריך שיהא איש בריש דפא ואת בסופה עשרת בסוף דפא בפרק בני העיר וכתב בה\"ג פר\"י כזה* איש ואת פרשנדתא ואת דלפון ואת אספתא ואת פורתא ואת אדליא ואת ארידתא ואת פרמשתא ואת אריסי ואת ארידי ואת ויזתא עשרת ומדקדק מל' ואת בסופה ע\"כ בסוף שטה ר\"ל שאת בסוף הדף והלא אמרי' שעשרת בסוף דפא אלא בראש שטה ובסוף שטה ר\"ל עכ\"ל וכן נהגו:","ומ\"ש בירוש' שניץ ונחיץ כהדין קנטירא נראה דשניץ היא מלשון שנצים כלומר כעין שנצים שעושים לכיס שאחד מהשנצים בולט מצד זה והאחד בולט מהצד השני כך איש בריש דפא ואת כנגדו בסוף אותה שטה ואצטריך למימר הכי כדי שלא תטעה לפרש דואת בסופה בסוף דפא קאמר ומשום הכי כתב שניץ ללמדך דלאו בסוף דפא קאמר אלא בסוף שטה דהיינו כעין שניץ כדפרישית ומ\"ש ונחיץ כהדין קנטירא נראה שר\"ל שוה מב' צדדין כמו בניין השוה שמשליכין משקולת הבנאין מראשה לסופה והיא שוה כך כל תיבות של שמות עשרת בני המן הם זעג\"ז בלי שום בליטה וזה כפר\"ח באריח ע\"ג אריח ולבינה ע\"ג לבינה ומצאתי כתיב ונחיץ פי' לשון חילוק והוא הנחלק ונחצה לב' חצאין קנטירא פי' הוא כמו מטה ושבט של ברזל שהוא של בנאין לחתוך בו את הכותל וכן פי' בערוך וביאור הענין ששירת בני המן את את מצד א' והשמות מצד אחד אלו כנגד אלו וזהו כוונת המאמר שניץ ונחיץ וכו' ר\"ל כמו הלולאות של כיס שעושין מצד זה ומצד זה ומכניס רצועה בין אלו שמצד זה ובין אלו שמצד אחר ומושך הרצועה ונקשר הכיס כך אלו את ואת מכאן ופרשנדתא ושמות האחרים מכאן כמו השנצים ונחלקה זו השירה לה' חלקים לכאן ולכאן כמו השבט של בנאין החותך את הכותל לכאן ולכאן ע\"כ:","נקראת ספר שאם תפרה בחוטי פשתן פסולה ונקראת אגרת שאם הטיל בה ג' חוטי גידים כשרה בלבד שיהיו משולשין בפ\"ב דמגילה (יט.) פירש\"י נקראת ספר. ונכתב בספר וכתב הרא\"ש פירש\"י שיהא מראש התפר עד מקום תפירת הגיד כממנו עד הגיד הב' וכן מן הב' לג' כמו מן הג' עד סוף התפר וכפירושו מצינו במכות (ט.) גבי ערי מקלט דאמרינן התם ושלשת שיהו משולשות שיהא מדרום לחברון כמחברון לשכם ומשכם לקדש כמקדש לצפון והרי\"ף כתב שאם הטיל בה ג' חוטי גידים כשירה שנים בשני קצות היריעה ואחד בתוך היריעה ובלבד שיהיו משולשין פי' שאותו שבתוך היריעה יהיו באמצע היריעה ואשכחן נמי משולשין בכה\"ג בפ' כיצד מעברין (עירובין נז.) גבי ג' כפרים משולשין ובבכורות (לט.) גבי מומים הלכך כיון דאשכחן תרי גווני משולשין יש להחמיר במגילה ולהטיל בה גידין כשני הפירושים והם ה' חוטי גידין עכ\"ל וכ\"כ המרדכי וכך הם דברי רבי' והוי יודע הרמב\"ם מפרש דמשולשין היינו שצריך לתפור ג' תפירות בראש היריעה וג' בסופה וג' באמצעיתה ולפי זה אם באנו לצאת ידי כל הפירושים צריך לתפור י\"א תפירות ג' בראש היריעה וג' בסופה וג' באמצעיתה ותפירה א' בחלק הד' מצד זה ותפירה אחת בחלק הד' שמצד האחר :","וצריך להיות שיור בראש היריעה ובסופה כשתופרים ביחד שלא יתפור הכל ובמשהו סגי בס\"ת בעינן הכי כדאית' בפרק שני דמגילה (שם:) וטעמא כדי שלא יקרע ולמד רבי' למגילה מס\"ת וז\"ל המרדכי מספקא לן אי בעינן במגילה שיור תפר וסברא היא דבעינן עכ\"ל:","\u0003וצריך שתהא כתובה לבדה שלא תהא מחוברת עם הספרים וכו'\u0004 בפרק שני דמגילה (שם:) אמר ר' חייא בר אבא אמר ר' יוחנן הקורא במגילה הכתובה בין הכתובים לא יצא ומחו ליה אמוחא בצבור שנו ומקמי הכי אמרינן התם אהא דלא יצא אמר רבא לא אמרן אלא דלא מחסרא ומייתרא פורתא אבל מחסרא ומייתרא פורתא לית לן בה ופירש\"י הכתובה בין הכתובים. ספרים שהיו בימי החכמים כולם בגליון כס\"ת שלנו: לא יצא. דבעינן אגרת לעצמה דמפרסם ניסא טפי דכי קוראה בין הכתובים נראה כקורא במקרא: או מחסרא או מייתרא. ארוכה משאר קלפים למעלה או למטה או קצרה מהם ויש לה היכר לעצמה וכתב הר\"ן ומחו ליה אמוחא לא אמרו אלא בצבור י\"מ לא אמרו לא יצא אלא בצבור אבל ביחיד יצא וכן דעת הרי\"ף ולישנא לא משמע הכי דא\"כ הול\"ל ה\"מ בצבור אבל ביחיד יצא ומדקאמר ומחו ליה אמוחא משמע שהם מחלישים כח הדבר בעצמו לפיכך נראה דה\"ק ומחו ליה אמוחא שאין לך לומר לא יצא שלא אמרו אלא בצבור אבל היחיד אפילו לכתחלה הלכך אפי' בצבור דיעבד מיהא יצא עכ\"ל אבל הרמב\"ם כתב בהדיא בצבור דיעבד נמי לא יצא וכדעת הרי\"ף וכן דעת הרא\"ש ג\"כ והכי נקטינן:","\u0003כתב ב\"ה ז\"ל הא דאמריני בצבור לא יצא פי' בב\"ה כשהוא מקום צבור וכו'\u0004 טעמו משום דאף על גב די' מיקרו צבור בכל מקום שהם היינו לענין קדיש וקדושה וכיוצא בהם דאכל בי י' שריא שכינתא אבל בדברים שהם משום פירסומי ניסא כל שאינם בב\"ה לא הוי פירסומי כולי האי והלכך חשיבי כיחיד לענין זה:","\u0003ואם אין מגילה כשרה יש מתירין לקרותה בחומש וכו'\u0004 כ\"כ הרוקח וא\"ח ונראה שמברכין עליה דאל\"כ מאי מתירים דקאמר והכי משמע נמי מדמייתי מלולב היבש בשעת הדחק שרוב הפוסקים סוברין שמברכין עליו וכמ\"ש הוא בעצמו בסימן תרמ\"ט אבל כבר כתבתי שם שלענין מעשה יש ליטלו בלא ברכה וכן יש לעשות כשאין מגילה כשרה קורא אותה בחומש בלא ברכה:","כתב ב\"ה שאם קורא במגילה גזולה יצא נראה שלמד כן מדין שופר שנתבאר בסימן תקפ\"ו וכן כתב הרשב\"א בהדיא בתשובה דיוצאין במגילה גזולה כמו שיוצאין בשופר הגזול דכאן וכאן בקול הוא יוצא ואין בקול דין גזל:"],["\u0003היתה כתובה בסם כו'\u0004 משנה וגמ' ריש פ\"ב דמגילה והתוס' בשם ר\"ת כתבו דקלפי' שלנו אע\"ג דלא עפיצי מ\"מ הסיד שאנו נותנין בקלפי' שלנו מהני כעפצים וכ\"כ הרא\"ש ומ\"ש וצריכה שרטוט מימרא דרב אסי בפ\"ק דמגילה דברי שלום ואמת מלמד שצריכה שרטוט כאמתה של תורה ופי' רש\"י כאמתה של תורה כספר תורה עצמו דבעי שרטוט הל\"מ וכתב המרדכי שם אומר ר\"ת אף על גב דהס\"ת לא בעי שרטוט בין שורה לשורה אבל מגילה צריכה שרטוט כאמתה של תורה דהיינו מזוזה שיש בה מלכות שמים ומ\"ש ור\"ת ז\"ל כתב כיון דנקרא ספר וכו' כ\"כ המרדכי משמו וכ\"כ בהגהת מיימוני משמו בתשובה המתחלת בקוצר אשיבך וכו' ונראה ברור שדברי ר\"ת הם עד הכל כס\"ת בזה נסתלקה תלונת הב\"י שחשב שרבינו עצמו פסק הפך דעת התוס' והרא\"ש ורבינו שמשון שפוסקין שצריכין עמוד בסופה וכדי היקף בראש' ולפעד\"נ דרבינו לא פסק כלום אלא העתיק דברי ר\"ת ודברי התוס' הם דברי ר\"י ז\"ל ואחריהם נמשך הרא\"ש בפי' במסכת ידים גם בפסקיו בספ\"ק דבבא בתרא אבל ר\"ת סובר כגירס' ספרים דעמוד בראשה וכדי היקף בסופה וכפי' רש\"י ומ\"ש הכל כס\"ת אף על גב דס\"ת לאמצעיתו נגלל ויש לו שני עמודין היינו דוקא ס\"ת שרגילין לקרות בו הסדר בשבוע אבל שאר ספרי תורות שאין רגילין לקרות בו די בעמוד א' בראשו כדקאמר התם ספר עזרא לתחלתו נגלל ופי' רש\"י ספר שכתב משה ובו קורין בעזרה פ' הקהל וכ\"ג ביום הכיפורים ואין לו אלא עמוד אחד בראשו ונגלל מתחילתו לסופו וה\"ט דכיון שאין קורין בו ברגילות נגלל מתחילתו ודומיא דהכי במגילה שאין קורין בו אלא בפורים וסברא זו כתוב להדיא בספר התרומה לחלק בין ס\"ת שרגילין לקרות בו לס\"ת שאינן רגילין לקרות בו שא\"צ אלא עמוד אחד. ואע\"פ שבהגהת מיימוני המתחלת בקוצר אשיבך יראה דאף רבי' תם סובר דעמוד בסופ' עבדינן יראה בעיני דטעות סופר הוא לשם וצריך להגיה בראשה כדי לגלול עמוד ובסופה כדי לגלול את המגילה ותדע שהרי בדרשות מהרי\"ל כתב דמגילה נגללת מראשה לסופה ובעמוד אחד כדאיתא במיימוני ורצונו לומר בהגהת מיימוני הנזכר כי הרמב\"ם ז\"ל לא כתב מזה כלום וא\"כ בהכרח דצריך להגיה לשם כדכתבתי וזה מסכים לדברי רבינו בשם ר\"ת ומ\"מ צריך עיון למה לא הזכיר רבינו כלל דעת אביו הרא\"ש בדין זה ואפשר דכיון שלא כתב לענין מגילה בדין זה כלום איכא למימר דאף על פי דבכל שאר ספרים נגללין מסופן לראשן היינו טעמא שכשירצה לקרות בו א\"צ לגללו אבל מגילה דפושט וקורא א\"כ שפיר יכול לגללה מראשה לסופה שהרי בלאו הכי צריך לפושט' קודם קריאה וסובר דהכי עדיף טפי לגללה מראשה לסופה שהסוף היא כמו שומר לתחלתו זה אפשר לומר במגילה כיון שלא גילה הרא\"ש ז\"ל דעתו בה בפירוש אבל קשה שאף בהל' ס\"ת לא כתב רבינו מדין זה כלל גם הרמב\"ם לא כתב מזה כלום וצ\"ע. ולענין הלכה יראה להכריע כדעת ר\"י ור\"ש והרא\"ש גם בספר התרומה סימן ר\"ב ובסמ\"ג סימן כ\"ה פסקו כן. וכן כתב באגודה דעמוד בסופה וכדי היקף בראשה וכתב הבית יוסף שכן נהגו ובמלכותו קאמר שנהגו כן אבל במלכותינו נהגו שלא לעשות לה עמוד כלל ואולי מפני מחלוקת הפוסקים בדין זה נהגו כן דשב ואל תעשה עדיף ובדרשות מהרי\"ל כתב טעם אחר על מנהגינו ולא מתיישב לע\"ד: לשון הרמב\"ם אין כותבין את המגלה אלא בדיו על הגויל או על הקלף כספר תורה ואם כתבה במי עפצא וקנקנתום כשרה וכו' ותימה שזה הפך משנתינו בקומוס ובקנקנתום לא יצא ונראה דעת הרמב\"ם ז\"ל דמשנתינו מדבר בקנקנתום לחודא אבל בשנותנין קנקנתו' במי עפצא שרי ולא גרע מס\"ת וראייתו בזה מדתניא בפ' היה נוטל רבי יהודה אומר אומר היה ר\"מ לכל מטילין קנקנתום לתוך הדיו חוץ מפרשת סוטה ומטעם זה פסק בפ\"א מה' תפילין דאם כתב במי עפצא וקנקנתום כשרה ר\"ל במי עפצא וקנקנתום מעורבין יחד ומש\"ה פסק במגלה נמי דכשר בכה\"ג דנלמדנו מדין ק\"ו מס\"ת כמ\"ש ה' המגיד בה' מגלה ועיין בפי' המשניות להרמב\"ם בפרק היה מביא שם נתבאר דכך היא דעתו והיא דעת הרא\"ש לענין ספר תורה דגומא עם מי עפצא כשר ועיין בי\"ד סוף סי' רס\"א. גם דברי הר\"ן ז\"ל שכתב בסוף דבריו דקנקנתום שרי בספר תורה היינו דוקא עם מי עפצא מעורב יחד אבל הקנקנתום לחודיה ודאי אסור כמו מגלה וכך מדוקדק בדבריו למעיין בה היטב ע\"ש פ\"ב דמגלה:","\u0003ומ\"ש והרמב\"ם ז\"ל כו'\u0004 כלומר חולק על ר\"ת בזה שסובר שא\"צ עבוד לשמה והוסיף על ר\"ת בזה היכא שכתבה מין או עו\"ג פסולה ובעל ה\"ג חולק ג\"כ על ר\"ת שסובר שאין צריך תגין:","\u0003עשרת בני המן וכו'\u0004 מימרא בספ\"ק שירה זו אריח על גבי אריח לבינה ע\"ג לבינה ודברי רבי' הם על על פי פי' רש\"י דאריח היינו הכתב ולבינה החלק ומשמע לפירושו דלא בעינן דליהוי ואת ואת זו ע\"ג זו דהוא הדין אם כתב כזה נמי שפיר דמי כיון דמניח חלק בין כתב לכתב אבל ר\"ת פירש אריח היינו ואת ואת דבעינן דלהוי כולן זו על זו וכן השמות זה ע\"ג זה עיין בר\"ן ובמרדכי ומ\"ש וקאמר בירו' שהיא פסולה וכו' כ\"כ המרדכי וז\"ל בירושלמי בעי כדין לעכב או למצוה ומסיק לעכב אבל באגודה כתב דבעי' זו דירושלמי קאי על עשרת דבעינן למהוי בנשימה אחת אי למצוה או לעכב ובמהרי\"ל כתב מעשה במעגנצ\"א שהפסיק ביניהם הקורא ולא אמרם בנשימה אחת והצריכו חכמי העיר לחזור לראש המגילה ובחנם החזירוהו לראש דדי לו לחזור לחמש מאות איש עכ\"ל נראה דחזרה זו כל עיקר היא ע\"פ האגודה שסובר דמסקנת הירושלמי לעכב היא קאי על עשרת דבעי למהוי בנשימה אחת אלמא דבעשר' בני המן עצמן לא קא מבעיא ליה דפשיטא דבעי נשימה אחת אף לעיכובא וכל זה שלא כדברי התו' שכתבו דנשימ' אחת דקאמר לכתחלה אבל דיעבד יצא ובהג\"ה מיימונית כתב דמספקא ליה לראבי\"ה אי למצוה אי לעכב ע\"כ:","ירושלמי אחר ר\"י בר בון צריך שיהא איש בריש דפ' ואת ואת בסוף שניץ ונחיץ כהדין קנתירא כבר פי' הב\"י מה שפי' ולי יראה דהירושל' בא לבאר שהשירה הזאת צריך לכתב' לענין שיהא את ואת ואת זו למעלה מזו ושמות הרשעי' ג\"כ זה למעל' מזה וזהו שניץ כעין שנצים לכיס רצועה אחת מצד זה ואחת מצד זה כך כל ואת ואת ואת מצד אחד כעין רצועה אחת וכל שמות הרשעים מצד אחר כעין רצועה שנייה ואתא לאורויי דלא נימא דעיקר קפידא להניח חלק לבד בין כתב לכתב איך שיהיה וכמו שפי' לדעת רש\"י דליתא ונחיץ פי' מלשון ההולך בשו' לא יטה לא לימין ולא לשמאל וקנטירא פי' הוא חוט של בנאין שמסמן בו את הקורה לחתך אותו מצדדיו כדי שיהא שוה מכל צד ור\"ל שתהא איש בריש דפא ואת בסוף שיטה כזה ולאפוקי דנכתוב את בריש דפא כזה פרשנדתא בסוף שיטה דבכה\"ג נמי הוי שניץ ואשמעי' הירושלמי דלאו שפי' דמי למהוי הכי דא\"כ לא היה שוה מכל צד דהא עשרת מכלל השירה היא וכשיכתוב את בריש דפא א\"כ בסוף הדף לא יהא שוה וכן בסוף השירה לא יהא שוה אבל אם איש בריש דפא שפיר הוא שוה מכל צדדיו בראש ובסוף וכן מכל צד וצד כקורה השוה מכל צד ולפ\"ז צריך לדקדק בעשרת שבסוף שלא יהא בולטת חוץ לשיטה טפי מואת ואת שלמעלה ממנו וכן נוהגין ועוד נראה לפרש דשניץ מורה ג\"כ כשם שהרצועה שמצד שמאל מושך עליו הכיס שביד ימין וכן הרצוע' שמצד ימין מושך אליו הכיס שמצד שמאל וכן כשיהי' איש בריש דפא ואת בסוף דפא השתא מושך אליו פרשנדת' שבשיטה שנייה בצד ימין וכן ואת בסוף שיטה שנייה מושך אליו דלפון שבשיטה שלישית לאפוקי אם יהא את בריש דפא ופרשנתא בסוף שיטה דאז אין נמשך שום שיטה לשטה שבצדה את פרשנדת' ואת דלפון ואת אספתא ואת פורתא ואת אדליא ואת ארידת' וכו' איש ואת פרשנדתא ואת דלפון וכו' ואת פרשנדתא ואת דלפון ואת וכו' כי אין קשר לשיטה אחת עם חברתה:","\u0003ואם אין מגילה כשרה יש מתירין לקרותה בחומש וכו'\u0004 כתב ב\"י נראה דמברכין עליה דאל\"כ מאי מתירין דקאמר ומיהו נראה דמיירי בחומשין שעשויין בגלילה כס\"ת ותפורה בגידין אלא שנמצא בו דבר הפוסלו ואעפ\"כ קורין בו ומברך אם אין שם מגלה כשר' וכדעת הרמב\"ם שהתיר לברך על ס\"ת פסולה אם אי אפשר בס\"ת כשרה כדלעיל בסי' קמ\"ג אבל בחומשין שלנו שהם בקונטרסים כתובים בשני עבריהם וכ\"ש ספרי הדפוס שלנו שאינן נכתבין וקרא קאמר ונכתב בספר דבר פשוט הוא שאין יוצאין בה והו\"ל כקורא ע\"פ ואפי' בשעת הדחק דלא אפשר באחר אינו מברך וכן השיב הרשב\"א בתשובה סי' ש\"ע על מגלה הכתובה בין הכתובים שלנו שהן כתובין בקונטרסים ותפורין בפשתן ומנוקדין יוצא בה או לא והשיב דבר ברור הוא שלא יצא דכל שאינו כתובה בגולל כס\"ת פסולה דהא נקראת ספר וצריכה נמי שתהא תפורה מקצתו בגידין כס\"ת וכו' אבל מחמת הניקוד איני רואה שתפסל בכך עכ\"ל וכן נראה עוד מדאייתי ראיי' מלולב ולשם לולב הוא אלא שנעשה יבש דפוסלו אף כאן בעינן דליהוי האי חומש ספר אלא שיש שם דבר שפוסלו התם הוא דקאמרינן שיצא בו בשעת הדחק ומברך עליו כתב הרשב\"א בתשובה סי' תס\"ז ודאי הקורא את המגילה להוציא הצבור אפילו לא השמיט בה אלא תיבה אחת חוזר וכדמשמע בירושלמי בטעות דיהודיים התם הוא דהלשון והענין אחד אינו חוזר הא לאו הכי חוזר אבל בשומעין א\"צ לכוין בכל תיבה ותיבה והביא ראיות לדבר:"]],["\u0010c0\u0011\u0010y0\u0011הקורא מגילה מברך לפניה ג' ברכות על מקרא מגילה ושהחיינו ושעשה נסים \u0010y1\u0011וכתב ר\"ת ז\"ל שאף ביום צריך לברך שהחיינו שעיקר מצות קריאתה ביום והרמב\"ם ז\"ל כתב שאין מברכין שהחיינו ביום וא\"א ז\"ל הסכים לדעת ר\"ת ואין נוהגין כן \u0010c1\u0011\u0010y2\u0011ולאחריה במקום שנוהגים לברך יברך והאידנא נוהגין לברך \u0010y3\u0011מאי מברך בא\"י אמ\"ה האל הרב את ריבנו והדן את דיננו והנוקם את נקמתינו והנפרע לנו מצרינו והמשלם גמול לכל אויבי נפשנו בא\"י הנפרע לעמו ישראל מכל צריהם האל המושיע \u0010y4\u0011כתב ר\"ע ז\"ל לא אמרינן האל הרב דהא אמרינן אלהינו \u0010c2\u0011\u0010y5\u0011וב\"ה ז\"ל כתב מסתברא כיון שברכה אחרונה במנהגא תליא מילתא אין לגעור במי ששח בקריאתה דלאו הפסקה היא אלא בקריאה תליא מילתא \u0010c3\u0011\u0010y6\u0011ואינו נראה דכיון שהוא מברך צריך שלא להפסיק דמאי נפקא מינה דתלי במנהגא סוף סוף הוא מברך: \u0010y7\u0011מי שקורא לחולה אע\"פ שהוא יצא כבר יברך להוציא מי שקורא לו דקי\"ל כל הברכות אע\"פ שיצא מוציא. \u0010y8\u0011תוספתא קרא בין עומד בין יושב בין שבירך לפניה ולא לאחריה בין לאחריה ולא לפניה או שלא בירך כלל לא לפניה ולא לאחריה יצא:",["\u0003הקורא מגילה מברך לפניה שלש ברכות וכו'\u0004 בריש פרק הקורא עומד (מגילה דף כא):","וכתב ר\"ת שאף ביום צריך לברך שהחיינו שעיקר מצות קריאתה ביום כ\"כ התוספות והרא\"ש והמרדכי בפ\"ק דמגילה (ד.) אהא דאריב\"ל חייב אדם לקרות המגילה בלילה ולשנותה ביום אבל הרמב\"ם כתב שאינו חוזר לברך שהחיינו ביום וטעמו כדאשכחן בסוכה שמברך שהחיינו בלילה ואינו חוזר לברך ביום וכן פשט המנהג :","ולאחריה במקום שנוהגים לברך יברך משנה בפרק הקורא עומד (מגילה כא.)","\u0003ומ\"ש מאי מברך הרב את ריבנו וכו'.\u0004 גם זה שם וכתב הר\"ן יש לתמוה ברכה זו למה פותחת בברוך שהרי היא סמוכה לברכה שלפניה דהא מגילה ודאי לא מפסקא כי היכי דלא מפסיק קריאת שמע בברכותיה דמשום הכי חשבינן ברכה אחרונה שלה סמוכה לחבירתה י\"ל דהאי ברכה אחרונה לאו אקריאת מגילה אלא ברכה בפני עצמה שנתקנה על הנס: ויש לדקדק למה קבעו בברכה זו חמשה לשונות הללו. הרב הדן הנוקם המשלם הנפרע. ונ\"ל שמפני שאומות העולם באים עלינו לפעמים שלא בטענה כלל רק בזדון יתן מצה ומריבה ולפעמים באים בטענה שאומרים שיש להם דין עלינו והקדוש ברוך הוא מצילנו מידם בין בזו ובין בזו וכנגד הראשונה אמר הרב את ריבנו וכנגד השנייה אמר (הדין) [הדן] את דיננו ולפי שלפעמים העונות גורמות שירעו לנו אויבינו מכל מקום אחר שסבלנו [עונש] עונותינו הקדוש ברוך הוא נוקם נקמתנו. ולפי שהמריעים לנו שני מינים האחד שהם אויבים מלב ומנפש ותמיד חורשים עלינו רעות וכנגדם אמר המשלם גמול לכל אויבי נפשנו ואמר לשון גמול כי הוא יתברך מודד להם מדה כנגד מדה כדי שיכירו כי יד יי' עשתה זאת על אשר הרעו לישראל. והמין השני שהם צוררים לנו ולא משנאתם אותנו אלא שדרכם להרע תמיד או שהם מצירים לנו במצות אדוניהם האויבים וכנגדם אמר הנפרע לנו מצרינו כי לאלו אינו חושש לשלם להם מדה כנגד מדה כי לא דעת להם ולא תבונה. ולפי שאין מדרך הטוב לפעול נזק או לשמוח בנזקי שום אדם ואף על פי שהוא רע דוגמא לדבר ויחד יתרו על כל הטובה לכך חתם הנפרע לעמו ישראל מכל צריהם האל המושיע, כלומר כשהקדוש ברוך הוא נפרע מהצרים לישראל אין התכלית לנקמה כי אם להושיע את ישראל כי הנשארים ולדורות הבאים ישמעו ויראו ולא יזידון עוד. ועוד יש לומר שלפעמים מלך אחד נפרע מצוררי אוהביו אבל (כבר) הצוררים [כבר] הרגו את אוהביו נמצא שאין תועלת לאוהביו בנקמה ההיא אבל הקדוש ברוך הוא אינו עושה כן אלא נפרע מהצוררים ומושיע את ישראל: כתוב בארחות חיים אף על גב דאין חותמין בשתים הני שתים שייכי אהדדי ואין תשועה שלמה [מן האויבים] אלא בשתיהן אחת שנפרע לנו מאויבינו ואחרת גדולה מזו שהושיענו מידם ולא נפקד ממנו איש כדכתיב ואיש לא עמד בפניהם. וכתוב עוד שם ירושלמי לא אמרו ברכה לאחריה אלא בצבור:","\u0003כתב ר\"ע לא אמרינן האל הרב וכו'\u0004 וכ\"כ המרדכי בשם בה\"ג דהכי נהוג במתיבתא וכ\"כ בא\"ח:","וב\"ה כ' כיון שברכה אחרונא במנהגא תליא מלתא כ\"כ בשבלי הלקט בשם בעל הדברות ואין לשון רבינו מדוקדק וכך היה לו לרבינו לכתוב כתב ב\"ה כיון שברכה אחרונה וכו' דהא לא אתא ב\"ה לאיפלוגי על שום אדם:","\u0003ומ\"ש רבי' ואינו נראה דכיון שהא מברך צריך שלא להפסיק וכו'\u0004 אינה טענה דכיון שאינו מחוייב לברך לבסוף נמצא שברכה זו לא שייכא אמגילה אלא הרי הוא כמשבח ומודה על הנס וכמו שכתב הר\"ן והלכך אינה עניין למגילה לומר שלא יפסיק בקריאתה. מיהו היינו בקורא עצמו אבל השומע מטעם אחר אין לו להפסיק דבעודו מפסיק לא ישמע מה שהקורא קורא ונמצא שלא שמעה כולה ולא יצא וז\"ל הרשב\"א שאלת ש\"צ שבירך על מקרא מגילה וקרא מקצתה ושמע קול קטטה בחוץ ויצאו מקצתם ואח\"כ חזרו מהו: תשובה אפילו שהא כדי לגמור את כולה אינו חוזר לראש בין להלל בין למגילה בין לשופר ואם חזרו וקראו עשו שלא כהוגן ואם ברכו ה\"ז ברכה לבטלה ולא עוד אלא שאפילו שח אין השיחה מפסקת מן הדין כי אין השיחה הפסק אלא כששח בין ברכה לתחלת המעשה אבל אחר התחלת המעשה או המצוה שבירך עליה אין הפסק ואינו חוזר אלא שכיוצא בזה ראוי שלא לשוח עד גמר המצוה וגוערים בו עד שיכוין במצוה אבל אם שח אינו חוזר והראיה שהרי פוסק באמצע ההלל מפני הכבוד ששואל ומשיב האי כדיניה והאי כדיניה ואינו חוזר ומברך עכ\"ל:","מי שקורא לחולה אע\"פ שהוא קרא כבר יברך להוציא מי שקורא לו דקי\"ל כל הברכות אע\"פ שיצא מוציא בסוף פ' ראוהו ב\"ד (ראש השנה כט.) תנא אהבה בריה דר\"ז של הברכות כולן אעפ\"י שיצא מוציא חוץ מברכת הלחם והיין ותו תניא התם בהלל ובמגילה אעפ\"י שיצא מוציא:","\u0003תוספתא קרא בין עומד בין יושב בין שבירך לפניה ולא לאחריה וכו'\u0004 תוספתא זו כתבה הרוקח: כתב בת\"ה מי שהוא אנוס קצת שלא יכול לילך לב\"ה לקריאת המגילה וצריך להמתין עד לאחר שקראו הקהל וקשה עליו לישב כ\"כ בתענית יכול לשמוע קריאתה מבעוד יום לאחר תפלת ערבית מפלג המנחה ואילך דהיינו שעה ורביע קודם הלילה:"],["\u0003הקורא מגלה מברך וכו'\u0004 ר\"פ הקורא עומד ומ\"ש וכתב ר\"ת וכו' כ\"כ התו' והרא\"ש והמרדכי משמו דמדיליף לה ריב\"ל דחייב אדם לקרות המגילה בלילה ולשנותה ביום מדקאמר קרא אלהי אקרא יומם ולא תענה ולילה ולא דומיה לי משמע דהעיקר הוי ביממא כיון שהזכירו הכתוב בתחלה וקרא משמע נמי הכי ולילה ולא דומיה לי כלומר אעפ\"י שקורא ביום חייב נמי לקרות בלילה ועיקר פרסומי ניסא הוי ביממא וגם עיקר הסעודה ביממא הוא כדאמרי' לקמן דאם אכלה בלילה לא יצא וכתיב נזכרים ונעשי' ואיתקש זכירה לעשייה כדאיתא בפרק הקורא למפרע וה\"נ איתקש מה עשייה ביממא אף זכירה כן והכי נהוג:","\u0003ולאחריה במקום שנוהגין וכו'\u0004 עד כתב רב עמרם לא אמרינן האל וכו' כ\"כ המרדכי בשם בה\"ג דהכי נהוג במתיבתא והר\"א טירנא כתב עוד דאף בחתימה אין אומרין האל הנפרע אלא בא\"י הנפרע כיון שגם עתה הזכיר השם וכתב עוד שיאמר הדן את דינינו הנוקם את נקמתינו וכו' והמשלם וכו' והנפרע וכו' סמוך לחתימה מעין חתימה ולא כספרים שכתוב בהן איפכא אבל ברמב\"ם בסמ\"ג כתב ברוך אתה ה' אלהינו מלך העולם האל הרב וכו' והנוקם וכו' והנפרע וכו' המשלם וכו' בא\"י האל הנפרע וכו' ונראה ליישב דס\"ל דצ\"ל בפתיחת הברכה בא\"י אמ\"ה וכן בחתימה צ\"ל בא\"י כדין כל הברכות ארוכות אלא שמוסיפין כאן שם האל לפי שבמזמור על אילת השחר שאמרה אסתר הזכירה שם האל בתפלתה אלי אלי למה עזבתני והוא לאשר נס זה על ידה היה בשם אל חסד אל כל היום שגם שכבר נגזר ונכתב ונחתם בב\"ד של מעלה להרוג ולאבד וגו' נהפוך היה שישלטו היהודים בשונאיהם ואין זה אלא במדת חסד אל ולכן גם בחתימה אומרים האל הנפרע וכו' לפי שלא היתה תשועתם שלימה אלא בשתי' אחת שנפרע לנו מאויבינו ושניה שהושיענו מידם וכל אחת משתים אלה לא היתה אלא במדת חסד אל כי לא היה הדור זכאי. גם אין לשבש הנוסחא בסמוך לחתימה כי גם המשלם גמול וכו' הוא מעין החתימה ומיהו כבר נהגו שלא לומר האל בפתיחה וכדברי ר\"ע אבל בחתימה אומרין האל:","\u0003וב\"ה כתב וכו'\u0004 איכא למידק אף לדעתו שאין השיח' הפסק מ\"מ יש לגעור בו כדי שיכוין למצוה דאפילו במצוה שאין מברכין לאחריה כגון תקיעת שופר ובדיקת חמץ וכיוצא בהן יש ליזהר שלא להשיח באמצע המצוה כ\"ש מגלה שנקראת אגרת שצריך לקרות כולה כאחד בלי הפסק ואין היתר אלא כדי נשימה בלחוד כמ\"ש בהגה' מיימוני ויראה דדעת ב\"ה דאין ברכה זו לאחר מגלה כברכת ישתבח לאחר פסוקי דזמרה וכיהללוך אחר הלל וכברכות ק\"ש שהשח בהם עבירה הוא בידו וחוזר עליה ממערכי המלחמה ולזה אמר אין לגעור וכו' כלומר אין לגעור בו שהוא עבריין והיינו גערה דידהו דנדוי הא מיהו ודאי יש לגעור בו שצד זה כדי שיכוין לבו למצוה וכדכ' הרשב\"א בתשובה בסי' רמ\"ד וכן לעיל בסי' תל\"ב גבי בדיק' חמץ בדברי הרא\"ש:","\u0003ומ\"ש ואינו נראה וכו'\u0004 טעמו דכיון שמברך הוה עליה חובה כמו ברכת ישתבח אחר פסוקי דזמרה מיהו ב\"י כתב דאעפ\"י שהוא מברך לא שייכא אמגלה אלא משבח ומודה על הנס לבד הוא וכדכ' הר\"ן אבל רבינו לא ס\"ל הכי אלא שייכא אמגלה והכי משמע מלישנא דקאמר מברך לאחריה דעל המגלה הוא מברך לאחריה:"]],["\u0010c0\u0011\u0010y0\u0011כתב ר\"ע ז\"ל בליל פורים אחר קריאת מגילה אומר ובא לציון וי\"א שא\"א אותה לפי שאין עיקר הגאולה בלילה אלא מתחילין ואתה קדוש ואם חל במ\"ש אומרים ויהי נועם אחר קריאת המגילה ובבוקר מתפללין כבשאר ימים אלא שמוסיפין על הניסים בהודאה וכן בלילה \u0010y1\u0011ואם לא אמרו אין מחזירין אותו ולעיל בהלכות חנוכה כתבתי אם מסיימין בו כשם שעשית וכו' \u0010y2\u0011ואין קורין ההלל \u0010y3\u0011כ' ר\"ע ז\"ל מנהג בשתי ישיבות ליפול על פניהם כיון שהוא יום נס ונגאלו בו צריכין אנו לבקש רחמים שיגאלנו באחרונה כבראשונה ובתשובה מצאתי שאין נופלים על פניהם וכן המנהג ומוציאין ס\"ת וקורין שלשה בפרשת בשלח מויבא עמלק עד סוף סדרא וקורין המגילה ואח\"כ סדר קדושה:",["\u0003כתב ר\"ע בליל פורים א\"ר קריאת המגילה אומר ובא לציון גואל וכו'\u0004 אלא שמוסיפין על הניסים בהודאה וכן בלילה כתב הגהות מיימוניות בפ\"ב מהלכות תפלה נראה להר\"מ שאומרים על הניסים בערבית פורים אע\"פ שלא קראו את המגילה דלא כסדר ר\"ע שפסק שאין לאומרו עד לאחר קריאת המגילה :","\u0003ומ\"ש ואם לא אמרו דאין מחזירין אותו נתבאר בהלכות חנוכה:\u0004 ","ומ\"ש ואין קורין את ההלל כלומר שמן הראוי היה לקריאת הלל על נס הנעשה ביום זה וכבר נתנו טעם לדבר בפ\"ק דמגילה (יד.) משום דקריאת המגילה זו היא הלילא ורבא אמר מי דמי בשלמא התם הללו עבדי ה' ולא עבדי פרעה אבל הכא מאי נימא הללו עבדי ה' ולא עבדי אחשורוש אכתי עבדי אחשורוש אנן כלומר דהא לא נגאלו אלא מן המיתה בלבד אבל עדיין נשארו משועבדים לאחשורוש:","\u0003כתב ר\"ע מנהג בב' ישיבות ליפול על פניהם וכו'\u0004 ובתשובות מצאתי שאין נופלין על פניהם כ\"כ התוס' בפ\"ק דמגילה וכ' ג\"כ דאין אומרין למנצח משום דכתיב ביה צרה וצרה בפורים לא מדכרינן וכן נוהגים העולם וז\"ל א\"ח אין אומרים תחנה ולא למנצח ושיר מזמור בב' הימים אבל לקרות בתורה ולהזכיר על הנסים בט\"ו אסור כי אם בי\"ד עכ\"ל ואיני יודע מה איסור יש בהזכרת על הנסים וכתב ע\"ש השיר שהיו הלוים אומרים במקדש שגיון לדוד ומוציאין ס\"ת וקורין ג' בפרשת בשלח מויבא עמלק עד סוף סדר משנה בפרק בני העיר בפורים ויבא עמלק וכתב הר\"ן ואע\"ג דלית ביה אלא ט' פסוקים וקיימא לן דאין פוחתין מי' פסוקים בב\"ה היכא דמפסיק עניינא שאני וכן כתבו התוספות והרא\"ש בפרק הקורא עומד ועכשיו נהגו לחזור פסוק אחרון כדי להשלים י' פסוקים: כתב הכלבו בסוף סי' מ\"א פורים שחל להיות במ\"ש שקורין מגילה לאור הנר מברך בורא מאורי האש קודם ויש חולקין ואומרים שאינו צריך לברך עליו לפי שכבר נפטר ביוצר המאורות אמנם טעמא דמסתבר הוא שלא יהנה ממנו בלא ברכה:"],["\u0003כתב ר\"ע וכו'\u0004 עד ואם לא אמרו מחזירין אותו כבר כתבנו מדין זה באריכות סי' תרפ\"ב והמסקנא דבתפלתה אין מחזירין אותו אפילו בשבת אבל בב\"ה מחזירין אותו בין בחנוכה ובין בפורים ע\"ש כתב בספר א\"ח אסור לקרות בתורה ולהזכיר ע\"ה כי אם בי\"ד עכ\"ל וכתב עליו ב\"י ואיני יודע מה איסור יש בהזכרת ע\"ה ע\"כ ולפע\"ד הדבר פשוט דאסור הוא ואם אמר ע\"ה בט\"ו צריך לחזור ולהתפלל דמשנה ממטבע הברכה שטבעו חכמים הוא ולא דמי למתפלל במ\"ש שתים דמבדיל בראשונה ואינו מבדיל בשנייה ואפ\"ה אם הבדיל בשניהם לא מחזירין ליה כמ\"ש הרי\"ף ר\"פ ת\"ה דהתם ודאי כיון דמ\"ש היא ותקנ' חכמים להבדיל בתפלה במ\"ש ושפיר עביד דאבדיל אלא דלכתחלה א\"צ לאבדולי בתשלומין אבל הכא בט\"ו לאו פורים הוא ולא אתקון לומר ע\"ה בתפלה אלא לפורים:"]],["\u0010c0\u0011\u0010y0\u0011חייב כל אדם ליתן מתנות לעניים ולפחות שתי מתנות לב' עניים \u0010c1\u0011\u0010y1\u0011מעות שגבן לחלק' לעניים בפורים אין רשאין לשנותן לצדקה אחרת \u0010c2\u0011ואין העני רשאי להוציאן לד\"א אלא בסעודת פורים \u0010c3\u0011ואין מדקדקין בהן אלא כל מי שפושט ידו ליטול נותנין לו \u0010y2\u0011אחד ישראל ואחד עו\"ג:",["חייב כל אדם ליתן מתנות לעניים ולפחות ב' מתנות לב' עניים בפ\"ק דמגילה (ז.) תני רב יוסף ומשלוח מנות איש לרעהו שני מנות לאיש א' ומתנות לאביונים ב' מתנות לשני ב\"א וכאן כתב רבינו דין מתנות לאביונים ובסי' תרצ\"ה כתב דין משלוח מנות איש לרעהו:","מעות שגבו לחלק לעניים בפורים אין רשאין לשנותם לצדקה אחרת ואין העני רשאי להוציאן לדבר אחר אלא בסעודת פורים ברייתא במציעא פ' האומנים (בבא מציעא עח:) מגבת פורים לפורים מגבת העיר לאותה העיר ואין מדקדקים בדבר אבל לוקחין את העגלים ושוחטין ואוכלין אותם והמותר יפול לכיס של צדקה ר' אליעזר אומר מגבת פורים לפורים ואין העני רשאי ליקח מהם רצועה לסנדלו אלא א\"כ התנה במעמד אנשי העיר דברי רבי יעקב שאמר משום ר\"מ ור' שמעון בן גמליאל מיקל ופירש\"י מגבת פורים. מעות שגובים הגבאין מבני העיר לחלק לעניים לסעודת פורים כולם יתנו לעניים בפורים ואין מדקדקין לומר דיים בפחות והמותר יפול לכיס של צדקה אבל לוקחין את העגלים לרוב בכל המעות והמותר שלא יספיקו לאכול בפורים ימכור ויפול לכיס של צדקה וז\"ל הג\"א פי' אין הגזבר רשאי להפריש לפי ראות עיניו לצורך פורים והשאר להוציא לצדקה אלא בתחלה יעשה צורכי פורים ואחר שעשה כמשפט יטול המותר לצדקה וכתב המרדכי בפ\"ק דב\"ב דהא דתניא מגבת פורים לפורים דוקא ואינו יכול לשנותם לדבר אחר היינו דוקא הגבאי אבל בני העיר יכולים לשנות מגבת פורים לצורך מצוה אחרת ויש לתמוה על רבינו שפסק להאי ברייתא דקתני אין העני רשאי ליקח מהם רצועה לסנדלו שהרי כתבו הרי\"ף והרא\"ש שם דליתא להא ברייתא דסברה דמעביר על דעתו של ב\"ה גזלן הוי אלא כר\"ג קי\"ל דמיקל וגם הרמב\"ם בפ\"ב מה' מגילה השמיט הא דאין עני רשאי להוציאן לדבר אחר ור\"י כתב להא ברייתא וגריס בה דברי רבי מאיר שאמר משום ר\"ע וכתב שרבים חולקים על הרי\"ף ופוסקים כר\"ע מחבירו ושדברי הרי\"ף נראים וכ\"נ שהוא דעת הרמב\"ם ז\"ל: כתב בהג\"א פ\"ח דמגילה מעות שחשב בלבו לחלקם ביום פורים אינו רשאי לשנותם אלא אותם מעות עצמם חייב לחלק ע\"כ ונראה שהטעם משום דס\"ל דצדקה מחייב בה במחשבה כמו שסוברים קצת פוסקים כמו שאכתוב בטור י\"ד סי' רנ\"ח בס\"ד: ואין מדקדקין במעות פורים אלא כל הפושט את ידו ליטול נותנין לו ירושל' דפ\"ק דמגילה:","ומ\"ש רבינו אחד ישראל ואחד עו\"ג כ\"כ נמוקי יוסף בפ' האומנין בשם הרמב\"ן שכן מנהג בכל ישראל ליתן אפילו לעו\"ג דהואיל ואין מדקדקין בדבר ונותנים לכל אם אין אנו נותנים לעו\"ג איכא משום איבה ותניא (גיטין סא.) מפרנסין עניי עו\"ג עם עניי ישראל מפני דרכי שלום עכ\"ל והגהות מיימוניות כתבו שכתב תלמיד א' לפני רש\"י ראיתי ב\"א שנוהגים לחלק מתנות בפורים לעבדים ולשפחות עו\"ג העומדים בבתי ישראל והר\"ם בשם רבי אפרים כתב דבעיר שלא הורגלו בכך אסור להרגילן אבל בעיר שהורגלו בכך אין לבטל הדבר משום דרכי שלום ע\"כ ורבינו אפשר שבמקום שנהגו קאמר בדוקא או בעיר חדשה אם צריכים לנהוג כך מפני דרכי שלום: כתב המרדכי בפ\"ק דמגילה במקום שאין עניים יכול לעכב מעות פורים שלו לעצמו וליתנו במקום שירצה:"],["\u0003חייב כל אדם וכו'\u0004 כלומר כל אדם אפי' עני המקבל צדקה חייב לתת ממה שנתנו לו לשאר אביונים בפורים דאין דין מתנות אביונים בפורים כדין שאר צדקה דהכשר מצות פורים כן הוא לתת מתנות לאביונים וכדין ד' כוסות בפסח ואפי' משלוח מנות חייבים בו העניים אעפ\"י שלא יספיק להם בסעודתם לאכול לעצמם ולשלוח גם לאחרים וכדמשמע מרב חנניא בר אבין ואביי בר אבין לפי פי' רבינו לקמן בסי' תרצ\"ה א\"כ ה\"ה למתנות אביונים בפורים אבל שאר צדקה דכל השנה אין עני המקבל הצדקה חייב בה אלא פעם אחת בשנה יתן דבר מועט לצדקה כדי לקיים מצות צדקה וכמ\"ש בי\"ד סי' רמ\"ח רמ\"ט:","\u0003מעות שגבו וכו'\u0004 ברייתא בפרק האומנים ופ' המקבל מגבת פורים לפורים מגבת העיר לאותה העיר וכתבו התוס' וא\"ת דאמר בערכין מעות של צדקה מותר לשנותן בכל מה שירצה ואפילו באו ליד גבאי ואפי' אמר מנורה זו לבית הכנסת מותר לשנות למצוה אחרת וי\"ל דדוקא בפורים אמרינן הכי דאין לשנות ומגבת העיר לאותו העיר נמי דפורים דוקא עכ\"ל וכ\"כ בהגהת מרדכי פ' האומנין ע\"ש ר\"ת וכך הם דברי רבינו וכ\"כ הרמב\"ם בפ\"ב דמגילה אבל ממה שכתב הגהת אשיר\"י פ\"ק דמגילה יראה שסובר דאין חלוק בענין זה בין פורים לצדקה אחרת דלעולם יכול לשנותם לכל מה שירצה אלא דברייתא ה\"ק דכיון דעכ\"פ צריך ליתן לעניים מעות לצורך סעודת פורים אם חשב בלבו לחלק ביום פורים ממעות אלו אותן מעות עצמן חייב לחלק ואין רשאי לשנות וה\"ה בכל צדקה המרדכי בשם ר\"י תירץ בפ\"ק דב\"ב דאין חילוק בין פורים לצדקה אחרת אלא בזה דבני העיר יכולין לשנות והגבאי אינו רשאי לשנות ע\"ש:","\u0003ואין העני רשאי וכו'\u0004 שם בברייתא ר' אליעזר אומר מגבת פורים לפורים ואין העני רשאי ליקח מהם רצועה לסנדלו אא\"כ התנה במעמד אנשי העיר דברי ר' יעקב שאמר משום ר\"מ ורשב\"ג מיקל וכתב הרי\"ף והרא\"ש בפ' האומנים דליתא לדר\"מ דסבר מעביר על דעתו של בעה\"ב גזלן הוא אלא כרשב\"ג קי\"ל דמיקל והמרדכי בפ' המקבל ופ\"ק דמגלה כתב ואין העני רשאי וכו' דר\"מ שאמר משום ר\"ע ורשב\"ג מיקל והלכה כר\"ע מחבירו וכ\"כ בהגהת מיימונית. ומקור דבריהם מהסמ\"ג סוף ה' מגלה שכתב כן אלא שכתב עוד וז\"ל יש ספרים שגורסין זו דברי ר' יעקב שאמר משום ר\"מ ולפי זה יכול להיות שהלכה כרשב\"ג שמיקל בשל סופרים עכ\"ל נראה דמסתפק בהלכה זו לפי הגרסאות ודעת המרדכי והגה\"ת מיימונית לסמוך על מ\"ש הסמ\"ק שאין העני רשאי וכו' וע\"ז נסמך גם רבינו אף נגד דעת אביו הרא\"ש ז\"ל ומיהו העניים נהגו לשנות ואין מוחין בידם:","\u0003ומ\"ש ואין מדקדקין וכו'\u0004 כ\"כ הרמב\"ם והסמ\"ג והסמ\"ק וכדאי' בירושל' ורבינו הוסיף לפרש אחד ישראל ואחד עו\"ג וכ\"כ בנ\"י בהאומנים אבל בהג\"מ בשם רש\"י קורא תגר על הנותנים לעו\"ג קורא עליהם כסף הרביתי להם וגו' ע\"ש ולפי דעת רש\"י אין מדקדקים דקאמר היינו לדקדק אחד העני הפושט יד אם הוא הגון וראוי וכשר או שמא הוא רמאי:"]],["\u0010c0\u0011\u0010y0\u0011מצוה להרבות בסעודת פורים \u0010c1\u0011וצריך שישתכר עד שלא ידע בין ארור המן לברוך מרדכי \u0010c2\u0011\u0010y1\u0011ואם אכל בלילה לא יצא \u0010y2\u0011ואומר על הניסים בבה\"מ בהודאה \u0010c3\u0011\u0010y3\u0011ואם התחיל בסעודתו ביום ומשכה עד הלילה כתב א\"א הרא\"ש ז\"ל שא\"א על הניסים \u0010c4\u0011\u0010y4\u0011צריך לשלוח מנות איש לרעהו לפחות ב' מנות לאדם אחד \u0010c5\u0011\u0010y5\u0011ואם החליף סעודתו בשל חבירו יצא:",["מצוה להרבות בסעודת פורים וצריך שישתכר עד שלא ידע בין ארור המן לברוך מרדכי מימרא דרבא בפ\"ק דמגילה (ז:) וכתבו התוספות לא ידע בין ארור המן לברוך מרדכי ארורה זרש ברוכה אסתר ארורים כל הרשעים ברוכים כל הצדיקים וכ\"כ הר\"ן כלומר דאי בין ארור המן לברוך מרדכי לחוד אפי' שתה טובא לא טעי ביה וכתב הר\"ן בשם רבינו אפרים דמההוא עובדא דקם רבה בסעודת פורים ושחטיה לר' זירא כדאיתא בגמרא אידחי ליה מימרא דרבא ולא ש\"ד למעבד הכי כתוב בא\"ח חייב איניש לבסומי בפוריא לא שישתכר שהשכרות איסור גמור ואין לך עבירה גדולה מזו שהוא גורם לג\"ע וש\"ד וכמה עבירות זולתן אך שישת' יותר מלימודו מעט:","ואם אכלה בלילה לא יצא מימרא דרבא שם ומפרש טעמא משום דימי משתה ושמחה כתיב כתב המרדכי בשם ראבי\"ה שצריך לנהוג לילו (שבת) ויומו דומיא דקריאה והמחבר תמה עליו : כתוב בא\"ח נהגו לאכול בליל פורים אחר התענית זרעונים זכר לזרעונים שהיו אוכלים בבית המלך דכתיב ויתנו לנו מן הזרעונים וכתב ה\"ר אשר יש שנהגו שלא לאכול בשר בלילה ההוא כדי שלא יטעו ויחשבו שהיא סעודת פורים וכתב ע\"ש סעודת פורים שאכלה בלילה לא יצא י\"ח י\"מ כעין לילה שאין אבוקה כנגדו דרך שמחה וי\"ט ונשאל רבינו האי מי שנשבע להתענות בפורים מהו והשיב אין כח במצות פורים לדחות שם שמים ואפשר לו לעשות סעודת פורים בלילה ויוצא י\"ח וכתב עו\"ש פורים שחל להיות בע\"ש עבדינן סעודת פורים מבע\"י ובלילה צריכים לקדושי וצריכי נמי למיטעם מידי בתר קידושא ויש שעושים סעודתם בבוקר והכל לפי המנהג בסימן תרפ\"ח כתבתי כשחל יום ט\"ו בשבת כרכים המוקפים אימתי עושים סעודת פורים. כתוב בתרומת הדשן שנהגו רוב העולם לעשות עיקר סעודת פורים בערבית ונמשכים בה עד הלילה ורוב הסעודה היא בלילה ונתן טעם לדבר ומ\"מ כתב שהוא ורבותיו נהגו לעשות עיקר הסעודה בשחרית וכתב עוד שמצא בתשובה שכל מאכל שלוקחים הבחורים זה מזה אפי' שלא ברשות משום שמחת פורים משעת קריאת המגילה עד ליל סעודת פורים שהם שני לילות ויום אחד אין בהם משום גניבה ולא גזילה ואין להזמינו לב\"ד ואין חוששין עליו ובלבד שלא יעשו שלא כהוגן ע\"פ ז' טובי העיר עכ\"ל. ונ\"ל דהיינו לדידהו שהיו נוהגים הבחורים כך אבל אנו שלא נהגו כן אין חילוק בין פורים לשאר ימות השנה לענין זה :","ואומר על הניסים בברכת המזון בהודאה בפרק במה מדליקין (שבת כד.):","ואם התחיל בסעודתו ביום ומשכה עד הלילה כתב הרא\"ש ז\"ל שאין אומרים על הניסים אבל הגהות מיימון כתב בפ\"ב מהלכות מגילה בשם הר\"ם שצריך לברך על הניסים כדאשכחן רב צלי של שבת במ\"ש וכ\"כ בא\"ח בשם הר\"י מקורביל :","\u0003וצריך לשלוח מנות איש לרעהו לפחות ב' מתנו' לאדם א' נתבאר בסימן תרצ\"ד:\u0004 ","ואם החליף סעודתו בשל חבירו יצא בפ\"ק דמגילה (ז:) אביי בר אבין ורב חנניא בר אבין מחלפי סעודתייהו להדדי ופירש הר\"ן לא היה לא' מהם כדי שיוכל לשלוח לחבירו ולהשאיר לעצמו ולפיכך שולחים כל אחד סעודתם זה לזה כדי לאכול סעודת פורים ולקיים מצות משלוח מנות ורש\"י פי' מחלפי סעודתייהו זה אוכל עם זה בפורים של שנה זו ובשנייה סועד חבירו עמו וקשה לי על דבריו דאם כן לא היו מקיימים משלוח מנות איש לרעהו וא\"ת שהיו שולחים מנות איש לרעהו א\"כ מאי אתא לאשמעינן :"],["\u0003מצוה להרבות בסעודת פורים וכו'\u0004 בפ\"ק רב אשי הוה יתיב קמיה דרב כהנא נגה ולא אתו רבנן א\"ל דילמא טרידי בסעודת פורים שמעי' דשרי להרבות בסעודת פורים ושלא לבא לבית המדרש מחמת טירדא דסעודת' דכיון דעסיק במצוה להרבות בסעודת פורים פטור ממצות ת\"ת בבית המדרש:","\u0003וצריך שישתכר וכו'\u0004 מימרא דרבא שם וקשה הא אפילו שתה טובא לא טעי בה ופי' התו' עד דלא ידע בין ארור המן לברוך מרדכי ארורה זרש ברוכה אסתר ארורים כל הרשעים ברוכים כל היהודים ורבא קיצר בלשונו כן פי' הר\"ן אבל בספר צידה לדרך פי' שישתכר עד שלפעמים יטעה לומר להפך ברוך מרדכי ארור המן וז\"ל האגודה י\"מ לחשבון כי חשבון זה כזה עכ\"ל ולפע\"ד כפשוטו דצריך שישתכר הרבה עד דלא ידע כלל מה חלוק יש בין ארור המן לברוך מרדכי שזה הגיע קרוב לשכרותו של לוט ואין לתמוה איך הרשוהו להשתכר כל כך שהרי רבה ור' זירא היו משתכרים עד שקם רבה ושחטיה לר' זירא והנכון מ\"ש הרב הגדול רבי' אפרים דמהך עובדא דשחטי' רבה לר' זירא אידחייא לי' מימרא דרבא ולאו שפיר למיעבד הכי וכ\"כ בעל המאור והר\"ן משמו ונראה דמהך טעמא סידר בעל התלמוד להך עובדא דרבה ור' זירא בתר מימרא דרבא למימרא דהכי הוי הילכתא ולדחויי לדרבא ומיהו דוקא לבסומי עד דלא ידע בין ארור המן לברוך מרדכי הוא דדחינן לה אבל מיהו צריך לשתות הרבה מלמודו שייטב לבו במשתה ויהא שתוי או אפילו שכור שאינו יכול לדבר לפני המלך רק שיהא דעתו עליו בהגהת מיימוני כתב בשם ראבי\"ה כל זה למצוה אבל לא לעכב ובתשובת מהרי\"ל סי נ\"ו ביאר טעמו ע\"ש:","ואם אכלה בלילה לא יצא מימרא דרבא שם מ\"ט ימי משתה ושמחה כתיב כת' המרדכי פי' ראבי\"ה שצריך לנהוג כלילי שבת ויומו דומיא דקריאה דכתיב והימים האלה נזכרים ונעשים ואין היקש למחצה ואיני מבין זה דהא רב כהנא קאמר לרב אשי אמאי טרידי רבנן בסעודת פורים וכי לא הוה אפשר למיכל באורתא א\"ל ולא ס\"ל למר להא דרבא דאמר סעודת פורים שאכלה בלילה לא יצא י\"ח מ\"ט ימי משתה כתיב משמע דסעודה אחת די עכ\"ל ולפעד\"נ ליישב דברי ראבי\"ה דסובר דודאי הסעודה החשובה ברבוי מינים אינו אלא ביום כדמוכח מההיא עובדא אלא דרב כהנא קס\"ד דבלילה נמי יצא אם אכל הסעודה החשובה בלילה וא\"כ לפי זה לא היה צריך להרבות כ\"כ בסעודה חשובה ג\"כ ביום עד דליהוי טרידי בה לבטל ב\"ה בשבילה דכבר יצא י\"ח במה שאכל סעודה חשובה בלילה ורב אשי מהדר ליה מדרבא דלא יצא י\"ח בסעודה חשובה שאכל בלילה אלא דוקא באכלה ביום והשתא לפ\"ז הוכיח ראבי\"ה דבע\"כ צריך לסעוד גם בלילה לערוך שלחנו ולסעוד ודינו כליל שבת ויומו אלא דכבוד יום עדיף דאי איתא דא\"צ לסעוד בלילה כלל היאך טעה כל כך רב כהנא וקס\"ד דיצא בסעודה חשובה כשאכלה בלילה הלא אינו חייב כלל לסעוד בלילה אלא ודאי דעכ\"פ חייב לסעוד בלילה דומיא דקריאה וכו' וקס\"ד דר\"כ דיצא נמי בה י\"ח אם אכל בלילה סעודה חשובה וכו' ומהדר ליה רב אשי דליתא אלא לא יצא י\"ח עד דסעיד סעודה חשובה ביום והכי נהוג לסעוד בלילה אף בחל י\"ד ביום א' וכבר סעד סעודה שלישית במנחה בשבת בסעודה חשובה אפ\"ה חוזרין וסועדין אחר יציאת ב\"ה בלילה דעורכין שלחן וסועדין ומרבין קצת בסעודה זו לשם פורים ולמחר ביום י\"ד סועדין סעודה חשובה בריבוי מעדנים:","\u0003ואם התחיל בסעודתו ביום וכו'\u0004 כ\"כ הרא\"ש כלל כ\"ב וכתב שאף בשבת בסעודה שלישית אם היה אוכל ויצא שבת אינו מזכיר של שבת אבל בהגהת מיימונית פ\"ב מה' מגילה בשם הר\"ם דצריך לברך ע\"ה כדאשכחן רב צלי של שבת במ\"ש וב\"י כתב שכ\"כ בא\"ח בשם מהר\"י מקורבי\"ל וכ\"כ במהרי\"ל סימן נ\"ו ע\"ש ואיכא לתמוה בש\"ע דבסוף סימן קפ\"ח פסק כמהר\"ם ובסי' רע\"א פסק כהרא\"ש וכאן גבי ע\"ה הביא ב' הסברות ולא הכריע ולענין הלכה אין אנו נוהגים כהרא\"ש אלא כמהר\"ם וכן פסק מהרש\"ל וכ\"כ בהגהת ש\"ע:","\u0003וצריך לשלוח מנות איש לרעהו וכו'\u0004 בפ\"ק דמגלה תני רב יוסף וכתב הר\"ן ז\"ל ב' מנות לאדם אחד היינו מיני מאכל ומשתה לעשירים. ולאביונים די לכל אחד במתנה אחת שהיא נחשבת בעיניהם כדבר גדול עכ\"ל ולעד\"נ בטעם מנות ומתנות אלו שהוא כדי שתהא השמחה כוללת שמחת עבודת יוצר הכל והם המתנות לאביונים וג\"כ כוללת שמחת האדם עם אוהביו וריעיו והם המנות ובהיות שהתשועה בפורים היתה כוללת שתי תשועות האחת שנפרע לנו מכל צרינו ונקם נקמתינו שנית שהושיע לנו עד שלא נפקד מאתנו איש והם באמת שתי מתנות טובות ומרומזים יפה בב' מתנות שנתן אחשורוש האחד בית המן שבזה נפרע לנו מצרינו והשני נתינ' הטבעת שלא יפגע בנו שום אויב וצר וכן כתוב ביום ההוא נתן המלך את בית המן וגו' וכתיב ויסר המלך את טבעתו ויתנה למרדכי וגו' וע\"כ לזכר אלו ב' מתנות תקנו לנו חכמינו ז\"ל בין בשמחת עבודת היוצר ובין בשמחת האדם עם אוהביו וריעיו ליתן מידו ומהונו שתי מתנות לזכר ב' תשועות אלו ע\"י מתנות שנתן אחשורוש לא יליזו מנגד פנינו והנה לאשר לא יחדל אביון מקרב הארץ ורבה העזובה מצוה לחלק ולתת לכל אביון מתנה אחת כי כך כתבו הקדמונים והשכל ג\"כ יחייב אותו כי מי שיש לו ק' זהו' ליתן לעניים שגדול שכרו כשיחלקם לק' עניים מאשר יתן כל ק' זהו' לעני אחד או לשנים וג' כי זה שנתן לק' החיה ק' נפשות אבל בשמחת האדם עם אוהביו ורעיו אולי לא ימצא לאדם אוהבים רבים כמ\"ש רז\"ל או חברא כחברי דאיוב וכן אמרו קנה לך חבר ע\"כ המצוה לשלוח ב' מנות לרעהו הטוב להיות שמח ושש עמו על שתי תשועות אלו כנזכר ישמע חכם ויוסף לקח:","ואם החליף סעודתו בשל חבירו יצא בפ\"ק דמגלה אביי בר אבין ורב חנניא בר אבין מחלפי סעודתייהו להדדי ופי' רבינו דבפורים שעמדו בו עכשיו בשנה זו היו מחליפין סעודתם זה שולח לזה סעודתו וזה שולח לזה סעודתו כדי לקיים משלות מנות ועשו כן לפי שלא היתה ידם משגת כדי שיוכל לשלוח מנות לרעהו ולהשאיר גם לעצמו כראוי וע\"כ היו צריכין להחליף סעודתן וכן פי' הרמב\"ם והר\"ן ז\"ל אבל רש\"י ז\"ל כתב וז\"ל מחלפין סעודתייהו זה אוכל עם זה בפורים של שנה זו ושנייה סועד חבירו עמו עכ\"ל ומשמע שר\"ל שלא היו שולחין זה לזה ופשיטא שאין שנה שנייה מועיל להוציא את חבירו ידי חובת משלוח מנות משנה שעברה אלא כך הוא הפי' דכיון דטעם משלוח מנות הוא כדי שיהא שמח ושש עם אוהביו וריעיו ולהשכין ביניהם אהבה ואחוה וריעות א\"כ אם יסעוד אחד עם חבירו ורעהו הרי הם בשמחה ובטוב לב משתה יחד ופטורים הם מעתה מחיוב משלוח מנות וה\"ה בשנה שנייה וכן בכל שנה ושנה אם יחזור ויסעוד אצלו כמו בשנה שעברה נמי יוצאין שניהם ידי חובתן אלא האמת אומר שהיו מחליפים בשנה שנייה ועיקרו לא אתא אלא לאשמעינן האי דינא דבסועד אצל רעהו פטורין שניהם מחיוב משלוח מנות ולפי זה אין צריך לפרש כלל שהיו עניים אלא אפילו בעשירים כן הדין אלא שהמה היו אוהבים זה את זה ביתר עוז והסכימו שטוב ויפה להם לשבת אחים יחד בסעודת פורים בשמחה ובטוב לב משתה כברכת ה' אשר נתן להם כנ\"ל דעת רש\"י ומקובל לע\"ד משאר פירושים שנאמרו בו:"]],["\u0010c0\u0011\u0010y0\u0011פורים מותר בעשיית מלאכה ובמקום שנהגו שלא לעשות אין עושין והעושה אינו רואה סימן ברכה לעולם \u0010c1\u0011\u0010y1\u0011ואסור בהספד ותענית בי\"ד ובט\"ו לבני כרכים ועיירות שתיהן אסורות בשניהן \u0010y2\u0011והנשים מענות בהם שכולן עונות כאחת ומטפחות ושמכות כף אל כף אבל לא מקוננות שתהא אחת מדברת וכולן עונות אחריהן נקבר המת לא מענות ולא מטפחות ובהלכות ר\"ח כתבתי אם י\"ל בו צידוק הדין וקדיש: \u0010y3\u0011כתוב בשאלתות שאם מת לו מת בפורים אסור להספידו ולא לנהוג אבילות ואם מת קודם פורים ופגע בו פורים בתוך ז' בטל ממנו גזירת ז' ודוקא פורים אבל חנוכה ור\"ח אין מבטלין האבלות אלא שאין מספידין בהן והר\"ם מרוטנבורק כתב שאין מבטלין האבילות ומ\"מ אין אבילות נוהג בהם לא בי\"ד ולא בט\"ו אלא דברים שבצנעה ולאחר שיתפלל בבית האבל בליל פורים ילך לב\"ה לשמוע מקרא מגילה וחייב לשלוח מנות ואע\"פ שאינו מתאבל בהן עולין לו ומשלים אבילות אח\"כ וי\"א שלא ילך האבל לב\"ה אלא יקרא המגילה בביתו וכן חתן לא ילך לב\"ה אלא יקרא המגילה בביתו וא\"א ז\"ל כתב כדברי הר\"ם מרוטנבורק",["\u0003פורים מותר בעשיית מלאכה וכו'\u0004 בפ\"ק דמגילה (ה:) אמרינן דרבי נטע נטיעה בפורים ומתמהין עליה דהא תני רב יוסף משתה ושמחה וי\"ט שמחה מלמד שאסורים בהספד משתה מלמד שאסור ובתענית וי\"ט מלמד שאסור בעשיית מלאכה רבי בר ארביסר הוה וכי נטע בחמשה עשר נטע ומי שרי והא כתיב במגילת תענית את יום י\"ד ואת יום ט\"ו יומא פוריא אינון דלא למספד בהון ואמר רבא לא נצרכה אלא לאסור את של זה בזה ואת של זה בזה ה\"מ בהספד ובתענית אבל מלאכה יום אחד ותו לא איני והא רב חזייה לההוא גברא דהוה קא שדי כיתנא בפוריא ולטייה ולא צמח כיתניה התם בר יומיה הוה רבה בריה דרבא אמר אפי' תימא ביומיה הספד ותענית קבילו עלייהו מלאכה לא קבילו עלייהו דמעיקרא כתיב שמחה ומשתה וי\"ט ולבסוף כתיב לעשות אותם ימי משתה ושמחה ואילו י\"ט לא כתיב ואלא רב מאי טעמא לטייה לההוא גברא משום דברים המותרים ואחרים נהגו בהם איסור הוה ובאתרי' דרבי לא נהגו ואיבעית אימא לעולם נהוג ורבי נטיעה של שמחה נטע ופסקו הרי\"ף והרא\"ש כרבא דאמר מלאכ' לא קבילו עלייהו וכ\"כ הרמב\"ם אלא שכתב שאעפ\"כ אין ראוי לעשות בו מלאכה אמרו חכמים כל העושה מלאכה ביום פורים אינו רואה סי' ברכה לעולם ונראה שכ\"כ מההוא עובדא דרב דלטייה לההוא גברא ולא צמח כיתניה: וכתוב בשבלי הלקט אהא דאמרינן דלטייה משום דברים המותרים ואחרים נהגו בהם איסור דאפילו במקום שנהגו לא נהגו אלא ביום מקרא מגילה עצמה אבל לאסור של זה בזה אינו מנהג עכ\"ל : כתוב בא\"ח אע\"ג דמלאכה לא קבילו עלייהו אחר כך נתקבל במנהג ומנדין כל העושה בו מלאכה כיון שפשט איסורו בכל ישראל אמנם בנין של שמחה כגון בית חתנות לבנו או אבורנקי של מלכים מותר וכן מלאכת מצוה שריא כגון כתיבה של מצוה ומותר לכתוב פסקי הלכות ופשטי המקראות שאדם שמח בהם כדכתיב פקודי ה' ישרים משמחי לב ואגרות של שאלת שלום ומזכרת חובותיו וכן כל דבר שא\"צ עיון גדול נראה שמותר עכ\"ל: כתב הרשב\"א שאלת אם מותר לישא אשה בפורים מסתברא שהוא מותר דושמחת בחגך כתיב בחגך ולא באשתך אבל בפורים מותר ועוד דהו\"ל חד יומא ומשום חד יומא לא משהי איניש נפשיה וכמ\"ד משום פריה ורביה ובענינים אלו הולכים בהן להקל דמדרבנן הם:","\u0003ואסור בהספד ובתענית בי\"ד ובט\"ו לבני כרכין ועיירות שתיהן אסורות בשניהן כבר נתבאר בסמוך:\u0004 ","והנשים מענות בהם שכולן עונות כא' מטפחות שמכות כף אלו כף אבל לא מקוננות שתהא אחת מדברת וכולן עונות אחריה נקבר המת לא מענות ולא מטפחות משנה בסוף מ\"ק (כח:) ואיתא התם א א\"ר פפא אין מועד בפני ת\"ח וכ\"ש חנוכה ופורים וכתבו רבינו בסוף טי\"ד:","כתוב בשאלתות שאם מת לו מת בפורים אסור להספידו ולא לנהוג אבילות ואם מת קודם פורים ופגע בו פורים וכו' ז\"ל הרא\"ש בסוף מ\"ק כתב בספר המקצועות והיכא דשכיב ליה שיכבא אסור ליה למספד ולמנהג אבילות בפורים ואי איתרע ביה מלתא אסור למיתב בתעניתא דאמר רב יוסף (מגילה ה:) שמחה ומשתה וי\"ט כתיב שמחה ומשתה מלמד שאסורים בהספד ובתענית ויום טוב מלמד שאסורין בעשיית מלאכה ומסקינן בהספד ובתענית אסור אבל י\"ט לא דתנן מקום שנהגו לעשות מלאכה בפורים עושים והיכא דשכיב ליה שיכבא מקמי פוריא ואתרמי פורים בגו ז' אבילות בטלה הימנו גזרת ז' מידי דהוה ארגלים ורגלים מפסיקין ואינם עולים מ\"ט דשמחה כתיב בהו ושמחת בחגך ופורים נמי שמחה כתיב ביה ועשה אותם ימי משתה ושמחה ודוקא פורים אבל חנוכה לא מפסקא ואסור בהספד דת\"ר (כא:) בכ\"ה בכסליו יומי חנוכה תמניא אינון דלא למספד בהון מספד הוא דאסור אבל ימי אבלות לא מפסקי וכן ראשי חדשים וכן מפורש בשאלתות ע\"כ והקשה ר\"מ כיון דס\"ל דשעה אחת לפני הפורים בטלה הימנו גזרת ז' א\"כ ה\"ה ז' ימים לפני פורים בטלו ממנו גזרת ל' כי דימה אותה לגמרי לרגל א\"כ כי פליגי בהאי פירקא דר\"ג אומר משחרב ב\"ה ר\"ה וי\"ה כרגלים ופליגי תנאי עליה אמאי לא חשיב נמי פורים ועוד דחזינן דפורים לא חשיב כרגלים דתנן נשים במועד מענות ולא מטפחות ובפורים מענות ומטפחות והורה רבינו מאיר שלא יתאבל כלל בפורים דיומי משתה ושמחה קבילו עלייהו וחנוכה ופורים אסורים בהספד ובתענית ונהי דבטלה מגילת תענית חנוכה ופורים לא בטלו ותנן נמי חנוכה ופורים מענות ומטפחות בזה ובזה אינן מקוננות נקבר המת לא מענות ולא מטפחות אבל דברים של צינעא נוהג דלא עדיף משבת ולאחר שהתפללו בבית האבל בליל פורים בערב הורה לו שילך לב\"ה בעת קריאת המגילה דאפי' עבודה שקרבן צבור שדוחה שבת קריאת המגילה דוחה אותה כ\"ש אבילות דרבנן וחייב לשלוח מנות דאבל חייב בכל המצות האמורות בתורה וביום חמשה עשר אינו מתאבל מדאמרינן בפרק שני דתעניות (יח:) יום י\"ד ויום ט\"ו יומי פורים דלא למספד בהון אמר רבא לא נצרכה אלא לאסור של זה בזה ואע\"ג דלא מתאבל בהן עולין לו מידי דהוה אשבת ואח\"כ משלים אבלותו עכ\"ל הרא\"ש ז\"ל וכ\"כ המרדכי בפ\"ק דמגילה ודברים אלו הם שכתב רבינו כאן בשם הרב רבי' מאיר מרוטנבורק ובקצת ספרי רבינו הרמב\"ם במקום הרב רבי מאיר מרוטנבורק וטעות סופר הוא שהרמב\"ם סובר שכל דברי אבילות נוהגים בחנוכה ובפורים שכך כתב בפירוש בפי\"א מהלכות אבילות: כתב הרוקח פורים שחל להיות במוצאי שבת ואירע שום אבל קודם הפורים והאבל יושב בבית הכנסת בשבת במנחה כשיהיה שם לא יצא וישב שם וישמע כל התפלה והמגילה ולמחרת לא יצא מפתח ביתו אלא קורין לו המתפללים עמו או קורא בעצמו וכן אם יום פורים באמצע השבוע אמרינן במ\"ק אבל אינו יוצא מפתח ביתו ע\"כ: כתב בא\"ח האונן מותר בבשר ויין דלא אתי עשה דיחיד דאבילות ודחי עשה דרבים דאורייתא ולשמוח בפורים דברי קבלה נינהו שהם כד\"ת:"],["\u0003פורים מותר בעשיית מלאכה וכו'\u0004 עד אינו רואה סימן ברכה לעולם כ\"כ הרמב\"ם וכן פסק הסמ\"ק והביא ראיה כדאיתא התם שרב קלל אדם אחד שראהו שזרע פשתן בפורים ולא צמח הפשתן ההוא מפני שבאותו מקום נהגו שלא לעשות מלאכה עכ\"ל אלא דקשיא לי דמראיה זו משמע דמשמתי' ליה דהא רב לטייה לההוא גברא וכ\"כ בהג\"ה מיימוני בשם השאלתות ע\"ש ונראה ודאי דהא דקאמר דלטייה פירושו שקלל אותו בזה שלא יצמח מה שזרע אבל לאדם עצמו לא קלל והיינו הך דאינו רואה סימן ברכה לעולם דר\"ל דבמלאכה זו אינו רואה סי' ברכה ולא הוה חמור קללה זו כשמתא שהוא שם מיתה וקללה של אדם עצמו ותדע דהא למאי דמשני רבא מלאכה לא קבילו עלייהו ורב דלטייה לההוא גברא דברים המותרים ונהגו בו איסור הוה וא\"כ אין כאן איסור מד\"ס כלל כ\"א מנהג והשתא כ\"ש הוא מע\"ש ועי\"ט דאיסור מלאכה בדידהו מד\"ס הוא ואפ\"ה דייק תלמודא בפ' מקום שנהגו סימן ברכה הוא דאינו רואה אבל שמותי לא הי' משמתינן ליה כ\"ש פורים דאין בו איסור מד\"ס דפשיטא דאין לשם עונש שמתא כ\"א דאינו רואה סימן ברכה לכל היותר והיינו דלטייה אך קשה למאי שהיה גורס הרא\"ם באותה הסוגיא דפריך תלמודא ולשמתיה מר שמותי כיון דלא צמח כיתניה היינו שמתיה וצריך לומר דהרמב\"ם והסמ\"ג ורבינו לא היו גורסין כך אלא גורסין כגירסא שלנו ועוד נלפע\"ד אף לפי גירסא זו דתלמודא לא פריך הכי אלא למאי דמשני מעיקרא דפורים אסור עשיית מלאכה מדכתיב יום טוב מלמד שאסור בעשיית דברי קבל כד\"ת ודינו כמו בע\"פ דהי' משמתינן ליה. אבל לשינויא דרבא דלא לטייה אלא משום דברים המותרים ואחרים נהגו בו איסור א\"כ לא קשיא כלל דלשמתיה דלא הי' חייב שמתא ומאי דלטייה אינו אלא עונש דאינו רואה סימן ברכה כדפי' ובזה נתיישב מה שהיה קשה להרא\"ם לפי גרסתו עיין בביאוריו כנ\"ל מהרי\"ל כתב דכתיבה אסורה בפורים ועיין בב\"י כתב היתר לקצת כתיבה:","\u0003ומ\"ש ואסור בהספד וכו'\u0004 ע\"ל בסי' תרפ\"ו ובי\"ד סי' ת\"א ומה שנוהגים בפורים ללבוש פרצופים וגבר לובש שמלת אשה וכו' כתב הר\"י מינץ טעם לדבר ובהגהת ש\"ע מביאו כאן ואינו נכון לע\"ד וכבר הארכתי בזה בי\"ד סוף סימן קפ\"ב ע\"ש:"]],["\u0010c0\u0011\u0010y0\u0011יום י\"ד וט\"ו שבאדר הראשון מותרים בהספד ובתענית והא דיום י\"ד וט\"ו דאדר הראשון והשני שוין בהספד ותענית היינו דוקא כשקראו המגילה ובו ביום נראה להם לעבר השנה אבל אם לא קראו המגילה מותרין בהספד ותענית ובספר המצות כתב שאסורין בהספד ותענית בכל השנים אע\"פ שלא קראו המגילה וכן יראה מדברי הרמב\"ם ז\"ל וכן כתב הרי\"ף ז\"ל שצריך להרבות בו בסעודה בי\"ד אבל בט\"ו כתב שאין צריך להרבות בו בסעודה וא\"א ז\"ל כתב כסברא ראשונה:\n\u0003נשלם הטור הראשון והוא האורח חיים ת\"ל\u0004",["יום י\"ד וט\"ו שבאדר הראשון מותרין בהספד ובתענית והא דיום י\"ד וט\"ו דאדר הראשון והשני שוים בהספד ובתענית היינו דוקא כשקראו המגילה וכו' בפ\"ק דמגילה (ז:) תנן קראו את המגילה באדר הראשון ונתעברה השנה קורין אותה באדר שני ואין בין אדר ראשון לאדר שני אלא קריאת המגילה לבד ומתנות לאביונים ובגמרא בברייתא שם אפליגו תנאי במלתא ומסיים בה ושוין בהספד ותענית שאסורין בזה ובזה וכתב הרא\"ש ושוין בהספד ותענית דאסורין בזה ובזה פירוש אם קראו המגילה בי\"ד ובו ביום עברו השנה אסור בהספד ובתענית אבל בשאר שנה מעוברת נ\"ל שמותר בהספד ותענית עכ\"ל וכך הם דברי רבינו אלא שכתב אבל אם לא קראו המגילה מותרין [במקום] אבל בשאר שנה מעוברת והכל אחד דכשיודעים קודם לכן שהשנה מעוברת ודאי שאינם קורים את המגילה בי\"ד ובט\"ו שבאדר ראשון. ופשוט הוא שמה שכתבו הרא\"ש ורבינו ובו ביום נראה להם לעבר השנה היינו משום דאם לא נראה להם עד אחר אותו יום פשיטא דאסור בהספד ובתענית שמאחר שבאותו יום לא היה בדעתם לעבר הו\"ל באותו יום כשאר שנים פשוטות וכתבו הגהות מיימונית והמרדכי שהר\"מ כתב כדברי הרא\"ש אבל הרמב\"ם כתב סתם ושני הימים אסורים בהספד ותענית באדר הראשון ובאדר השני וכתבו הגהות שכן פסק בסמ\"ג וכן דעת הר\"ן וכתב שקרוב הדבר ג\"כ שראוי להרבות בסעודה בי\"ד שבראשון אבל לענין לשלוח מנות כיון דדמו למתנות לאביונים דליתנהו אלא בשני משמע נמי שאף משלוח מנות אינו אלא בשני והתוס' כתבו ויש נוהגין לעשות ימי משתה ושמחה בי\"ד וט\"ו של אדר הראשון וריהטא דמתני' נמי משמע כן ולא נהירא דאמרינן בגמרא הא לענין הספד ותענית זה וזה שוים מכלל דשמחה ומשתה ליכא וכן הלכה שאין צריך להחמיר לעשות משתה ושמחה באדר הראשון עכ\"ל והגהות מיימונית כתבו בשם סמ\"ק שהעולם לא נהגו לעשות משתה ושמחה כי אם בי\"ד שבאדר הראשון אע\"פ שבאדר השני נהגו גם בט\"ו שמחה ומשתה וטעמא משום דאמר תלמודא אין בין י\"ד שבאדר הראשון וכו' ולא הזכיר ט\"ו ושמא נקט אותו שהוא עיקר אבל לעניין עשיית מלאכה אין איסור בא' כי גם בב' אין בו איסור כי אם במקום שנהגו ע\"כ ועכשיו לא נהגו להרבות בסעודה לא בי\"ד ולא בט\"ו שבאדר הראשון ומ\"מ נוהגים שלא ליפול ע\"פ ושלא לומר מזמור יענך ה' ביום צרה משום דיומי נס והצלה הם:"],["\u0003יום י\"ד וכו'\u0004 כבר הבאתי בסוף סימן תרפ\"ח מ\"ש הרא\"ש שהוכיח מהסוגיא דסיפא ארישא קאי וממילא לפי המסקנא נמי בשאר שנים המעוברות אינו אסור בהספד ותענית באדר הראשון ולפע\"ד יראה דודאי כך הוא כדכתב הרא\"ש קודם המסקנא אבל למסקנא נראה בהיפך והוא דכיון דמסקינן אליבא דרשב\"ג דמתני' אתיא כותיה וה\"ק אין בין י\"ד של אדר הראשון וכו' השתא אי איתא דסיפא ארישא קיימא קשי' אתנא דמתניתין גופיה אמאי קתני אין בין י\"ד של אדר הא' וכו' ובסדר הפרשיות לא מיירי דאמאי שייר טפי סדר הפרשיות ממקרא מגלה ומתנות לאביונים דהא הני תלתא מילי שוין דינייהו שצריך לחזור ולעשותן בשני והו\"ל למיתני נמי סדר הפרשיות ולפרושי אין בין חדש אדר הראשון וכו' אבל אי סיפא לאו ארישא קאי ובכל השנים המעוברות קאמר דאין בין י\"ד של אדר הראשון וכו' ניחא וכן נראה מבואר מלשון הרי\"ף והסמ\"ג דלמאי דמסיק אין בין י\"ד וכו' אף בכל השנים המעוברות אסור בהספד ובתענית בי\"ד אדר הראשון כל זה כתבתי ליישב המנהג שנוהגין איסור בהספד ובתענית באדר הראשון דלא כהרא\"ש. שוב ראיתי שכתב ה\"ר ירוחם כי לפי דברי הרי\"ף נראה דאסור ע\"ש וכן הוא העיקר נראה לי:"]]]};
